// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPolicyWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

/// @title FrostSecp256k1: on-chain check of a FROST(secp256k1, SHA-256) signature (RFC 9591)
/// @notice A FROST signature is a plain Schnorr signature (R, z) under the group key PK:
///         z·G == R + c·PK with c = H2(R ‖ PK ‖ msg) (RFC 9591 §6.5: hash_to_field over
///         expand_message_xmd(SHA-256), DST "FROST-secp256k1-SHA256-v1chal"; points SEC1-compressed).
///         The EVM has no secp256k1 point multiplication, so the check uses ECRECOVER:
///         ecrecover(h, v, r, s) returns the address of r⁻¹·(s·Rr − h·G), where Rr is the point with
///         x = r and y-parity v−27. With r = PK.x, v from PK.y, s = −c·PK.x and h = −z·PK.x (mod n) it
///         returns the address of z·G − c·PK, which must equal R: we compare it with the address of
///         R, lifted from its compressed form with the modexp precompile. This is the construction
///         of V. Buterin, "You can *kinda* abuse ECRECOVER to do ECMUL in secp256k1 today"
///         (ethresear.ch, 2018), used by Chainlink's SchnorrSECP256K1.sol, noot/schnorr-verify and
///         Chronicle's Scribe. Unlike those, the challenge here is RFC 9591's (so signatures from any
///         RFC 9591 implementation verify) and R is a whole curve point lifted from x and parity,
///         not an address the signer supplies.
///         Caveats (docs/future/agents.md): like every ecrecover verifier it compares 160-bit
///         addresses; the group key's x must be below the curve order n (true except with ~2^-128
///         probability; the DKG refuses such a key).
library FrostSecp256k1 {
    uint256 internal constant N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
    uint256 internal constant P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F;

    /// y of the curve point with this x and y-parity (ok = false when x is not on the curve).
    function liftX(uint256 x, uint256 parity) internal view returns (bool ok, uint256 y) {
        if (x >= P || parity > 1) return (false, 0);
        uint256 rhs = addmod(mulmod(mulmod(x, x, P), x, P), 7, P);
        y = _modexp(rhs, (P + 1) / 4, P); // P ≡ 3 (mod 4)
        if (mulmod(y, y, P) != rhs) return (false, 0);
        if (y & 1 != parity) y = P - y; // y != 0: secp256k1 has no point of order 2
        return (true, y);
    }

    /// RFC 9380 hash_to_field(msg, 1) for secp256k1's scalar field: expand_message_xmd with SHA-256,
    /// L = 48 bytes, reduced mod n. RFC 9591 uses it for H1, H2, H3 with DST = context ‖ tag.
    function hashToScalar(bytes memory message, bytes memory dst) internal pure returns (uint256) {
        bytes memory dstPrime = abi.encodePacked(dst, uint8(dst.length));
        bytes32 b0 = sha256(abi.encodePacked(bytes32(0), bytes32(0), message, uint16(48), uint8(0), dstPrime));
        bytes32 b1 = sha256(abi.encodePacked(b0, uint8(1), dstPrime));
        bytes32 b2 = sha256(abi.encodePacked(b0 ^ b1, uint8(2), dstPrime));
        // the 48 bytes b1 ‖ b2[0:16] as an integer, mod n
        return addmod(mulmod(uint256(b1), 1 << 128, N), uint256(b2) >> 128, N);
    }

    /// RFC 9591 H2 (the challenge) for R (33 bytes), the group key (x, parity) and the message.
    function challenge(bytes memory rEnc, uint256 pkX, uint256 pkParity, bytes memory message) internal pure returns (uint256) {
        return hashToScalar(abi.encodePacked(rEnc, uint8(2 + pkParity), pkX, message), "FROST-secp256k1-SHA256-v1chal");
    }

    /// True when `sig` (RFC 9591 serialization: compressed R ‖ z, 65 bytes) is a valid signature of
    /// `message` under the group key (pkX, pkParity = PK.y mod 2).
    function verify(uint256 pkX, uint256 pkParity, bytes memory message, bytes memory sig) internal view returns (bool) {
        if (sig.length != 65 || pkX == 0 || pkX >= N || pkParity > 1) return false;
        uint256 prefix = uint8(sig[0]);
        if (prefix != 2 && prefix != 3) return false;
        uint256 rx;
        uint256 z;
        assembly {
            rx := mload(add(sig, 33))
            z := mload(add(sig, 65))
        }
        if (z == 0 || z >= N) return false;
        (bool ok, uint256 ry) = liftX(rx, prefix - 2);
        if (!ok) return false;
        uint256 c = challenge(abi.encodePacked(uint8(prefix), rx), pkX, pkParity, message);
        if (c == 0) return false;
        address q = _zGminusCP(pkX, pkParity, z, c);
        return q != address(0) && q == address(uint160(uint256(keccak256(abi.encodePacked(rx, ry)))));
    }

    /// The address of z·G − c·PK: ecrecover(−z·x, v(PK), x, −c·x) = x⁻¹·(−c·x·PK + z·x·G).
    function _zGminusCP(uint256 pkX, uint256 pkParity, uint256 z, uint256 c) private pure returns (address) {
        return ecrecover(bytes32(N - mulmod(z, pkX, N)), uint8(27 + pkParity), bytes32(pkX), bytes32(N - mulmod(c, pkX, N)));
    }

    /// A compressed group key (33 bytes) -> (x, parity), checking it is a curve point with 0 < x < n.
    function parseKey(bytes memory key) internal view returns (bool ok, uint256 x, uint256 parity) {
        if (key.length != 33 || (uint8(key[0]) != 2 && uint8(key[0]) != 3)) return (false, 0, 0);
        assembly { x := mload(add(key, 33)) }
        parity = uint8(key[0]) - 2;
        if (x == 0 || x >= N) return (false, 0, 0);
        (ok,) = liftX(x, parity);
    }

    function _modexp(uint256 b, uint256 e, uint256 m) private view returns (uint256 r) {
        (bool ok, bytes memory out) = address(0x05).staticcall(abi.encode(uint256(32), uint256(32), uint256(32), b, e, m));
        require(ok && out.length == 32, "modexp");
        r = uint256(bytes32(out));
    }
}

/// @title FrostVerifier: FrostSecp256k1 as a contract anyone can call (and the tests use)
contract FrostVerifier {
    /// groupKey: SEC1-compressed (33 bytes); sig: R (33) ‖ z (32), RFC 9591's serialization.
    function verify(bytes calldata groupKey, bytes calldata message, bytes calldata sig) external view returns (bool) {
        (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
        return ok && FrostSecp256k1.verify(x, parity, message, sig);
    }

    /// RFC 9591's challenge H2(R ‖ PK ‖ msg), for cross-checking implementations.
    function challenge(bytes calldata rEnc, bytes calldata groupKey, bytes calldata message) external view returns (uint256) {
        (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
        require(ok && rEnc.length == 33, "key");
        return FrostSecp256k1.challenge(rEnc, x, parity, message);
    }
}

/// @title CosignCommittee: runners that co-sign large agent transactions
/// @notice Two ways to co-sign, both set by governance (the chain's gov module
///         through a MsgEVMCall proposal, or a SimpleMultisig):
///           - k-of-n separate ECDSA signatures (isValid): each member signs
///             the digest; signers in ascending order, no repeats. Simple and
///             checkable, k signatures of gas. Kept as the fallback.
///           - a FROST threshold signature (isValidFrost, RFC 9591): the
///             members ran a distributed key generation (no dealer;
///             `zetaphy cosign dkg1|dkg2|dkg3`) for a t-of-n group key; any t
///             of them make ONE 65-byte Schnorr signature in two rounds
///             (`zetaphy cosign commit | frost-sign | frost-aggregate`),
///             checked by FrostSecp256k1 at the cost of about one ecrecover
///             whatever t is. Which members signed is not visible on chain.
///         A member signs only after running Neuro's checks on the transaction.
contract CosignCommittee {
    uint256 public constant MAX_MEMBERS = 32;

    address public governance;
    mapping(address => bool) public isMember;
    address[] private memberList;
    uint256 public threshold;
    uint256 public frostKeyX;      // FROST group key: x (0 = none) ...
    uint256 public frostKeyParity; // ... and the parity of y

    event MembersSet(address[] members, uint256 threshold);
    event GovernanceChanged(address governance);
    event FrostKeySet(bytes groupKey);

    error NotGovernance();
    error BadMembers();
    error BadFrostKey();

    constructor(address governance_, address[] memory initialMembers, uint256 threshold_) {
        governance = governance_;
        _set(initialMembers, threshold_);
    }

    function setMembers(address[] calldata newMembers, uint256 threshold_) external {
        if (msg.sender != governance) revert NotGovernance();
        _set(newMembers, threshold_);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        governance = g;
        emit GovernanceChanged(g);
    }

    /// The FROST group key (33 bytes, SEC1-compressed, from `zetaphy cosign dkg3`); empty removes it.
    function setFrostKey(bytes calldata groupKey) external {
        if (msg.sender != governance) revert NotGovernance();
        if (groupKey.length == 0) {
            frostKeyX = 0;
            frostKeyParity = 0;
        } else {
            (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
            if (!ok) revert BadFrostKey();
            frostKeyX = x;
            frostKeyParity = parity;
        }
        emit FrostKeySet(groupKey);
    }

    /// True when `sig` is the group's FROST signature (RFC 9591, 65 bytes) of the 32-byte digest.
    function isValidFrost(bytes32 digest, bytes calldata sig) external view returns (bool) {
        if (frostKeyX == 0) return false;
        return FrostSecp256k1.verify(frostKeyX, frostKeyParity, abi.encodePacked(digest), sig);
    }

    function members() external view returns (address[] memory) {
        return memberList;
    }

    /// True when at least `threshold` distinct members signed `digest` (65-byte ECDSA each, signers ascending).
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool) {
        if (threshold == 0) return false;
        uint256 count;
        address last;
        for (uint256 i = 0; i < sigs.length; i++) {
            address s = _recover(digest, sigs[i]);
            if (s <= last) return false; // ascending: no signer counted twice
            last = s;
            if (isMember[s]) count++;
        }
        return count >= threshold;
    }

    function _set(address[] memory members_, uint256 threshold_) private {
        if (members_.length > MAX_MEMBERS || threshold_ == 0 || threshold_ > members_.length) revert BadMembers();
        for (uint256 i = 0; i < memberList.length; i++) isMember[memberList[i]] = false;
        delete memberList;
        for (uint256 i = 0; i < members_.length; i++) {
            if (members_[i] == address(0) || isMember[members_[i]]) revert BadMembers();
            isMember[members_[i]] = true;
            memberList.push(members_[i]);
        }
        threshold = threshold_;
        emit MembersSet(members_, threshold_);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

interface ICosignCommittee {
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool);
    function isValidFrost(bytes32 digest, bytes calldata sig) external view returns (bool);
}

/// PQCosignCommittee (contracts/PQCosignCommittee.sol): t-of-n ML-DSA-44 co-signatures.
interface IPQCosignCommittee {
    function isValid(bytes32 digest, bytes calldata proof) external view returns (bool);
}

/// @title AgentPolicyWallet: a wallet an AI agent runs inside guardrails (testnet)
/// @notice The owner (a person) holds the funds and sets the policy; the agent
///         key can only act inside it:
///           - spend caps per period, per token (address 0 = the native coin),
///             counting native value, ERC-20 transfer amounts and approvals;
///             a token without a cap cannot be moved by the agent at all;
///           - allow-listed recipients (native sends and ERC-20 transfers) and
///             contracts (approval spenders, and contract calls); a contract
///             call runs only if its (target, selector) pair is allow-listed
///             too (setAllowedCall): deny by default, so a function that moves
///             value without passing through transfer/approve (APW-1) cannot
///             run just because its contract is allowed. Its native value is
///             capped like any native send;
///           - transfer-like functions are refused outright and cannot be
///             allow-listed: transferFrom, increaseAllowance, setApprovalForAll,
///             permit (EIP-2612, DAI, Permit2), ERC-721/1155 safeTransferFrom and
///             safeBatchTransferFrom, ERC-777 send/operatorSend/authorizeOperator,
///             ERC-677/1363 transferAndCall/transferFromAndCall/approveAndCall,
///             DAI move/pull/push, burn/burnFrom. Only transfer and approve run,
///             counted against the token's cap;
///           - above a per-token threshold ("cosignAbove"), an action either
///             waits in a timelock (queue, then executeQueued after `delay`;
///             the owner may cancel) or carries co-signatures of the runner
///             committee (CosignCommittee, set by governance) that ran Neuro
///             checks on it: k-of-n ECDSA (executeCosigned) or one FROST
///             threshold signature (executeCosignedFrost); or, when the owner
///             has set one (setPqCosign), t-of-n ML-DSA-44 co-signatures of a
///             PQCosignCommittee (executeCosignedPq), and the owner may turn
///             the two secp256k1 paths off (pqOnly). Caps apply to all;
///           - emergency freeze: the owner's account, the owner's passkey
///             (WebAuthn, P-256 precompile via WebAuthnVerifier) or the
///             owner's ML-DSA-44 key (precompile 0x…0900) stops the agent at
///             once; passkey and PQ freezes are signed messages anyone can
///             relay. Only the owner's account unfreezes.
///         Every agent action logs (modelHash, promptHash) provenance.
///         The owner itself is not limited (ownerExecute), so it can always
///         take the funds back, frozen or not.
contract AgentPolicyWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    bytes4 private constant TRANSFER = 0xa9059cbb;
    bytes4 private constant APPROVE = 0x095ea7b3;
    uint256 public constant MAX_DELAY = 30 days;

    struct Limit {
        bool set;
        uint256 perPeriod;
        uint256 cosignAbove; // amounts above this need the timelock or the committee
        uint256 spent;
        uint64 windowStart;
    }

    address public owner;
    address public agent;
    ICosignCommittee public committee;
    IPolicyWebAuthn public webauthn;
    IPQCosignCommittee public pqCommittee; // ML-DSA-44 co-signers (0 = none)
    bool public pqCosignOnly;              // true: executeCosigned / executeCosignedFrost are refused

    bytes32 public pqKeyHash;   // owner's ML-DSA-44 key (0 = none)
    uint256 public passkeyX;    // owner's passkey (0,0 = none)
    uint256 public passkeyY;
    bytes32 public rpIdHash;

    bool public frozen;
    uint256 public freezeNonce;
    uint256 public cosignNonce;
    uint256 public period;
    uint256 public delay;
    uint256 public queueCount;

    mapping(address => Limit) public limits;
    mapping(address => bool) public allowedTarget;
    mapping(address => bool) public allowedRecipient;
    mapping(bytes32 => uint64) public queuedAt; // id -> ready time (0 = none)
    mapping(address => mapping(bytes4 => bool)) public allowedCall; // target -> selector -> allowed

    event AgentAction(address indexed to, uint256 value, bytes4 selector, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path);
    event Queued(bytes32 indexed id, uint256 seq, address to, uint256 value, bytes data, bytes32 modelHash, bytes32 promptHash, uint64 readyAt);
    event Cancelled(bytes32 indexed id);
    event Frozen(address by, uint8 how);
    event Unfrozen();
    event LimitSet(address indexed token, uint256 perPeriod, uint256 cosignAbove);
    event AllowSet(address indexed who, bool target, bool recipient);
    event CallAllowSet(address indexed target, bytes4 indexed selector, bool allowed);
    event ConfigSet(address agent, address committee, uint256 period, uint256 delay);
    event EmergencyKeysSet(bytes32 pqKeyHash, uint256 passkeyX, uint256 passkeyY, bytes32 rpIdHash);
    event OwnerChanged(address owner);
    event PqCosignSet(address pqCommittee, bool pqOnly);

    error NotOwner();
    error NotAgent();
    error IsFrozen();
    error NotAllowed(address who);
    error SelectorNotAllowed(address target, bytes4 selector);
    error Forbidden(bytes4 selector);
    error NoLimit(address token);
    error OverCap(address token, uint256 spent, uint256 cap);
    error NeedsDelayOrCosign(address token, uint256 amount);
    error NotQueued();
    error NotReady();
    error BadCosign();
    error ClassicalCosignOff();
    error Expired();
    error BadEmergencyKey();
    error BadConfig();
    error CallFailed(bytes reason);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAgent() {
        if (msg.sender != agent) revert NotAgent();
        if (frozen) revert IsFrozen();
        _;
    }

    constructor(address owner_, address agent_, address committee_, address webauthn_, uint256 period_, uint256 delay_) payable {
        owner = owner_;
        webauthn = IPolicyWebAuthn(webauthn_);
        _config(agent_, committee_, period_, delay_);
    }

    receive() external payable {}

    // ------------------------------------------------------------- agent

    /// Within caps, allow-lists and below every cosignAbove: runs at once.
    function execute(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        (address token, uint256 amount) = _classify(to, value, data);
        if (amount != 0 && !limits[token].set) revert NoLimit(token);
        if (amount > limits[token].cosignAbove) revert NeedsDelayOrCosign(token, amount);
        return _run(to, value, data, token, amount, modelHash, promptHash, 0);
    }

    /// Above a threshold, path 1: wait `delay`, during which the owner sees it and may cancel or freeze.
    function queue(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes32 id)
    {
        _classify(to, value, data); // allow-lists checked now too, so a bad action fails early
        uint256 seq = ++queueCount;
        id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = uint64(block.timestamp + delay);
        queuedAt[id] = readyAt;
        emit Queued(id, seq, to, value, data, modelHash, promptHash, readyAt);
    }

    function executeQueued(uint256 seq, address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        bytes32 id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = queuedAt[id];
        if (readyAt == 0) revert NotQueued();
        if (block.timestamp < readyAt) revert NotReady();
        delete queuedAt[id];
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 1);
    }

    /// The digest committee members sign for one large action (raw 32 bytes, no EIP-191 prefix;
    /// bound to this chain, this wallet and cosignNonce). src/cosign.js computes the same.
    function cosignDigest(address to, uint256 value, bytes calldata data, bytes32 reportHash, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encode("ZETAPHY AgentCosign", block.chainid, address(this), cosignNonce, to, value,
            keccak256(data), reportHash, deadline));
    }

    /// cosignDigest at the current nonce, then consumes that nonce: the replay counter moves before the
    /// committee is called (checks-effects-interactions; a BadCosign revert undoes it).
    function _useCosignDigest(address to, uint256 value, bytes calldata data, bytes32 reportHash, uint256 deadline)
        private returns (bytes32 d)
    {
        d = cosignDigest(to, value, data, reportHash, deadline);
        cosignNonce++;
    }

    /// Above a threshold, path 2: no wait, with the committee's co-signatures
    /// (reportHash = the Neuro report the runners checked).
    function executeCosigned(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes[] calldata sigs
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (pqCosignOnly) revert ClassicalCosignOff();
        if (address(committee) == address(0) || !committee.isValid(_useCosignDigest(to, value, data, reportHash, deadline), sigs)) revert BadCosign();
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 2);
    }

    /// Path 2 with ONE FROST threshold signature of the same digest (any t of the committee's DKG
    /// group signed it in two rounds) instead of k separate ECDSA signatures.
    function executeCosignedFrost(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes calldata sig
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (pqCosignOnly) revert ClassicalCosignOff();
        if (address(committee) == address(0) || !committee.isValidFrost(_useCosignDigest(to, value, data, reportHash, deadline), sig)) revert BadCosign();
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 3);
    }

    /// Path 2 with t-of-n ML-DSA-44 co-signatures of the same digest by the owner's chosen
    /// PQCosignCommittee (proof: see that contract; src/pqcosign.js builds it). Post-quantum, unlike
    /// the ECDSA and FROST paths; costs one precompile call per signer and ~3.7 KB of calldata each.
    function executeCosignedPq(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes calldata proof
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (address(pqCommittee) == address(0) || !pqCommittee.isValid(_useCosignDigest(to, value, data, reportHash, deadline), proof)) revert BadCosign();
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 4);
    }

    // ------------------------------------------------------------- emergency freeze

    /// The 32 bytes the owner's passkey or ML-DSA key signs to freeze the wallet.
    function freezeChallenge() public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY freeze", block.chainid, address(this), freezeNonce));
    }

    function freeze() external onlyOwner {
        _freeze(0);
    }

    function freezeWithPasskey(IPolicyWebAuthn.Assertion calldata assertion) external {
        if (passkeyX == 0 && passkeyY == 0) revert BadEmergencyKey();
        if (!webauthn.verify(freezeChallenge(), assertion, passkeyX, passkeyY, rpIdHash, true)) revert BadEmergencyKey();
        _freeze(1);
    }

    function freezeWithPq(bytes calldata pqPublicKey, bytes calldata pqSig) external {
        if (pqKeyHash == bytes32(0) || keccak256(pqPublicKey) != pqKeyHash) revert BadEmergencyKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), freezeChallenge(), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadEmergencyKey();
        _freeze(2);
    }

    function unfreeze() external onlyOwner {
        frozen = false;
        emit Unfrozen();
    }

    // ------------------------------------------------------------- owner

    function ownerExecute(address to, uint256 value, bytes calldata data) external onlyOwner returns (bytes memory ret) {
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
    }

    function cancel(bytes32 id) external onlyOwner {
        if (queuedAt[id] == 0) revert NotQueued();
        delete queuedAt[id];
        emit Cancelled(id);
    }

    function setLimit(address token, uint256 perPeriod, uint256 cosignAbove) external onlyOwner {
        Limit storage l = limits[token];
        l.set = true;
        l.perPeriod = perPeriod;
        l.cosignAbove = cosignAbove;
        emit LimitSet(token, perPeriod, cosignAbove);
    }

    function setAllowed(address who, bool target, bool recipient) external onlyOwner {
        allowedTarget[who] = target;
        allowedRecipient[who] = recipient;
        emit AllowSet(who, target, recipient);
    }

    /// Allow-lists one function of one contract for the agent's contract calls. Transfer-like
    /// selectors can never be allowed (the agent moves tokens only through capped transfer / approve).
    function setAllowedCall(address target, bytes4 selector, bool allowed) external onlyOwner {
        if (allowed && (isTransferLike(selector) || selector == TRANSFER || selector == APPROVE)) revert Forbidden(selector);
        allowedCall[target][selector] = allowed;
        emit CallAllowSet(target, selector, allowed);
    }

    /// Selectors that move or authorise moving tokens other than transfer/approve (APW-1). The same list is in
    /// IntentExecutor._transferLike.
    function isTransferLike(bytes4 s) public pure returns (bool) {
        return s == 0x23b872dd // transferFrom(address,address,uint256)               ERC-20 / ERC-721
            || s == 0x39509351 // increaseAllowance(address,uint256)
            || s == 0xa22cb465 // setApprovalForAll(address,bool)                      ERC-721 / ERC-1155
            || s == 0xd505accf // permit(address,address,uint256,uint256,uint8,bytes32,bytes32) EIP-2612
            || s == 0x42842e0e // safeTransferFrom(address,address,uint256)           ERC-721
            || s == 0xb88d4fde // safeTransferFrom(address,address,uint256,bytes)     ERC-721
            || s == 0xf242432a // safeTransferFrom(address,address,uint256,uint256,bytes) ERC-1155
            || s == 0x2eb2c2d6 // safeBatchTransferFrom(address,address,uint256[],uint256[],bytes) ERC-1155
            || s == 0x9bd9bbc6 // send(address,uint256,bytes)                         ERC-777
            || s == 0x62ad1b83 // operatorSend(address,address,uint256,bytes,bytes)   ERC-777
            || s == 0x959b8c3f // authorizeOperator(address)                          ERC-777
            || s == 0x4000aea0 // transferAndCall(address,uint256,bytes)              ERC-677 / ERC-1363
            || s == 0x1296ee62 // transferAndCall(address,uint256)                    ERC-1363
            || s == 0xd8fbe994 // transferFromAndCall(address,address,uint256)        ERC-1363
            || s == 0xc1d34b89 // transferFromAndCall(address,address,uint256,bytes)  ERC-1363
            || s == 0x3177029f // approveAndCall(address,uint256)                     ERC-1363
            || s == 0xcae9ca51 // approveAndCall(address,uint256,bytes)               ERC-1363
            || s == 0xbb35783b // move(address,address,uint256)                      DAI
            || s == 0xf2d5d56b // pull(address,uint256)                              DAI
            || s == 0xb753a98c // push(address,uint256)                              DAI
            || s == 0x8fcbaf0c // permit(address,address,uint256,uint256,bool,uint8,bytes32,bytes32) DAI
            || s == 0x2b67b570 // permit(address,((address,uint160,uint48,uint48),address,uint256),bytes) Permit2
            || s == 0x2a2d80d1 // permit(address,((address,uint160,uint48,uint48)[],address,uint256),bytes) Permit2
            || s == 0x87517c45 // approve(address,address,uint160,uint48)             Permit2
            || s == 0x36c78516 // transferFrom(address,address,uint160,address)       Permit2
            || s == 0x42966c68 // burn(uint256)
            || s == 0x9dc29fac // burn(address,uint256)
            || s == 0x79cc6790; // burnFrom(address,uint256)
    }

    function setConfig(address agent_, address committee_, uint256 period_, uint256 delay_) external onlyOwner {
        _config(agent_, committee_, period_, delay_);
    }

    /// The ML-DSA-44 co-signing committee (0 removes it) and whether it is the only co-signing path:
    /// with pqOnly, the secp256k1 paths (k-of-n ECDSA, FROST) are refused, so a quantum attacker who
    /// derives the classical committee's keys cannot co-sign for this wallet.
    function setPqCosign(address pqCommittee_, bool pqOnly) external onlyOwner {
        if (pqOnly && pqCommittee_ == address(0)) revert BadConfig();
        pqCommittee = IPQCosignCommittee(pqCommittee_);
        pqCosignOnly = pqOnly;
        emit PqCosignSet(pqCommittee_, pqOnly);
    }

    function setEmergencyKeys(bytes32 pqKeyHash_, uint256 x, uint256 y, bytes32 rpIdHash_) external onlyOwner {
        pqKeyHash = pqKeyHash_;
        passkeyX = x;
        passkeyY = y;
        rpIdHash = rpIdHash_;
        emit EmergencyKeysSet(pqKeyHash_, x, y, rpIdHash_);
    }

    function setOwner(address o) external onlyOwner {
        if (o == address(0)) revert BadConfig();
        owner = o;
        emit OwnerChanged(o);
    }

    /// What is left of a token's cap in the current period.
    function remaining(address token) external view returns (uint256) {
        Limit storage l = limits[token];
        if (!l.set) return 0;
        uint256 spent = block.timestamp >= l.windowStart + period ? 0 : l.spent;
        return spent >= l.perPeriod ? 0 : l.perPeriod - spent;
    }

    // ------------------------------------------------------------- internals

    function _config(address agent_, address committee_, uint256 period_, uint256 delay_) private {
        if (period_ == 0 || delay_ > MAX_DELAY) revert BadConfig();
        agent = agent_;
        committee = ICosignCommittee(committee_);
        period = period_;
        delay = delay_;
        emit ConfigSet(agent_, committee_, period_, delay_);
    }

    function _freeze(uint8 how) private {
        frozen = true;
        freezeNonce++;
        emit Frozen(msg.sender, how);
    }

    /// Which token an action moves and how much, after the allow-list checks.
    function _classify(address to, uint256 value, bytes calldata data) private view returns (address token, uint256 amount) {
        if (data.length == 0) {
            if (!allowedRecipient[to] && !allowedTarget[to]) revert NotAllowed(to);
            return (address(0), value);
        }
        bytes4 sel = data.length >= 4 ? bytes4(data[0:4]) : bytes4(0);
        if (isTransferLike(sel)) revert Forbidden(sel);
        if (sel == TRANSFER || sel == APPROVE) {
            if (value != 0 || data.length < 68) revert Forbidden(sel);
            (address who, uint256 amt) = abi.decode(data[4:68], (address, uint256));
            if (sel == TRANSFER ? !allowedRecipient[who] : !allowedTarget[who]) revert NotAllowed(who);
            if (!limits[to].set) revert NoLimit(to);
            return (to, amt);
        }
        if (!allowedTarget[to]) revert NotAllowed(to);
        if (!allowedCall[to][sel]) revert SelectorNotAllowed(to, sel); // deny by default (APW-1)
        return (address(0), value);
    }

    function _run(address to, uint256 value, bytes calldata data, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path)
        private returns (bytes memory ret)
    {
        if (amount != 0) {
            Limit storage l = limits[token];
            if (!l.set) revert NoLimit(token);
            if (block.timestamp >= l.windowStart + period) {
                l.windowStart = uint64(block.timestamp);
                l.spent = 0;
            }
            uint256 spent = l.spent + amount;
            if (spent > l.perPeriod) revert OverCap(token, spent, l.perPeriod);
            l.spent = spent;
        }
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit AgentAction(to, value, data.length >= 4 ? bytes4(data[0:4]) : bytes4(0), token, amount, modelHash, promptHash, path);
    }
}

contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// A deterministic policy checker: given an action an agent recorded, the
/// agent's constitution (the document whose keccak256 the agent registered)
/// and optional evidence, says whether the action broke the policy, who was
/// harmed and how much. It must be a pure function of its inputs.
interface IPolicyChecker {
    struct ActionView {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        uint64 time;
    }

    function check(ActionView calldata action, bytes calldata constitution, bytes calldata evidence)
        external view returns (bool violated, address victim, uint256 damage);
}

/// @title AgentRegistry: AI agents with an identity, a bond and liability (testnet)
/// @notice An agent is registered by its operator (who answers for it) with:
///           - the EVM account it transacts from (for human/agent labels),
///           - an ML-DSA-44 public key (only its keccak256 is stored; the key
///             rides in calldata, as in QuantumWallet) that signs every action
///             it records, checked by ZETAPHY's precompile at 0x…0900,
///           - a bond in testnet ZETAPHY (at least minBond),
///           - a constitution: the keccak256 of its policy document, and an
///             optional deterministic checker contract for that policy, one
///             that governance approved (AR-2: an operator cannot pick a checker
///             that pays itself).
///         Each recorded action carries provenance: the hash of the model
///         (weights or model id + version) and of the prompt that produced it.
///
///         Claims, when an action broke the policy:
///           - checker path: anyone shows the constitution document; the
///             agent's checker decides deterministically, and the damage (at
///             most the bond) is paid to the victim the checker names, at once;
///           - committee path: a claimant posts claimDeposit and an evidence
///             hash; governance's claims committee votes; threshold "yes"
///             pays the claimed amount (at most the bond) to the claimant and
///             returns the deposit; threshold "no", or no decision within
///             VOTE_PERIOD, rejects it and the deposit goes to the operator.
///         The operator can take the bond back only UNBOND_DELAY after asking,
///         with no open claim, and only once the CLAIM_WINDOW of its last
///         action is over (AR-1): claims on an action are open for CLAIM_WINDOW
///         and the bond must still be there for all of it.
contract AgentRegistry {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant PQ_VARIANT = 44;
    uint256 public constant UNBOND_DELAY = 7 days;
    uint256 public constant CLAIM_WINDOW = 30 days;
    uint256 public constant VOTE_PERIOD = 7 days;
    uint256 public constant MAX_COMMITTEE = 32;

    struct Agent {
        address operator;
        address account;
        bytes32 pqKeyHash;
        bytes32 constitution;
        address checker;
        uint256 bond;
        uint64 unbondAt;   // 0 = not unbonding
        uint64 actions;    // per-agent sequence, in every action digest (no replay)
        uint32 openClaims;
    }

    /// agent id -> time of its last recorded action (the bond stays until its claim window is over)
    mapping(uint256 => uint64) public lastActionAt;

    struct Action {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        bytes32 constitution; // the agent's constitution when it acted
        address checker;      // and its checker
        uint64 time;
        bool slashed;         // a checker claim was paid (one payout per action)
    }

    enum ClaimState { None, Open, Upheld, Rejected }

    struct Claim {
        uint256 actionId;
        address claimant;
        uint256 amount;
        uint256 deposit;
        bytes32 evidenceHash;
        uint64 opened;
        uint16 yes;
        uint16 no;
        ClaimState state;
    }

    address public governance;
    uint256 public minBond;
    uint256 public claimDeposit;

    uint256 public agentCount;
    mapping(uint256 => Agent) public agents;
    mapping(address => uint256) public agentOfAccount; // account -> agent id (0 = none)

    uint256 public actionCount;
    mapping(uint256 => Action) public actions;

    uint256 public claimCount;
    mapping(uint256 => Claim) public claims;
    mapping(uint256 => mapping(address => bool)) public voted;

    /// Checkers governance approved (AR-2). register/update take only these (or none), and a checker claim
    /// pays only while the action's checker is still approved: revoking a bad checker stops its payouts.
    mapping(address => bool) public approvedChecker;

    mapping(address => bool) public isCommittee;
    address[] private committee;
    uint256 public committeeThreshold;

    event AgentRegistered(uint256 indexed id, address indexed operator, address indexed account, bytes32 pqKeyHash, bytes32 constitution, address checker, uint256 bond);
    event AgentUpdated(uint256 indexed id, bytes32 pqKeyHash, bytes32 constitution, address checker);
    event BondAdded(uint256 indexed id, uint256 amount, uint256 bond);
    event UnbondRequested(uint256 indexed id, uint64 at);
    event BondWithdrawn(uint256 indexed id, uint256 amount);
    event ActionRecorded(uint256 indexed agentId, uint256 indexed actionId, ActionInput action);
    event Slashed(uint256 indexed agentId, uint256 indexed actionId, address indexed to, uint256 amount);
    event ClaimFiled(uint256 indexed claimId, uint256 indexed actionId, address indexed claimant, uint256 amount, bytes32 evidenceHash);
    event ClaimVoted(uint256 indexed claimId, address indexed member, bool uphold);
    event ClaimClosed(uint256 indexed claimId, ClaimState state, uint256 paid);
    event CommitteeSet(address[] members, uint256 threshold);
    event ParamsSet(uint256 minBond, uint256 claimDeposit);
    event GovernanceChanged(address governance);
    event CheckerApproved(address indexed checker, bool approved);

    error NotGovernance();
    error NotOperator();
    error BondTooLow();
    error BadAccount();
    error AccountTaken();
    error NoAgent();
    error Inactive();
    error WrongKey();
    error BadPq();
    error Unbonding();
    error NotYet();
    error OpenClaims();
    error NoAction();
    error ClaimWindowOver();
    error BadConstitution();
    error NoChecker();
    error NotViolated();
    error AlreadySlashed();
    error BadDeposit();
    error NotCommittee();
    error AlreadyVoted();
    error ClaimNotOpen();
    error BadCommittee();
    error TransferFailed();
    error CheckerNotApproved();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, uint256 minBond_, uint256 claimDeposit_) {
        governance = governance_;
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    // ------------------------------------------------------------- agents

    function register(address account, bytes32 pqKeyHash, bytes32 constitution, address checker) external payable returns (uint256 id) {
        if (msg.value < minBond) revert BondTooLow();
        if (account == address(0) || pqKeyHash == bytes32(0)) revert BadAccount();
        if (agentOfAccount[account] != 0) revert AccountTaken();
        _checkerOk(checker);
        id = ++agentCount;
        agents[id] = Agent({operator: msg.sender, account: account, pqKeyHash: pqKeyHash, constitution: constitution,
            checker: checker, bond: msg.value, unbondAt: 0, actions: 0, openClaims: 0});
        agentOfAccount[account] = id;
        emit AgentRegistered(id, msg.sender, account, pqKeyHash, constitution, checker, msg.value);
    }

    /// New key, constitution or checker. Past actions keep the constitution
    /// and checker they were recorded under.
    function update(uint256 id, bytes32 pqKeyHash, bytes32 constitution, address checker) external {
        Agent storage a = _operated(id);
        if (pqKeyHash == bytes32(0)) revert BadAccount();
        _checkerOk(checker);
        a.pqKeyHash = pqKeyHash;
        a.constitution = constitution;
        a.checker = checker;
        emit AgentUpdated(id, pqKeyHash, constitution, checker);
    }

    function addBond(uint256 id) external payable {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        a.bond += msg.value;
        emit BondAdded(id, msg.value, a.bond);
    }

    /// Stops new actions; the bond can be withdrawn UNBOND_DELAY later.
    function requestUnbond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt != 0) revert Unbonding();
        a.unbondAt = uint64(block.timestamp + UNBOND_DELAY);
        emit UnbondRequested(id, a.unbondAt);
    }

    /// When withdrawBond may run (0 = not unbonding): UNBOND_DELAY after the request, and after the claim
    /// window of the agent's last action.
    function withdrawableAt(uint256 id) public view returns (uint256) {
        Agent storage a = agents[id];
        if (a.unbondAt == 0) return 0;
        uint256 claimsOver = lastActionAt[id] == 0 ? 0 : uint256(lastActionAt[id]) + CLAIM_WINDOW + 1;
        return claimsOver > a.unbondAt ? claimsOver : a.unbondAt;
    }

    function withdrawBond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt == 0 || block.timestamp < withdrawableAt(id)) revert NotYet();
        if (a.openClaims != 0) revert OpenClaims();
        uint256 amount = a.bond;
        a.bond = 0;
        delete agentOfAccount[a.account];
        emit BondWithdrawn(id, amount);
        _pay(a.operator, amount);
    }

    /// Active = bonded at least minBond and not unbonding.
    function isActive(uint256 id) public view returns (bool) {
        Agent storage a = agents[id];
        return a.operator != address(0) && a.unbondAt == 0 && a.bond >= minBond;
    }

    /// For label readers: the active agent an account belongs to (0 = none).
    function activeAgentOf(address account) external view returns (uint256) {
        uint256 id = agentOfAccount[account];
        return id != 0 && isActive(id) ? id : 0;
    }

    // ------------------------------------------------------------- actions

    /// What an agent did (or is about to do), with its provenance.
    struct ActionInput {
        address target;
        uint256 value;
        bytes32 dataHash;   // keccak256 of the calldata (or of an off-chain action's description)
        bytes32 modelHash;  // keccak256 of the model weights, or of "provider/model-id@version"
        bytes32 promptHash; // keccak256 of the full prompt (system + user) that produced the action
    }

    /// The 32 bytes the agent's ML-DSA-44 key signs for its next action.
    function actionDigest(uint256 id, ActionInput calldata x) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY AgentAction", block.chainid, address(this), id, agents[id].actions,
            x.target, x.value, x.dataHash, x.modelHash, x.promptHash));
    }

    /// Records one action with its provenance. Anyone may submit it (a relay);
    /// only the agent's ML-DSA key can have signed it.
    function recordAction(uint256 id, ActionInput calldata x, bytes calldata pqPublicKey, bytes calldata pqSig)
        external returns (uint256 actionId)
    {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (!isActive(id)) revert Inactive();
        if (keccak256(pqPublicKey) != a.pqKeyHash) revert WrongKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(PQ_VARIANT, actionDigest(id, x), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadPq();
        a.actions++;
        actionId = ++actionCount;
        Action storage r = actions[actionId];
        r.agentId = id;
        r.target = x.target;
        r.value = x.value;
        r.dataHash = x.dataHash;
        r.modelHash = x.modelHash;
        r.promptHash = x.promptHash;
        r.constitution = a.constitution;
        r.checker = a.checker;
        r.time = uint64(block.timestamp);
        lastActionAt[id] = uint64(block.timestamp);
        emit ActionRecorded(id, actionId, x);
    }

    // ------------------------------------------------------------- claims: deterministic checker

    /// Shows the constitution an action was recorded under; if the agent's
    /// checker finds a violation, the damage (at most the bond) goes to the
    /// victim the checker names. Anyone may call it; one payout per action.
    function claimByChecker(uint256 actionId, bytes calldata constitution, bytes calldata evidence) external returns (uint256 paid) {
        Action storage act = _claimable(actionId);
        if (act.checker == address(0)) revert NoChecker();
        if (!approvedChecker[act.checker]) revert CheckerNotApproved();
        if (act.slashed) revert AlreadySlashed();
        if (keccak256(constitution) != act.constitution) revert BadConstitution();
        IPolicyChecker.ActionView memory v = IPolicyChecker.ActionView({agentId: act.agentId, target: act.target,
            value: act.value, dataHash: act.dataHash, modelHash: act.modelHash, promptHash: act.promptHash, time: act.time});
        (bool violated, address victim, uint256 damage) = IPolicyChecker(act.checker).check(v, constitution, evidence);
        if (!violated || victim == address(0) || damage == 0) revert NotViolated();
        act.slashed = true;
        paid = _slash(act.agentId, actionId, victim, damage);
    }

    // ------------------------------------------------------------- claims: committee vote

    function fileClaim(uint256 actionId, uint256 amount, bytes32 evidenceHash) external payable returns (uint256 claimId) {
        Action storage act = _claimable(actionId);
        if (msg.value != claimDeposit) revert BadDeposit();
        claimId = ++claimCount;
        claims[claimId] = Claim({actionId: actionId, claimant: msg.sender, amount: amount, deposit: msg.value,
            evidenceHash: evidenceHash, opened: uint64(block.timestamp), yes: 0, no: 0, state: ClaimState.Open});
        agents[act.agentId].openClaims++;
        emit ClaimFiled(claimId, actionId, msg.sender, amount, evidenceHash);
    }

    function vote(uint256 claimId, bool uphold) external {
        if (!isCommittee[msg.sender]) revert NotCommittee();
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open || block.timestamp > c.opened + VOTE_PERIOD) revert ClaimNotOpen();
        if (voted[claimId][msg.sender]) revert AlreadyVoted();
        voted[claimId][msg.sender] = true;
        if (uphold) c.yes++; else c.no++;
        emit ClaimVoted(claimId, msg.sender, uphold);
        if (c.yes >= committeeThreshold) _close(claimId, true);
        else if (c.no >= committeeThreshold) _close(claimId, false);
    }

    /// After VOTE_PERIOD without a decision, anyone may close the claim as rejected.
    function expireClaim(uint256 claimId) external {
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open) revert ClaimNotOpen();
        if (block.timestamp <= c.opened + VOTE_PERIOD) revert NotYet();
        _close(claimId, false);
    }

    // ------------------------------------------------------------- governance

    function setCommittee(address[] calldata members, uint256 threshold) external onlyGovernance {
        if (members.length > MAX_COMMITTEE || threshold == 0 || threshold > members.length) revert BadCommittee();
        for (uint256 i = 0; i < committee.length; i++) isCommittee[committee[i]] = false;
        delete committee;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == address(0) || isCommittee[members[i]]) revert BadCommittee();
            isCommittee[members[i]] = true;
            committee.push(members[i]);
        }
        committeeThreshold = threshold;
        emit CommitteeSet(members, threshold);
    }

    function committeeMembers() external view returns (address[] memory) {
        return committee;
    }

    function setParams(uint256 minBond_, uint256 claimDeposit_) external onlyGovernance {
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    /// Approves (or revokes) a deterministic checker. Revoking stops checker claims on every action recorded
    /// under it; the committee path stays open for those actions.
    function setChecker(address checker, bool approved) external onlyGovernance {
        if (checker == address(0)) revert NoChecker();
        approvedChecker[checker] = approved;
        emit CheckerApproved(checker, approved);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _operated(uint256 id) private view returns (Agent storage a) {
        a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (a.operator != msg.sender) revert NotOperator();
    }

    function _checkerOk(address checker) private view {
        if (checker != address(0) && !approvedChecker[checker]) revert CheckerNotApproved();
    }

    function _claimable(uint256 actionId) private view returns (Action storage act) {
        act = actions[actionId];
        if (act.agentId == 0) revert NoAction();
        if (block.timestamp > act.time + CLAIM_WINDOW) revert ClaimWindowOver();
        if (agents[act.agentId].bond == 0) revert Inactive(); // bond withdrawn or slashed away: nothing to claim
    }

    function _close(uint256 claimId, bool upheld) private {
        Claim storage c = claims[claimId];
        uint256 agentId = actions[c.actionId].agentId;
        Agent storage a = agents[agentId];
        a.openClaims--;
        uint256 paid;
        if (upheld) {
            c.state = ClaimState.Upheld;
            paid = _slash(agentId, c.actionId, c.claimant, c.amount);
            _pay(c.claimant, c.deposit);
        } else {
            c.state = ClaimState.Rejected;
            _pay(a.operator, c.deposit);
        }
        emit ClaimClosed(claimId, c.state, paid);
    }

    function _slash(uint256 agentId, uint256 actionId, address to, uint256 amount) private returns (uint256 paid) {
        Agent storage a = agents[agentId];
        paid = amount < a.bond ? amount : a.bond;
        a.bond -= paid;
        emit Slashed(agentId, actionId, to, paid);
        _pay(to, paid);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title ConstitutionChecker: a deterministic checker for simple agent policies
/// @notice The constitution document is
///           abi.encode(address principal, uint256 maxValuePerAction,
///                      address[] allowedTargets, bytes32[] allowedModels)
///         and an action violates it when its value is above the cap, its
///         target is not allowed (an empty list allows none), or its model is
///         not allowed (an empty list allows any). The victim is the
///         principal; the damage is the action's value (the part above the
///         cap, for a cap violation).
contract ConstitutionChecker is IPolicyChecker {
    function check(ActionView calldata action, bytes calldata constitution, bytes calldata)
        external pure returns (bool violated, address victim, uint256 damage)
    {
        (address principal, uint256 maxValue, address[] memory targets, bytes32[] memory models) =
            abi.decode(constitution, (address, uint256, address[], bytes32[]));
        if (!_allowed(action.target, action.modelHash, targets, models)) return (true, principal, action.value);
        if (action.value > maxValue) return (true, principal, action.value - maxValue);
        return (false, address(0), 0);
    }

    function _allowed(address target, bytes32 model, address[] memory targets, bytes32[] memory models) private pure returns (bool) {
        bool targetOk;
        for (uint256 i = 0; i < targets.length; i++) if (targets[i] == target) targetOk = true;
        bool modelOk = models.length == 0;
        for (uint256 i = 0; i < models.length; i++) if (models[i] == model) modelOk = true;
        return targetOk && modelOk;
    }
}

