// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// What AuditCertificate reads from AuditNetwork (AuditNetwork.Request, same layout).
interface IACNetwork {
    struct Request {
        address sponsor;
        uint64 chainId;
        uint64 createdAt;
        uint64 contestEnd;
        uint8 tier;
        bool naDeclared;
        bool settled;
        bool reclaimed;
        bool certified;
        address target;
        uint32 minContest;
        uint16 minAuditors;
        uint32 reports;
        uint32 rejected;
        uint32 undecided;
        uint32 critHigh;
        uint32 openAppeals;
        uint32 totalWeight;
        uint64 certExpiry;
        uint64 prev;
        bytes32 codeHash;
        bytes32 sourceHash;
        bytes32 naReason;
        uint128 pool;
        uint128 reserve;
        uint128 reportSlash;
        bytes32 uriHash;
    }

    function getRequest(uint256 id) external view returns (Request memory);
    function carriedOf(uint256 id) external view returns (uint64[] memory);
    function markCertified(uint256 id, uint64 expiry) external;
}

/// What the judges decided (AuditJudges).
interface IACJudges {
    function naAccepted(uint256 id) external view returns (bool);
    function fixConfirmed(uint256 id, uint256 findingId) external view returns (bool);
}

/// AuditRunners.result (AuditRunners.Result, same layout).
interface IACRunners {
    struct Result {
        bytes32 resultHash;
        uint32 critHigh;
        uint32 invFailed;
        uint32 invNotRun;
        uint16 mutationBps;
    }

    function result(uint256 id) external view returns (bool agreed, Result memory r);
}

/// @title AuditCertificate: "passed the ZETAPHY audit process at codeHash X on date Y"
/// @notice Anyone calls `certify(requestId)`; it is issued ONLY if ALL of these hold (else it reverts
///         with the first failing reason, see `check`):
///           1. the request is settled (contest, reveal, judging and appeal windows over, no appeal open);
///           2. the automated tier agreed (2 of 3 runners, same result) with zero open critical/high;
///           3. no invariant suite failed, and either all ran or the sponsor's "not applicable" was
///              accepted by the judges;
///           4. the contest ran at least its minimum (governance minimum + the tier's extra) and
///              at least `minAuditors` distinct bonded auditors revealed a report the judges did not reject;
///           5. no valid critical/high finding, no undecided finding, and every critical/high finding of
///              the version it fixes was confirmed fixed by the judges (a fix is a new codeHash and a new
///              request through the whole process);
///           6. on ZETAPHY, the target's EXTCODEHASH is still the audited codeHash; the codeHash was never
///              revoked; the sponsor did not take the post-certificate reserve back.
///         Levels: Gold / Silver / Bronze by distinct auditors, contest length and mutation score
///         (governance thresholds, bounded). A certificate expires (`validity`, 30..365 days) and is
///         revoked at once when a post-certificate finding of critical/high severity is judged valid
///         (AuditNetwork calls `revokeFor`); revocation covers the codeHash everywhere.
///         `isCertified(chainId, target)` re-checks EXTCODEHASH on ZETAPHY at every call, so a proxy
///         upgrade or a redeploy fails at once. For another chain the codeHash is recorded and the
///         reader (or NeuroOracle there, which can check EXTCODEHASH locally) compares it.
///         A certificate is NOT a guarantee that the code is safe.
contract AuditCertificate {
    uint8 public constant BRONZE = 1;
    uint8 public constant SILVER = 2;
    uint8 public constant GOLD = 3;
    uint8 public constant KIND_CERT = 3;  // NeuroOracle message kind (1 threats, 2 verdicts)

    // reasons `check` returns (0 = certifiable)
    uint8 public constant R_NOT_SETTLED = 1;
    uint8 public constant R_NO_AGREEMENT = 2;
    uint8 public constant R_AUTO_CRIT_HIGH = 3;
    uint8 public constant R_INVARIANT_FAILED = 4;
    uint8 public constant R_INVARIANT_NOT_RUN = 5;
    uint8 public constant R_CONTEST_SHORT = 6;
    uint8 public constant R_FEW_AUDITORS = 7;
    uint8 public constant R_CRIT_HIGH = 8;
    uint8 public constant R_UNDECIDED = 9;
    uint8 public constant R_APPEAL_OPEN = 10;
    uint8 public constant R_FIX_UNCONFIRMED = 11;
    uint8 public constant R_RECLAIMED = 12;
    uint8 public constant R_CODE_CHANGED = 13;
    uint8 public constant R_CODE_REVOKED = 14;
    uint8 public constant R_ALREADY = 15;

    uint32 public constant MIN_CONTEST_FLOOR = 3 days;

    struct Levels {
        uint32 validity;            // [30 days, 365 days]
        uint16 silverAuditors;      // [3, 100]
        uint16 goldAuditors;        // [silverAuditors, 200]
        uint32 silverContest;       // [7 days, 90 days]
        uint32 goldContest;         // [silverContest, 180 days]
        uint16 silverMutationBps;   // [5000, 10000]
        uint16 goldMutationBps;     // [silverMutationBps, 10000]
    }

    struct Cert {
        uint256 requestId;
        uint64 chainId;
        address target;
        bytes32 codeHash;
        bytes32 reportHash;         // the agreed automated-tier result hash (REPORT.md + tools + Neuro)
        bytes32 sourceHash;
        uint8 level;
        uint16 auditors;
        uint16 mutationBps;
        uint64 issuedAt;
        uint64 expiresAt;
        uint64 revokedAt;
        uint256 revokedBy;          // the finding id plus one (0: not revoked)
    }

    IACNetwork public immutable network;
    IACRunners public immutable runners;
    IACJudges public immutable judges;
    address public governance;      // the ZetaphyTimelock
    Levels public levels;

    mapping(bytes32 => Cert) private _certs;             // keccak256(chainId, target) -> newest certificate
    mapping(uint256 => bool) public issued;              // request id -> certified once
    mapping(bytes32 => uint256) public revokedCode;      // codeHash -> finding id + 1 that revoked it
    bytes32[] public keys;

    event CertificateIssued(uint256 indexed requestId, uint64 indexed chainId, address indexed target, bytes32 codeHash, bytes32 reportHash, uint8 level, uint64 expiresAt);
    event CertificateRevoked(uint256 indexed requestId, bytes32 indexed codeHash, uint256 findingId);
    event LevelsSet();
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotNetwork();
    error BadParams();
    error NotCertifiable(uint8 reason);

    constructor(IACNetwork network_, IACRunners runners_, IACJudges judges_, address governance_, Levels memory l) {
        require(address(network_) != address(0) && address(runners_) != address(0) && address(judges_) != address(0) && governance_ != address(0), "zero");
        network = network_;
        runners = runners_;
        judges = judges_;
        governance = governance_;
        _setLevels(l);
    }

    // ---------------------------------------------------------------- certify

    /// 0 when request `id` can be certified now, else the first failing reason (R_*).
    function check(uint256 id) public view returns (uint8) {
        if (issued[id]) return R_ALREADY;
        IACNetwork.Request memory s = network.getRequest(id);
        if (!s.settled) return R_NOT_SETTLED;
        (bool agreed, IACRunners.Result memory r) = runners.result(id);
        if (!agreed) return R_NO_AGREEMENT;
        if (r.critHigh != 0) return R_AUTO_CRIT_HIGH;
        if (r.invFailed != 0) return R_INVARIANT_FAILED;
        if (r.invNotRun != 0 && !(s.naDeclared && judges.naAccepted(id))) return R_INVARIANT_NOT_RUN;
        uint256 ran = uint256(s.contestEnd) - s.createdAt;
        if (ran < s.minContest || ran < MIN_CONTEST_FLOOR) return R_CONTEST_SHORT;
        if (s.reports - s.rejected < s.minAuditors) return R_FEW_AUDITORS;
        if (s.critHigh != 0) return R_CRIT_HIGH;
        if (s.undecided != 0) return R_UNDECIDED;
        if (s.openAppeals != 0) return R_APPEAL_OPEN;
        uint64[] memory carried = network.carriedOf(id);
        for (uint256 i = 0; i < carried.length; i++) if (!judges.fixConfirmed(id, carried[i])) return R_FIX_UNCONFIRMED;
        if (s.reclaimed) return R_RECLAIMED;
        if (s.chainId == block.chainid && s.target.codehash != s.codeHash) return R_CODE_CHANGED;
        if (revokedCode[s.codeHash] != 0) return R_CODE_REVOKED;
        return 0;
    }

    function certify(uint256 id) external returns (uint8 level) {
        uint8 why = check(id);
        if (why != 0) revert NotCertifiable(why);
        IACNetwork.Request memory s = network.getRequest(id);
        (, IACRunners.Result memory r) = runners.result(id);
        uint32 auditors = s.reports - s.rejected;
        level = levelOf(auditors, uint256(s.contestEnd) - s.createdAt, r.mutationBps);
        bytes32 k = keyOf(s.chainId, s.target);
        if (_certs[k].issuedAt == 0) keys.push(k);
        Cert storage c = _certs[k];
        c.requestId = id;
        c.chainId = s.chainId;
        c.target = s.target;
        c.codeHash = s.codeHash;
        c.reportHash = r.resultHash;
        c.sourceHash = s.sourceHash;
        c.level = level;
        c.auditors = uint16(auditors > type(uint16).max ? type(uint16).max : auditors);
        c.mutationBps = r.mutationBps;
        c.issuedAt = uint64(block.timestamp);
        c.expiresAt = uint64(block.timestamp + levels.validity);
        c.revokedAt = 0;
        c.revokedBy = 0;
        issued[id] = true;
        network.markCertified(id, c.expiresAt);
        emit CertificateIssued(id, s.chainId, s.target, s.codeHash, r.resultHash, level, c.expiresAt);
    }

    function levelOf(uint256 auditors, uint256 contest, uint16 mutationBps) public view returns (uint8) {
        Levels memory l = levels;
        if (auditors >= l.goldAuditors && contest >= l.goldContest && mutationBps >= l.goldMutationBps) return GOLD;
        if (auditors >= l.silverAuditors && contest >= l.silverContest && mutationBps >= l.silverMutationBps) return SILVER;
        return BRONZE;
    }

    /// AuditNetwork: a post-certificate critical/high finding was judged valid against request `id`'s code.
    function revokeFor(uint256 id, uint256 findingId) external {
        if (msg.sender != address(network)) revert NotNetwork();
        IACNetwork.Request memory s = network.getRequest(id);
        if (revokedCode[s.codeHash] == 0) revokedCode[s.codeHash] = findingId + 1;
        Cert storage c = _certs[keyOf(s.chainId, s.target)];
        if (c.requestId == id && c.issuedAt != 0 && c.revokedAt == 0) {
            c.revokedAt = uint64(block.timestamp);
            c.revokedBy = findingId + 1;
        }
        emit CertificateRevoked(id, s.codeHash, findingId);
    }

    // ---------------------------------------------------------------- reads

    function keyOf(uint64 chainId, address target) public pure returns (bytes32) {
        return keccak256(abi.encode(chainId, target));
    }

    function _valid(Cert storage c) internal view returns (bool) {
        if (c.issuedAt == 0 || c.revokedAt != 0 || revokedCode[c.codeHash] != 0 || block.timestamp >= c.expiresAt) return false;
        if (c.chainId == block.chainid && c.target.codehash != c.codeHash) return false; // upgraded / redeployed / destroyed
        return true;
    }

    /// True only while the newest certificate of (chainId, target) is unexpired, unrevoked and, on
    /// ZETAPHY, the target still runs exactly the certified code.
    function isCertified(uint64 chainId, address target) external view returns (bool) {
        return _valid(_certs[keyOf(chainId, target)]);
    }

    /// The newest certificate of (chainId, target) and whether it holds right now.
    function certificate(uint64 chainId, address target) external view returns (Cert memory c, bool valid) {
        Cert storage s = _certs[keyOf(chainId, target)];
        return (s, _valid(s));
    }

    function count() external view returns (uint256) {
        return keys.length;
    }

    /// The NeuroOracle message for (chainId, target): kind 3, this chain's id, then the certificate
    /// (all static fields, so it decodes as a struct on the other side). NeuroOracleSender.pushCertificate sends it.
    function certificateBody(uint64 chainId, address target) external view returns (bytes memory) {
        Cert storage c = _certs[keyOf(chainId, target)];
        if (c.issuedAt == 0) revert NotCertifiable(R_NOT_SETTLED);
        bool revoked = c.revokedAt != 0 || revokedCode[c.codeHash] != 0;
        return abi.encode(KIND_CERT, block.chainid, c.chainId, c.target, c.codeHash, c.reportHash, c.level, c.issuedAt, c.expiresAt, revoked, c.requestId);
    }

    // ---------------------------------------------------------------- governance

    function setLevels(Levels calldata l) external {
        if (msg.sender != governance) revert NotGovernance();
        _setLevels(l);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    function _setLevels(Levels memory l) internal {
        if (l.validity < 30 days || l.validity > 365 days) revert BadParams();
        if (l.silverAuditors < 3 || l.silverAuditors > 100 || l.goldAuditors < l.silverAuditors || l.goldAuditors > 200) revert BadParams();
        if (l.silverContest < 7 days || l.silverContest > 90 days || l.goldContest < l.silverContest || l.goldContest > 180 days) revert BadParams();
        if (l.silverMutationBps < 5000 || l.silverMutationBps > 10_000 || l.goldMutationBps < l.silverMutationBps || l.goldMutationBps > 10_000) revert BadParams();
        levels = l;
        emit LevelsSet();
    }
}

contracts/AuditJudges.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of AuditNetwork the judges read and write.
interface IAJNetwork {
    function core(uint256 id) external view returns (address sponsor, uint64 contestEnd, uint256 revealEnd, uint256 judgeEnd, bool naDeclared, bool settled);
    function findingCore(uint256 fid) external view returns (uint64 req, uint8 st, bool late, uint256 judgeBy);
    function timing() external view returns (uint32 judgeWindow, uint32 appealWindow, uint32 appealTimeout);
    function involved(uint256 id, address who) external view returns (bool);
    function reportHash(uint256 id, address auditor) external view returns (bytes32);
    function isCarried(uint256 id, uint256 fid) external view returns (bool);
    function checkGroup(uint256 fid, uint8 sev, uint256 group) external view;
    function decide(uint256 fid, bool valid, uint8 sev, uint256 group) external;
    function rejectReport(uint256 id, address auditor) external;
    function setAppeal(uint256 fid, bool open) external;
    function treasury() external view returns (address);
}

interface IAJReputation {
    function scoreOf(address worker) external view returns (uint256);
}

/// @title AuditJudges: the judging committee of AuditNetwork
/// @notice Judges post a bond (`judgeBond`) and need a WorkerReputation score of at least `judgeMinScore`
///         (a track record from useful work, bug bounties and NeuroJobs); at most `maxJudges` sit at once
///         and governance (the timelock) can remove or slash one. They decide, per request:
///           - every revealed finding: invalid, or valid with a severity and its duplicate group;
///           - participation reports: accepted, or rejected as empty / plagiarised / spam;
///           - the sponsor's "invariant suites do not apply" declaration;
///           - for a fix, whether each carried critical/high finding of the old version is fixed.
///         An item is decided when `quorum()` judges cast the SAME outcome: at least `judgeQuorum` (3 or
///         more) AND a majority of all active judges, so a minority cannot decide anything, whatever it
///         votes. A judge never votes on a request it sponsored or audited, and votes once per item.
///         Decided findings can be appealed (bond `appealBond`) until AuditNetwork's appeal window ends;
///         governance resolves the appeal (the bond comes back if it changed the outcome, else it goes to
///         the treasury) or, after `appealTimeout`, the decision stands and the bond comes back.
///         The judges' part of each fee is shared by the judges who voted with each contest decision.
contract AuditJudges {
    bytes32 internal constant YES = keccak256(abi.encode(true));
    bytes32 internal constant NO = keccak256(abi.encode(false));

    uint8 public constant K_FINDING = 1;
    uint8 public constant K_REPORT = 2;
    uint8 public constant K_NA = 3;
    uint8 public constant K_FIX = 4;
    uint8 internal constant F_REVEALED = 2;
    uint8 internal constant F_VALID = 3;
    uint8 internal constant F_INVALID = 4;

    struct Params {
        uint16 judgeQuorum;         // [3, 50]
        uint16 maxJudges;           // [judgeQuorum, 255]
        uint16 judgeMinScore;       // [0, 1000]
        uint32 unbondDelay;         // [1 day, 60 days]
        uint128 judgeBond;          // (0, 10000 ether]
        uint128 appealBond;         // (0, 1000 ether]
    }

    struct Judge {
        uint128 bond;
        uint64 lockedUntil;
        uint64 unbondAt;            // 0: active
        bool counted;
        bool blocked;
    }

    struct Appeal {
        address by;
        uint64 at;
        uint128 bond;
    }

    IAJNetwork public immutable network;
    IAJReputation public immutable reputation;
    address public governance;
    Params public params;

    mapping(address => Judge) public judges;
    uint256 public judgeCount;

    mapping(bytes32 => mapping(bytes32 => uint16)) public tally;
    mapping(bytes32 => mapping(address => bytes32)) public votedFor;
    mapping(bytes32 => bytes32) public decided;
    mapping(bytes32 => uint64) public itemReq;            // request id + 1 for items that pay judges
    mapping(bytes32 => mapping(address => bool)) public judgeClaimed;
    mapping(uint256 => uint128) public pot;               // the judges' part of the fee
    mapping(uint256 => uint32) public credits;            // winning votes on paid items
    mapping(uint256 => bool) public potReclaimed;
    mapping(uint256 => Appeal) public appeals;            // by finding id
    mapping(address => uint256) public owed;
    uint256 private _lock = 1;

    event Opened(uint256 indexed id, uint256 pot);
    event Bonded(address indexed judge, uint256 bond);
    event UnbondRequested(address indexed judge, uint64 at);
    event BondWithdrawn(address indexed judge, uint256 amount);
    event Voted(bytes32 indexed item, address indexed judge, bytes32 outcome);
    event Decided(bytes32 indexed item, uint256 indexed id, bytes32 outcome);
    event Appealed(uint256 indexed findingId, address indexed by);
    event AppealResolved(uint256 indexed findingId, bool changed, bool expired);
    event JudgeBlocked(address indexed judge, bool blocked);
    event JudgeSlashed(address indexed judge, uint256 amount);
    event Paid(address indexed to, uint256 amount, uint256 indexed id);
    event Withdrawn(address indexed to, uint256 amount);
    event ParamsSet();
    event GovernanceSet(address governance);

    error NotNetwork();
    error NotGovernance();
    error NotJudge();
    error BadParams();
    error BadValue();
    error Conflict();
    error Closed();
    error TooEarly();
    error TooMany();
    error AlreadyIn();
    error Locked();
    error Nothing();
    error Reentrant();
    error BadOutcome();         // from AuditNetwork.checkGroup (bubbles up)

    constructor(IAJNetwork network_, IAJReputation reputation_, address governance_, Params memory p) {
        require(address(network_) != address(0) && governance_ != address(0), "zero");
        network = network_;
        reputation = reputation_;
        governance = governance_;
        _setParams(p);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier nonReentrant() {
        if (_lock != 1) revert Reentrant();
        _lock = 2;
        _;
        _lock = 1;
    }

    /// AuditNetwork hands over the judges' part of a new request's fee.
    function open(uint256 id) external payable {
        if (msg.sender != address(network)) revert NotNetwork();
        pot[id] += uint128(msg.value);
        emit Opened(id, msg.value);
    }

    // ================================================================ the committee

    function bond() external payable {
        Judge storage j = judges[msg.sender];
        if (msg.value == 0) revert BadValue();
        if (j.unbondAt != 0) revert Locked();
        if (j.blocked) revert NotJudge();
        if (address(reputation) != address(0) && reputation.scoreOf(msg.sender) < params.judgeMinScore) revert NotJudge();
        j.bond += uint128(msg.value);
        _recount(j);
        emit Bonded(msg.sender, j.bond);
    }

    function requestUnbond() external {
        Judge storage j = judges[msg.sender];
        if (j.bond == 0 || j.unbondAt != 0) revert Nothing();
        uint64 at = uint64(block.timestamp + params.unbondDelay);
        if (j.lockedUntil > at) at = j.lockedUntil;
        j.unbondAt = at;
        _recount(j);
        emit UnbondRequested(msg.sender, at);
    }

    function withdrawBond() external nonReentrant {
        Judge storage j = judges[msg.sender];
        if (j.unbondAt == 0 || block.timestamp < j.unbondAt || block.timestamp < j.lockedUntil) revert TooEarly();
        uint256 a = j.bond;
        j.bond = 0;
        j.unbondAt = 0;
        _send(msg.sender, a);
        emit BondWithdrawn(msg.sender, a);
    }

    function _recount(Judge storage j) internal {
        bool active = j.unbondAt == 0 && !j.blocked && j.bond >= params.judgeBond;
        if (active && !j.counted) {
            if (judgeCount >= params.maxJudges) revert TooMany();
            j.counted = true;
            judgeCount++;
        } else if (!active && j.counted) {
            j.counted = false;
            judgeCount--;
        }
    }

    function isJudge(address who) external view returns (bool) {
        return judges[who].counted;
    }

    /// Votes a decision needs: judgeQuorum, and never fewer than a majority of the active judges.
    function quorum() public view returns (uint256) {
        uint256 q = params.judgeQuorum;
        uint256 maj = judgeCount / 2 + 1;
        return maj > q ? maj : q;
    }

    // ================================================================ votes

    function itemKey(uint8 kind, uint256 a, uint256 b) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.audit.item", kind, a, b));
    }

    function findingOutcome(bool valid, uint8 sev, uint256 group) public pure returns (bytes32) {
        return keccak256(abi.encode(valid, sev, group));
    }

    /// A revealed finding: invalid, or valid with a severity (1 info .. 5 critical) and its group (its own
    /// id for an original, else an earlier finding of the same request already decided valid as original).
    function voteFinding(uint256 fid, bool valid, uint8 sev, uint256 group) external {
        (uint64 id, uint8 st, bool late, uint256 judgeBy) = network.findingCore(fid);
        if (st != F_REVEALED || block.timestamp >= judgeBy) revert Closed();
        if (valid) network.checkGroup(fid, sev, group);
        else { sev = 0; group = fid; }
        if (_cast(itemKey(K_FINDING, fid, 0), findingOutcome(valid, sev, group), id, !late)) network.decide(fid, valid, sev, group);
    }

    function voteReport(uint256 id, address auditor, bool accept) external {
        (, , , uint256 judgeEnd, , ) = network.core(id);
        if (network.reportHash(id, auditor) == bytes32(0) || block.timestamp >= judgeEnd) revert Closed();
        if (_cast(itemKey(K_REPORT, id, uint256(uint160(auditor))), accept ? YES : NO, id, true) && !accept) network.rejectReport(id, auditor);
    }

    function voteNotApplicable(uint256 id, bool accept) external {
        (, , , uint256 judgeEnd, bool na, ) = network.core(id);
        if (!na || block.timestamp >= judgeEnd) revert Closed();
        _cast(itemKey(K_NA, id, 0), accept ? YES : NO, id, true);
    }

    /// For a fix: is the carried critical/high finding `fid` of the old version fixed in request `id`?
    function voteFixed(uint256 id, uint256 fid, bool fixed_) external {
        (, uint64 contestEnd, , uint256 judgeEnd, , ) = network.core(id);
        if (block.timestamp < contestEnd || block.timestamp >= judgeEnd || !network.isCarried(id, fid)) revert Closed();
        _cast(itemKey(K_FIX, id, fid), fixed_ ? YES : NO, id, true);
    }

    /// Records a judge's vote; true when it made the decision. `paid`: counts for the judges' pot.
    function _cast(bytes32 item, bytes32 outcome, uint256 id, bool paid) internal returns (bool) {
        Judge storage j = judges[msg.sender];
        if (!j.counted) revert NotJudge();
        if (network.involved(id, msg.sender)) revert Conflict();
        if (decided[item] != bytes32(0)) revert Closed();
        if (votedFor[item][msg.sender] != bytes32(0)) revert AlreadyIn();
        votedFor[item][msg.sender] = outcome;
        if (paid) itemReq[item] = uint64(id + 1);
        uint16 t = ++tally[item][outcome];
        (, uint32 aw, uint32 at) = network.timing();
        uint256 until = block.timestamp + aw + at;
        if (until > j.lockedUntil) j.lockedUntil = uint64(until);
        emit Voted(item, msg.sender, outcome);
        if (t < quorum()) return false;
        decided[item] = outcome;
        if (paid) credits[id] += t;
        emit Decided(item, id, outcome);
        return true;
    }

    function naAccepted(uint256 id) external view returns (bool) {
        return decided[itemKey(K_NA, id, 0)] == YES;
    }

    function fixConfirmed(uint256 id, uint256 fid) external view returns (bool) {
        return decided[itemKey(K_FIX, id, fid)] == YES;
    }

    // ================================================================ appeals

    /// Anyone appeals a decided finding before AuditNetwork's appeal window for it ends.
    function appeal(uint256 fid) external payable {
        if (msg.value != params.appealBond) revert BadValue();
        network.setAppeal(fid, true); // reverts unless decided, in time and not already appealed
        appeals[fid] = Appeal(msg.sender, uint64(block.timestamp), uint128(msg.value));
        emit Appealed(fid, msg.sender);
    }

    /// Governance (the timelock) decides an appeal; its outcome replaces the judges'.
    function resolveAppeal(uint256 fid, bool valid, uint8 sev, uint256 group) external onlyGovernance {
        Appeal memory a = appeals[fid];
        if (a.by == address(0)) revert Closed();
        if (!valid) { sev = 0; group = fid; }
        bytes32 item = itemKey(K_FINDING, fid, 0);
        bytes32 old = decided[item];
        bytes32 next = findingOutcome(valid, sev, group);
        bool changed = old != next;
        if (changed) {
            network.decide(fid, valid, sev, group);
            decided[item] = next;
            uint64 r = itemReq[item];
            if (r != 0) credits[r - 1] = credits[r - 1] - tally[item][old] + tally[item][next];
        }
        _close(fid, a, changed, false);
    }

    /// After appealTimeout without a governance decision the judges' decision stands; the bond comes back.
    function expireAppeal(uint256 fid) external {
        Appeal memory a = appeals[fid];
        if (a.by == address(0)) revert Closed();
        (, , uint32 timeout) = network.timing();
        if (block.timestamp < uint256(a.at) + timeout) revert TooEarly();
        _close(fid, a, true, true);
    }

    function _close(uint256 fid, Appeal memory a, bool refund, bool expired) internal {
        delete appeals[fid];
        network.setAppeal(fid, false);
        owed[refund ? a.by : network.treasury()] += a.bond;
        emit AppealResolved(fid, refund && !expired, expired);
    }

    // ================================================================ pay

    /// A judge's share of request `id`'s pot: one credit per contest decision it voted with.
    function claim(uint256 id, bytes32[] calldata items) external {
        (, , , , , bool settled) = network.core(id);
        if (!settled) revert TooEarly();
        uint256 n;
        for (uint256 i = 0; i < items.length; i++) {
            bytes32 it = items[i];
            bytes32 d = decided[it];
            if (itemReq[it] != id + 1 || judgeClaimed[it][msg.sender] || d == bytes32(0) || votedFor[it][msg.sender] != d) revert Nothing();
            judgeClaimed[it][msg.sender] = true;
            n++;
        }
        if (n == 0 || credits[id] == 0) revert Nothing();
        uint256 amount = (uint256(pot[id]) * n) / credits[id];
        owed[msg.sender] += amount;
        emit Paid(msg.sender, amount, id);
    }

    /// Nothing was decided on a settled request: the sponsor takes the judges' pot back.
    function reclaimPot(uint256 id) external {
        (address sponsor, , , , , bool settled) = network.core(id);
        if (msg.sender != sponsor || !settled || credits[id] != 0 || potReclaimed[id]) revert Nothing();
        potReclaimed[id] = true;
        owed[sponsor] += pot[id];
        emit Paid(sponsor, pot[id], id);
    }

    function withdraw() external nonReentrant {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        _send(msg.sender, a);
        emit Withdrawn(msg.sender, a);
    }

    function _send(address to, uint256 a) internal {
        (bool ok, ) = to.call{value: a}("");
        if (!ok) revert Nothing();
    }

    // ================================================================ governance

    function setParams(Params calldata p) external onlyGovernance {
        _setParams(p);
    }

    function setGovernance(address g) external onlyGovernance {
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    /// Removes (or re-admits) a judge; its bond stays its own (withdraw after unbonding).
    function setJudgeBlocked(address who, bool blocked) external onlyGovernance {
        Judge storage j = judges[who];
        j.blocked = blocked;
        _recount(j);
        emit JudgeBlocked(who, blocked);
    }

    /// Slashes a judge for proven collusion (at most its bond), to the treasury.
    function slashJudge(address who, uint128 amount) external onlyGovernance {
        Judge storage j = judges[who];
        if (amount > j.bond) amount = j.bond;
        j.bond -= amount;
        owed[network.treasury()] += amount;
        _recount(j);
        emit JudgeSlashed(who, amount);
    }

    function _setParams(Params memory p) internal {
        if (p.judgeQuorum < 3 || p.judgeQuorum > 50 || p.maxJudges < p.judgeQuorum || p.maxJudges > 255 || p.judgeMinScore > 1000) revert BadParams();
        if (p.unbondDelay < 1 days || p.unbondDelay > 60 days) revert BadParams();
        if (p.judgeBond == 0 || p.judgeBond > 10_000 ether || p.appealBond == 0 || p.appealBond > 1000 ether) revert BadParams();
        if (judgeCount > p.maxJudges) revert BadParams();
        params = p;
        emit ParamsSet();
    }
}

contracts/AuditNetwork.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// WorkerReputation: AuditNetwork must be one of its reporters.
interface IANReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

/// AuditRunners / AuditJudges: receive their part of each request's fee.
interface IANPot {
    function open(uint256 reqId) external payable;
}

/// AuditJudges: who is a judge (judges never audit) and what the judges decided.
interface IANJudges {
    function isJudge(address who) external view returns (bool);
    function fixConfirmed(uint256 reqId, uint256 findingId) external view returns (bool);
}

/// AuditCertificate: told when certified code gets a valid critical/high finding.
interface IANCertificate {
    function revokeFor(uint256 reqId, uint256 findingId) external;
}

/// @title AuditNetwork: ZETAPHY's open audit platform (docs/future/audit-network.md)
/// @notice Anyone asks for an audit of a contract (on ZETAPHY or another chain Neuro reads), anyone
///         bonded audits it, a bonded judging committee (AuditJudges) decides every finding, three
///         runners (AuditRunners) run the automated pipeline, and only code that went through ALL of it
///         gets a certificate (AuditCertificate). This contract holds the requests, the auditors' bonds,
///         reports and findings, and the bounty money:
///           - Request: the target {chainId, address, codeHash, source hash}, a deposit (bounty pool +
///             fee), a scope tier, a contest window (at least the governance minimum plus a week per tier)
///             and the minimum number of auditors. On ZETAPHY the codeHash must be the target's
///             EXTCODEHASH right now. A fix is a NEW request (a new codeHash) naming the request it fixes:
///             every valid critical/high finding of the old version is carried over and must be confirmed
///             fixed by the judges on the new one.
///           - Auditors: register with a bond (locked while their submissions can still be judged or
///             appealed). During the contest they commit hashes only: a participation report and any
///             findings (severity claim + evidence / PoC hash, bound to the auditor and the request). All
///             reveals happen after the contest closed, so nobody can copy a finding.
///           - Money: valid findings share the pool by severity weight (duplicates split their group's
///             share), revealed reports share `participationBps`, an invalid finding or a rejected report
///             slashes `slashBps` of the auditor bond (escrowed until appeals are over, then to the sponsor,
///             or to the treasury for post-certificate findings). The fee goes to the runners and the
///             judges. Pull payments only, behind a reentrancy lock.
///           - After a certificate: findings stay open (post-certificate bug bounty, paid from what was
///             left of the pool) until it expires; a valid critical/high one revokes the certificate of that
///             codeHash at once.
///         No owner key: governance is the ZetaphyTimelock, and every parameter is bounded.
contract AuditNetwork {
    uint8 internal constant REP_SLASHED = 3;
    uint8 internal constant REP_BUG_VALID = 4;
    uint8 internal constant REP_BUG_INVALID = 5;

    // severities (the pipeline's schema: info < low < medium < high < critical)
    uint8 internal constant SEV_INFO = 1;
    uint8 internal constant SEV_LOW = 2;
    uint8 internal constant SEV_MEDIUM = 3;
    uint8 internal constant SEV_HIGH = 4;
    uint8 internal constant SEV_CRITICAL = 5;

    // finding status
    uint8 internal constant F_COMMITTED = 1;
    uint8 internal constant F_REVEALED = 2;
    uint8 internal constant F_VALID = 3;
    uint8 internal constant F_INVALID = 4;

    uint256 internal constant MAX_FINDINGS = 200;      // per request (contest + post-certificate)
    uint256 internal constant MAX_CARRY = 50;          // carried critical/high findings of a fix
    uint256 internal constant MAX_URI = 200;
    uint32 internal constant MIN_CONTEST_FLOOR = 3 days;
    uint32 internal constant TIER_EXTRA = 7 days;      // each scope tier adds a week to the minimum contest

    struct Params {
        uint32 minContest;          // [3 days, 60 days]
        uint32 maxContest;          // [minContest + 14 days, 180 days]
        uint32 revealWindow;        // [1 day, 14 days]
        uint32 judgeWindow;         // [2 days, 30 days]
        uint32 appealWindow;        // [2 days, 30 days]
        uint32 appealTimeout;       // [7 days, 90 days]: governance resolves an appeal in time, or the decision stands
        uint32 unbondDelay;         // [1 day, 60 days]
        uint16 minAuditorsFloor;    // [2, 50]
        uint16 slashBps;            // [500, 5000] of auditorBond per invalid finding / rejected report
        uint16 feeBps;              // [100, 3000] of a request's deposit that is fee (the rest is the pool)
        uint16 runnerBps;           // [2000, 8000] of the fee to the automated tier (the rest: judges)
        uint16 participationBps;    // [0, 2000] of the pool to the revealed, accepted reports
        uint16 maxFindingsPerAuditor; // [1, 50] per request
        uint128 auditorBond;        // (0, 1000 ether]
        uint128 minPool;            // (0, 1e6 ether]
    }

    /// What is audited: the contract on its chain, its runtime code hash and the source it was built from.
    struct Target {
        uint64 chainId;
        address target;
        bytes32 codeHash;           // EXTCODEHASH on ZETAPHY; keccak256(runtime bytecode) elsewhere
        bytes32 sourceHash;         // git commit / IPFS hash of the source
    }

    struct Request {
        address sponsor;
        uint64 chainId;
        uint64 createdAt;
        uint64 contestEnd;
        uint8 tier;                 // 0 basic, 1 standard, 2 deep
        bool naDeclared;
        bool settled;
        bool reclaimed;
        bool certified;
        address target;
        uint32 minContest;          // the minimum this request had to meet (snapshot)
        uint16 minAuditors;
        uint32 reports;             // revealed participation reports
        uint32 rejected;            // reports the judges rejected
        uint32 undecided;           // revealed contest findings not decided yet
        uint32 critHigh;            // valid critical/high contest findings
        uint32 openAppeals;
        uint32 totalWeight;         // sum of the severity weights of the valid groups (contest)
        uint64 certExpiry;
        uint64 prev;                // the request this one fixes, plus one (0: none)
        bytes32 codeHash;
        bytes32 sourceHash;
        bytes32 naReason;           // why invariant suites do not apply (when declared)
        uint128 pool;               // the bounty pool
        uint128 reserve;            // left after settlement: post-certificate bounty, then the sponsor's
        uint128 reportSlash;        // escrowed slashes of rejected reports (to the sponsor at settlement)
        bytes32 uriHash;            // keccak256 of the scope / docs / report link (the link itself: RequestUri event)
    }

    struct Finding {
        uint64 req;
        uint64 committedAt;
        uint64 commitBlock;
        uint64 revealedAt;
        uint64 decidedAt;
        address auditor;
        uint8 status;
        uint8 claimed;              // the severity the auditor claims
        uint8 sev;                  // the severity the judges decided (valid)
        bool late;                  // filed after the certificate (post-certificate bounty)
        bool paid;
        bool appealOpen;
        uint64 group;               // the original finding of its duplicate group
        uint128 slashed;            // escrowed until appeals are over
        bytes32 commitment;
        bytes32 findingHash;
        bytes32 evidenceHash;       // e.g. keccak256 of the PoC test file
    }

    struct Member {
        uint128 bond;
        uint64 lockedUntil;         // a submission can still be judged or appealed until then
        uint64 unbondAt;            // 0: active
    }

    address public governance;              // the ZetaphyTimelock
    address public treasury;
    IANReputation public immutable reputation;    // address(0): none
    IANPot public immutable runners;              // AuditRunners
    IANPot public immutable judging;              // AuditJudges
    IANCertificate public immutable certificate;  // AuditCertificate
    Params internal params;

    Request[] private _reqs;
    Finding[] private _findings;
    mapping(uint256 => uint256[]) private _reqFindings;
    mapping(uint256 => uint64[]) private _carry;

    mapping(address => Member) public auditors;
    mapping(uint256 => mapping(address => bytes32)) public reportCommit;
    mapping(uint256 => mapping(address => bytes32)) public reportHash;      // revealed
    mapping(uint256 => mapping(address => bool)) public reportRejected;
    mapping(uint256 => mapping(address => bool)) public reportClaimed;
    mapping(uint256 => mapping(address => uint256)) public findingsBy;
    mapping(uint256 => mapping(address => bool)) public involved;          // sponsor or auditor of a request
    mapping(uint256 => uint32) public groupSize;
    mapping(address => uint256) public owed;
    uint256 private _lock = 1;

    event Requested(uint256 indexed id, address indexed sponsor, uint64 indexed chainId, address target, bytes32 codeHash, bytes32 sourceHash, uint256 pool);
    event RequestUri(uint256 indexed id, string uri);
    event Carried(uint256 indexed id, uint256 indexed findingId);
    event NaDeclared(uint256 indexed id, bytes32 reason);
    event Bonded(address indexed auditor, uint256 bond);
    event UnbondRequested(address indexed auditor, uint64 at);
    event BondWithdrawn(address indexed auditor, uint256 amount);
    event ReportCommitted(uint256 indexed id, address indexed auditor);
    event ReportRevealed(uint256 indexed id, address indexed auditor, bytes32 reportHash);
    event ReportRejected(uint256 indexed id, address indexed auditor);
    event FindingCommitted(uint256 indexed findingId, uint256 indexed id, address indexed auditor, bool late);
    event FindingRevealed(uint256 indexed findingId, uint256 indexed id, address indexed auditor, uint8 severity, bytes32 findingHash, bytes32 evidenceHash, string uri);
    event FindingDecided(uint256 indexed findingId, bool valid, uint8 severity, uint256 group);
    event AppealSet(uint256 indexed findingId, bool open);
    event Slashed(address indexed auditor, uint256 amount, uint256 ref);
    event Settled(uint256 indexed id, uint256 reserve);
    event Certified(uint256 indexed id, uint64 expiry);
    event Paid(address indexed to, uint256 amount, bytes32 what);
    event Withdrawn(address indexed to, uint256 amount);
    event ParamsSet();
    event GovernanceSet(address governance);
    event TreasurySet(address treasury);

    error NotGovernance();
    error NotJudging();
    error NotCertificate();
    error BadParams();
    error BadValue();
    error BadRequest();
    error BadFinding();
    error BadOutcome();
    error CodeMismatch();
    error Closed();
    error TooEarly();
    error TooMany();
    error NotBonded();
    error Conflict();
    error AlreadyIn();
    error BadReveal();
    error Locked();
    error Nothing();
    error Reentrant();

    /// runners_, judging_ and certificate_ are the addresses those contracts get when deployed right after
    /// this one (the deploy script computes them from the deployer's nonce; no key binds them later).
    constructor(address governance_, address treasury_, IANReputation reputation_, IANPot runners_, IANPot judging_, IANCertificate certificate_, Params memory p) {
        if (governance_ == address(0) || treasury_ == address(0) || address(runners_) == address(0) || address(judging_) == address(0)
            || address(certificate_) == address(0)) revert BadParams();
        governance = governance_;
        treasury = treasury_;
        reputation = reputation_;
        runners = runners_;
        judging = judging_;
        certificate = certificate_;
        _setParams(p);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier onlyJudging() {
        if (msg.sender != address(judging)) revert NotJudging();
        _;
    }

    modifier nonReentrant() {
        if (_lock != 1) revert Reentrant();
        _lock = 2;
        _;
        _lock = 1;
    }

    // ================================================================ requests

    /// Asks for an audit. msg.value = bounty pool + fee (fee = feeBps of it). `prev`: the request this
    /// version fixes plus one (0: a first version).
    function request(Target calldata t, uint8 tier, uint32 contest, uint16 minAuditors, uint64 prev, string calldata uri)
        external payable returns (uint256 id)
    {
        if (t.chainId == 0 || t.target == address(0) || t.codeHash == bytes32(0) || t.sourceHash == bytes32(0) || tier > 2) revert BadRequest();
        if (bytes(uri).length > MAX_URI) revert BadRequest();
        if (t.chainId == block.chainid && t.target.codehash != t.codeHash) revert CodeMismatch();
        id = _reqs.length;
        Request storage r = _reqs.push();
        uint256 judgePot = _terms(r, tier, contest, minAuditors);
        r.sponsor = msg.sender;
        r.chainId = t.chainId;
        r.target = t.target;
        r.codeHash = t.codeHash;
        r.sourceHash = t.sourceHash;
        r.uriHash = keccak256(bytes(uri));
        involved[id][msg.sender] = true;
        if (prev != 0) _carryFrom(id, r, prev - 1);
        r.prev = prev;
        emit Requested(id, msg.sender, t.chainId, t.target, t.codeHash, t.sourceHash, r.pool);
        if (bytes(uri).length != 0) emit RequestUri(id, uri);
        runners.open{value: msg.value - r.pool - judgePot}(id);
        judging.open{value: judgePot}(id);
    }

    /// The request's window, auditors and money, checked against the parameters. Returns the judges' pot.
    function _terms(Request storage r, uint8 tier, uint32 contest, uint16 minAuditors) internal returns (uint256) {
        Params storage p = params;
        uint32 need = p.minContest + uint32(tier) * TIER_EXTRA;
        if (contest < need || contest > p.maxContest) revert BadRequest();
        if (minAuditors < p.minAuditorsFloor + 2 * uint16(tier)) revert BadRequest();
        uint256 fee = (msg.value * p.feeBps) / 10_000;
        if (msg.value - fee < p.minPool) revert BadValue();
        r.tier = tier;
        r.createdAt = uint64(block.timestamp);
        r.contestEnd = uint64(block.timestamp + contest);
        r.minContest = need;
        r.minAuditors = minAuditors;
        r.pool = uint128(msg.value - fee);
        return fee - (fee * p.runnerBps) / 10_000;
    }

    /// A fix: the old version's valid critical/high findings, and its own carried ones that were not
    /// confirmed fixed, must be confirmed fixed on this one. The old request must be settled.
    function _carryFrom(uint256 id, Request storage r, uint256 old) internal {
        Request storage o = _req(old);
        if (!o.settled || o.chainId != r.chainId || o.codeHash == r.codeHash) revert BadRequest();
        uint256[] storage fs = _reqFindings[old];
        for (uint256 i = 0; i < fs.length; i++) {
            Finding storage f = _findings[fs[i]];
            if (f.status == F_VALID && f.sev >= SEV_HIGH) _pushCarry(id, fs[i]);
        }
        uint64[] storage oc = _carry[old];
        for (uint256 i = 0; i < oc.length; i++) if (!IANJudges(address(judging)).fixConfirmed(old, oc[i])) _pushCarry(id, oc[i]);
    }

    function _pushCarry(uint256 id, uint256 fid) internal {
        if (_carry[id].length >= MAX_CARRY) revert TooMany();
        _carry[id].push(uint64(fid));
        emit Carried(id, fid);
    }

    /// The sponsor says the invariant suites do not apply (e.g. a plain token); the judges must accept it.
    function declareNotApplicable(uint256 id, bytes32 reason) external {
        Request storage r = _req(id);
        if (msg.sender != r.sponsor || reason == bytes32(0)) revert BadRequest();
        if (block.timestamp >= r.contestEnd || r.naDeclared) revert Closed();
        r.naDeclared = true;
        r.naReason = reason;
        emit NaDeclared(id, reason);
    }

    // ================================================================ auditor bonds

    function bond() external payable {
        Member storage m = auditors[msg.sender];
        if (msg.value == 0) revert BadValue();
        if (m.unbondAt != 0) revert Locked();
        m.bond += uint128(msg.value);
        emit Bonded(msg.sender, m.bond);
    }

    function requestUnbond() external {
        Member storage m = auditors[msg.sender];
        if (m.bond == 0 || m.unbondAt != 0) revert Nothing();
        uint64 at = uint64(block.timestamp + params.unbondDelay);
        if (m.lockedUntil > at) at = m.lockedUntil;
        m.unbondAt = at;
        emit UnbondRequested(msg.sender, at);
    }

    function withdrawBond() external nonReentrant {
        Member storage m = auditors[msg.sender];
        if (m.unbondAt == 0 || block.timestamp < m.unbondAt || block.timestamp < m.lockedUntil) revert TooEarly();
        uint256 a = m.bond;
        m.bond = 0;
        m.unbondAt = 0;
        _send(msg.sender, a);
        emit BondWithdrawn(msg.sender, a);
    }

    function _checkAuditor(Request storage r) internal view {
        Member storage m = auditors[msg.sender];
        if (m.unbondAt != 0 || m.bond < params.auditorBond) revert NotBonded();
        if (msg.sender == r.sponsor || IANJudges(address(judging)).isJudge(msg.sender)) revert Conflict();
    }

    function _lockAuditor(uint256 until) internal {
        Member storage m = auditors[msg.sender];
        if (until > m.lockedUntil) m.lockedUntil = uint64(until);
    }

    /// Slashes slashBps of the auditor bond requirement (at most what is left).
    function _slash(address a, uint256 ref) internal returns (uint128 s) {
        Member storage m = auditors[a];
        uint256 want = (uint256(params.auditorBond) * params.slashBps) / 10_000;
        s = uint128(want > m.bond ? m.bond : want);
        m.bond -= s;
        emit Slashed(a, s, ref);
    }

    // ================================================================ reports and findings

    function reportCommitment(bytes32 hash, address auditor, bytes32 salt, uint256 id) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.audit.report", hash, auditor, salt, id));
    }

    function findingCommitment(bytes32 findingHash, uint8 severity, bytes32 evidenceHash, address auditor, bytes32 salt, uint256 id)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode("zetaphy.audit.finding", findingHash, severity, evidenceHash, auditor, salt, id));
    }

    /// An auditor's participation: the hash of its full report ("no findings" is a report too).
    function commitReport(uint256 id, bytes32 commitment) external {
        Request storage r = _req(id);
        _checkAuditor(r);
        if (block.timestamp >= r.contestEnd) revert Closed();
        if (commitment == bytes32(0) || reportCommit[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        reportCommit[id][msg.sender] = commitment;
        involved[id][msg.sender] = true;
        _lockAuditor(_horizon(r));
        emit ReportCommitted(id, msg.sender);
    }

    function revealReport(uint256 id, bytes32 hash, bytes32 salt) external {
        Request storage r = _req(id);
        if (block.timestamp < r.contestEnd) revert TooEarly();
        if (block.timestamp >= uint256(r.contestEnd) + params.revealWindow) revert Closed();
        bytes32 c = reportCommit[id][msg.sender];
        if (c == bytes32(0) || reportHash[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (hash == bytes32(0) || reportCommitment(hash, msg.sender, salt, id) != c) revert BadReveal();
        reportHash[id][msg.sender] = hash;
        r.reports++;
        emit ReportRevealed(id, msg.sender, hash);
    }

    /// During the contest, or (post-certificate bounty) while the request's certificate has not expired.
    function commitFinding(uint256 id, bytes32 commitment) external returns (uint256 fid) {
        Request storage r = _req(id);
        _checkAuditor(r);
        bool late = block.timestamp >= r.contestEnd;
        if (late && (!r.certified || block.timestamp >= r.certExpiry)) revert Closed();
        if (commitment == bytes32(0)) revert BadValue();
        if (_reqFindings[id].length >= MAX_FINDINGS || findingsBy[id][msg.sender] >= params.maxFindingsPerAuditor) revert TooMany();
        findingsBy[id][msg.sender]++;
        fid = _findings.length;
        Finding storage f = _findings.push();
        f.req = uint64(id);
        f.auditor = msg.sender;
        f.committedAt = uint64(block.timestamp);
        f.commitBlock = uint64(block.number);
        f.status = F_COMMITTED;
        f.late = late;
        f.group = uint64(fid);
        f.commitment = commitment;
        _reqFindings[id].push(fid);
        involved[id][msg.sender] = true;
        Params storage p = params;
        _lockAuditor(late ? block.timestamp + p.revealWindow + p.judgeWindow + p.appealWindow + p.appealTimeout : _horizon(r));
        emit FindingCommitted(fid, id, msg.sender, late);
    }

    /// Contest findings: after the contest, inside the reveal window. Post-certificate ones: from the next
    /// block, inside the reveal window counted from the commit (a watcher cannot front-run the reveal).
    function revealFinding(uint256 fid, bytes32 findingHash, uint8 severity, bytes32 evidenceHash, bytes32 salt, string calldata uri) external {
        Finding storage f = _finding(fid);
        if (msg.sender != f.auditor || f.status != F_COMMITTED) revert BadFinding();
        Request storage r = _reqs[f.req];
        if (f.late) {
            if (block.number <= f.commitBlock) revert TooEarly();
            if (block.timestamp >= uint256(f.committedAt) + params.revealWindow) revert Closed();
        } else {
            if (block.timestamp < r.contestEnd) revert TooEarly();
            if (block.timestamp >= uint256(r.contestEnd) + params.revealWindow) revert Closed();
        }
        if (severity < SEV_INFO || severity > SEV_CRITICAL || findingHash == bytes32(0) || bytes(uri).length > MAX_URI) revert BadValue();
        if (findingCommitment(findingHash, severity, evidenceHash, msg.sender, salt, f.req) != f.commitment) revert BadReveal();
        f.findingHash = findingHash;
        f.evidenceHash = evidenceHash;
        f.claimed = severity;
        f.revealedAt = uint64(block.timestamp);
        f.status = F_REVEALED;
        if (!f.late) r.undecided++;
        emit FindingRevealed(fid, f.req, msg.sender, severity, findingHash, evidenceHash, uri);
    }

    // ================================================================ decisions (from AuditJudges)

    /// Reverts unless (valid, sev, group) is a possible decision for finding `fid`: a severity, and a
    /// group that is the finding itself or an EARLIER finding of the same request (and kind) already
    /// decided valid as the original of its group.
    function checkGroup(uint256 fid, uint8 sev, uint256 group) public view {
        Finding storage f = _finding(fid);
        if (sev < SEV_INFO || sev > SEV_CRITICAL || group > fid) revert BadOutcome();
        if (group != fid) {
            Finding storage g = _findings[group];
            if (g.req != f.req || g.status != F_VALID || g.group != group || g.late != f.late) revert BadOutcome();
        }
    }

    /// The judges' decision on a revealed finding, or governance's on an appealed one (it replaces the old).
    function decide(uint256 fid, bool valid, uint8 sev, uint256 group) external onlyJudging {
        Finding storage f = _finding(fid);
        Request storage r = _reqs[f.req];
        if (f.status == F_VALID || f.status == F_INVALID) {
            if (!f.appealOpen) revert Closed();
            _undo(fid, f, r);
        } else if (f.status != F_REVEALED) revert Closed();
        if (valid) checkGroup(fid, sev, group);
        else { sev = 0; group = fid; }
        if (!f.late) r.undecided--;
        f.decidedAt = uint64(block.timestamp);
        f.group = uint64(group);
        if (valid) {
            f.status = F_VALID;
            f.sev = sev;
            groupSize[group]++;
            if (!f.late) {
                if (group == fid) r.totalWeight += weight(sev);
                if (sev >= SEV_HIGH) r.critHigh++;
            } else if (sev >= SEV_HIGH) {
                certificate.revokeFor(f.req, fid); // a valid critical/high against certified code: revoked now
            }
            _rep(f.auditor, REP_BUG_VALID, bytes32(fid));
        } else {
            f.status = F_INVALID;
            f.sev = 0;
            f.slashed = _slash(f.auditor, fid);
            _rep(f.auditor, REP_BUG_INVALID, bytes32(fid));
        }
        emit FindingDecided(fid, valid, sev, group);
    }

    function _undo(uint256 fid, Finding storage f, Request storage r) internal {
        if (f.status == F_VALID) {
            groupSize[f.group]--;
            if (!f.late) {
                if (f.group == fid) r.totalWeight -= weight(f.sev);
                if (f.sev >= SEV_HIGH) r.critHigh--;
            }
        } else if (f.slashed > 0) {
            auditors[f.auditor].bond += f.slashed; // the slash was wrong: back into the bond
            f.slashed = 0;
        }
        f.status = F_REVEALED;
        if (!f.late) r.undecided++;
    }

    /// The judges rejected a revealed report (empty, plagiarised, spam): it does not count, and slashes.
    function rejectReport(uint256 id, address auditor) external onlyJudging {
        Request storage r = _req(id);
        if (reportHash[id][auditor] == bytes32(0) || reportRejected[id][auditor]) revert Closed();
        reportRejected[id][auditor] = true;
        r.rejected++;
        r.reportSlash += _slash(auditor, id);
        _rep(auditor, REP_SLASHED, bytes32(id));
        emit ReportRejected(id, auditor);
    }

    /// AuditJudges opens (an appeal was filed in time) or closes an appeal on a decided finding.
    function setAppeal(uint256 fid, bool open) external onlyJudging {
        Finding storage f = _finding(fid);
        Request storage r = _reqs[f.req];
        if (open) {
            if ((f.status != F_VALID && f.status != F_INVALID) || f.appealOpen || block.timestamp >= appealEnd(fid)) revert Closed();
            r.openAppeals++;
        } else {
            if (!f.appealOpen) revert Closed();
            r.openAppeals--;
        }
        f.appealOpen = open;
        emit AppealSet(fid, open);
    }

    /// Severity weights of the bounty split: info 0, low 1, medium 3, high 10, critical 30.
    function weight(uint8 sev) public pure returns (uint32) {
        if (sev == SEV_CRITICAL) return 30;
        if (sev == SEV_HIGH) return 10;
        if (sev == SEV_MEDIUM) return 3;
        if (sev == SEV_LOW) return 1;
        return 0;
    }

    /// The share (bps) of the reserve a post-certificate finding takes: critical all, high half, ...
    function lateBps(uint8 sev) internal pure returns (uint256) {
        if (sev == SEV_CRITICAL) return 10_000;
        if (sev == SEV_HIGH) return 5_000;
        if (sev == SEV_MEDIUM) return 1_000;
        if (sev == SEV_LOW) return 200;
        return 0;
    }

    // ================================================================ settlement and payouts

    /// Anyone, once the appeal window is over and no appeal is open: the contest's money is final.
    function settle(uint256 id) external {
        Request storage r = _req(id);
        if (r.settled) revert Closed();
        if (block.timestamp < judgeEnd(id) + params.appealWindow || r.openAppeals != 0) revert TooEarly();
        r.settled = true;
        uint256 part = (uint256(r.pool) * params.participationBps) / 10_000;
        uint256 reserve;
        if (r.reports == r.rejected) reserve += part;
        if (r.totalWeight == 0) reserve += r.pool - part;
        r.reserve = uint128(reserve);
        if (r.reportSlash > 0) {
            owed[r.sponsor] += r.reportSlash;
            r.reportSlash = 0;
        }
        emit Settled(id, reserve);
    }

    /// A valid contest finding's share: the pool (less the participation part) by its group's severity
    /// weight, split equally in its duplicate group.
    function _payout(uint256 fid) internal view returns (uint256) {
        Finding storage f = _finding(fid);
        Request storage r = _reqs[f.req];
        if (f.status != F_VALID || f.late || r.totalWeight == 0) return 0;
        Finding storage g = _findings[f.group];
        if (g.status != F_VALID || g.group != f.group) return 0; // its original was overturned on appeal
        uint256 pot = uint256(r.pool) - (uint256(r.pool) * params.participationBps) / 10_000;
        return (pot * weight(g.sev)) / r.totalWeight / groupSize[f.group];
    }

    function claimFinding(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.paid || f.appealOpen) revert Closed();
        uint256 amount;
        if (f.late) {
            // the original of its group only: a duplicate filed after it saw the reveal earns nothing
            if (f.status != F_VALID || f.group != fid || block.timestamp < appealEnd(fid)) revert TooEarly();
            Request storage r = _reqs[f.req];
            amount = (uint256(r.reserve) * lateBps(f.sev)) / 10_000;
            r.reserve -= uint128(amount);
        } else {
            if (!_reqs[f.req].settled) revert TooEarly();
            amount = _payout(fid);
        }
        if (amount == 0) revert Nothing();
        f.paid = true;
        owed[f.auditor] += amount;
        emit Paid(f.auditor, amount, bytes32(fid));
    }

    /// An escrowed slash of an invalid finding, once it can no longer be appealed: to the sponsor
    /// (contest) or the treasury (post-certificate).
    function claimSlash(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.slashed == 0 || f.appealOpen || block.timestamp < appealEnd(fid)) revert TooEarly();
        uint256 a = f.slashed;
        f.slashed = 0;
        address to = f.late ? treasury : _reqs[f.req].sponsor;
        owed[to] += a;
        emit Paid(to, a, keccak256(abi.encode("slash", fid)));
    }

    function claimReport(uint256 id) external {
        Request storage r = _req(id);
        if (!r.settled) revert TooEarly();
        if (reportHash[id][msg.sender] == bytes32(0) || reportRejected[id][msg.sender] || reportClaimed[id][msg.sender]) revert Nothing();
        reportClaimed[id][msg.sender] = true;
        uint256 amount = (uint256(r.pool) * params.participationBps) / 10_000 / (r.reports - r.rejected);
        owed[msg.sender] += amount;
        emit Paid(msg.sender, amount, keccak256(abi.encode("report", id)));
    }

    /// The sponsor takes the reserve back: never certified, or once the certificate expired.
    function reclaim(uint256 id) external {
        Request storage r = _req(id);
        if (msg.sender != r.sponsor || !r.settled || r.reclaimed) revert Nothing();
        if (r.certified && block.timestamp < r.certExpiry) revert TooEarly();
        r.reclaimed = true;
        uint256 a = r.reserve;
        r.reserve = 0;
        owed[r.sponsor] += a;
        emit Paid(r.sponsor, a, keccak256(abi.encode("reclaim", id)));
    }

    function withdraw() external nonReentrant {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        _send(msg.sender, a);
        emit Withdrawn(msg.sender, a);
    }

    function _send(address to, uint256 a) internal {
        (bool ok, ) = to.call{value: a}("");
        if (!ok) revert Nothing();
    }

    /// AuditCertificate marks a request certified (its post-certificate bounty opens).
    function markCertified(uint256 id, uint64 expiry) external {
        if (msg.sender != address(certificate)) revert NotCertificate();
        Request storage r = _req(id);
        r.certified = true;
        r.certExpiry = expiry;
        emit Certified(id, expiry);
    }

    // ================================================================ governance

    function setParams(Params memory p) external onlyGovernance {
        _setParams(p);
    }

    function setGovernance(address g) external onlyGovernance {
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    function setTreasury(address t) external onlyGovernance {
        if (t == address(0)) revert BadParams();
        treasury = t;
        emit TreasurySet(t);
    }

    function _setParams(Params memory p) internal {
        if (p.minContest < MIN_CONTEST_FLOOR || p.minContest > 60 days || p.maxContest < p.minContest + 2 * TIER_EXTRA || p.maxContest > 180 days) revert BadParams();
        if (p.revealWindow < 1 days || p.revealWindow > 14 days || p.judgeWindow < 2 days || p.judgeWindow > 30 days) revert BadParams();
        if (p.appealWindow < 2 days || p.appealWindow > 30 days || p.appealTimeout < 7 days || p.appealTimeout > 90 days) revert BadParams();
        if (p.unbondDelay < 1 days || p.unbondDelay > 60 days || p.minAuditorsFloor < 2 || p.minAuditorsFloor > 50) revert BadParams();
        if (p.slashBps < 500 || p.slashBps > 5000 || p.feeBps < 100 || p.feeBps > 3000) revert BadParams();
        if (p.runnerBps < 2000 || p.runnerBps > 8000 || p.participationBps > 2000) revert BadParams();
        if (p.maxFindingsPerAuditor < 1 || p.maxFindingsPerAuditor > 50) revert BadParams();
        if (p.auditorBond == 0 || p.auditorBond > 1000 ether || p.minPool == 0 || p.minPool > 1e6 ether) revert BadParams();
        params = p;
        emit ParamsSet();
    }

    // ================================================================ reads

    function getParams() external view returns (Params memory) {
        return params;
    }

    function requestCount() external view returns (uint256) {
        return _reqs.length;
    }

    function getRequest(uint256 id) external view returns (Request memory) {
        return _req(id);
    }

    function findingCount() external view returns (uint256) {
        return _findings.length;
    }

    function getFinding(uint256 fid) external view returns (Finding memory) {
        return _finding(fid);
    }

    function findingsOf(uint256 id) external view returns (uint256[] memory) {
        return _reqFindings[id];
    }

    function carriedOf(uint256 id) external view returns (uint64[] memory) {
        return _carry[id];
    }

    function isCarried(uint256 id, uint256 fid) external view returns (bool) {
        uint64[] storage c = _carry[id];
        for (uint256 i = 0; i < c.length; i++) if (c[i] == fid) return true;
        return false;
    }

    /// What AuditRunners and AuditJudges need about request `id`: its sponsor and windows.
    function core(uint256 id) external view returns (address sponsor, uint64 contestEnd, uint256 revealEnd, uint256 judgeEnd_, bool naDeclared, bool settled) {
        Request storage r = _req(id);
        return (r.sponsor, r.contestEnd, uint256(r.contestEnd) + params.revealWindow, judgeEnd(id), r.naDeclared, r.settled);
    }

    /// What AuditJudges needs about a finding: (request, status, late, judging deadline).
    function findingCore(uint256 fid) external view returns (uint64 req, uint8 st, bool late, uint256 judgeBy) {
        Finding storage f = _finding(fid);
        judgeBy = f.late ? uint256(f.revealedAt) + params.judgeWindow : judgeEnd(f.req);
        return (f.req, f.status, f.late, judgeBy);
    }

    /// (judgeWindow, appealWindow, appealTimeout) for AuditJudges.
    function timing() external view returns (uint32, uint32, uint32) {
        return (params.judgeWindow, params.appealWindow, params.appealTimeout);
    }

    function judgeEnd(uint256 id) public view returns (uint256) {
        return uint256(_req(id).contestEnd) + params.revealWindow + params.judgeWindow;
    }

    /// The last moment the decision on finding `fid` can be appealed.
    function appealEnd(uint256 fid) public view returns (uint256) {
        Finding storage f = _finding(fid);
        if (f.late) return uint256(f.decidedAt) + params.appealWindow;
        return judgeEnd(f.req) + params.appealWindow;
    }

    /// The last moment anything about request `r`'s contest can still change.
    function _horizon(Request storage r) internal view returns (uint256) {
        Params storage p = params;
        return uint256(r.contestEnd) + p.revealWindow + p.judgeWindow + p.appealWindow + p.appealTimeout;
    }

    function _req(uint256 id) internal view returns (Request storage) {
        if (id >= _reqs.length) revert BadRequest();
        return _reqs[id];
    }

    function _finding(uint256 fid) internal view returns (Finding storage) {
        if (fid >= _findings.length) revert BadFinding();
        return _findings[fid];
    }

    function _rep(address w, uint8 kind, bytes32 ref) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, ref) {} catch {}
    }
}

contracts/AuditRunners.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The request windows and sponsor AuditNetwork exposes.
interface IARNetwork {
    function core(uint256 id) external view returns (address sponsor, uint64 contestEnd, uint256 revealEnd, uint256 judgeEnd, bool naDeclared, bool settled);
}

/// NeuroJobs' runner record (the same bar BugBounty and ThreatRegistry use).
interface IARJobs {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IARReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

/// @title AuditRunners: the automated tier of an AuditNetwork request
/// @notice Three bonded NeuroJobs runners (the useful-work runners: `zetaphy audit run`) run the audit
///         pipeline (audit/report.js: Slither, Aderyn, Semgrep, SMTChecker, fuzzers, Halmos, mutation
///         testing), Neuro's rules and, if their owner set one up, an LLM review on the EXACT code of the
///         request, and commit the hash of the canonical result together with its summary numbers:
///             (resultHash, open critical+high, invariant suites failed, suites not run, mutation score bps)
///         commitment = keccak256("zetaphy.audit.run", keccak256(abi.encode(result)), runner, salt, requestId)
///         Commits until the contest ends, reveals in the request's reveal window, so nobody copies a
///         result. The tier counts only when at least 2 of the 3 seats revealed the SAME tuple
///         (UsefulWork's agreement pattern); the agreeing seats share the runners' part of the fee,
///         the others are reported to WorkerReputation (disagreed / missed). With no agreement the fee
///         goes back to the sponsor and the request can never be certified (strict: a new request).
///         The LLM review is advisory and is NOT part of the hashed result: two honest runners must get
///         the same hash; AI findings enter the contest as ordinary findings that judges decide.
contract AuditRunners {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    uint8 internal constant AGREED = 0;
    uint8 internal constant DISAGREED = 1;
    uint8 internal constant MISSED = 2;

    struct Result {
        bytes32 resultHash;      // keccak256 of the canonical pipeline + Neuro result (src/auditnet.js canonicalResult)
        uint32 critHigh;         // open (or accepted) critical + high findings in it
        uint32 invFailed;        // invariant suites that failed
        uint32 invNotRun;        // invariant suites that did not run (n/a must then be accepted by the judges)
        uint16 mutationBps;      // mutation score, 0..10000
    }

    struct Tier {
        uint128 fee;
        uint8 taken;
        uint8 revealed;
        bool settled;
        bool agreed;
        bytes32 accepted;        // keccak256(abi.encode(Result)) of the agreed tuple
    }

    IARNetwork public immutable network;
    IARJobs public immutable jobs;
    IARReputation public immutable reputation;
    uint32 public immutable minAgreed;

    mapping(uint256 => Tier) public tiers;
    mapping(uint256 => address[]) private _seats;
    mapping(uint256 => mapping(address => bytes32)) public commitments;
    mapping(uint256 => mapping(address => bytes32)) public revealedKey;
    mapping(bytes32 => Result) private _results;
    mapping(address => uint256) public owed;
    uint256 private _lock = 1;

    event Opened(uint256 indexed id, uint256 fee);
    event Committed(uint256 indexed id, address indexed runner);
    event Revealed(uint256 indexed id, address indexed runner, bytes32 resultHash, uint32 critHigh, uint32 invFailed, uint32 invNotRun, uint16 mutationBps);
    event TierSettled(uint256 indexed id, bool agreed, bytes32 resultHash, uint256 agreedSeats, uint256 paidEach);
    event Withdrawn(address indexed to, uint256 amount);

    error NotNetwork();
    error NotRunner();
    error Closed();
    error TooEarly();
    error AlreadyIn();
    error BadReveal();
    error Nothing();
    error Reentrant();

    constructor(IARNetwork network_, IARJobs jobs_, IARReputation reputation_, uint32 minAgreed_) {
        require(address(network_) != address(0) && address(jobs_) != address(0), "zero");
        network = network_;
        jobs = jobs_;
        reputation = reputation_;
        minAgreed = minAgreed_;
    }

    /// AuditNetwork opens the tier of a new request with the runners' part of its fee.
    function open(uint256 id) external payable {
        if (msg.sender != address(network)) revert NotNetwork();
        tiers[id].fee += uint128(msg.value);
        emit Opened(id, msg.value);
    }

    function commitmentOf(Result calldata r, address runner, bytes32 salt, uint256 id) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.audit.run", keccak256(abi.encode(r)), runner, salt, id));
    }

    function eligible(address runner) public view returns (bool) {
        (, , bool active, uint32 agreed, uint32 rejected) = jobs.workers(runner);
        return active && agreed >= minAgreed && rejected <= agreed;
    }

    function commit(uint256 id, bytes32 commitment) external {
        (address sponsor, uint64 contestEnd, , , , ) = network.core(id);
        Tier storage t = tiers[id];
        if (t.settled || t.taken >= SEATS || block.timestamp >= contestEnd) revert Closed();
        if (!eligible(msg.sender) || msg.sender == sponsor) revert NotRunner();
        if (commitment == bytes32(0) || commitments[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        commitments[id][msg.sender] = commitment;
        _seats[id].push(msg.sender);
        t.taken++;
        emit Committed(id, msg.sender);
    }

    function reveal(uint256 id, Result calldata r, bytes32 salt) external {
        (, uint64 contestEnd, uint256 revealEnd, , , ) = network.core(id);
        Tier storage t = tiers[id];
        if (block.timestamp < contestEnd) revert TooEarly();
        if (t.settled || block.timestamp >= revealEnd) revert Closed();
        bytes32 c = commitments[id][msg.sender];
        if (c == bytes32(0) || revealedKey[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (r.resultHash == bytes32(0) || r.mutationBps > 10_000 || commitmentOf(r, msg.sender, salt, id) != c) revert BadReveal();
        bytes32 k = keccak256(abi.encode(r));
        revealedKey[id][msg.sender] = k;
        _results[k] = r;
        t.revealed++;
        emit Revealed(id, msg.sender, r.resultHash, r.critHigh, r.invFailed, r.invNotRun, r.mutationBps);
    }

    /// Anyone, once all 3 seats revealed or the reveal window ended.
    function settle(uint256 id) external {
        (address sponsor, uint64 contestEnd, uint256 revealEnd, , , ) = network.core(id);
        Tier storage t = tiers[id];
        if (t.settled) revert Closed();
        bool allIn = t.taken == SEATS && t.revealed == SEATS && block.timestamp >= contestEnd;
        if (!allIn && block.timestamp < revealEnd) revert TooEarly();
        t.settled = true;
        address[] memory seats = _seats[id];
        bytes32 k = _majority(id, seats);
        uint256 n;
        for (uint256 i = 0; i < seats.length; i++) if (k != bytes32(0) && revealedKey[id][seats[i]] == k) n++;
        uint256 each;
        if (n > 0) {
            t.agreed = true;
            t.accepted = k;
            each = t.fee / n;
        } else {
            owed[sponsor] += t.fee; // no agreement: the fee goes back
        }
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = revealedKey[id][seats[i]];
            uint8 kind = v == bytes32(0) ? MISSED : (k != bytes32(0) && v == k ? AGREED : DISAGREED);
            if (kind == AGREED) owed[seats[i]] += each;
            if (k != bytes32(0) || kind == MISSED) _rep(seats[i], kind, id);
        }
        emit TierSettled(id, t.agreed, t.agreed ? _results[k].resultHash : bytes32(0), n, each);
    }

    function withdraw() external {
        if (_lock != 1) revert Reentrant();
        _lock = 2;
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: a}("");
        if (!ok) revert Nothing();
        _lock = 1;
        emit Withdrawn(msg.sender, a);
    }

    /// The agreed result of request `id` (agreed = false: none, or not settled yet).
    function result(uint256 id) external view returns (bool agreed, Result memory r) {
        Tier storage t = tiers[id];
        if (!t.settled || !t.agreed) return (false, r);
        return (true, _results[t.accepted]);
    }

    function seatsOf(uint256 id) external view returns (address[] memory) {
        return _seats[id];
    }

    function _majority(uint256 id, address[] memory seats) internal view returns (bytes32) {
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = revealedKey[id][seats[i]];
            if (v == bytes32(0)) continue;
            uint256 n;
            for (uint256 j = 0; j < seats.length; j++) if (revealedKey[id][seats[j]] == v) n++;
            if (n >= QUORUM) return v; // QUORUM > SEATS/2: at most one tuple reaches it
        }
        return bytes32(0);
    }

    function _rep(address w, uint8 kind, uint256 id) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, keccak256(abi.encode("zetaphy.audit.run", id))) {} catch {}
    }
}

contracts/AuditVerified.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of the NeuroOracle mirror (NeuroOracle.sol) AuditVerified reads: ZETAPHY's audit certificates as
/// pushed over Hyperlane (message kind 3). isCertified re-checks EXTCODEHASH on THIS chain at every call.
interface IAVOracle {
    function isCertified(uint64 chainId, address target) external view returns (bool);
    function certs(bytes32 key) external view returns (uint64 chainId, address target, bytes32 codeHash, bytes32 reportHash, uint8 level,
        uint64 issuedAt, uint64 expiresAt, bool revoked, uint256 requestId);
}

/// What a proxy says it forwards to (beacon proxies' beacons and many UUPS/custom proxies expose it).
interface IAVImplementation {
    function implementation() external view returns (address);
}

/// @title AuditVerified: require a valid ZETAPHY audit certificate, on any EVM chain with a NeuroOracle mirror
/// @notice For routers, vaults, launchpads and lending markets that only want to list or call audited code:
///
///             using AuditVerified for IAVOracle;
///             IAVOracle immutable oracle;           // the NeuroOracle on this chain
///             function list(address pool) external {
///                 oracle.requireCertified(pool);    // reverts unless certified, unexpired, unrevoked, same code
///                 ...
///             }
///
///         "Valid" is exactly NeuroOracle.isCertified(block.chainid, target): a certificate ZETAPHY's
///         AuditCertificate issued for this chain and address, not expired, not revoked (also: the same code
///         revoked elsewhere), the mirror not paused, and the target's EXTCODEHASH on THIS chain still the
///         certified code hash (a redeploy or self-destruct fails at once). A mirror that cannot be read fails closed.
///
///         Proxies: the proxy's own code does not change when its implementation is swapped, so a proxy is
///         ordered as two certificates (proxy + implementation; zetaphy-network/src/aas/intake.js) and checked
///         with requireCertifiedProxy, which also requires the proxy's current implementation to be the
///         certified one. Contracts cannot read another contract's EIP-1967 slot, so this needs a proxy that
///         answers implementation() (or pass its beacon); for a transparent proxy that hides it, pin the
///         implementation you reviewed and re-check off-chain (the hub's certificate page reads the slot).
///
///         A certificate states that the code went through ZETAPHY's audit process; it is NOT a guarantee
///         that the code is safe (docs/future/audit-as-a-service.md).
library AuditVerified {
    error NotCertified(address target);
    error LevelTooLow(address target, uint8 level, uint8 minLevel);
    error ImplementationUnknown(address proxy);
    error ImplementationChanged(address proxy, address expected, address actual);

    /// Whether `target` (on this chain) holds a valid certificate now. False if the oracle reverts or is not a contract.
    function isVerified(IAVOracle oracle, address target) internal view returns (bool) {
        if (address(oracle).code.length == 0) return false;
        try oracle.isCertified(uint64(block.chainid), target) returns (bool ok) {
            return ok;
        } catch {
            return false;
        }
    }

    /// The level of a valid certificate (1 bronze, 2 silver, 3 gold), 0 when there is none valid now.
    function levelOf(IAVOracle oracle, address target) internal view returns (uint8) {
        if (!isVerified(oracle, target)) return 0;
        try oracle.certs(keccak256(abi.encode(uint64(block.chainid), target))) returns (uint64, address, bytes32, bytes32, uint8 level, uint64, uint64, bool, uint256) {
            return level;
        } catch {
            return 0;
        }
    }

    function requireCertified(IAVOracle oracle, address target) internal view {
        if (!isVerified(oracle, target)) revert NotCertified(target);
    }

    /// Certified at `minLevel` or above (1 bronze, 2 silver, 3 gold).
    function requireLevel(IAVOracle oracle, address target, uint8 minLevel) internal view {
        uint8 l = levelOf(oracle, target);
        if (l == 0) revert NotCertified(target);
        if (l < minLevel) revert LevelTooLow(target, l, minLevel);
    }

    /// The proxy and the implementation are both certified, and the proxy (or its beacon: pass the beacon as
    /// `reader`, else the proxy itself) reports that implementation right now.
    function requireCertifiedProxy(IAVOracle oracle, address proxy, address reader, address implementation) internal view {
        requireCertified(oracle, proxy);
        requireCertified(oracle, implementation);
        address r = reader == address(0) ? proxy : reader;
        if (r.code.length == 0) revert ImplementationUnknown(proxy); // a failed decode of empty return data is not caught
        address actual;
        try IAVImplementation(r).implementation() returns (address a) {
            actual = a;
        } catch {
            revert ImplementationUnknown(proxy);
        }
        if (actual != implementation) revert ImplementationChanged(proxy, implementation, actual);
    }
}

contracts/BridgeAirlock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnerRecords {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IGuardInbound {
    function inbound(bytes32 route, address to, uint256 amount) external;
    function guardian(address who) external view returns (bool);
}

/// ThreatRegistry's views (Reason as its uint8 value). is*Held: once the flag is
/// the registry's holdDelay old (e.g. 10 minutes), or at once through its fast
/// lane or a guardian's holdNow. is*Enforced: once the flag is the registry's
/// enforceDelay old, or at once through its fast lane.
interface IThreatFlags {
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractEnforced(address who) external view returns (bool, uint8);
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// NeuroControl (Neuro's stop switch); only `paused()` is used here.
interface INeuroControl {
    function paused() external view returns (bool);
}

/// A lane says who decides what it attests (NeuroLane: its runner records;
/// HyperlaneLane: its Mailbox). Lanes whose controllers are the same address
/// are one lane as far as independence goes.
interface ILaneInfo {
    function laneController() external view returns (address);
}

/// @title BridgeAirlock: nothing enters ZETAPHY on one bridge's word (stage 3)
/// @notice Defence in depth for incoming assets:
///   1. Several independent "lanes" (Hyperlane, IBC, the Neuro runner lane...)
///      must each attest the SAME transfer. One hacked bridge alone cannot
///      create money.
///   2. Even then the transfer waits in quarantine. During it, vetoers (the
///      Neuro lane by quorum, or a guardian) can stop it.
///   3. Markers: keys governance names (setMarker), typically the bridge
///      monitor's own low-privilege key, can mark an address (trip). A
///      transfer from or to a marked address is not released until governance
///      lifts the mark (untrip). Why an address is marked is decided off-chain
///      by the marker; the airlock keeps no list of what it watches.
///   4. Vaccine: with a ThreatRegistry set, a transfer whose source sender or
///      source contract (on its chain), or whose ZETAPHY recipient (address or
///      code), is flagged by the Neuro runners is not released:
///        - flagged, within the registry's holdDelay (e.g. 10 minutes): not
///          held yet, so a 2-runner quorum alone cannot freeze anyone's
///          transfers at once; governance or a guardian can holdNow(key)
///          meanwhile (the registry's fast lane holds at once too).
///        - held (past holdDelay, fast lane or holdNow), not enforced yet:
///          release reverts with ThreatHeld. It comes out once the flag is
///          cleared (same quorum, or an upheld appeal) or governance protects
///          the key; nothing else releases it.
///        - enforced (past the registry's enforceDelay, or at once through its
///          fast lane): refused, release reverts with ThreatFlagged, as long as
///          the flag stands. The transfer stays, so it still comes out if the
///          flag is cleared or the key protected.
///      For a hold that outlives any flag, the Neuro lane or a guardian vetoes.
///      The coins stay locked in the source chain's LockBox meanwhile: it has no
///      refund path, so a held (or vetoed) transfer is not paid back there.
///      deploy-bridge therefore protects the bridge's own keys and the source
///      LockBox in the registry, so runners cannot hold every transfer at once.
///   Released transfers still pass BridgeGuard's daily limits.
///   Independence: each lane names its controller (laneController(): NeuroLane
///   its runner records, HyperlaneLane its Mailbox; a plain key is its own).
///   independentLanes() counts distinct controllers, and BridgeGuard enables
///   this airlock's route only while it is 2 or more.
contract BridgeAirlock {
    struct Transfer {
        uint64 readyFrom;    // when the threshold was reached; quarantine counts from here
        uint8 attestations;  // independent attestations of lanes still on, as of the last attest
        bool released;
        bool vetoed;
        uint64 readyEpoch;   // removalEpoch when readyFrom was set
        bool held;           // a challenge is open on it (the challenger: SaphanChallenges); release waits
    }

    IGuardInbound public immutable guard;
    bytes32 public immutable route;     // this airlock's route in BridgeGuard
    address public governance;
    uint8 public threshold;             // distinct lanes that must agree
    uint64 public quarantine;           // seconds a transfer waits after enough lanes agreed
    mapping(address => bool) public isLane;
    address[] private laneList;         // the lanes now on, in no particular order
    uint256 public constant MAX_LANES = 16;
    mapping(address => bool) public isVetoer;
    /// Keys that may mark addresses (trip). See trip(): a marker can only mark.
    mapping(address => bool) public isMarker;
    uint256 public markerCount;         // markers now on
    /// Who marked an address (zero: not marked). A mark counts while its
    /// marker is a marker, or was removed by a guardian (markerRevoked);
    /// governance removing a marker (setMarker) lifts all of its marks at once
    /// (see tripped()).
    mapping(address => address) public trippedBy;
    /// Markers a guardian removed (emergencyRemoveMarker): they mark no more,
    /// but the marks they made still count until governance decides
    /// (setMarker, untrip).
    mapping(address => bool) public markerRevoked;
    mapping(bytes32 => Transfer) public transfers;
    mapping(bytes32 => mapping(address => bool)) public attestedBy;
    /// By controller (laneControllerOf at attest time): two lanes with one
    /// controller count once, so the threshold means independent lanes.
    mapping(bytes32 => mapping(address => bool)) public attestedByController;
    /// The lanes that attested each transfer and their controller at attest time. Only lanes that are
    /// still on count at release (BA-1): removing a lane withdraws its attestations.
    mapping(bytes32 => address[]) private _attesters;
    mapping(bytes32 => mapping(address => address)) private _controllerAt;
    mapping(bytes32 => mapping(address => uint64)) private _genAt;
    /// A lane's generation: bumped when it is removed, so a lane re-added later does not bring back
    /// the attestations it made before its removal.
    mapping(address => uint64) public laneGen;
    /// Bumped by every lane removal; a transfer that became ready before a removal is recounted.
    uint64 public removalEpoch;
    IThreatFlags public threats;        // zero: no vaccine check

    event LaneSet(address lane, bool on);
    event GovernanceSet(address governance);
    event ThresholdSet(uint8 threshold);
    event QuarantineSet(uint64 quarantine);
    event Untripped(address indexed who);
    event VetoerSet(address who, bool on);
    event MarkerSet(address marker, bool on);
    event ChallengerSet(address challenger);
    event Held(bytes32 indexed id, bool on);
    /// The transfer's details too, so a monitor sees two lanes that disagree
    /// about one source deposit (same chain, contract and nonce; another id).
    event Attested(bytes32 indexed id, address indexed lane, uint8 count, uint256 srcChainId, address srcContract,
        uint256 indexed srcNonce, address sender, address to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by, string reason);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event Tripped(address indexed who, address indexed by);
    event ThreatsSet(address registry);

    error NotGovernance();
    error NotLane();
    error NotVetoer();
    error NotMarker();
    error NotChallenger();
    error NotGuardian();
    error Twice();
    error NotReady();
    error Blocked();
    /// what: 1 source sender, 2 source contract, 3 ZETAPHY recipient (enforced flag)
    error ThreatFlagged(uint8 what);
    /// the same, for a held flag that is not enforced yet: held until it is cleared
    error ThreatHeld(uint8 what);

    constructor(IGuardInbound guard_, bytes32 route_, address governance_, uint8 threshold_, uint64 quarantine_) {
        require(threshold_ >= 2, "need 2+ independent lanes");
        guard = guard_;
        route = route_;
        governance = governance_;
        threshold = threshold_;
        quarantine = quarantine_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    /// The challenge contract (SaphanChallenges, docs/SAPHAN-SAFETY.md), or none. Like a marker it can only DELAY:
    /// hold(id) stops one transfer's release while its challenge is open, unhold(id) lets it go again; a challenge
    /// that is upheld ends in veto() (the challenger is also a vetoer, set apart). It cannot attest, release, mint,
    /// pause or move funds. Governance sets or removes it; removing it lifts nothing by itself (unhold does).
    address public challenger;

    function setChallenger(address c) external onlyGov { challenger = c; emit ChallengerSet(c); }

    function hold(bytes32 id) external {
        if (msg.sender != challenger || challenger == address(0)) revert NotChallenger();
        Transfer storage t = transfers[id];
        if (t.released || t.vetoed || t.attestations == 0) revert Blocked(); // only a transfer some lane attested
        t.held = true;
        emit Held(id, true);
    }

    /// The challenger, or governance (e.g. after removing a challenger that left a hold behind).
    function unhold(bytes32 id) external {
        if (msg.sender != governance && (msg.sender != challenger || challenger == address(0))) revert NotChallenger();
        transfers[id].held = false;
        emit Held(id, false);
    }

    function setLane(address lane, bool on) external onlyGov {
        if (on && !isLane[lane]) {
            require(lane != address(0) && laneList.length < MAX_LANES, "lane");
            laneList.push(lane);
        } else if (!on && isLane[lane]) {
            for (uint256 i = 0; i < laneList.length; i++) {
                if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
            }
            _removed(lane);
        }
        isLane[lane] = on;
        emit LaneSet(lane, on);
    }
    function setVetoer(address who, bool on) external onlyGov { isVetoer[who] = on; emit VetoerSet(who, on); }
    /// Names (or removes) a marker: typically the bridge monitor's own key, which
    /// holds no other role. Governance removes a lost or misused marker key here.
    /// Removing one lifts its marks, also after a guardian's emergencyRemoveMarker.
    function setMarker(address marker, bool on) external onlyGov {
        if (on != isMarker[marker]) {
            if (on) markerCount += 1;
            else markerCount -= 1;
        }
        isMarker[marker] = on;
        markerRevoked[marker] = false;
        emit MarkerSet(marker, on);
    }
    /// release() compares with the threshold in force then: raising it also holds back transfers that
    /// reached only the old one (the safer way).
    function setThreshold(uint8 t) external onlyGov { require(t >= 2, "need 2+"); threshold = t; emit ThresholdSet(t); }
    function setQuarantine(uint64 q) external onlyGov { quarantine = q; emit QuarantineSet(q); }
    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    /// The ThreatRegistry whose flags hold transfers (zero turns the check off).
    function setThreats(IThreatFlags r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }
    /// Governance can lift a mark set by mistake.
    function untrip(address who) external onlyGov { delete trippedBy[who]; emit Untripped(who); }

    // ---- emergency: BridgeGuard's guardians act at once, but only to reduce risk ----
    // Governance is meant to be the ZetaphyTimelock (48 h). Adding a lane or a
    // marker, lowering the threshold or the quarantine, lifting a mark, a new
    // registry or governance all wait that delay. These four only make release
    // harder, so a guardian of the guard (a multisig, BridgeGuard.setGuardian)
    // makes them at once. (A guardian removing a marker stops it from marking
    // but keeps the marks it made: only governance, through setMarker or
    // untrip, lifts marks.)
    uint64 public constant MAX_QUARANTINE = 30 days;

    function emergencyRemoveLane(address lane) external {
        _guardian();
        if (!isLane[lane]) revert NotLane();
        for (uint256 i = 0; i < laneList.length; i++) {
            if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
        }
        isLane[lane] = false;
        _removed(lane);
        emit LaneSet(lane, false);
    }

    function emergencyRemoveMarker(address marker) external {
        _guardian();
        if (!isMarker[marker]) revert NotMarker();
        isMarker[marker] = false;
        markerRevoked[marker] = true;
        markerCount -= 1;
        emit MarkerSet(marker, false);
    }

    /// More independent lanes must agree (at most MAX_LANES; above the lane count nothing is released).
    function emergencyRaiseThreshold(uint8 t) external {
        _guardian();
        require(t > threshold && t <= MAX_LANES, "raise only");
        threshold = t;
        emit ThresholdSet(t);
    }

    /// A longer quarantine (at most MAX_QUARANTINE), more time to veto.
    function emergencyRaiseQuarantine(uint64 q) external {
        _guardian();
        require(q > quarantine && q <= MAX_QUARANTINE, "raise only");
        quarantine = q;
        emit QuarantineSet(q);
    }

    /// Governance, or a guardian of the guard (a guard without guardian() has none).
    function _guardian() private view {
        if (msg.sender == governance) return;
        (bool ok, bytes memory ret) = address(guard).staticcall(abi.encodeCall(IGuardInbound.guardian, (msg.sender)));
        if (!ok || ret.length < 32 || !abi.decode(ret, (bool))) revert NotGuardian();
    }

    /// Marked by a marker that is still on, or that a guardian removed.
    /// setMarker(m, false) lifts every mark m made (setting m on again would
    /// bring them back).
    function tripped(address who) public view returns (bool) {
        address m = trippedBy[who];
        return m != address(0) && (isMarker[m] || markerRevoked[m]);
    }

    /// The lanes now on.
    function lanes() external view returns (address[] memory) { return laneList; }
    function laneCount() external view returns (uint256) { return laneList.length; }

    /// Who decides what a lane attests: its laneController(), or the lane itself
    /// (a key, or a contract that does not say).
    function laneControllerOf(address lane) public view returns (address) {
        if (lane.code.length == 0) return lane;
        try ILaneInfo(lane).laneController() returns (address c) { return c == address(0) ? lane : c; } catch { return lane; }
    }

    /// Lanes with distinct controllers. BridgeGuard will not enable this
    /// airlock's route while it is below 2: one controller behind two lane
    /// contracts is still one bridge's word.
    function independentLanes() external view returns (uint256 n) {
        uint256 len = laneList.length;
        address[] memory seen = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            address c = laneControllerOf(laneList[i]);
            bool dup = false;
            for (uint256 j = 0; j < n; j++) if (seen[j] == c) { dup = true; break; }
            if (!dup) seen[n++] = c;
        }
    }

    /// The id every lane computes for one transfer seen on the source chain:
    /// the source contract's own running number, not a tx hash or log
    /// position, which can change if the source chain reorganises.
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount));
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        if (!isLane[msg.sender]) revert NotLane();
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        if (attestedBy[id][msg.sender] && _genAt[id][msg.sender] == laneGen[msg.sender]) revert Twice();
        attestedBy[id][msg.sender] = true;
        Transfer storage t = transfers[id];
        address c = laneControllerOf(msg.sender);
        attestedByController[id][c] = true;
        _attesters[id].push(msg.sender);
        _controllerAt[id][msg.sender] = c;
        _genAt[id][msg.sender] = laneGen[msg.sender];
        uint8 live = liveAttestations(id);
        t.attestations = live;
        // (re)start the quarantine when the threshold is reached, or reached again after a lane removal
        if (live >= threshold && (t.readyFrom == 0 || t.readyEpoch != removalEpoch)) {
            t.readyFrom = uint64(block.timestamp);
            t.readyEpoch = removalEpoch;
        }
        emit Attested(id, msg.sender, live, srcChainId, srcContract, srcNonce, sender, to, amount);
    }

    function _removed(address lane) private {
        laneGen[lane] += 1;
        removalEpoch += 1;
    }

    /// Independent attestations of a transfer that still count: distinct controllers (as recorded at
    /// attest time) of the lanes that attested it and are still on.
    function liveAttestations(bytes32 id) public view returns (uint8 n) {
        address[] storage a = _attesters[id];
        address[] memory seen = new address[](a.length);
        for (uint256 i = 0; i < a.length; i++) {
            if (!isLane[a[i]] || _genAt[id][a[i]] != laneGen[a[i]]) continue;
            address c = _controllerAt[id][a[i]];
            bool dup;
            for (uint256 k = 0; k < n; k++) if (seen[k] == c) { dup = true; break; }
            if (!dup) seen[n++] = c;
        }
    }

    function veto(bytes32 id, string calldata reason) external {
        if (!isVetoer[msg.sender]) revert NotVetoer();
        Transfer storage t = transfers[id];
        if (t.released) revert Blocked();
        t.vetoed = true;
        emit Vetoed(id, msg.sender, reason);
    }

    /// A marker marks `who`: release() then refuses (Blocked) every transfer
    /// whose source sender or ZETAPHY recipient is `who`, until governance
    /// untrips it. That is all a marker can do: it cannot attest, veto,
    /// release, mint, pause or move any funds, and a mark loses nothing (the
    /// transfer stays and comes out once the mark is lifted). So a stolen or
    /// misused marker key can at worst delay some addresses' transfers until
    /// governance removes the marker (setMarker), which lifts all its marks.
    /// A mark that counts is kept by its first marker (another marker's
    /// mark does not replace it).
    function trip(address who) external {
        if (!isMarker[msg.sender]) revert NotMarker();
        if (tripped(who)) return;
        trippedBy[who] = msg.sender;
        emit Tripped(who, msg.sender);
    }

    /// Anyone may release a transfer that passed every check.
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        Transfer storage t = transfers[id];
        if (t.released || t.vetoed || t.held || tripped(sender) || tripped(to)) revert Blocked();
        if (t.readyFrom == 0 || block.timestamp < t.readyFrom + quarantine || liveAttestations(id) < threshold) revert NotReady();
        uint8 what = flaggedParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatFlagged(what);
        what = heldParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatHeld(what);
        t.released = true;
        guard.inbound(route, to, amount);
        emit Released(id, to, amount);
    }

    /// 0 when no party of this transfer has an enforced flag, else which one
    /// has (see ThreatFlagged). NeuroLane watchers ask this before they attest.
    function flaggedParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, true);
    }

    /// 0 when no party of this transfer is held, else which one is (the
    /// registry's is*Held views: past holdDelay, fast lane or holdNow). A
    /// transfer with a held party is not released; NeuroLane watchers ask this
    /// before they release.
    function heldParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, false);
    }

    function _party(uint256 srcChainId, address srcContract, address sender, address to, bool enforced) private view returns (uint8) {
        IThreatFlags r = threats;
        if (address(r) == address(0)) return 0;
        bool f;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, sender) : r.isAddressHeld(srcChainId, sender);
        if (f) return 1;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, srcContract) : r.isAddressHeld(srcChainId, srcContract);
        if (f) return 2;
        (f, ) = enforced ? r.isContractEnforced(to) : r.isContractHeld(to);
        if (f) return 3;
        return 0;
    }

    function status(bytes32 id) external view returns (uint8 attestations, bool released, bool vetoed, uint64 readyAt) {
        Transfer storage t = transfers[id];
        return (liveAttestations(id), t.released, t.vetoed, t.readyFrom == 0 ? 0 : t.readyFrom + quarantine);
    }
}

/// @title NeuroLane: Neuro runners as one of the airlock's bridges
/// @notice Runners watch the source chain's LockBox and each attest the
///         transfers they see. When `quorum` distinct proven runners attest
///         the same transfer, this lane attests it to the airlock. Runners
///         can also vote to veto a transfer still in quarantine.
///         While Neuro is paused (NeuroControl, if set) nothing is attested;
///         vetoes still work, since holding money back is always safe.
contract NeuroLane {
    IRunnerRecords public immutable runners;
    BridgeAirlock public immutable airlock;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    INeuroControl public immutable control; // zero: no pause check

    mapping(bytes32 => uint8) public votes;
    mapping(bytes32 => mapping(address => bool)) public votedBy;
    mapping(bytes32 => bool) public done;

    event RunnerAttested(bytes32 indexed id, address indexed runner, uint8 votes);

    /// The runner records decide what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return address(runners); }
    event RunnerVetoVote(bytes32 indexed id, address indexed runner, uint8 votes);

    error NotRunner();
    error Twice();
    error NeuroPaused();

    constructor(IRunnerRecords runners_, BridgeAirlock airlock_, uint8 quorum_, uint32 minAgreed_, INeuroControl control_) {
        require(quorum_ >= 2, "quorum");
        runners = runners_;
        airlock = airlock_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        control = control_;
    }

    function _runner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        _runner();
        if (address(control) != address(0) && control.paused()) revert NeuroPaused();
        bytes32 id = airlock.transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        bytes32 key = keccak256(abi.encode("attest", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerAttested(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.attest(srcChainId, srcContract, srcNonce, sender, to, amount);
        }
    }

    function voteVeto(bytes32 id, string calldata reason) external {
        _runner();
        bytes32 key = keccak256(abi.encode("veto", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerVetoVote(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.veto(id, reason);
        }
    }
}

/// @title LockBox: the source-chain side of the Neuro lane (test / testnet)
/// @notice Locks native coin and emits what the lanes need to attest. Lanes
///         attest (chainid, this contract, nonce, sender, to, amount).
contract LockBox {
    uint256 public nonce;
    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);

    function lock(address to) external payable {
        require(msg.value > 0 && to != address(0), "lock");
        emit Locked(nonce++, msg.sender, to, msg.value);
    }
}

contracts/BridgeGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// ThreatRegistry's hold view for code on ZETAPHY (Reason as its uint8 value):
/// true once a flag on its address or code is the registry's holdDelay old, or at
/// once through the registry's fast lane or a guardian's holdNow.
interface IContractThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// BridgeAirlock's count of lanes with distinct controllers.
interface IIndependentLanes {
    function independentLanes() external view returns (uint256);
}

/// @title BridgedToken: a token that exists on ZETAPHY only through a bridge
/// @notice Only its BridgeGuard can mint (assets arriving) or burn (leaving).
contract BridgedToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    address public immutable guard;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory n, string memory s, uint8 d, address guard_) {
        name = n; symbol = s; decimals = d; guard = guard_;
    }

    modifier onlyGuard() { require(msg.sender == guard, "only guard"); _; }

    function mint(address to, uint256 v) external onlyGuard { totalSupply += v; balanceOf[to] += v; emit Transfer(address(0), to, v); }
    function burn(address from, uint256 v) external onlyGuard {
        require(balanceOf[from] >= v, "balance");
        balanceOf[from] -= v; totalSupply -= v; emit Transfer(from, address(0), v);
    }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v); return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v; balanceOf[to] += v; emit Transfer(f, to, v);
    }
}

/// @title BridgeGuard: limits and a stop button for every bridge route (stage 3)
/// @notice A bridge adapter (Hyperlane warp route, IBC hook, ...) never mints
///         or burns directly: it asks this guard, which enforces
///           - a daily limit per route and direction, so a hacked bridge can
///             lose at most one day's limit, not everything;
///           - a pause that only guardians can pull and only governance can
///             release. Pausing stops the bridges, never the chain.
///           - vaccine (with a ThreatRegistry set): no coins to, or out of, an
///             address or contract the registry holds (is*Held: a flag that is
///             holdDelay old, e.g. 10 minutes, or held at once by the fast lane or
///             a guardian's holdNow; two runners alone cannot freeze anyone at
///             once). This is a hold, not a loss:
///               - inbound: the mint is QUEUED, not reverted (InboundHeld, an id
///                 in `held`). The adapter's message is delivered, so nothing
///                 depends on an adapter retrying. Anyone calls releaseHeld(id)
///                 once the hold ends (the flag cleared, or governance protects
///                 the key); it then passes the pause, the route (still enabled)
///                 and the route's daily limit like any inbound. Governance can
///                 dropHeld(id) a queued mint (e.g. from a hacked adapter).
///               - outbound: the call reverts (the burn simply did not happen;
///                 the holder keeps the coins).
///             The adapter itself is NOT checked: governance chose it and can
///             disable its route; a runner flag on its code hash or address must
///             not be able to freeze a whole route.
///         Opening gates (a route stays closed until they hold):
///           - an audit on record: setAudit(https url, sha256 of the report)
///             before any route can be enabled;
///           - the route's adapter is a BridgeAirlock with at least 2 lanes
///             whose controllers differ (independentLanes() >= 2);
///           - a hard cap, maxDailyLimit, over every route's daily limit and over all routes together per day. It
///             starts at 1,000 whole tokens (createToken), is lowered at once,
///             and is raised only by governance, at most x2 per step (or back up
///             to the cap before a lowerMaxDailyLimit cut), each step 7 days after
///             it was proposed: caps grow gradually and in public.
///         Outbound-only routes (setOutboundRoute): an adapter that only burns, e.g. a
///         HyperlaneOutbox sending the token back to its source chain. inbound() refuses
///         such a route, so it never mints and needs no airlock; enabling it still needs the
///         audit on record and a daily limit within the hard cap. An id is either kind, for good.
///         Governance should be the ZetaphyTimelock (proposers: the chain's gov
///         module or a multisig). Guardians act at once, but only to reduce risk:
///         pause, lowerMaxDailyLimit, cancelMaxDailyLimit, disableRoute.
contract BridgeGuard {
    struct Route {
        address adapter;      // the only caller allowed for this route
        uint128 dailyLimit;   // per direction, in token units
        uint128 inToday;
        uint128 outToday;
        uint64 day;
        bool enabled;
    }

    BridgedToken public token;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    mapping(bytes32 => Route) public routes;
    IContractThreats public threats; // zero: no vaccine check
    address[] private guardianList;  // everyone ever made a guardian (guardians() filters the current ones)

    /// The audit the bridge opened on: where to read it and the sha256 of the report.
    string public auditUrl;
    bytes32 public auditSha256;
    /// Hard cap over every route's daily limit (token units).
    uint128 public maxDailyLimit;
    uint128 public pendingMaxDailyLimit;
    uint64 public pendingMaxAt;      // when the pending raise may be applied (0: none)
    uint64 public constant CAP_DELAY = 7 days;
    /// The highest cap before lowerMaxDailyLimit cut it (0: none). Governance may
    /// propose a raise back up to it in one step (still CAP_DELAY), so a guardian's
    /// emergency cut (even to 0) is never undone only by x2 steps of 7 days each.
    uint128 public restoreMaxDailyLimit;
    uint128 public constant STARTER_UNITS = 1000; // whole tokens: the cap at createToken
    /// Every route together, per direction and day: the hard cap binds the
    /// guard, so more routes cannot multiply it.
    uint128 public totalInToday;
    uint128 public totalOutToday;
    uint64 public totalDay;

    /// Inbound mints held by the vaccine, waiting for releaseHeld.
    struct HeldMint {
        bytes32 route;
        address to;
        uint256 amount;
        bool done;       // released or dropped
    }
    HeldMint[] public held;
    /// Routes that only burn (setOutboundRoute): inbound() refuses them.
    mapping(bytes32 => bool) public outboundOnly;

    event RouteSet(bytes32 indexed id, address adapter, uint128 dailyLimit, bool enabled);
    event GovernanceSet(address governance);
    event AuditSet(string url, bytes32 sha256);
    event MaxDailyLimitProposed(uint128 value, uint64 at);
    event MaxDailyLimitSet(uint128 value);
    event MaxDailyLimitCancelled();
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event Inbound(bytes32 indexed route, address indexed to, uint256 amount);
    event Outbound(bytes32 indexed route, address indexed from, uint256 amount);
    event ThreatsSet(address registry);
    event InboundHeld(uint256 indexed id, bytes32 indexed route, address indexed to, uint256 amount);
    event HeldReleased(uint256 indexed id, address indexed to, uint256 amount);
    event HeldDropped(uint256 indexed id);
    event OutboundOnly(bytes32 indexed id);

    error NotGovernance();
    error NotGuardian();
    error NotAdapter();
    error BridgePaused();
    error OverLimit(uint256 remaining);
    error FlaggedContract(address who);
    error NoHeld();
    error AuditMissing();
    error NeedLanes(uint256 independent);
    error OverCap(uint128 cap);
    error CapStep(uint128 most);
    error TooEarly(uint64 at);
    error NoPending();
    error RouteKind();

    constructor(address governance_) {
        governance = governance_;
    }

    /// One-time: the guard deploys and owns its token.
    function createToken(string calldata n, string calldata s, uint8 d) external returns (BridgedToken) {
        if (msg.sender != governance) revert NotGovernance();
        require(address(token) == address(0), "token exists");
        require(d <= 30, "decimals");
        token = new BridgedToken(n, s, d, address(this));
        maxDailyLimit = uint128(uint256(STARTER_UNITS) * (uint256(10) ** d));
        emit MaxDailyLimitSet(maxDailyLimit);
        return token;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool allowed) external onlyGov {
        if (allowed && !guardian[who]) {
            bool known = false;
            for (uint256 i = 0; i < guardianList.length; i++) if (guardianList[i] == who) { known = true; break; }
            if (!known) { require(guardianList.length < 32, "guardians"); guardianList.push(who); }
        }
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    /// The current guardians.
    function guardians() external view returns (address[] memory out) {
        uint256 n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) n++;
        out = new address[](n);
        n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) out[n++] = guardianList[i];
    }

    /// The audit report the bridge opens on (an https url and the report's sha256).
    function setAudit(string calldata url, bytes32 sha) external onlyGov {
        bytes memory u = bytes(url);
        require(sha != bytes32(0) && u.length > 8 && u.length <= 200 && u[0] == "h" && u[1] == "t" && u[2] == "t" && u[3] == "p"
            && u[4] == "s" && u[5] == ":" && u[6] == "/" && u[7] == "/", "audit: https url and sha256");
        auditUrl = url;
        auditSha256 = sha;
        emit AuditSet(url, sha);
    }

    /// Lowering the cap applies at once (and cancels a pending raise); a raise
    /// (at most x2 of the cap, or up to restoreMaxDailyLimit) waits CAP_DELAY,
    /// then anyone applies it.
    function proposeMaxDailyLimit(uint128 v) external onlyGov {
        if (v <= maxDailyLimit) {
            maxDailyLimit = v;
            pendingMaxAt = 0;
            pendingMaxDailyLimit = 0;
            emit MaxDailyLimitSet(v);
            return;
        }
        uint256 most = uint256(maxDailyLimit) * 2;
        if (restoreMaxDailyLimit > most) most = restoreMaxDailyLimit;
        if (v > most) revert CapStep(uint128(most));
        pendingMaxDailyLimit = v;
        pendingMaxAt = uint64(block.timestamp) + CAP_DELAY;
        emit MaxDailyLimitProposed(v, pendingMaxAt);
    }

    function applyMaxDailyLimit() external {
        uint64 at = pendingMaxAt;
        if (at == 0) revert NoPending();
        if (block.timestamp < at) revert TooEarly(at);
        maxDailyLimit = pendingMaxDailyLimit;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        if (maxDailyLimit >= restoreMaxDailyLimit) restoreMaxDailyLimit = 0;
        emit MaxDailyLimitSet(maxDailyLimit);
    }

    /// Governance or a guardian: drop a pending raise (reducing risk never waits).
    function cancelMaxDailyLimit() external {
        _govOrGuardian();
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitCancelled();
    }

    // ---- emergency: guardians act at once, but only to reduce risk ----
    // With governance behind a timelock (ZetaphyTimelock, 48 h), everything that
    // raises risk or changes rules (enable a route, raise a cap, unpause, new
    // guardians, audit, registry, governance) waits the delay. These calls only
    // shrink what can cross, so a guardian (a multisig) makes them at once.

    /// Lower the hard cap (never raise it) and drop a pending raise.
    function lowerMaxDailyLimit(uint128 v) external {
        _govOrGuardian();
        if (v >= maxDailyLimit) revert CapStep(maxDailyLimit);
        if (maxDailyLimit > restoreMaxDailyLimit) restoreMaxDailyLimit = maxDailyLimit;
        maxDailyLimit = v;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitSet(v);
    }

    /// Close a route (its adapter and limit are kept; enabling it again is governance's).
    function disableRoute(bytes32 id) external {
        _govOrGuardian();
        Route storage r = routes[id];
        r.enabled = false;
        emit RouteSet(id, r.adapter, r.dailyLimit, false);
    }

    function _govOrGuardian() private view {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
    }
    /// The ThreatRegistry whose flags refuse coins (zero turns the check off).
    function setThreats(IContractThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Enabling needs the audit on record, a daily limit within the hard cap and
    /// an adapter that is a BridgeAirlock with 2+ independent lanes. Disabling (or
    /// setting a closed route up) needs none of them: closing always works.
    function setRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        if (outboundOnly[id]) revert RouteKind();
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            uint256 n = _independentLanes(adapter);
            if (n < 2) revert NeedLanes(n);
        }
        Route storage r = routes[id];
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// An outbound-only route: its adapter may only burn (outbound); inbound() refuses it.
    /// Enabling needs the audit on record and a daily limit within the hard cap, and an
    /// adapter that is a contract; an id used by an inbound route is refused (RouteKind).
    function setOutboundRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        Route storage r = routes[id];
        if (!outboundOnly[id]) {
            if (r.adapter != address(0)) revert RouteKind();
            outboundOnly[id] = true;
            emit OutboundOnly(id);
        }
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            if (adapter.code.length == 0) revert NotAdapter();
        }
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// Any guardian (or governance) can stop all bridges at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Restarting needs governance: a stolen guardian key can only stop things.
    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    /// A held recipient: the mint is queued (InboundHeld), not reverted, and
    /// counts against the daily limit only when it is released.
    function inbound(bytes32 id, address to, uint256 amount) external {
        Route storage r = _use(id, amount, true);
        if (_isHeld(to)) {
            held.push(HeldMint(id, to, amount, false));
            emit InboundHeld(held.length - 1, id, to, amount);
            return;
        }
        _total(amount, true);
        r.inToday += uint128(amount);
        token.mint(to, amount);
        emit Inbound(id, to, amount);
    }

    /// Anyone: mint a queued inbound once its recipient is no longer held.
    /// Passes the pause, the route being enabled and its daily limit, as inbound does.
    function releaseHeld(uint256 hid) external {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        HeldMint storage h = held[hid];
        if (paused) revert BridgePaused();
        Route storage r = routes[h.route];
        if (!r.enabled || outboundOnly[h.route]) revert NotAdapter();
        _clean(h.to);
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint128 lim = _limit(r);
        if (r.inToday + h.amount > lim) revert OverLimit(lim > r.inToday ? lim - r.inToday : 0);
        _total(h.amount, true);
        h.done = true;
        r.inToday += uint128(h.amount);
        token.mint(h.to, h.amount);
        emit HeldReleased(hid, h.to, h.amount);
        emit Inbound(h.route, h.to, h.amount);
    }

    /// Governance drops a queued mint (e.g. one a hacked adapter sent).
    function dropHeld(uint256 hid) external onlyGov {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        held[hid].done = true;
        emit HeldDropped(hid);
    }

    function heldCount() external view returns (uint256) {
        return held.length;
    }

    function outbound(bytes32 id, address from, uint256 amount) external {
        Route storage r = _use(id, amount, false);
        _clean(from);
        _total(amount, false);
        r.outToday += uint128(amount);
        token.burn(from, amount);
        emit Outbound(id, from, amount);
    }

    function remaining(bytes32 id) external view returns (uint256 inLeft, uint256 outLeft) {
        Route storage r = routes[id];
        bool fresh = r.day != uint64(block.timestamp / 1 days);
        uint128 lim = _limit(r);
        uint128 i = fresh ? 0 : r.inToday;
        uint128 o = fresh ? 0 : r.outToday;
        inLeft = lim > i ? lim - i : 0;
        outLeft = lim > o ? lim - o : 0;
    }

    /// A route's daily limit, never above the hard cap.
    function _limit(Route storage r) private view returns (uint128) {
        return r.dailyLimit < maxDailyLimit ? r.dailyLimit : maxDailyLimit;
    }

    /// The hard cap over all routes together (per direction, per day).
    function _total(uint256 amount, bool isIn) private {
        uint64 today = uint64(block.timestamp / 1 days);
        if (totalDay != today) { totalDay = today; totalInToday = 0; totalOutToday = 0; }
        uint256 used = isIn ? totalInToday : totalOutToday;
        uint256 cap = maxDailyLimit;
        if (used + amount > cap) revert OverLimit(cap > used ? cap - used : 0);
        if (isIn) totalInToday = uint128(used + amount); else totalOutToday = uint128(used + amount);
    }

    function _independentLanes(address adapter) private view returns (uint256) {
        if (adapter.code.length == 0) return 0;
        (bool ok, bytes memory ret) = adapter.staticcall(abi.encodeCall(IIndependentLanes.independentLanes, ()));
        if (!ok || ret.length < 32) return 0;
        return abi.decode(ret, (uint256));
    }

    /// Vaccine: holds back a party (the coins' owner) that the registry holds.
    function _clean(address who) private view {
        if (_isHeld(who)) revert FlaggedContract(who);
    }

    function _isHeld(address who) private view returns (bool f) {
        IContractThreats t = threats;
        if (address(t) == address(0)) return false;
        (f, ) = t.isContractHeld(who);
    }

    function _use(bytes32 id, uint256 amount, bool isIn) private returns (Route storage r) {
        if (paused) revert BridgePaused();
        r = routes[id];
        if (!r.enabled || msg.sender != r.adapter || (isIn && outboundOnly[id])) revert NotAdapter();
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint256 used = isIn ? r.inToday : r.outToday;
        uint256 lim = _limit(r);
        if (used + amount > lim) revert OverLimit(lim > used ? lim - used : 0);
    }
}

contracts/BtcLightClient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BtcLightClient: Bitcoin headers and SPV proofs on ZETAPHY's EVM (prototype)
/// @notice For BTC -> ZETAPHY deposits: a contract on ZETAPHY learns Bitcoin's header chain from
///         anyone (permissionless relaying) and proves a transaction's inclusion. Checks per header,
///         as Bitcoin Core does for mainnet:
///           - double-SHA256 of the 80-byte header is at or below the target its `bits` encode,
///             and the target is at most the proof-of-work limit;
///           - it links to a known header (prev hash);
///           - difficulty: `bits` equals the parent's, except at heights divisible by 2016, where it
///             must equal the retarget (CalculateNextWorkRequired: parent target x actual timespan of
///             the period / two weeks, the timespan clamped to [1/4, 4] x two weeks, capped at the
///             limit, re-encoded compactly);
///           - timestamp above the median of the previous 11 (once 11 are known) and at most two
///             hours ahead of this chain's clock.
///         The best chain is the one with the most cumulative work (forks are kept; the tip moves to
///         the heavier branch). SPV: a transaction (its raw bytes, so 64-byte txs are refused) is
///         included in a block on the best chain with at least `minConfirmations` blocks on top.
///         Trust: the checkpoint (a recent header, its height, the period start time) is pinned at
///         deployment; after it, only Bitcoin's proof of work. An SPV light client accepts the chain
///         with the most work it was SHOWN: a relayer can withhold headers (liveness), and a miner
///         coalition can produce a fake branch at the cost of real work - deposits must wait for
///         enough confirmations for their value. Not checked: version rules (BIP 34/65/66/9),
///         transaction validity (only inclusion), and testnet's 20-minute rule (mainnet only).
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract BtcLightClient {
    struct Header {
        bytes32 prev;
        bytes32 merkleRoot;
        uint64 height;
        uint32 time;
        uint32 bits;
        uint32 periodStart;   // time of the first block of this header's 2016-block period
        uint256 work;         // cumulative work from the checkpoint
    }

    uint256 public constant POW_LIMIT = 0x00000000ffff0000000000000000000000000000000000000000000000000000;
    uint256 public constant RETARGET = 2016;
    uint256 public constant TIMESPAN = 14 days;

    mapping(bytes32 => Header) private headers; // by block hash, internal byte order (as in `prev`)
    bytes32 public tip;
    bytes32 public immutable checkpoint;
    uint256 public immutable maxReorgWalk;

    event HeaderAdded(bytes32 indexed hash, uint64 height, uint256 work);
    event NewTip(bytes32 indexed hash, uint64 height);

    error BadHeader(uint256 code); // 1 length 2 unknown parent 3 bits 4 work 5 time 6 duplicate
    error BadProof(uint256 code);  // 1 unknown block 2 not on the best chain 3 confirmations 4 merkle 5 64-byte tx

    /// @param hash checkpoint block hash (internal order); @param periodStart time of block height - height % 2016
    constructor(bytes32 hash, uint64 height, uint32 time, uint32 bits, uint32 periodStart, uint256 maxReorgWalk_) {
        headers[hash] = Header(bytes32(0), bytes32(0), height, time, bits, periodStart, 1);
        tip = hash;
        checkpoint = hash;
        maxReorgWalk = maxReorgWalk_;
        emit NewTip(hash, height);
    }

    // ------------------------------------------------------------------ headers

    /// Adds consecutive raw headers (80 bytes each); each must link to a known header.
    function addHeaders(bytes calldata raw) external {
        if (raw.length == 0 || raw.length % 80 != 0) revert BadHeader(1);
        for (uint256 o = 0; o < raw.length; o += 80) _add(raw[o:o + 80]);
    }

    function _add(bytes calldata h) private {
        bytes32 hash = dsha(h);
        if (headers[hash].work != 0) revert BadHeader(6);
        bytes32 prev = bytes32(h[4:36]);
        Header storage p = headers[prev];
        if (p.work == 0) revert BadHeader(2);
        uint32 time = _le32(h, 68);
        uint32 bits = _le32(h, 72);
        uint64 height = p.height + 1;

        uint256 target = targetOf(bits);
        if (target == 0 || target > POW_LIMIT) revert BadHeader(3);
        if (_reverse(hash) > target) revert BadHeader(4);
        if (height % RETARGET == 0) {
            if (bits != nextBits(p.bits, p.periodStart, p.time)) revert BadHeader(3);
        } else if (bits != p.bits) revert BadHeader(3);
        if (time > block.timestamp + 2 hours || time <= _medianTimePast(prev)) revert BadHeader(5);

        uint256 work = p.work + workOf(target);
        headers[hash] = Header(prev, bytes32(h[36:68]), height, time, bits, height % RETARGET == 0 ? time : p.periodStart, work);
        emit HeaderAdded(hash, height, work);
        if (work > headers[tip].work) {
            tip = hash;
            emit NewTip(hash, height);
        }
    }

    /// Median of the last 11 block times ending at `h` (0 while fewer than 11 are known).
    function _medianTimePast(bytes32 h) private view returns (uint256) {
        uint256[11] memory t;
        for (uint256 i = 0; i < 11; i++) {
            Header storage x = headers[h];
            if (x.work == 0 || (x.prev == bytes32(0) && i < 10)) return 0;
            t[i] = x.time;
            h = x.prev;
        }
        for (uint256 i = 1; i < 11; i++) {
            uint256 v = t[i];
            uint256 j = i;
            while (j > 0 && t[j - 1] > v) { t[j] = t[j - 1]; j--; }
            t[j] = v;
        }
        return t[5];
    }

    // ------------------------------------------------------------------ SPV

    /// The txid (internal order) of a raw non-witness transaction included in block `blockHash`
    /// at `index` (siblings: the Merkle branch, bottom-up), with at least `minConfirmations` on the
    /// best chain (1 = the block itself is the tip).
    function verifyTx(bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations)
        external view returns (bytes32 txid)
    {
        if (rawTx.length == 64) revert BadProof(5); // a 64-byte "tx" could be an inner Merkle node
        txid = dsha(rawTx);
        _included(txid, blockHash, index, siblings, minConfirmations);
    }

    /// Inclusion of a txid (internal order); the caller must know the tx is not 64 bytes long.
    function verifyTxid(bytes32 txid, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations)
        external view returns (bool)
    {
        _included(txid, blockHash, index, siblings, minConfirmations);
        return true;
    }

    function _included(bytes32 txid, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations) private view {
        Header storage b = headers[blockHash];
        if (b.work == 0 || blockHash == checkpoint) revert BadProof(1);
        Header storage t = headers[tip];
        if (t.height < b.height || t.height - b.height + 1 < minConfirmations) revert BadProof(3);
        if (!onBestChain(blockHash)) revert BadProof(2);
        bytes32 node = txid;
        uint256 i = index;
        for (uint256 k = 0; k < siblings.length; k++) {
            node = i & 1 == 1 ? dsha(abi.encodePacked(siblings[k], node)) : dsha(abi.encodePacked(node, siblings[k]));
            i >>= 1;
        }
        if (i != 0 || node != b.merkleRoot) revert BadProof(4);
    }

    /// Whether `hash` is an ancestor of (or is) the tip, within maxReorgWalk blocks.
    function onBestChain(bytes32 hash) public view returns (bool) {
        Header storage b = headers[hash];
        if (b.work == 0) return false;
        bytes32 h = tip;
        uint64 target = b.height;
        for (uint256 i = 0; i <= maxReorgWalk; i++) {
            Header storage x = headers[h];
            if (x.height == target) return h == hash;
            if (x.height < target || x.prev == bytes32(0)) return false;
            h = x.prev;
        }
        return false;
    }

    // ------------------------------------------------------------------ difficulty

    /// Bitcoin's compact target ("nBits") as an integer (0 for negative or overflowing encodings).
    function targetOf(uint32 bits) public pure returns (uint256) {
        uint256 exp = bits >> 24;
        uint256 mant = bits & 0x007fffff;
        if (bits & 0x00800000 != 0 || exp > 32) return 0;
        return exp <= 3 ? mant >> (8 * (3 - exp)) : mant << (8 * (exp - 3));
    }

    /// arith_uint256::GetCompact
    function compactOf(uint256 target) public pure returns (uint32) {
        uint256 size = 0;
        for (uint256 t = target; t > 0; t >>= 8) size++;
        uint256 c = size <= 3 ? target << (8 * (3 - size)) : target >> (8 * (size - 3));
        if (c & 0x00800000 != 0) { c >>= 8; size++; }
        return uint32(c | (size << 24));
    }

    /// CalculateNextWorkRequired (mainnet): bits of the first block of the next period.
    function nextBits(uint32 lastBits, uint256 firstTime, uint256 lastTime) public pure returns (uint32) {
        uint256 span = lastTime > firstTime ? lastTime - firstTime : 0;
        if (span < TIMESPAN / 4) span = TIMESPAN / 4;
        if (span > TIMESPAN * 4) span = TIMESPAN * 4;
        uint256 t = targetOf(lastBits) * span / TIMESPAN;
        if (t > POW_LIMIT) t = POW_LIMIT;
        return compactOf(t);
    }

    /// Expected hashes for a target: 2^256 / (target + 1).
    function workOf(uint256 target) public pure returns (uint256) {
        return (type(uint256).max - target) / (target + 1) + 1;
    }

    // ------------------------------------------------------------------ reading

    function header(bytes32 hash) external view returns (Header memory) {
        return headers[hash];
    }

    function tipHeight() external view returns (uint64) {
        return headers[tip].height;
    }

    function dsha(bytes memory b) public pure returns (bytes32) {
        return sha256(abi.encodePacked(sha256(b)));
    }

    function _le32(bytes calldata h, uint256 o) private pure returns (uint32) {
        return uint32(uint8(h[o])) | (uint32(uint8(h[o + 1])) << 8) | (uint32(uint8(h[o + 2])) << 16) | (uint32(uint8(h[o + 3])) << 24);
    }

    function _reverse(bytes32 x) private pure returns (uint256 v) {
        uint256 a = uint256(x);
        for (uint256 i = 0; i < 32; i++) { v = (v << 8) | (a & 0xff); a >>= 8; }
    }
}

