// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ISpvClient {
    function verifyTx(bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations)
        external view returns (bytes32 txid);
}

interface ISpvAirlock {
    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
}

/// @title BtcSpvLane: Bitcoin deposits to ZETAPHY, attested by proof of work instead of by signers
/// @notice A lane of a BTC route's BridgeAirlock (docs/SAPHAN-PROOFS.md), testnet only, not audited.
///         A deposit is a Bitcoin transaction (its non-witness serialization: what the txid hashes) with
///           - an output paying `custodyScript` (the route's custody, e.g. a federation's P2WSH), and
///           - an OP_RETURN output: "ZTPHY" (5 bytes) || the 20-byte ZETAPHY recipient.
///         Anyone hands it in with its block and Merkle branch; BtcLightClient checks the inclusion on the
///         heaviest chain with `minConfirmations`. The lane then attests to the airlock:
///           (BTC_CHAIN_ID, the custody's id, keccak256(txid, output index), sender 0, recipient, sats x 10^10)
///         (the bridged token has 18 decimals). The airlock still needs its other independent lane(s), the
///         quarantine and the threat checks before anything mints. Each (txid, output) attests once (the
///         airlock refuses a lane's second attestation of the same transfer).
///         What it does not do: send BTC back (that needs keys on Bitcoin; after an external audit).
contract BtcSpvLane {
    uint256 public constant BTC_CHAIN_ID = 0x425443;      // "BTC": the source "chain id" in transfer ids
    bytes5 public constant TAG = "ZTPHY";
    uint256 public constant SATS_TO_WEI = 1e10;

    ISpvClient public immutable client;
    ISpvAirlock public immutable airlock;
    bytes32 public immutable custodyHash;   // keccak256 of the custody output's scriptPubKey
    address public immutable custodyId;     // the transfer ids' "source contract": address(uint160(custodyHash))
    uint256 public immutable minConfirmations;
    uint256 public immutable minSats;

    event Deposit(bytes32 indexed txid, uint32 vout, address indexed to, uint64 sats);

    error BadTx(uint256 code); // 1 truncated 2 no custody output 3 no tag 4 too small 5 output index
    error NotCustody();

    constructor(ISpvClient client_, ISpvAirlock airlock_, bytes memory custodyScript, uint256 minConfirmations_, uint256 minSats_) {
        require(address(client_) != address(0) && address(airlock_) != address(0) && custodyScript.length > 0 && minConfirmations_ >= 1, "config");
        client = client_;
        airlock = airlock_;
        custodyHash = keccak256(custodyScript);
        custodyId = address(uint160(uint256(keccak256(custodyScript))));
        minConfirmations = minConfirmations_;
        minSats = minSats_;
    }

    /// Anyone: proves a deposit (output `vout` pays the custody) and attests it to the airlock.
    function attest(bytes calldata rawTx, uint32 vout, bytes32 blockHash, uint256 index, bytes32[] calldata siblings) external {
        (uint64 sats, address to) = parse(rawTx, vout);
        bytes32 txid = client.verifyTx(rawTx, blockHash, index, siblings, minConfirmations);
        emit Deposit(txid, vout, to, sats);
        airlock.attest(BTC_CHAIN_ID, custodyId, uint256(keccak256(abi.encode(txid, vout))), address(0), to, uint256(sats) * SATS_TO_WEI);
    }

    /// Output `vout`'s value when it pays the custody, and the recipient of the transaction's tagged OP_RETURN.
    function parse(bytes calldata t, uint32 vout) public view returns (uint64 sats, address to) {
        uint256 p = 4;                                    // version
        uint256 n;
        (n, p) = _varint(t, p);                           // inputs
        for (uint256 i = 0; i < n; i++) {
            p += 36;                                      // outpoint
            uint256 len;
            (len, p) = _varint(t, p);
            p += len + 4;                                 // script, sequence
        }
        uint256 outs;
        (outs, p) = _varint(t, p);
        if (vout >= outs) revert BadTx(5);
        bool paid;
        for (uint256 i = 0; i < outs; i++) {
            if (p + 8 > t.length) revert BadTx(1);
            uint64 value = _le64(t, p);
            p += 8;
            uint256 len;
            (len, p) = _varint(t, p);
            if (p + len > t.length) revert BadTx(1);
            bytes calldata script = t[p:p + len];
            if (i == vout) {
                if (keccak256(script) != custodyHash) revert BadTx(2);
                sats = value;
                paid = true;
            } else if (len == 27 && script[0] == 0x6a && script[1] == 0x19 && bytes5(script[2:7]) == TAG) {
                to = address(bytes20(script[7:27]));      // OP_RETURN, push 25: "ZTPHY" || recipient
            }
            p += len;
        }
        if (p + 4 != t.length) revert BadTx(1);           // locktime, nothing after
        if (!paid) revert BadTx(2);
        if (to == address(0)) revert BadTx(3);
        if (sats < minSats) revert BadTx(4);
    }

    function _varint(bytes calldata t, uint256 p) private pure returns (uint256 v, uint256 q) {
        if (p >= t.length) revert BadTx(1);
        uint8 f = uint8(t[p]);
        if (f < 0xfd) return (f, p + 1);
        uint256 size = f == 0xfd ? 2 : f == 0xfe ? 4 : 8;
        if (p + 1 + size > t.length) revert BadTx(1);
        for (uint256 i = 0; i < size; i++) v |= uint256(uint8(t[p + 1 + i])) << (8 * i);
        q = p + 1 + size;
    }

    function _le64(bytes calldata t, uint256 p) private pure returns (uint64 v) {
        for (uint256 i = 0; i < 8; i++) v |= uint64(uint8(t[p + i])) << uint64(8 * i);
    }
}

contracts/BugBounty.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IBBRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IBBReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

interface IBBIssuance {
    function draw(uint256 amount) external returns (uint256 paid);
}

/// @title BugBounty: bug-hunting jobs for browsers, paid after runners verify
/// @notice A sponsor posts a bounty on a testnet contract: the hash of a fuzz SPEC (the
///         contract's init code, the functions to call, the setup, and the invariant, e.g.
///         "the attacker must not end with more than it started"; see
///         zetaphy-hub/bounties/*.json) and a reward. Browsers fuzz the contract in an
///         in-memory EVM (the same EthereumJS EVM the contract tests use) and, on a finding:
///           1. `commitFinding`: keccak(findingHash, finder, salt, bountyId) and a deposit.
///              Findings are numbered in commit order, so whoever committed first is first;
///              watching someone's reveal cannot help a copier, whose commit is later.
///           2. `revealFinding` (a later block, within `revealWindow`): the finding itself
///              (the call sequence) is calldata of this transaction and in the event, so the
///              runners need no server to read it.
///           3. Bonded NeuroJobs runners with a track record (the bar ThreatRegistry uses:
///              active, at least `minAgreed` accepted verdicts, no more rejected than
///              accepted) replay it against the spec (`zetaphy bounty verify`) and `attest`.
///              `quorum` matching attestations accept or reject it.
///           4. `claim`: the earliest accepted finding (every earlier one rejected or never
///              revealed) gets the reward, plus the bounty's subsidy from UsefulIssuance, plus
///              its deposit back. Later accepted duplicates get their deposit back.
///         A rejected (or never revealed) finding's deposit grows the bounty's reward for its
///         winner; if nobody wins, it is burned at the refund rather than given to the sponsor,
///         and once the bounty is paid or refunded it is burned at once (BB-1, BB-2).
///         Finding slots: the sponsor cannot commit to its own bounty, one address holds at most
///         MAX_PER_FINDER commitments per bounty, and only findings still in play (not rejected,
///         closed or past their reveal window unrevealed) count against MAX_FINDINGS, so junk
///         commitments free their slot when their reveal window ends (BB-1). Outcomes feed
///         WorkerReputation (bugValid / bugInvalid). Governance only sets the subsidy of a
///         bounty and the deposit; it cannot take a bounty's reward, which only goes to a
///         verified finding or back to the sponsor after the bounty ended.
contract BugBounty {
    uint8 internal constant BUG_VALID = 4;
    uint8 internal constant BUG_INVALID = 5;
    uint256 public constant MAX_FINDINGS = 32;      // findings in play at once, per bounty
    uint256 public constant MAX_COMMITS = 256;      // all commitments ever, per bounty (bounds the loops)
    uint256 public constant MAX_PER_FINDER = 4;     // commitments per address, per bounty
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    enum State { None, Committed, Revealed, Accepted, Rejected, Paid, Closed }

    struct Bounty {
        address sponsor;
        uint64 deadline;     // last moment to commit a finding
        bool paid;
        bool refunded;
        uint128 reward;
        uint128 subsidy;     // drawn from UsefulIssuance on payout (set by governance)
        bytes32 specHash;    // keccak256 of the spec file
        string specURI;
        uint256[] findings;
    }

    struct Finding {
        uint256 bounty;
        address finder;
        uint64 committedAt;
        uint64 commitBlock;
        uint64 revealedAt;
        State state;
        uint8 yes;
        uint8 no;
        uint128 deposit;
        bytes32 commitment;
        bytes32 findingHash;
    }

    IBBRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    address public governance;
    IBBReputation public reputation;
    IBBIssuance public issuance;
    uint128 public findingDeposit;
    uint32 public revealWindow;
    uint32 public judgeWindow;
    /// New bounties and new findings stop while paused (reveals, votes, claims, refunds go on, so
    /// nothing is stuck). `zetaphy deploy-useful-work` deploys it paused; governance opens it.
    bool public paused;
    address public guardian;           // may pause (never unpause): a fast brake for governance

    Bounty[] private _bounties;
    Finding[] private _findings;
    mapping(uint256 => mapping(address => bool)) public attested;
    mapping(address => uint256) public owed;
    /// Part of a bounty's reward that came from forfeited deposits: never refunded to the sponsor.
    mapping(uint256 => uint256) public forfeitedOf;
    mapping(uint256 => mapping(address => uint256)) public commitsBy;
    uint256 public burned;

    event BountyPosted(uint256 indexed id, address indexed sponsor, bytes32 specHash, string specURI, uint256 reward, uint64 deadline);
    event SubsidySet(uint256 indexed id, uint256 subsidy);
    event FindingCommitted(uint256 indexed findingId, uint256 indexed bounty, address indexed finder);
    event FindingRevealed(uint256 indexed findingId, uint256 indexed bounty, address indexed finder, bytes finding);
    event Attested(uint256 indexed findingId, address indexed runner, bool valid);
    event FindingJudged(uint256 indexed findingId, bool valid);
    event BountyPaid(uint256 indexed id, uint256 indexed findingId, address indexed finder, uint256 amount);
    event BountyRefunded(uint256 indexed id, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);
    event PausedSet(bool paused);
    event GuardianSet(address guardian);
    event GovernanceSet(address governance);
    event Burned(uint256 indexed bountyId, uint256 amount);

    error Paused();
    error NotGovernance();
    error NotRunner();
    error BadValue();
    error BadBounty();
    error BadFinding();
    error Closed();
    error TooEarly();
    error TooMany();
    error BadReveal();
    error AlreadyVoted();
    error Nothing();

    constructor(IBBRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, IBBReputation reputation_,
        IBBIssuance issuance_, uint128 findingDeposit_, uint32 revealWindow_, uint32 judgeWindow_)
    {
        if (quorum_ == 0 || revealWindow_ == 0 || judgeWindow_ == 0) revert BadValue();
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        reputation = reputation_;
        issuance = issuance_;
        findingDeposit = findingDeposit_;
        revealWindow = revealWindow_;
        judgeWindow = judgeWindow_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    /// UsefulIssuance.draw pays through here.
    receive() external payable {}

    // ---------------------------------------------------------------- bounties

    function post(bytes32 specHash, string calldata specURI, uint64 duration) external payable returns (uint256 id) {
        if (paused) revert Paused();
        if (msg.value == 0 || specHash == bytes32(0) || duration == 0 || bytes(specURI).length > 256) revert BadValue();
        id = _bounties.length;
        Bounty storage b = _bounties.push();
        b.sponsor = msg.sender;
        b.deadline = uint64(block.timestamp + duration);
        b.reward = uint128(msg.value);
        b.specHash = specHash;
        b.specURI = specURI;
        emit BountyPosted(id, msg.sender, specHash, specURI, msg.value, b.deadline);
    }

    function setSubsidy(uint256 id, uint128 subsidy) external onlyGovernance {
        _bounty(id).subsidy = subsidy;
        emit SubsidySet(id, subsidy);
    }

    function setFindingDeposit(uint128 d) external onlyGovernance {
        findingDeposit = d;
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceSet(next);
    }

    /// Governance pauses or unpauses; the guardian may only pause.
    function setPaused(bool p) external {
        if (msg.sender != governance && !(p && msg.sender == guardian && guardian != address(0))) revert NotGovernance();
        paused = p;
        emit PausedSet(p);
    }

    function setGuardian(address g) external onlyGovernance {
        guardian = g;
        emit GuardianSet(g);
    }

    // ---------------------------------------------------------------- findings

    /// keccak(abi.encode(findingHash, finder, salt, bountyId)): bound to the finder, so a copy is useless.
    function commitmentOf(bytes32 findingHash, address finder, bytes32 salt, uint256 bountyId) public pure returns (bytes32) {
        return keccak256(abi.encode(findingHash, finder, salt, bountyId));
    }

    function commitFinding(uint256 bountyId, bytes32 commitment) external payable returns (uint256 fid) {
        if (paused) revert Paused();
        Bounty storage b = _bounty(bountyId);
        if (b.paid || b.refunded || block.timestamp > b.deadline) revert Closed();
        if (msg.value != findingDeposit || commitment == bytes32(0)) revert BadValue();
        if (msg.sender == b.sponsor) revert BadFinding();
        if (b.findings.length >= MAX_COMMITS || commitsBy[bountyId][msg.sender] >= MAX_PER_FINDER) revert TooMany();
        uint256 inPlay;
        for (uint256 i = 0; i < b.findings.length; i++) if (!_settledOut(_findings[b.findings[i]])) inPlay++;
        if (inPlay >= MAX_FINDINGS) revert TooMany();
        commitsBy[bountyId][msg.sender] += 1;
        fid = _findings.length;
        _findings.push(Finding({
            bounty: bountyId, finder: msg.sender, committedAt: uint64(block.timestamp), commitBlock: uint64(block.number),
            revealedAt: 0, state: State.Committed, yes: 0, no: 0, deposit: uint128(msg.value), commitment: commitment, findingHash: bytes32(0)
        }));
        b.findings.push(fid);
        emit FindingCommitted(fid, bountyId, msg.sender);
    }

    function revealFinding(uint256 fid, bytes calldata finding, bytes32 salt) external {
        Finding storage f = _finding(fid);
        if (msg.sender != f.finder) revert BadFinding();
        if (f.state != State.Committed) revert Closed();
        if (block.number <= f.commitBlock) revert TooEarly();
        if (block.timestamp > f.committedAt + revealWindow) revert Closed();
        bytes32 h = keccak256(finding);
        if (commitmentOf(h, msg.sender, salt, f.bounty) != f.commitment) revert BadReveal();
        f.findingHash = h;
        f.revealedAt = uint64(block.timestamp);
        f.state = State.Revealed;
        emit FindingRevealed(fid, f.bounty, msg.sender, finding);
    }

    /// A proven runner's verdict on a revealed finding (it replayed it against the spec).
    function attest(uint256 fid, bool valid) external {
        Finding storage f = _finding(fid);
        if (f.state != State.Revealed) revert Closed();
        if (block.timestamp > f.revealedAt + judgeWindow) revert Closed();
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == f.finder) revert NotRunner();
        if (attested[fid][msg.sender]) revert AlreadyVoted();
        attested[fid][msg.sender] = true;
        emit Attested(fid, msg.sender, valid);
        if (valid) f.yes++;
        else f.no++;
        if (f.yes >= quorum) {
            f.state = State.Accepted;
            emit FindingJudged(fid, true);
            _rep(f.finder, BUG_VALID, fid);
        } else if (f.no >= quorum) {
            f.state = State.Rejected;
            _forfeit(f.bounty, f.deposit); // the deposit of a wrong finding grows the reward
            emit FindingJudged(fid, false);
            _rep(f.finder, BUG_INVALID, fid);
        }
    }

    /// Pays an accepted finding: the reward if it is the earliest valid one, else its deposit.
    function claim(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.state != State.Accepted) revert Closed();
        Bounty storage b = _bounties[f.bounty];
        f.state = State.Paid;
        if (b.paid || b.refunded) {
            owed[f.finder] += f.deposit; // a later duplicate: its deposit back
            return;
        }
        for (uint256 i = 0; i < b.findings.length; i++) {
            uint256 other = b.findings[i];
            if (other == fid) break;
            if (!_settledOut(_findings[other])) revert TooEarly(); // an earlier finding is still open
        }
        b.paid = true;
        uint256 amount = b.reward;
        if (b.subsidy > 0 && address(issuance) != address(0)) {
            uint256 before = address(this).balance;
            try issuance.draw(b.subsidy) returns (uint256) {} catch {}
            amount += address(this).balance - before;
        }
        owed[f.finder] += amount + f.deposit;
        emit BountyPaid(f.bounty, fid, f.finder, amount);
    }

    /// After the judging window: an unjudged finding's deposit goes back (runners did not
    /// decide in time), and an unrevealed one is closed (its deposit grows the reward).
    function close(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.state == State.Committed) {
            if (block.timestamp <= f.committedAt + revealWindow) revert TooEarly();
            f.state = State.Closed;
            _forfeit(f.bounty, f.deposit);
            return;
        } else if (f.state == State.Revealed) {
            if (block.timestamp <= f.revealedAt + judgeWindow) revert TooEarly();
            owed[f.finder] += f.deposit;
        } else {
            revert Closed();
        }
        f.state = State.Closed;
    }

    /// The sponsor takes an unpaid reward back once nobody can still win it.
    function refund(uint256 bountyId) external {
        Bounty storage b = _bounty(bountyId);
        if (b.paid || b.refunded) revert Closed();
        if (block.timestamp <= uint256(b.deadline) + revealWindow + judgeWindow) revert TooEarly();
        for (uint256 i = 0; i < b.findings.length; i++) {
            State s = _findings[b.findings[i]].state;
            if (s == State.Accepted) revert TooEarly(); // a winner can still claim
        }
        b.refunded = true;
        uint256 forfeited = forfeitedOf[bountyId];
        owed[b.sponsor] += b.reward - forfeited;
        emit BountyRefunded(bountyId, b.reward - forfeited);
        _burn(bountyId, forfeited); // forfeited deposits never go to the sponsor (BB-1)
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: a}("");
        if (!ok) revert Nothing();
        emit Withdrawn(msg.sender, a);
    }

    // ---------------------------------------------------------------- reads

    function bountyCount() external view returns (uint256) {
        return _bounties.length;
    }

    function getBounty(uint256 id) external view returns (Bounty memory) {
        return _bounty(id);
    }

    function findingCount() external view returns (uint256) {
        return _findings.length;
    }

    function getFinding(uint256 fid) external view returns (Finding memory) {
        return _finding(fid);
    }

    // ---------------------------------------------------------------- internals

    function _bounty(uint256 id) internal view returns (Bounty storage) {
        if (id >= _bounties.length) revert BadBounty();
        return _bounties[id];
    }

    function _finding(uint256 fid) internal view returns (Finding storage) {
        if (fid >= _findings.length) revert BadFinding();
        return _findings[fid];
    }

    function _settledOut(Finding storage f) internal view returns (bool) {
        if (f.state == State.Rejected || f.state == State.Closed) return true;
        // committed and never revealed in time: out, even before anyone calls close()
        return f.state == State.Committed && block.timestamp > f.committedAt + revealWindow;
    }

    /// A forfeited deposit: grows the reward of a bounty that can still be won; burned if it is
    /// already paid or refunded (BB-2).
    function _forfeit(uint256 bountyId, uint128 amount) internal {
        Bounty storage b = _bounties[bountyId];
        if (b.paid || b.refunded) {
            _burn(bountyId, amount);
        } else {
            b.reward += amount;
            forfeitedOf[bountyId] += amount;
        }
    }

    function _burn(uint256 bountyId, uint256 amount) internal {
        if (amount == 0) return;
        burned += amount;
        emit Burned(bountyId, amount);
        (bool ok, ) = BURN.call{value: amount}("");
        if (!ok) revert Nothing();
    }

    function _rep(address w, uint8 kind, uint256 fid) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, bytes32(fid)) {} catch {}
    }
}

contracts/CircuitBreakable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of CircuitBreaker a protected protocol calls.
interface ICircuitBreaker {
    function isPaused(address protocol, bytes4 selector) external view returns (bool);
    function isTripped(address protocol) external view returns (bool);
    function recordOutflow(address asset, uint256 amount) external returns (bool payNow);
    function policyGovernance(address protocol) external view returns (address);
    function holdReviewOf(address protocol) external view returns (uint32);
}

/// @title CircuitBreakable: what a protocol adds to opt in to CircuitBreaker (docs/future/self-healing.md)
/// @notice Three things:
///           - `whenNotTripped(this.fn.selector)` on the functions the policy lists: they revert
///             with SelectorTripped while a live trip pauses that selector. Nothing else stops.
///           - `_outflow(asset, to, amount)` before every payment out of the protocol: it reports
///             the outflow to the breaker and returns whether to pay now. When it returns false
///             the payment is HELD here (`held`), the protocol keeps the funds, and the call goes
///             on (it must not revert, or the trip it may have caused would be undone).
///           - `_payOut(asset, to, amount)`: how the protocol pays (native or token), used to pay a
///             held outflow later.
///         A held outflow is paid by anyone with releaseHeld once the protocol is not tripped and
///         the policy's holdReview has passed since it was held (the payment is then accounted
///         like any other and may be held again if over the cap); the protocol's governance (its
///         policy's governance) may cancelHeld it instead: the funds stay in the protocol.
///         The breaker address is fixed at deployment; address(0) turns everything off.
abstract contract CircuitBreakable {
    ICircuitBreaker public immutable circuitBreaker;

    struct HeldOutflow {
        address asset;
        address to;
        uint256 amount;
        uint64 heldAt;
        uint8 state; // 0 held, 1 paid, 2 cancelled
    }

    HeldOutflow[] public held;

    event OutflowHeld(uint256 indexed id, address indexed asset, address indexed to, uint256 amount);
    event HeldPaid(uint256 indexed id);
    event HeldCancelled(uint256 indexed id);

    error SelectorTripped(bytes4 selector);
    error HeldNotReady();
    error NotPolicyGovernance();

    constructor(ICircuitBreaker breaker) {
        circuitBreaker = breaker;
    }

    modifier whenNotTripped(bytes4 selector) {
        if (address(circuitBreaker) != address(0) && circuitBreaker.isPaused(address(this), selector)) revert SelectorTripped(selector);
        _;
    }

    /// True: pay now. False: held (see `held`); the caller must not pay and must not revert.
    function _outflow(address asset, address to, uint256 amount) internal returns (bool) {
        if (address(circuitBreaker) == address(0) || amount == 0) return true;
        if (circuitBreaker.recordOutflow(asset, amount)) return true;
        held.push(HeldOutflow(asset, to, amount, uint64(block.timestamp), 0));
        emit OutflowHeld(held.length - 1, asset, to, amount);
        return false;
    }

    function _payOut(address asset, address to, uint256 amount) internal virtual;

    function heldCount() external view returns (uint256) {
        return held.length;
    }

    function releaseHeld(uint256 id) external {
        HeldOutflow storage h = held[id];
        if (h.state != 0 || circuitBreaker.isTripped(address(this))
            || block.timestamp < uint256(h.heldAt) + circuitBreaker.holdReviewOf(address(this))) revert HeldNotReady();
        if (!circuitBreaker.recordOutflow(h.asset, h.amount)) revert HeldNotReady();
        h.state = 1;
        emit HeldPaid(id);
        _payOut(h.asset, h.to, h.amount);
    }

    function cancelHeld(uint256 id) external {
        if (msg.sender != circuitBreaker.policyGovernance(address(this))) revert NotPolicyGovernance();
        HeldOutflow storage h = held[id];
        if (h.state != 0) revert HeldNotReady();
        h.state = 2;
        emit HeldCancelled(id);
    }
}

contracts/CircuitBreaker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// NeuroJobs' runner record (the first five fields of NeuroJobs.workers): bond, unbonding, active, track record.
interface IBreakerRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title CircuitBreaker: opt-in, narrow, time-boxed self-healing for protocols on ZETAPHY (testnet prototype)
/// @notice docs/future/self-healing.md. A protocol OPTS IN by registering a policy (from its own
///         contract), and integrates CircuitBreakable (contracts/CircuitBreakable.sol): the
///         `whenNotTripped(selector)` modifier and `_outflow(asset, to, amount)` accounting.
///
///         The policy states, in advance, everything a trip may do:
///           - which selectors of the protocol may be paused (at most 16), and which of them an
///             invariant trip pauses (`invariantMask`);
///           - outflow caps per window for each listed asset (at most 8; address(0) = native coin);
///           - while tripped: the caps are cut to `tripCapBps` and single outflows above `holdAbove`
///             are HELD (kept by the protocol, paid later or cancelled by its governance);
///           - `maxPause`: how long a trip lasts (at most MAX_PAUSE); it always expires by itself;
///           - `quorum`: how many bonded Neuro runners must sign the same evidence (>= minQuorum);
///           - `governance`: the protocol's OWN governance. It ends a trip early (release), changes
///             the policy (after POLICY_DELAY, never while tripped), opts out (after POLICY_DELAY),
///             cancels held outflows and claims a trip was false.
///
///         Two ways to trip, nothing else:
///           1. Evidence: >= quorum distinct eligible runners sign the same evidence
///              {protocol, epoch, block range, evidence hash, detector id, selector mask}: either
///              ECDSA signatures gathered off chain (tripWithSignatures) or one attest() tx each
///              (so a runner with an ML-DSA account, MsgEVMCall, attests post-quantum). Eligible =
///              an active NeuroJobs runner with >= minAgreed accepted verdicts AND a guardian bond
///              of >= guardianBond posted here (slashable: NeuroJobs bonds cannot be slashed from
///              outside). Evidence must be fresh: its range starts after the previous trip's, ends
///              at most MAX_EVIDENCE_AGE blocks ago, and its hash was never used.
///           2. Invariant: the protocol's own outflow accounting exceeds a cap within a window.
///              The breaker sees it itself (recordOutflow); the outflow that broke it is held,
///              not reverted, so the trip stays.
///         At most MAX_STREAK trips in a row (each starting within maxPause of the last one's end)
///         before the protocol's governance must rearm: runners cannot keep a protocol paused.
///
///         No admin key: `governance` (the ZetaphyTimelock) only sets bounded parameters, vetoes a
///         trip (ends it at once) and judges false-trip claims. It can never pause anything.
///
///         False trips: within CLAIM_WINDOW of a runner trip, the protocol's governance may
///         claimFalse (posting claimBond); the timelock judges it. Proven false: each signer loses
///         slashBps of its guardian bond, COMPENSATION_BPS of it goes to the protocol's governance
///         (plus its claim bond back), the rest is burned. Rejected: the claim bond goes to the
///         signers. Not judged within RESOLVE_WINDOW: the claim bond is refunded, nobody slashed.
///         Signers cannot exit while a trip they signed can still be claimed or is being judged.
contract CircuitBreaker {
    // ---- bounds (constants: governance cannot widen them) ----
    uint256 public constant MAX_SELECTORS = 16;
    uint256 public constant MAX_ASSETS = 8;
    uint256 public constant MAX_QUORUM = 16;
    uint32 public constant MIN_PAUSE = 10 minutes;
    uint32 public constant MAX_PAUSE = 3 days;
    uint32 public constant MIN_WINDOW = 1 minutes;
    uint32 public constant MAX_WINDOW = 1 days;
    uint32 public constant MAX_REVIEW = 7 days;
    uint64 public constant POLICY_DELAY = 2 days;
    uint64 public constant EXIT_DELAY = 7 days;
    uint64 public constant CLAIM_WINDOW = 7 days;
    uint64 public constant RESOLVE_WINDOW = 14 days;
    uint64 public constant MAX_EVIDENCE_AGE = 64; // blocks
    uint64 public constant MAX_RANGE = 256;       // blocks
    uint8 public constant MAX_STREAK = 3;
    uint16 public constant MAX_SLASH_BPS = 5000;
    uint16 public constant COMPENSATION_BPS = 8000;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    bytes32 public constant TRIP_TYPEHASH = keccak256("ZetaphyCircuitBreakerTrip(uint256 chainId,address breaker,address protocol,uint256 epoch,uint64 fromBlock,uint64 toBlock,bytes32 evidenceHash,bytes32 detectorId,uint16 mask)");

    struct Policy {
        address governance;
        bytes4[] selectors;
        address[] assets;
        uint256[] caps;
        uint32 window;
        uint32 maxPause;
        uint8 quorum;
        uint16 invariantMask;
        uint16 tripCapBps;
        uint256 holdAbove;
        uint32 holdReview;
    }

    struct Config {
        address governance;
        uint32 window;
        uint32 maxPause;
        uint8 quorum;
        bool active;
        uint16 invariantMask;
        uint16 tripCapBps;
        uint32 holdReview;
        uint256 holdAbove;
        bytes4[] selectors;
        address[] assets;
    }

    struct Evidence {
        uint64 fromBlock;
        uint64 toBlock;
        bytes32 evidenceHash;
        bytes32 detectorId;
        uint16 mask;
    }

    enum Kind { Runners, Invariant }
    enum Claim { None, Open, ProvenFalse, Rejected, Expired }

    struct Trip {
        address protocol;
        Kind kind;
        Claim claim;
        uint16 mask;
        uint64 start;
        uint64 until;      // the trip is live while block.timestamp < until (release/veto set it to now)
        uint64 fromBlock;
        uint64 toBlock;
        uint64 claimedAt;
        bytes32 evidenceHash;
        bytes32 detectorId;
        uint256 claimBond;
        address[] runners;
    }

    struct Guardian {
        uint128 bond;
        uint64 exitAt;        // 0 while serving
        uint64 lockedUntil;   // trips it signed can be claimed until then
        uint32 openClaims;    // claims on trips it signed, not yet settled
        uint32 trips;         // trips it signed
        uint32 slashed;       // trips it signed that were proven false
    }

    struct Flow {
        uint64 windowId;
        uint192 used;
    }

    IBreakerRunners public immutable runners;
    address public governance;
    uint256 public guardianBond;
    uint256 public claimBond;
    uint8 public minQuorum;
    uint32 public minAgreed;
    uint16 public slashBps = 5000;

    mapping(address => Config) internal _policy;
    mapping(address => mapping(address => uint256)) public capOf;        // protocol => asset => cap per window
    mapping(address => mapping(address => Flow)) public flowOf;          // protocol => asset => this window's outflow
    mapping(address => Config) internal _pending;
    mapping(address => mapping(address => uint256)) internal _pendingCap;
    mapping(address => uint64) public pendingAt;      // policy change ready at (0: none)
    mapping(address => uint64) public optOutAt;       // opt-out ready at (0: none)
    address[] public protocols;
    mapping(address => bool) public listed;

    Trip[] internal _trips;
    mapping(address => uint256) public lastTrip;      // protocol => trip id + 1 (0: never)
    mapping(address => uint256) public epoch;         // bumps on every trip: older signatures stop counting
    mapping(address => uint64) public lastToBlock;    // evidence must start after this
    mapping(address => uint8) public streak;
    mapping(bytes32 => bool) public usedEvidence;
    mapping(bytes32 => address[]) internal _attesters; // digest => runners who attested it on chain

    mapping(address => Guardian) public guardians;
    mapping(address => uint256) public owed;

    event Registered(address indexed protocol, address governance);
    event PolicyProposed(address indexed protocol, uint64 readyAt);
    event PolicyApplied(address indexed protocol);
    event OptOutProposed(address indexed protocol, uint64 readyAt);
    event OptedOut(address indexed protocol);
    event GuardianJoined(address indexed runner, uint256 bond);
    event GuardianExitRequested(address indexed runner, uint64 at);
    event GuardianExited(address indexed runner, uint256 bond);
    event Attested(address indexed protocol, bytes32 indexed digest, address indexed runner, uint256 count);
    event Tripped(uint256 indexed id, address indexed protocol, Kind kind, uint16 mask, uint64 until, bytes32 evidenceHash, bytes32 detectorId, uint64 fromBlock, uint64 toBlock);
    event Outflow(address indexed protocol, address indexed asset, uint256 amount, uint256 used, bool held);
    event Released(uint256 indexed id, address indexed by);
    event Vetoed(uint256 indexed id);
    event Rearmed(address indexed protocol);
    event ClaimedFalse(uint256 indexed id, uint256 bond);
    event ClaimResolved(uint256 indexed id, bool provenFalse, uint256 slashed);
    event ClaimExpired(uint256 indexed id);
    event Slashed(address indexed runner, uint256 amount);
    event ParamsSet(uint256 guardianBond, uint256 claimBond, uint8 minQuorum, uint32 minAgreed, uint16 slashBps);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotProtocolGovernance();
    error BadPolicy();
    error AlreadyRegistered();
    error NotRegistered();
    error IsTripped();
    error NotTripped();
    error TooEarly();
    error NotEligible();
    error StaleEvidence();
    error UsedEvidence();
    error BadMask();
    error NoQuorum();
    error BadSignature();
    error NotSorted();
    error AlreadyAttested();
    error StreakLimit();
    error BadValue();
    error BadClaim();
    error Locked();

    constructor(IBreakerRunners runners_, address governance_, uint256 guardianBond_, uint256 claimBond_, uint8 minQuorum_, uint32 minAgreed_) {
        if (address(runners_) == address(0) || governance_ == address(0)) revert BadValue();
        runners = runners_;
        governance = governance_;
        _setParams(guardianBond_, claimBond_, minQuorum_, minAgreed_, slashBps);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier onlyProtocolGov(address protocol) {
        if (!_policy[protocol].active) revert NotRegistered();
        if (msg.sender != _policy[protocol].governance) revert NotProtocolGovernance();
        _;
    }

    // ======================================================================= policies

    /// Opt in. Called by the protocol contract itself (its own governance decides to call it).
    function register(Policy calldata p) external {
        if (_policy[msg.sender].active) revert AlreadyRegistered();
        _check(p);
        _store(_policy[msg.sender], capOf[msg.sender], p);
        if (!listed[msg.sender]) { listed[msg.sender] = true; protocols.push(msg.sender); }
        emit Registered(msg.sender, p.governance);
    }

    /// A new policy, applied after POLICY_DELAY (applyPolicy). Loosening a policy is never instant.
    function proposePolicy(address protocol, Policy calldata p) external onlyProtocolGov(protocol) {
        _check(p);
        _store(_pending[protocol], _pendingCap[protocol], p);
        uint64 at = uint64(block.timestamp) + POLICY_DELAY;
        pendingAt[protocol] = at;
        emit PolicyProposed(protocol, at);
    }

    function applyPolicy(address protocol) external {
        uint64 at = pendingAt[protocol];
        if (at == 0 || block.timestamp < at) revert TooEarly();
        if (isTripped(protocol)) revert IsTripped();
        Config storage cur = _policy[protocol];
        Config storage nxt = _pending[protocol];
        for (uint256 i = 0; i < cur.assets.length; i++) capOf[protocol][cur.assets[i]] = 0;
        cur.governance = nxt.governance;
        cur.window = nxt.window;
        cur.maxPause = nxt.maxPause;
        cur.quorum = nxt.quorum;
        cur.invariantMask = nxt.invariantMask;
        cur.tripCapBps = nxt.tripCapBps;
        cur.holdReview = nxt.holdReview;
        cur.holdAbove = nxt.holdAbove;
        cur.selectors = nxt.selectors;
        cur.assets = nxt.assets;
        for (uint256 i = 0; i < nxt.assets.length; i++) {
            capOf[protocol][nxt.assets[i]] = _pendingCap[protocol][nxt.assets[i]];
            _pendingCap[protocol][nxt.assets[i]] = 0;
            delete flowOf[protocol][nxt.assets[i]];
        }
        delete _pending[protocol];
        pendingAt[protocol] = 0;
        emit PolicyApplied(protocol);
    }

    function proposeOptOut(address protocol) external onlyProtocolGov(protocol) {
        uint64 at = uint64(block.timestamp) + POLICY_DELAY;
        optOutAt[protocol] = at;
        emit OptOutProposed(protocol, at);
    }

    /// After POLICY_DELAY and not while tripped: the protocol is no longer protected (or limited).
    function optOut(address protocol) external {
        uint64 at = optOutAt[protocol];
        if (at == 0 || block.timestamp < at) revert TooEarly();
        if (isTripped(protocol)) revert IsTripped();
        Config storage cur = _policy[protocol];
        for (uint256 i = 0; i < cur.assets.length; i++) capOf[protocol][cur.assets[i]] = 0;
        delete _policy[protocol];
        optOutAt[protocol] = 0;
        pendingAt[protocol] = 0;
        emit OptedOut(protocol);
    }

    function _check(Policy calldata p) internal view {
        if (p.governance == address(0) || p.selectors.length > MAX_SELECTORS || p.assets.length > MAX_ASSETS
            || p.assets.length != p.caps.length) revert BadPolicy();
        if (p.window < MIN_WINDOW || p.window > MAX_WINDOW || p.maxPause < MIN_PAUSE || p.maxPause > MAX_PAUSE) revert BadPolicy();
        if (p.quorum < minQuorum || p.quorum > MAX_QUORUM || p.tripCapBps > 10_000 || p.holdReview > MAX_REVIEW) revert BadPolicy();
        if (uint256(p.invariantMask) >> p.selectors.length != 0) revert BadPolicy();
        for (uint256 i = 0; i < p.selectors.length; i++) {
            if (p.selectors[i] == bytes4(0)) revert BadPolicy();
            for (uint256 j = 0; j < i; j++) if (p.selectors[j] == p.selectors[i]) revert BadPolicy();
        }
        for (uint256 i = 0; i < p.assets.length; i++) {
            if (p.caps[i] == 0 || p.caps[i] > type(uint192).max) revert BadPolicy();
            for (uint256 j = 0; j < i; j++) if (p.assets[j] == p.assets[i]) revert BadPolicy();
        }
    }

    function _store(Config storage c, mapping(address => uint256) storage caps, Policy calldata p) internal {
        c.governance = p.governance;
        c.window = p.window;
        c.maxPause = p.maxPause;
        c.quorum = p.quorum;
        c.active = true;
        c.invariantMask = p.invariantMask;
        c.tripCapBps = p.tripCapBps;
        c.holdReview = p.holdReview;
        c.holdAbove = p.holdAbove;
        c.selectors = p.selectors;
        c.assets = p.assets;
        for (uint256 i = 0; i < p.assets.length; i++) caps[p.assets[i]] = p.caps[i];
    }

    // ======================================================================= guardians (bonded runners)

    /// Post (or top up) a guardian bond. Only active NeuroJobs runners with a track record.
    function joinGuardians() external payable {
        Guardian storage g = guardians[msg.sender];
        if (g.exitAt != 0) revert Locked();
        uint256 bond = uint256(g.bond) + msg.value;
        if (bond < guardianBond || bond > type(uint128).max || !_isRunner(msg.sender)) revert NotEligible();
        g.bond = uint128(bond);
        emit GuardianJoined(msg.sender, bond);
    }

    function requestExit() external {
        Guardian storage g = guardians[msg.sender];
        if (g.bond == 0 || g.exitAt != 0) revert BadValue();
        g.exitAt = uint64(block.timestamp) + EXIT_DELAY;
        emit GuardianExitRequested(msg.sender, g.exitAt);
    }

    /// After EXIT_DELAY, once nothing it signed can still be claimed or is being judged.
    function exit() external {
        Guardian storage g = guardians[msg.sender];
        if (g.exitAt == 0 || block.timestamp < g.exitAt || block.timestamp < g.lockedUntil || g.openClaims != 0) revert Locked();
        uint256 amount = g.bond;
        g.bond = 0;
        g.exitAt = 0;
        owed[msg.sender] += amount;
        emit GuardianExited(msg.sender, amount);
    }

    function _isRunner(address r) internal view returns (bool) {
        (uint128 bond, , bool active, uint32 agreed, ) = runners.workers(r);
        return active && bond > 0 && agreed >= minAgreed;
    }

    /// May sign or attest evidence now.
    function eligible(address r) public view returns (bool) {
        Guardian storage g = guardians[r];
        return g.bond >= guardianBond && g.bond > 0 && g.exitAt == 0 && _isRunner(r);
    }

    // ======================================================================= evidence trips

    /// What runners sign (personal_sign / EIP-191 over this 32-byte digest).
    function digest(address protocol, Evidence calldata ev) public view returns (bytes32) {
        return keccak256(abi.encode(TRIP_TYPEHASH, block.chainid, address(this), protocol, epoch[protocol],
            ev.fromBlock, ev.toBlock, ev.evidenceHash, ev.detectorId, ev.mask));
    }

    /// One runner attests on chain (any account type: ECDSA, or ML-DSA through MsgEVMCall).
    /// The attestation that reaches the policy's quorum trips the breaker.
    function attest(address protocol, Evidence calldata ev) external returns (bool tripped) {
        _checkEvidence(protocol, ev);
        if (!eligible(msg.sender)) revert NotEligible();
        bytes32 d = digest(protocol, ev);
        address[] storage list = _attesters[d];
        for (uint256 i = 0; i < list.length; i++) if (list[i] == msg.sender) revert AlreadyAttested();
        list.push(msg.sender);
        emit Attested(protocol, d, msg.sender, list.length);
        // only attesters still eligible now count toward the quorum
        uint256 q = _policy[protocol].quorum;
        if (list.length < q) return false;
        address[] memory ok = new address[](list.length);
        uint256 n;
        for (uint256 i = 0; i < list.length; i++) if (eligible(list[i])) ok[n++] = list[i];
        if (n < q) return false;
        assembly { mstore(ok, n) }
        _tripRunners(protocol, ev, ok);
        return true;
    }

    /// k-of-n ECDSA signatures gathered off chain, submitted by anyone. Signers strictly ascending.
    function tripWithSignatures(address protocol, Evidence calldata ev, address[] calldata signers, bytes[] calldata sigs) external {
        _checkEvidence(protocol, ev);
        if (signers.length != sigs.length) revert BadValue();
        if (signers.length < _policy[protocol].quorum) revert NoQuorum();
        bytes32 h = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", digest(protocol, ev)));
        address prev = address(0);
        for (uint256 i = 0; i < signers.length; i++) {
            if (signers[i] <= prev) revert NotSorted();
            prev = signers[i];
            if (_recover(h, sigs[i]) != signers[i]) revert BadSignature();
            if (!eligible(signers[i])) revert NotEligible();
        }
        _tripRunners(protocol, ev, signers);
    }

    function _checkEvidence(address protocol, Evidence calldata ev) internal view {
        Config storage c = _policy[protocol];
        if (!c.active) revert NotRegistered();
        if (isTripped(protocol)) revert IsTripped();
        if (ev.evidenceHash == bytes32(0) || ev.fromBlock > ev.toBlock || ev.toBlock >= block.number
            || block.number - ev.toBlock > MAX_EVIDENCE_AGE || ev.toBlock - ev.fromBlock > MAX_RANGE
            || ev.fromBlock <= lastToBlock[protocol]) revert StaleEvidence();
        if (usedEvidence[ev.evidenceHash]) revert UsedEvidence();
        if (uint256(ev.mask) >> c.selectors.length != 0) revert BadMask();
    }

    function _tripRunners(address protocol, Evidence calldata ev, address[] memory signers) internal {
        usedEvidence[ev.evidenceHash] = true;
        uint256 id = _start(protocol, Kind.Runners, ev.mask, ev.evidenceHash, ev.detectorId, ev.fromBlock, ev.toBlock);
        Trip storage t = _trips[id];
        uint64 lockUntil = t.start + CLAIM_WINDOW;
        for (uint256 i = 0; i < signers.length; i++) {
            t.runners.push(signers[i]);
            Guardian storage g = guardians[signers[i]];
            if (g.lockedUntil < lockUntil) g.lockedUntil = lockUntil;
            g.trips += 1;
        }
    }

    function _start(address protocol, Kind kind, uint16 mask, bytes32 evidenceHash, bytes32 detectorId, uint64 fromBlock, uint64 toBlock)
        internal returns (uint256 id)
    {
        Config storage c = _policy[protocol];
        uint256 prev = lastTrip[protocol];
        uint8 s = streak[protocol];
        if (prev != 0 && block.timestamp > uint256(_trips[prev - 1].until) + c.maxPause) s = 0; // a quiet period resets it
        if (s >= MAX_STREAK) revert StreakLimit();
        streak[protocol] = s + 1;
        epoch[protocol] += 1;
        lastToBlock[protocol] = toBlock;
        id = _trips.length;
        Trip storage t = _trips.push();
        t.protocol = protocol;
        t.kind = kind;
        t.mask = mask;
        t.start = uint64(block.timestamp);
        t.until = uint64(block.timestamp) + c.maxPause;
        t.fromBlock = fromBlock;
        t.toBlock = toBlock;
        t.evidenceHash = evidenceHash;
        t.detectorId = detectorId;
        lastTrip[protocol] = id + 1;
        emit Tripped(id, protocol, kind, mask, t.until, evidenceHash, detectorId, fromBlock, toBlock);
    }

    /// ECDSA (65 bytes r,s,v), low-s only.
    function _recover(bytes32 h, bytes calldata sig) internal pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0 || (v != 27 && v != 28)) revert BadSignature();
        address a = ecrecover(h, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    // ======================================================================= outflow accounting (invariant trips)

    /// Called by a registered protocol (CircuitBreakable._outflow) before it pays `amount` of `asset`.
    /// Returns false when the payment must be HELD: over the window's cap (this trips the breaker
    /// if it is not tripped yet), or above holdAbove while tripped. Unregistered callers and unlisted
    /// assets: always true, nothing recorded.
    function recordOutflow(address asset, uint256 amount) external returns (bool payNow) {
        Config storage c = _policy[msg.sender];
        if (!c.active) return true;
        uint256 cap = capOf[msg.sender][asset];
        if (cap == 0) return true;
        Flow storage f = flowOf[msg.sender][asset];
        uint64 w = uint64(block.timestamp / c.window);
        if (f.windowId != w) { f.windowId = w; f.used = 0; }
        bool tripped = isTripped(msg.sender);
        uint256 limit = tripped ? cap * c.tripCapBps / 10_000 : cap;
        uint256 used = uint256(f.used) + amount;
        if ((tripped && c.holdAbove != 0 && amount > c.holdAbove) || used > limit) {
            if (!tripped && streak[msg.sender] < MAX_STREAK) {
                // the invariant broke: the chain saw it itself, no runners needed
                uint64 b = uint64(block.number);
                if (b > lastToBlock[msg.sender]) {
                    _start(msg.sender, Kind.Invariant, c.invariantMask, keccak256(abi.encode(msg.sender, asset, used, cap, b)), bytes32("invariant:outflow-cap"), b, b);
                }
            }
            emit Outflow(msg.sender, asset, amount, f.used, true);
            return false;
        }
        f.used = uint192(used);
        emit Outflow(msg.sender, asset, amount, used, false);
        return true;
    }

    // ======================================================================= ending trips, rearm

    /// The protocol's own governance ends its trip early.
    function release(address protocol) external onlyProtocolGov(protocol) {
        uint256 id = _live(protocol);
        _trips[id].until = uint64(block.timestamp);
        emit Released(id, msg.sender);
    }

    /// Chain governance (the timelock) overrides: ends a trip at once.
    function veto(address protocol) external onlyGovernance {
        uint256 id = _live(protocol);
        _trips[id].until = uint64(block.timestamp);
        emit Vetoed(id);
    }

    /// The protocol's governance resets the streak (allows MAX_STREAK new trips).
    function rearm(address protocol) external onlyProtocolGov(protocol) {
        streak[protocol] = 0;
        emit Rearmed(protocol);
    }

    function _live(address protocol) internal view returns (uint256) {
        if (!isTripped(protocol)) revert NotTripped();
        return lastTrip[protocol] - 1;
    }

    // ======================================================================= false-trip claims

    function claimFalse(uint256 id) external payable {
        Trip storage t = _trips[id];
        if (msg.sender != _policy[t.protocol].governance) revert NotProtocolGovernance();
        if (t.kind != Kind.Runners || t.claim != Claim.None || block.timestamp > t.start + CLAIM_WINDOW) revert BadClaim();
        if (msg.value != claimBond) revert BadValue();
        t.claim = Claim.Open;
        t.claimedAt = uint64(block.timestamp);
        t.claimBond = msg.value;
        for (uint256 i = 0; i < t.runners.length; i++) guardians[t.runners[i]].openClaims += 1;
        emit ClaimedFalse(id, msg.value);
    }

    /// The timelock judges a claim. Proven false: the signers are slashed and the protocol compensated.
    function resolveClaim(uint256 id, bool provenFalse) external onlyGovernance {
        Trip storage t = _trips[id];
        if (t.claim != Claim.Open) revert BadClaim();
        address gov = _policy[t.protocol].governance;
        uint256 n = t.runners.length;
        uint256 total;
        if (provenFalse) {
            t.claim = Claim.ProvenFalse;
            for (uint256 i = 0; i < n; i++) {
                Guardian storage g = guardians[t.runners[i]];
                uint256 cut = uint256(g.bond) * slashBps / 10_000;
                g.bond -= uint128(cut);
                g.openClaims -= 1;
                g.slashed += 1;
                total += cut;
                emit Slashed(t.runners[i], cut);
            }
            uint256 comp = total * COMPENSATION_BPS / 10_000;
            owed[gov == address(0) ? BURN : gov] += comp + t.claimBond;
            owed[BURN] += total - comp;
        } else {
            t.claim = Claim.Rejected;
            uint256 share = t.claimBond / n;
            for (uint256 i = 0; i < n; i++) {
                guardians[t.runners[i]].openClaims -= 1;
                owed[t.runners[i]] += share;
            }
            owed[BURN] += t.claimBond - share * n;
        }
        emit ClaimResolved(id, provenFalse, total);
    }

    /// Nobody judged it in time: the claim bond goes back, nobody is slashed.
    function expireClaim(uint256 id) external {
        Trip storage t = _trips[id];
        if (t.claim != Claim.Open || block.timestamp < t.claimedAt + RESOLVE_WINDOW) revert BadClaim();
        t.claim = Claim.Expired;
        for (uint256 i = 0; i < t.runners.length; i++) guardians[t.runners[i]].openClaims -= 1;
        address gov = _policy[t.protocol].governance;
        owed[gov == address(0) ? BURN : gov] += t.claimBond;
        emit ClaimExpired(id);
    }

    function withdraw() external {
        uint256 amount = owed[msg.sender];
        if (amount == 0) revert BadValue();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "send");
    }

    /// Burned shares are paid to BURN by anyone (nobody holds its key).
    function flushBurn() external {
        uint256 amount = owed[BURN];
        owed[BURN] = 0;
        (bool ok, ) = BURN.call{value: amount}("");
        require(ok, "send");
    }

    // ======================================================================= governance (the timelock)

    function setParams(uint256 guardianBond_, uint256 claimBond_, uint8 minQuorum_, uint32 minAgreed_, uint16 slashBps_) external onlyGovernance {
        _setParams(guardianBond_, claimBond_, minQuorum_, minAgreed_, slashBps_);
    }

    function _setParams(uint256 guardianBond_, uint256 claimBond_, uint8 minQuorum_, uint32 minAgreed_, uint16 slashBps_) internal {
        if (guardianBond_ == 0 || claimBond_ == 0 || minQuorum_ < 2 || minQuorum_ > MAX_QUORUM || slashBps_ == 0 || slashBps_ > MAX_SLASH_BPS) revert BadValue();
        guardianBond = guardianBond_;
        claimBond = claimBond_;
        minQuorum = minQuorum_;
        minAgreed = minAgreed_;
        slashBps = slashBps_;
        emit ParamsSet(guardianBond_, claimBond_, minQuorum_, minAgreed_, slashBps_);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceSet(next);
    }

    // ======================================================================= views

    function isTripped(address protocol) public view returns (bool) {
        uint256 id = lastTrip[protocol];
        return id != 0 && block.timestamp < _trips[id - 1].until;
    }

    /// True while a live trip pauses this selector of the protocol.
    function isPaused(address protocol, bytes4 selector) external view returns (bool) {
        if (!isTripped(protocol)) return false;
        uint16 mask = _trips[lastTrip[protocol] - 1].mask;
        bytes4[] storage s = _policy[protocol].selectors;
        for (uint256 i = 0; i < s.length; i++) if (s[i] == selector) return (mask >> i) & 1 == 1;
        return false;
    }

    function policyOf(address protocol) external view returns (Config memory) {
        return _policy[protocol];
    }

    function policyGovernance(address protocol) external view returns (address) {
        return _policy[protocol].governance;
    }

    function holdReviewOf(address protocol) external view returns (uint32) {
        return _policy[protocol].holdReview;
    }

    function tripCount() external view returns (uint256) {
        return _trips.length;
    }

    function protocolCount() external view returns (uint256) {
        return protocols.length;
    }

    function tripOf(uint256 id) external view returns (Trip memory) {
        return _trips[id];
    }

    function attesters(bytes32 d) external view returns (address[] memory) {
        return _attesters[d];
    }
}

contracts/ComputeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnersView {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title ComputeMarket: pay node runners in ZETAPHY for AI work (stage 4)
/// @notice Model output (tier 2+) is not deterministic, so it cannot be
///         settled by 2-of-3 agreement like Neuro tier 1. Instead: escrow.
///         The requester pays up front; a runner with a NeuroJobs track
///         record takes the task and delivers a result (hash + URI); the
///         requester accepts or rejects within REVIEW. Silence pays the
///         runner. Both sides' reject counts are public, so runners can avoid
///         requesters who reject everything, and requesters can avoid runners
///         who deliver junk.
contract ComputeMarket {
    uint64 public constant REVIEW = 1 days;

    enum Status { None, Open, Taken, Delivered, Paid, Refunded }

    struct Task {
        address requester;
        address runner;
        Status status;
        uint64 deadline;     // delivery due
        uint64 deliveredAt;
        bytes32 model;       // e.g. "llama-3.1-8b-instruct-q4"
        bytes32 inputHash;
        bytes32 resultHash;
        uint256 price;
        string inputURI;
        string resultURI;
    }

    IRunnersView public immutable runners;
    uint32 public immutable minAgreed;
    Task[] internal tasks;
    mapping(address => uint256) public credit;
    mapping(address => uint32) public runnerDone;
    mapping(address => uint32) public runnerRejected;
    mapping(address => uint32) public requesterRejections;

    event Requested(uint256 indexed id, bytes32 indexed model, uint256 price, uint64 deadline);
    event Taken(uint256 indexed id, address indexed runner);
    event Delivered(uint256 indexed id, bytes32 resultHash, string resultURI);
    event Settled(uint256 indexed id, Status status);

    error BadValue();
    error BadState();
    error NotAllowed();
    error TooEarly();
    error Nothing();

    constructor(IRunnersView runners_, uint32 minAgreed_) {
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function request(bytes32 model, bytes32 inputHash, string calldata inputURI, uint64 seconds_) external payable returns (uint256 id) {
        if (msg.value == 0 || model == bytes32(0) || seconds_ == 0 || seconds_ > 7 days || bytes(inputURI).length > 256) revert BadValue();
        id = tasks.length;
        Task storage t = tasks.push();
        t.requester = msg.sender;
        t.status = Status.Open;
        t.deadline = uint64(block.timestamp) + seconds_;
        t.model = model;
        t.inputHash = inputHash;
        t.inputURI = inputURI;
        t.price = msg.value;
        emit Requested(id, model, msg.value, t.deadline);
    }

    function take(uint256 id) external {
        Task storage t = _task(id, Status.Open);
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == t.requester) revert NotAllowed();
        if (block.timestamp >= t.deadline) revert BadState();
        t.runner = msg.sender;
        t.status = Status.Taken;
        emit Taken(id, msg.sender);
    }

    function deliver(uint256 id, bytes32 resultHash, string calldata resultURI) external {
        Task storage t = _task(id, Status.Taken);
        if (msg.sender != t.runner) revert NotAllowed();
        if (block.timestamp > t.deadline || resultHash == bytes32(0) || bytes(resultURI).length > 256) revert BadValue();
        t.resultHash = resultHash;
        t.resultURI = resultURI;
        t.deliveredAt = uint64(block.timestamp);
        t.status = Status.Delivered;
        emit Delivered(id, resultHash, resultURI);
    }

    function accept(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        _pay(id, t);
    }

    function reject(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        if (block.timestamp > t.deliveredAt + REVIEW) revert BadState();
        runnerRejected[t.runner] += 1;
        requesterRejections[t.requester] += 1;
        _refund(id, t);
    }

    /// The runner is paid once the review window passes without a rejection.
    function claim(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (block.timestamp <= t.deliveredAt + REVIEW) revert TooEarly();
        _pay(id, t);
    }

    /// Requester gets the money back if nobody took the task, or nothing was delivered in time.
    function cancel(uint256 id) external {
        if (id >= tasks.length) revert BadState();
        Task storage t = tasks[id];
        if (msg.sender != t.requester) revert NotAllowed();
        bool open = t.status == Status.Open;
        bool late = t.status == Status.Taken && block.timestamp > t.deadline;
        if (!open && !late) revert BadState();
        _refund(id, t);
    }

    function withdraw() external {
        uint256 a = credit[msg.sender];
        if (a == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        require(ok, "transfer failed");
    }

    function taskCount() external view returns (uint256) { return tasks.length; }

    function getTask(uint256 id) external view returns (Task memory) {
        if (id >= tasks.length) revert BadState();
        return tasks[id];
    }

    function _task(uint256 id, Status want) private view returns (Task storage t) {
        if (id >= tasks.length) revert BadState();
        t = tasks[id];
        if (t.status != want) revert BadState();
    }

    function _pay(uint256 id, Task storage t) private {
        t.status = Status.Paid;
        credit[t.runner] += t.price;
        runnerDone[t.runner] += 1;
        emit Settled(id, Status.Paid);
    }

    function _refund(uint256 id, Task storage t) private {
        t.status = Status.Refunded;
        credit[t.requester] += t.price;
        emit Settled(id, Status.Refunded);
    }
}

contracts/DataDAO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title DataDAO: labelled data for Neuro's model, rewarded by measured improvement (testnet)
/// @notice Contributors register labelled data (its sha256/keccak hash + where to get it +
///         row count + licence). The weekly ML training job (GitHub Actions, no server) measures
///         how much each contributor's data improves the model on held-out rows
///         (zetaphy-neuro/ml/dao/attribute.js: leave-one-contributor-out or a Shapley estimate)
///         and turns that into a merkle root of (round, account, amount). The poster (a
///         governance-chosen address, e.g. a multisig that checked the job's report) posts the
///         root with the hash and URI of the job's report. Claims open after `vetoDelay`, during
///         which governance can veto a wrong root; what is not claimed before `claimPeriod`
///         ends goes back to the pool. Rewards are testnet ZETAPHY from `fund()`.
contract DataDAO {
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_LICENSE = 32;

    struct Submission {
        address contributor;
        uint64 at;
        uint32 rows;
        bool excluded;       // governance: bad / copied / unlicensed data
        bytes32 dataHash;
        string uri;
        string license;      // SPDX id, e.g. "MIT", "CC0-1.0"
    }

    struct Round {
        bytes32 root;
        uint128 total;
        uint128 claimed;
        uint64 postedAt;
        uint64 claimFrom;
        uint64 expires;
        bool vetoed;
        bool swept;
        bytes32 reportHash;  // hash of the attribution report (metrics per contributor)
        string reportUri;
    }

    address public governance;
    address public poster;
    uint64 public vetoDelay = 2 days;
    uint64 public claimPeriod = 60 days;
    uint256 public reserved;            // promised to posted, live rounds

    Submission[] private _subs;
    mapping(bytes32 => uint256) public idOfHash; // dataHash -> id (1-based)
    Round[] private _rounds;
    mapping(uint256 => mapping(address => bool)) public claimed;

    event Submitted(uint256 indexed id, address indexed contributor, bytes32 dataHash, uint32 rows, string uri, string license);
    event Excluded(uint256 indexed id, bool excluded);
    event RoundPosted(uint256 indexed round, bytes32 root, uint256 total, bytes32 reportHash, string reportUri);
    event RoundVetoed(uint256 indexed round);
    event Claimed(uint256 indexed round, address indexed account, uint256 amount);
    event Swept(uint256 indexed round, uint256 amount);
    event Funded(address indexed from, uint256 amount);
    event PosterSet(address poster);
    event GovernanceSet(address governance);
    event DelaysSet(uint64 vetoDelay, uint64 claimPeriod);

    error NotGovernance();
    error NotPoster();
    error BadInput();
    error Duplicate();
    error NotEnoughFunds();
    error BadRound();
    error NotOpen();
    error AlreadyClaimed();
    error BadProof();
    error SendFailed();

    constructor(address governance_, address poster_) {
        governance = governance_;
        poster = poster_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable { emit Funded(msg.sender, msg.value); }
    function fund() external payable { emit Funded(msg.sender, msg.value); }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setPoster(address p) external onlyGov { poster = p; emit PosterSet(p); }
    function setDelays(uint64 vetoFor, uint64 period) external onlyGov {
        if (vetoFor > 30 days || period < 7 days || period > 365 days) revert BadInput();
        (vetoDelay, claimPeriod) = (vetoFor, period);
        emit DelaysSet(vetoFor, period);
    }

    // ------------------------------------------------------------------ data

    function submit(bytes32 dataHash, string calldata uri, uint32 rows, string calldata license) external returns (uint256 id) {
        if (dataHash == bytes32(0) || rows == 0 || bytes(uri).length == 0 || bytes(uri).length > MAX_URI
            || bytes(license).length == 0 || bytes(license).length > MAX_LICENSE) revert BadInput();
        if (idOfHash[dataHash] != 0) revert Duplicate();
        _subs.push(Submission(msg.sender, uint64(block.timestamp), rows, false, dataHash, uri, license));
        id = _subs.length;
        idOfHash[dataHash] = id;
        emit Submitted(id, msg.sender, dataHash, rows, uri, license);
    }

    function exclude(uint256 id, bool on) external onlyGov {
        if (id == 0 || id > _subs.length) revert BadInput();
        _subs[id - 1].excluded = on;
        emit Excluded(id, on);
    }

    function submissionCount() external view returns (uint256) { return _subs.length; }

    function submission(uint256 id) external view returns (address contributor, uint64 at, uint32 rows, bool excluded, bytes32 dataHash, string memory uri, string memory license) {
        Submission storage s = _subs[id - 1];
        return (s.contributor, s.at, s.rows, s.excluded, s.dataHash, s.uri, s.license);
    }

    // ------------------------------------------------------------------ rewards

    function available() public view returns (uint256) {
        return address(this).balance - reserved;
    }

    function postRound(bytes32 root, uint128 total, bytes32 reportHash, string calldata reportUri) external returns (uint256 round) {
        if (msg.sender != poster) revert NotPoster();
        if (root == bytes32(0) || total == 0 || bytes(reportUri).length > MAX_URI) revert BadInput();
        if (total > available()) revert NotEnoughFunds();
        reserved += total;
        uint64 nowT = uint64(block.timestamp);
        _rounds.push(Round(root, total, 0, nowT, nowT + vetoDelay, nowT + vetoDelay + claimPeriod, false, false, reportHash, reportUri));
        round = _rounds.length;
        emit RoundPosted(round, root, total, reportHash, reportUri);
    }

    function veto(uint256 round) external onlyGov {
        Round storage r = _round(round);
        if (r.vetoed || block.timestamp >= r.claimFrom) revert NotOpen();
        r.vetoed = true;
        reserved -= r.total;
        emit RoundVetoed(round);
    }

    /// Leaf: keccak256(keccak256(abi.encode(this, chainid, round, account, amount))); pairs hashed sorted.
    function leafOf(uint256 round, address account, uint256 amount) public view returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(address(this), block.chainid, round, account, amount))));
    }

    /// Pays `account` its reward for `round` (anyone may send it; the coins go to the account).
    function claim(uint256 round, address account, uint256 amount, bytes32[] calldata proof) external {
        Round storage r = _round(round);
        if (r.vetoed || block.timestamp < r.claimFrom || block.timestamp >= r.expires) revert NotOpen();
        if (claimed[round][account]) revert AlreadyClaimed();
        bytes32 h = leafOf(round, account, amount);
        for (uint256 i; i < proof.length; i++) {
            bytes32 p = proof[i];
            h = h < p ? keccak256(abi.encode(h, p)) : keccak256(abi.encode(p, h));
        }
        if (h != r.root) revert BadProof();
        if (uint256(r.claimed) + amount > r.total) revert NotEnoughFunds();
        claimed[round][account] = true;
        r.claimed += uint128(amount);
        reserved -= amount;
        (bool ok,) = account.call{value: amount}("");
        if (!ok) revert SendFailed();
        emit Claimed(round, account, amount);
    }

    /// After the claim period, what was not claimed goes back to the pool.
    function sweep(uint256 round) external {
        Round storage r = _round(round);
        if (r.vetoed || r.swept || block.timestamp < r.expires) revert NotOpen();
        r.swept = true;
        uint256 left = r.total - r.claimed;
        reserved -= left;
        emit Swept(round, left);
    }

    function roundCount() external view returns (uint256) { return _rounds.length; }

    function rounds(uint256 round) external view returns (bytes32 root, uint256 total, uint256 claimedAmount, uint64 postedAt, uint64 claimFrom, uint64 expires, bool vetoed, bytes32 reportHash, string memory reportUri) {
        Round storage r = _round(round);
        return (r.root, r.total, r.claimed, r.postedAt, r.claimFrom, r.expires, r.vetoed, r.reportHash, r.reportUri);
    }

    function _round(uint256 round) private view returns (Round storage) {
        if (round == 0 || round > _rounds.length) revert BadRound();
        return _rounds[round - 1];
    }
}

contracts/DetectorPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IForesightTracks {
    function modelOwner(bytes32 modelId) external view returns (address);
    function tracks(bytes32 modelId) external view returns (uint32 n, uint32 unrevealed, uint64 brierSum);
}

/// @title DetectorPool: evolving scam detectors (testnet)
/// @notice A detector "organism" is a rule set or model (its spec's hash + URI, e.g. a
///         zetaphy-neuro/ml/detectors spec JSON) with an author, a testnet stake, a parent
///         (the organism it was mutated from, 0 for none) and a ForesightRegistry model id.
///         The organism forecasts resolved questions (RiskForecasts, the arena) through
///         ForesightRegistry with commit-reveal, so its record cannot be faked or copied.
///
///         Every round (anyone may call `scoreRound` once it ended), each living organism's
///         Brier scores from that round are read from ForesightRegistry:
///           - at least `minForecasts` scored and better than always-50% (Brier < 0.25): a
///             winner, paid from the slashed stakes plus `rewardPerRound` from the pool, in
///             proportion to (0.25 - Brier) x forecasts;
///           - worse than always-50%: a loser, `slashBps` of its stake is slashed, one strike;
///             at `maxStrikes` strikes, or a stake below `minStake`, it is retired (the rest
///             of its stake is returned to its author);
///           - fewer forecasts: no change, but after MAX_IDLE such rounds in a row it is retired
///             (stake returned, not slashed), so the pool only keeps detectors that keep working.
///         A mutation script (zetaphy-neuro/ml/detectors/mutate.js, run on a GitHub Actions
///         schedule) breeds new variants from the best organisms and registers them.
contract DetectorPool {
    uint256 public constant BPS = 10_000;
    uint256 public constant COIN_FLIP = 25_000_000; // Brier 0.25 at 1e8 scale
    uint256 public constant MAX_ALIVE = 64;
    uint256 public constant MAX_URI = 200;
    uint16 public constant MAX_IDLE = 4;     // retired (stake returned, no slash) after 4 idle rounds

    struct Organism {
        address author;
        uint32 parent;
        uint16 strikes;
        uint16 wins;
        uint16 idle;         // rounds in a row with too few forecasts
        bool alive;
        bool leaving;
        uint64 born;
        uint128 stake;
        bytes32 modelId;
        bytes32 specHash;
        uint32 lastN;        // Foresight track at the last round
        uint64 lastSum;
        uint64 lastBrier;    // the last round's mean Brier (1e8), 0 if not scored
        string uri;
    }

    address public governance;
    IForesightTracks public foresight;
    uint128 public minStake = 1 ether;
    uint16 public slashBps = 2000;
    uint16 public maxStrikes = 3;
    uint32 public minForecasts = 3;
    uint64 public roundLength = 7 days;
    uint128 public rewardPerRound = 10 ether;
    uint64 public roundEnd;
    uint32 public round = 1;
    uint256 public pool;        // funded rewards + slashed stakes not yet paid
    uint256 public totalStake;

    Organism[] private _orgs;
    uint32[] public aliveIds;
    mapping(bytes32 => uint32) public organismOfModel;
    mapping(address => uint256) public owed;

    event Born(uint32 indexed id, address indexed author, uint32 indexed parent, bytes32 modelId, bytes32 specHash, uint256 stake, string uri);
    event Won(uint32 indexed id, uint32 indexed round, uint256 brier, uint256 reward);
    event Slashed(uint32 indexed id, uint32 indexed round, uint256 brier, uint256 n, uint256 amount, uint16 strikes);
    event Retired(uint32 indexed id, uint32 indexed round, uint256 returned);
    event RoundScored(uint32 indexed round, uint256 winners, uint256 losers, uint256 paid, uint64 nextEnd);
    event Funded(address indexed from, uint256 amount);
    event ParamsSet(uint128 minStake, uint16 slashBps, uint16 maxStrikes, uint32 minForecasts, uint64 roundLength, uint128 rewardPerRound);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadInput();
    error NotModelOwner();
    error ModelInUse();
    error Full();
    error NotAuthor();
    error NotYet();
    error NothingOwed();
    error SendFailed();

    constructor(address governance_, IForesightTracks foresight_) {
        governance = governance_;
        foresight = foresight_;
        roundEnd = uint64(block.timestamp) + roundLength;
        _orgs.push(); // id 0 = none
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable { pool += msg.value; emit Funded(msg.sender, msg.value); }
    function fund() external payable { pool += msg.value; emit Funded(msg.sender, msg.value); }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }

    function setParams(uint128 stake, uint16 slash, uint16 strikes, uint32 minF, uint64 length, uint128 reward) external onlyGov {
        if (stake == 0 || slash > 5000 || strikes == 0 || minF == 0 || length < 1 hours || length > 90 days) revert BadInput();
        (minStake, slashBps, maxStrikes, minForecasts, roundLength, rewardPerRound) = (stake, slash, strikes, minF, length, reward);
        emit ParamsSet(stake, slash, strikes, minF, length, reward);
    }

    // ------------------------------------------------------------------ organisms

    function register(bytes32 modelId, bytes32 specHash, uint32 parent, string calldata uri) external payable returns (uint32 id) {
        if (msg.value < minStake || msg.value > type(uint128).max || specHash == bytes32(0) || bytes(uri).length > MAX_URI || parent >= _orgs.length) revert BadInput();
        if (foresight.modelOwner(modelId) != msg.sender) revert NotModelOwner();
        if (organismOfModel[modelId] != 0) revert ModelInUse();
        if (aliveIds.length >= MAX_ALIVE) revert Full();
        (uint32 n,, uint64 sum) = foresight.tracks(modelId);
        id = uint32(_orgs.length);
        _orgs.push(Organism(msg.sender, parent, 0, 0, 0, true, false, uint64(block.timestamp), uint128(msg.value), modelId, specHash, n, sum, 0, uri));
        organismOfModel[modelId] = id;
        aliveIds.push(id);
        totalStake += msg.value;
        emit Born(id, msg.sender, parent, modelId, specHash, msg.value, uri);
    }

    /// Leaves after the next round is scored (so a bad round cannot be dodged).
    function requestExit(uint32 id) external {
        Organism storage o = _orgs[id];
        if (o.author != msg.sender || !o.alive) revert NotAuthor();
        o.leaving = true;
    }

    function organismCount() external view returns (uint256) { return _orgs.length - 1; }
    function aliveCount() external view returns (uint256) { return aliveIds.length; }

    function organism(uint32 id) external view returns (address author, uint32 parent, bool alive, uint128 stake, uint16 strikes, uint16 wins, bytes32 modelId, bytes32 specHash, uint64 lastBrier, string memory uri) {
        Organism storage o = _orgs[id];
        return (o.author, o.parent, o.alive, o.stake, o.strikes, o.wins, o.modelId, o.specHash, o.lastBrier, o.uri);
    }

    // ------------------------------------------------------------------ rounds

    function scoreRound() external {
        if (block.timestamp < roundEnd) revert NotYet();
        uint256 len = aliveIds.length;
        uint256[] memory weight = new uint256[](len);
        uint256 totalWeight;
        uint256 slashed;
        uint256 winners;
        uint256 losers;
        for (uint256 i; i < len; i++) {
            (uint256 w, uint256 cut, bool lost) = _judge(aliveIds[i]);
            weight[i] = w;
            totalWeight += w;
            slashed += cut;
            if (w > 0) winners++;
            if (lost) losers++;
        }
        pool += slashed;
        uint256 paid;
        if (totalWeight > 0) {
            // slashed stakes are always passed on; the funded part is capped per round
            uint256 budget = rewardPerRound + slashed;
            if (budget > pool) budget = pool;
            for (uint256 i; i < len; i++) {
                if (weight[i] == 0) continue;
                uint256 r = (budget * weight[i]) / totalWeight;
                Organism storage o = _orgs[aliveIds[i]];
                owed[o.author] += r;
                paid += r;
                emit Won(aliveIds[i], round, o.lastBrier, r);
            }
            pool -= paid;
        }
        _retire();
        emit RoundScored(round, winners, losers, paid, uint64(block.timestamp) + roundLength);
        round++;
        roundEnd = uint64(block.timestamp) + roundLength;
    }

    /// One organism's round: its weight if it won, the stake cut if it lost.
    function _judge(uint32 id) private returns (uint256 w, uint256 cut, bool lost) {
        Organism storage o = _orgs[id];
        (uint32 n,, uint64 sum) = foresight.tracks(o.modelId);
        uint256 dn = n - o.lastN;
        uint256 dsum = sum - o.lastSum;
        (o.lastN, o.lastSum) = (n, sum);
        if (dn < minForecasts) { o.lastBrier = 0; o.idle++; return (0, 0, false); }
        o.idle = 0;
        uint256 mean = dsum / dn;
        o.lastBrier = uint64(mean);
        if (mean < COIN_FLIP) {
            o.strikes = 0;
            o.wins++;
            return ((COIN_FLIP - mean) * dn, 0, false);
        }
        if (mean > COIN_FLIP) {
            cut = (uint256(o.stake) * slashBps) / BPS;
            o.stake -= uint128(cut);
            totalStake -= cut;
            o.strikes++;
            emit Slashed(id, round, mean, dn, cut, o.strikes);
            return (0, cut, true);
        }
    }

    /// Retires organisms with too many strikes, too little stake, or that asked to leave.
    function _retire() private {
        for (uint256 i = aliveIds.length; i > 0; i--) {
            uint32 id = aliveIds[i - 1];
            Organism storage o = _orgs[id];
            if (o.strikes >= maxStrikes || o.stake < minStake || o.leaving || o.idle >= MAX_IDLE) {
                o.alive = false;
                uint256 back = o.stake;
                o.stake = 0;
                totalStake -= back;
                owed[o.author] += back;
                aliveIds[i - 1] = aliveIds[aliveIds.length - 1];
                aliveIds.pop();
                emit Retired(id, round, back);
            }
        }
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingOwed();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }
}

contracts/FederatedRounds.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title FederatedRounds: commit-reveal inbox for Neuro's federated updates (testnet)
/// @notice Browsers send their clipped + noised update (zetaphy-neuro/ml/fl/codec.js
///         bytes) in two steps, so nobody can tailor an update to the others of
///         the same round:
///           1. commit phase: commit(round, keccak256(abi.encode(keccak256(payload), salt, sender)))
///           2. reveal phase: reveal(round, salt, payload) emits the payload.
///         The aggregator (a scheduled GitHub Actions job or a runner) reads
///         the Revealed events after the round; the transaction's sender is the
///         update's signer. No server, no storage of payloads (events only).
///
///         Round r covers blocks [start + r*period, start + (r+1)*period) with
///         period = commitBlocks + revealBlocks; the first commitBlocks of it
///         are the commit phase, the rest the reveal phase.
///
///         Closed by default: the constructor leaves it paused (no commits) until
///         governance (the ZetaphyTimelock) calls setPaused(false); see
///         `zetaphy fl propose open`. Reveals of commitments already made stay
///         possible while paused, so a pause never strands a committed update.
///
///         Limits (testnet): one commitment per address per round, at most
///         maxPerRound commitments per round, payload <= 16 KiB. Sybil
///         resistance is NOT provided here: robust aggregation bounds what a
///         minority of addresses can do (docs/future/federated.md).
contract FederatedRounds {
    uint256 public constant MAX_PAYLOAD = 16384;

    address public governance;
    bool public paused;
    uint64 public immutable start;
    uint64 public immutable commitBlocks;
    uint64 public immutable revealBlocks;
    uint32 public maxPerRound;

    mapping(uint256 => mapping(address => bytes32)) public commitmentOf;
    mapping(uint256 => mapping(address => bool)) public revealed;
    mapping(uint256 => uint32) public commits;
    mapping(uint256 => uint32) public reveals;

    event Committed(uint256 indexed round, address indexed sender, bytes32 commitment);
    event Revealed(uint256 indexed round, address indexed sender, bytes32 payloadHash, bytes payload);
    event Paused(bool paused);
    event MaxPerRound(uint32 value);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadValue();
    error WrongPhase();
    error AlreadyCommitted();
    error RoundFull();
    error BadReveal();
    error IsPaused();

    constructor(address governance_, uint64 start_, uint64 commitBlocks_, uint64 revealBlocks_, uint32 maxPerRound_) {
        if (governance_ == address(0) || commitBlocks_ == 0 || revealBlocks_ == 0 || maxPerRound_ == 0) revert BadValue();
        governance = governance_;
        start = start_;
        commitBlocks = commitBlocks_;
        revealBlocks = revealBlocks_;
        maxPerRound = maxPerRound_;
        paused = true; // closed until governance opens it
        emit Paused(true);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    function setPaused(bool p) external onlyGovernance {
        paused = p;
        emit Paused(p);
    }

    function setMaxPerRound(uint32 n) external onlyGovernance {
        if (n == 0) revert BadValue();
        maxPerRound = n;
        emit MaxPerRound(n);
    }

    /// First block of a round.
    function roundStart(uint256 round) public view returns (uint256) {
        return uint256(start) + round * (uint256(commitBlocks) + revealBlocks);
    }

    /// The round and phase (1 = commit, 2 = reveal) at a block; phase 0 before the first round.
    function phaseAt(uint256 blockNumber) public view returns (uint256 round, uint8 phase) {
        if (blockNumber < start) return (0, 0);
        uint256 period = uint256(commitBlocks) + revealBlocks;
        uint256 off = blockNumber - start;
        round = off / period;
        phase = off % period < commitBlocks ? 1 : 2;
    }

    function commitmentFor(bytes32 payloadHash, bytes32 salt, address sender) public pure returns (bytes32) {
        return keccak256(abi.encode(payloadHash, salt, sender));
    }

    function commit(uint256 round, bytes32 commitment) external {
        if (paused) revert IsPaused();
        (uint256 r, uint8 phase) = phaseAt(block.number);
        if (phase != 1 || r != round) revert WrongPhase();
        if (commitment == bytes32(0)) revert BadValue();
        if (commitmentOf[round][msg.sender] != bytes32(0)) revert AlreadyCommitted();
        if (commits[round] >= maxPerRound) revert RoundFull();
        commitmentOf[round][msg.sender] = commitment;
        commits[round] += 1;
        emit Committed(round, msg.sender, commitment);
    }

    function reveal(uint256 round, bytes32 salt, bytes calldata payload) external {
        (uint256 r, uint8 phase) = phaseAt(block.number);
        if (phase != 2 || r != round) revert WrongPhase();
        if (payload.length == 0 || payload.length > MAX_PAYLOAD) revert BadValue();
        bytes32 c = commitmentOf[round][msg.sender];
        bytes32 ph = keccak256(payload);
        if (c == bytes32(0) || revealed[round][msg.sender] || c != commitmentFor(ph, salt, msg.sender)) revert BadReveal();
        revealed[round][msg.sender] = true;
        reveals[round] += 1;
        emit Revealed(round, msg.sender, ph, payload);
    }
}

contracts/ForesightRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ForesightRegistry: Proof of Foresight (testnet)
/// @notice Forecasters and AI models commit keccak256(eventId, modelId, p, salt)
///         before an event's commit deadline and reveal p after it, so nobody can
///         copy a forecast or change it once the answer is known. When the event's
///         resolver states the outcome, every commitment is scored with the Brier
///         score (p - outcome)^2 and added to the model's public track record.
///         A commitment that is never revealed scores the worst possible loss (1.0),
///         so hiding a bad forecast never pays.
///
///         Probabilities are in basis points (0..10000 = 0..100%); a Brier score is
///         stored scaled by 1e8 (1.0 = 100_000_000). Always saying 50% scores 0.25.
///
///         Only resolvers that governance approved (contracts that resolve from
///         on-chain facts, such as RiskForecasts and RedBlueArena) may open events,
///         so nobody can make up events whose outcome they choose.
///         The track record is a weight, not money: DetectorPool pays and slashes
///         detectors with it, and Neuro may weight models by `skill`.
contract ForesightRegistry {
    uint256 public constant ONE = 10_000;
    uint256 public constant MAX_LOSS = ONE * ONE;      // 1.0
    uint256 public constant COIN_FLIP = MAX_LOSS / 4;  // 0.25: always 50%
    uint256 public constant PRIOR_N = 10;              // skill shrinks toward 0 with few forecasts

    enum Outcome { Open, No, Yes, Void }

    struct Event {
        address resolver;
        uint64 commitEnd;
        uint64 revealEnd;
        Outcome outcome;
        uint32 commits;
        bytes32 topic;       // what the event is, e.g. keccak256(abi.encode(market contract, market id))
    }

    struct Forecast {
        bytes32 commitment;
        uint16 p;            // revealed probability of Yes, basis points
        bool revealed;
        bool scored;
    }

    struct Track {
        uint32 n;            // scored forecasts
        uint32 unrevealed;   // of which never revealed (scored 1.0)
        uint64 brierSum;     // sum of Brier scores, 1e8 each at most
    }

    address public governance;
    uint256 public eventCount;
    mapping(address => bool) public resolvers;
    mapping(bytes32 => address) public modelOwner;
    mapping(uint256 => Event) public events;
    mapping(uint256 => mapping(bytes32 => Forecast)) public forecasts;
    mapping(bytes32 => Track) public tracks;

    event GovernanceSet(address governance);
    event ResolverSet(address indexed resolver, bool on);
    event ModelRegistered(bytes32 indexed modelId, address indexed owner);
    event ModelTransferred(bytes32 indexed modelId, address indexed to);
    event EventOpened(uint256 indexed id, address indexed resolver, bytes32 topic, uint64 commitEnd, uint64 revealEnd);
    event CommitsClosed(uint256 indexed id, uint64 at);
    event Committed(uint256 indexed id, bytes32 indexed modelId, bytes32 commitment);
    event Revealed(uint256 indexed id, bytes32 indexed modelId, uint16 p);
    event Resolved(uint256 indexed id, Outcome outcome);
    event Scored(uint256 indexed id, bytes32 indexed modelId, uint256 brier, bool revealed);

    error NotGovernance();
    error NotResolver();
    error NotModelOwner();
    error Taken();
    error BadTimes();
    error Closed();
    error NotYet();
    error BadReveal();
    error BadOutcome();
    error NothingToScore();

    constructor(address governance_) {
        governance = governance_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
        emit GovernanceSet(g);
    }

    function setResolver(address r, bool on) external onlyGov {
        resolvers[r] = on;
        emit ResolverSet(r, on);
    }

    // ------------------------------------------------------------------ models

    /// A model id (e.g. keccak256("neuro-ml nml-b4c35477f7b1") or a detector's id) belongs to the first to claim it.
    function registerModel(bytes32 modelId) external {
        if (modelId == bytes32(0) || modelOwner[modelId] != address(0)) revert Taken();
        modelOwner[modelId] = msg.sender;
        emit ModelRegistered(modelId, msg.sender);
    }

    function transferModel(bytes32 modelId, address to) external {
        if (modelOwner[modelId] != msg.sender || to == address(0)) revert NotModelOwner();
        modelOwner[modelId] = to;
        emit ModelTransferred(modelId, to);
    }

    // ------------------------------------------------------------------ events

    function openEvent(bytes32 topic, uint64 commitEnd, uint64 revealEnd) external returns (uint256 id) {
        if (!resolvers[msg.sender]) revert NotResolver();
        if (commitEnd <= block.timestamp || revealEnd <= commitEnd) revert BadTimes();
        id = ++eventCount;
        events[id] = Event(msg.sender, commitEnd, revealEnd, Outcome.Open, 0, topic);
        emit EventOpened(id, msg.sender, topic, commitEnd, revealEnd);
    }

    /// The resolver closes commits early, e.g. as soon as the watched condition is seen.
    function closeCommits(uint256 id) external {
        Event storage e = events[id];
        if (msg.sender != e.resolver) revert NotResolver();
        if (block.timestamp < e.commitEnd) {
            uint64 shift = e.commitEnd - uint64(block.timestamp);
            e.commitEnd = uint64(block.timestamp);
            e.revealEnd -= shift; // the reveal period keeps its length
            emit CommitsClosed(id, uint64(block.timestamp));
        }
    }

    function resolve(uint256 id, Outcome outcome) external {
        Event storage e = events[id];
        if (msg.sender != e.resolver) revert NotResolver();
        if (outcome == Outcome.Open) revert BadOutcome();
        if (e.outcome != Outcome.Open) revert Closed();
        if (block.timestamp < e.commitEnd) {
            // resolving closes commits
            uint64 shift = e.commitEnd - uint64(block.timestamp);
            e.commitEnd = uint64(block.timestamp);
            e.revealEnd -= shift;
        }
        e.outcome = outcome;
        emit Resolved(id, outcome);
    }

    // ------------------------------------------------------------------ forecasts

    function commitmentOf(uint256 id, bytes32 modelId, uint16 p, bytes32 salt) public pure returns (bytes32) {
        return keccak256(abi.encode(id, modelId, p, salt));
    }

    /// Commits (or replaces, before the deadline) a model's hidden forecast.
    function commit(uint256 id, bytes32 modelId, bytes32 commitment) external {
        Event storage e = events[id];
        if (modelOwner[modelId] != msg.sender) revert NotModelOwner();
        if (e.resolver == address(0) || e.outcome != Outcome.Open || block.timestamp >= e.commitEnd) revert Closed();
        if (commitment == bytes32(0)) revert BadReveal();
        Forecast storage f = forecasts[id][modelId];
        if (f.commitment == bytes32(0)) e.commits++;
        f.commitment = commitment;
        emit Committed(id, modelId, commitment);
    }

    /// Anyone holding the salt may reveal, after the commit deadline and before the reveal deadline.
    function reveal(uint256 id, bytes32 modelId, uint16 p, bytes32 salt) external {
        Event storage e = events[id];
        if (block.timestamp < e.commitEnd) revert NotYet();
        if (block.timestamp >= e.revealEnd) revert Closed();
        Forecast storage f = forecasts[id][modelId];
        if (p > ONE || f.revealed || f.commitment == bytes32(0) || f.commitment != commitmentOf(id, modelId, p, salt)) revert BadReveal();
        f.p = p;
        f.revealed = true;
        emit Revealed(id, modelId, p);
    }

    /// Adds a forecast's Brier score to its model's track record (anyone may call).
    /// A revealed forecast is scored once the event is resolved; an unrevealed one after the reveal deadline (as 1.0).
    function score(uint256 id, bytes32 modelId) public returns (uint256 brier) {
        Event storage e = events[id];
        Forecast storage f = forecasts[id][modelId];
        if (f.commitment == bytes32(0) || f.scored || e.outcome == Outcome.Open || e.outcome == Outcome.Void) revert NothingToScore();
        if (!f.revealed && block.timestamp < e.revealEnd) revert NotYet();
        if (f.revealed) {
            uint256 target = e.outcome == Outcome.Yes ? ONE : 0;
            uint256 d = f.p > target ? f.p - target : target - f.p;
            brier = d * d;
        } else {
            brier = MAX_LOSS;
        }
        f.scored = true;
        Track storage t = tracks[modelId];
        t.n += 1;
        if (!f.revealed) t.unrevealed += 1;
        t.brierSum += uint64(brier);
        emit Scored(id, modelId, brier, f.revealed);
    }

    function scoreMany(uint256 id, bytes32[] calldata modelIds) external {
        for (uint256 i; i < modelIds.length; i++) {
            Forecast storage f = forecasts[id][modelIds[i]];
            if (f.commitment != bytes32(0) && !f.scored) score(id, modelIds[i]);
        }
    }

    // ------------------------------------------------------------------ track record

    /// Mean Brier score (1e8 = 1.0) over n scored forecasts; mean is 0 when n is 0.
    function brierOf(bytes32 modelId) external view returns (uint256 n, uint256 mean) {
        Track memory t = tracks[modelId];
        n = t.n;
        mean = n == 0 ? 0 : t.brierSum / n;
    }

    /// Skill in basis points: how much better than always saying 50% (0 = no better, 10000 = perfect),
    /// shrunk by n / (n + PRIOR_N) so a short lucky record weighs little.
    function skill(bytes32 modelId) external view returns (uint256) {
        Track memory t = tracks[modelId];
        if (t.n == 0) return 0;
        uint256 mean = t.brierSum / t.n;
        if (mean >= COIN_FLIP) return 0;
        uint256 s = ((COIN_FLIP - mean) * ONE) / COIN_FLIP;
        return (s * t.n) / (t.n + PRIOR_N);
    }
}

contracts/HackInsurance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Parametric hack insurance, TESTNET ONLY (docs/future/crosschain-assist.md, item 32). Testnet ZETAPHY has no
// value; nothing here is an insurance product and no real money may ever be put in it.
//
//   pool:    anyone deposits testnet ZETAPHY for shares; a withdrawal is requested and paid after
//            `withdrawDelay` (longer than a claim's whole life, so a known incident cannot be fled), at the
//            share price of that time (requested shares still carry losses until then). A request can be
//            executed only within WITHDRAW_WINDOW after it is ready (no standing exit), and no withdrawal
//            runs while any claim is open (voting, approved and not fully paid, or disputed). Shares are
//            priced with a virtual share and a virtual wei (ERC-4626-style offset): a pool emptied by payouts
//            does not hand new deposits to old share holders, and a donation cannot inflate the price.
//   targets: governance lists the covered contracts (a target key, as ThreatRegistry.addressKey(chainid, a))
//            with a cap per claim.
//   covers:  anyone buys cover on a listed target: amount, duration; premium = amount x premiumBps x
//            duration / year, paid into the pool. Total active cover is limited to maxCoverBps of the pool.
//   claims:  the holder files the incident as deterministic replay evidence: the exploit's transaction hashes
//            and the block range (all inside the cover's blocks), the hash of Neuro's forensic report of that
//            replay and the loss it computed, with a bond. evidenceHash = keccak256(abi.encode(chain id, target,
//            txHashes, fromBlock, toBlock)) is what every runner replays.
//   vote:    the committee is NeuroJobs' runners (active, with a track record, like ThreatRegistry). A runner
//            approves by restating the SAME report hash and loss its own replay produced; anything else counts
//            as a rejection. `quorum` approvals approve, `quorum` rejections reject (the bond goes to the pool),
//            neither within `voteWindow`: expired (bond refunded).
//   dispute: during `disputeWindow` after approval anyone may dispute with a bond; governance (the chain's
//            gov module or the timelock) then upholds or overturns. Undisputed, anyone triggers the payout.
//   payout:  the entitlement min(loss, the cover's amount, the target's cap, maxClaimBps of the pool) is fixed
//            when the claim is approved; each payout pays what is left of it, at most what is left of the
//            day's cap and what the pool holds. The claim stays Approved (and the cover taken) until the whole
//            entitlement is paid, on later days if the cap is used; a payout that would pay 0 reverts.
// What this does not do (the doc says it plainly): prove the loss on chain (the runners' replays are the
// evidence), cover chains other than this one, price risk, or protect LPs from a governance mistake.

interface IHIRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

contract HackInsurance {
    enum ClaimState { None, Voting, Approved, Rejected, Expired, Disputed, Paid, Overturned }

    struct Target { bool listed; uint128 capPerClaim; }
    struct Cover { address holder; bytes32 target; uint128 amount; uint64 startBlock; uint64 endBlock; uint64 end; bool claimed; }
    struct Claim {
        uint256 coverId;
        address claimant;
        ClaimState state;
        uint8 approvals;
        uint8 rejections;
        uint64 filedAt;
        uint64 decidedAt;     // approval time (start of the dispute window)
        uint128 loss;         // what the forensic report computed (wei)
        uint128 bond;
        bytes32 evidenceHash;
        bytes32 reportHash;
        address disputer;
        uint128 disputeBond;
    }

    uint256 public constant MAX_TXS = 16;
    uint256 public constant YEAR = 365 days;
    uint64 public constant WITHDRAW_WINDOW = 2 days; // a ready withdrawal request must be used within this

    IHIRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    address public governance;

    // parameters (governance)
    uint16 public premiumBps = 200;          // per year of cover
    uint16 public maxCoverBps = 30000;       // active cover at most 3x the pool
    uint16 public maxClaimBps = 2000;        // one claim pays at most 20% of the pool
    uint128 public dailyCap = 1000 ether;    // all payouts per UTC day
    uint128 public claimBond = 1 ether;
    uint128 public disputeBond = 5 ether;
    uint64 public voteWindow = 3 days;
    uint64 public disputeWindow = 2 days;
    uint64 public withdrawDelay = 7 days;

    // pool
    uint256 public totalShares;
    mapping(address => uint256) public shares;
    mapping(address => uint256) public pendingShares;
    mapping(address => uint64) public withdrawReadyAt;
    uint256 public bondsHeld;                // claim + dispute bonds (not pool money)
    uint256 public activeCover;
    uint64 public payDay;
    uint128 public paidToday;

    mapping(bytes32 => Target) public targets;
    Cover[] public covers;
    Claim[] public claims;
    mapping(uint256 => mapping(address => bool)) public voted;
    mapping(uint256 => uint256) public claimOfCover;   // cover id -> claim id + 1 of its open/approved claim
    mapping(uint256 => uint256) public entitlement;    // claim id -> what it is owed in total (set at approval)
    mapping(uint256 => uint256) public paidOut;        // claim id -> paid so far
    uint256 public openClaims;                         // claims Voting, Approved (not fully paid) or Disputed

    event Deposited(address indexed lp, uint256 amount, uint256 shares);
    event WithdrawRequested(address indexed lp, uint256 shares, uint64 readyAt);
    event Withdrawn(address indexed lp, uint256 shares, uint256 amount);
    event TargetSet(bytes32 indexed target, bool listed, uint128 capPerClaim);
    event CoverBought(uint256 indexed id, address indexed holder, bytes32 indexed target, uint128 amount, uint64 end, uint256 premium);
    event ClaimFiled(uint256 indexed id, uint256 indexed coverId, bytes32 evidenceHash, bytes32 reportHash, uint128 loss);
    event ClaimEvidence(uint256 indexed id, bytes32[] txHashes, uint64 fromBlock, uint64 toBlock, string uri);
    event ClaimVoted(uint256 indexed id, address indexed runner, bool approve, bytes32 reportHash, uint128 loss);
    event ClaimStateChanged(uint256 indexed id, ClaimState state);
    event Disputed(uint256 indexed id, address indexed by, string why);
    event PaidOut(uint256 indexed id, address indexed to, uint256 amount);
    event ParamsSet();
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error NotListed();
    error OverCapacity(uint256 room);
    error Premium(uint256 needed);
    error Bond(uint256 needed);
    error NotHolder();
    error CoverEnded();
    error Claimed();
    error BadEvidence();
    error WrongState(ClaimState state);
    error AlreadyVoted();
    error TooLate();
    error NotYet(uint64 at);
    error NoShares();
    error PayFailed();
    error BadParams();
    error ClaimsOpen();
    error RequestExpired(uint64 at);
    error NothingToPay();

    constructor(IHIRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_) {
        require(quorum_ >= 2 && governance_ != address(0), "params");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }

    function setParams(uint16 premiumBps_, uint16 maxCoverBps_, uint16 maxClaimBps_, uint128 dailyCap_, uint128 claimBond_, uint128 disputeBond_,
        uint64 voteWindow_, uint64 disputeWindow_, uint64 withdrawDelay_) external onlyGov
    {
        if (maxClaimBps_ > 10000 || maxClaimBps_ == 0 || premiumBps_ > 10000 || voteWindow_ < 1 hours || disputeWindow_ < 1 hours
            || withdrawDelay_ < voteWindow_ + disputeWindow_) revert BadParams();
        (premiumBps, maxCoverBps, maxClaimBps, dailyCap, claimBond, disputeBond) = (premiumBps_, maxCoverBps_, maxClaimBps_, dailyCap_, claimBond_, disputeBond_);
        (voteWindow, disputeWindow, withdrawDelay) = (voteWindow_, disputeWindow_, withdrawDelay_);
        emit ParamsSet();
    }

    function setTarget(bytes32 target, bool listed, uint128 capPerClaim) external onlyGov {
        targets[target] = Target(listed, capPerClaim);
        emit TargetSet(target, listed, capPerClaim);
    }

    /// keccak256(abi.encode("zetaphy.threat.address", chainId, a)): the same key as ThreatRegistry.addressKey.
    function targetKey(uint256 chainId, address a) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.address", chainId, a)); }

    // ---------------------------------------------------------------- pool

    /// Pool money: everything held minus the bonds.
    function assets() public view returns (uint256) { return address(this).balance - bondsHeld; }

    function deposit() external payable {
        uint256 before = assets() - msg.value;
        // +1 virtual share and +1 virtual wei: 1:1 for the first deposit, and when the pool is empty but
        // shares exist the old shares are worth < 1 wei of the new money (HI-3).
        uint256 s = (msg.value * (totalShares + 1)) / (before + 1);
        if (s == 0) revert NoShares();
        shares[msg.sender] += s;
        totalShares += s;
        emit Deposited(msg.sender, msg.value, s);
    }

    function requestWithdraw(uint256 s) external {
        if (s == 0 || s > shares[msg.sender]) revert NoShares();
        pendingShares[msg.sender] = s;
        withdrawReadyAt[msg.sender] = uint64(block.timestamp) + withdrawDelay;
        emit WithdrawRequested(msg.sender, s, withdrawReadyAt[msg.sender]);
    }

    function withdraw() external {
        uint256 s = pendingShares[msg.sender];
        if (s == 0) revert NoShares();
        uint64 readyAt = withdrawReadyAt[msg.sender];
        if (block.timestamp < readyAt) revert NotYet(readyAt);
        if (block.timestamp > readyAt + WITHDRAW_WINDOW) revert RequestExpired(readyAt + WITHDRAW_WINDOW);  // HI-2
        if (openClaims != 0) revert ClaimsOpen();                                                            // HI-2
        if (s > shares[msg.sender]) s = shares[msg.sender];
        uint256 pool = assets();
        uint256 amount = (s * (pool + 1)) / (totalShares + 1);
        if (amount > pool) amount = pool;
        pendingShares[msg.sender] = 0;
        shares[msg.sender] -= s;
        totalShares -= s;
        emit Withdrawn(msg.sender, s, amount);
        _send(msg.sender, amount);
    }

    // ---------------------------------------------------------------- covers

    function premiumOf(uint128 amount, uint64 duration) public view returns (uint256) {
        return (uint256(amount) * premiumBps * duration) / (10000 * YEAR);
    }

    function buyCover(bytes32 target, uint128 amount, uint64 duration) external payable returns (uint256 id) {
        if (!targets[target].listed) revert NotListed();
        if (amount == 0 || duration < 1 days || duration > YEAR) revert BadParams();
        uint256 premium = premiumOf(amount, duration);
        if (msg.value < premium) revert Premium(premium);
        uint256 room = ((assets() - msg.value + premium) * maxCoverBps) / 10000;
        if (activeCover + amount > room) revert OverCapacity(room > activeCover ? room - activeCover : 0);
        activeCover += amount;
        covers.push(Cover(msg.sender, target, amount, uint64(block.number), type(uint64).max, uint64(block.timestamp) + duration, false));
        id = covers.length - 1;
        emit CoverBought(id, msg.sender, target, amount, uint64(block.timestamp) + duration, premium);
        if (msg.value > premium) _send(msg.sender, msg.value - premium);
    }

    /// Ends an expired cover's capacity use (anyone).
    function expireCover(uint256 coverId) external {
        Cover storage c = covers[coverId];
        if (block.timestamp < c.end || c.endBlock != type(uint64).max || claimOfCover[coverId] != 0) revert NotYet(c.end);
        c.endBlock = uint64(block.number);
        activeCover -= c.amount;
    }

    // ---------------------------------------------------------------- claims

    /// What every runner replays: this chain, the target, the exploit's transactions and the block range.
    function evidenceHash(bytes32 target, bytes32[] calldata txHashes, uint64 fromBlock, uint64 toBlock) public view returns (bytes32) {
        return keccak256(abi.encode(block.chainid, target, txHashes, fromBlock, toBlock));
    }

    function fileClaim(uint256 coverId, bytes32[] calldata txHashes, uint64 fromBlock, uint64 toBlock, bytes32 reportHash, uint128 loss, string calldata uri)
        external payable returns (uint256 id)
    {
        Cover storage c = covers[coverId];
        _checkFiling(c, coverId, txHashes.length, fromBlock, toBlock, reportHash, loss, bytes(uri).length);
        bondsHeld += msg.value;
        bytes32 ev = evidenceHash(c.target, txHashes, fromBlock, toBlock);
        claims.push(Claim(coverId, msg.sender, ClaimState.Voting, 0, 0, uint64(block.timestamp), 0, loss, uint128(msg.value), ev, reportHash, address(0), 0));
        id = claims.length - 1;
        claimOfCover[coverId] = id + 1;
        openClaims += 1;
        emit ClaimFiled(id, coverId, ev, reportHash, loss);
        emit ClaimEvidence(id, txHashes, fromBlock, toBlock, uri);
    }

    function _checkFiling(Cover storage c, uint256 coverId, uint256 txs, uint64 fromBlock, uint64 toBlock, bytes32 reportHash, uint128 loss, uint256 uriLen) private view {
        if (msg.sender != c.holder) revert NotHolder();
        if (c.claimed || claimOfCover[coverId] != 0) revert Claimed();
        if (block.timestamp > c.end + voteWindow) revert CoverEnded();
        if (msg.value != claimBond) revert Bond(claimBond);
        if (txs == 0 || txs > MAX_TXS || reportHash == bytes32(0) || loss == 0 || uriLen > 200
            || fromBlock > toBlock || fromBlock < c.startBlock || toBlock >= block.number) revert BadEvidence();
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    /// A runner's vote: approve only by restating the same forensic report hash and loss its replay produced.
    function vote(uint256 id, bool approve, bytes32 reportHash, uint128 loss) external {
        _checkRunner();
        Claim storage k = claims[id];
        if (k.state != ClaimState.Voting) revert WrongState(k.state);
        if (block.timestamp > k.filedAt + voteWindow) revert TooLate();
        if (msg.sender == k.claimant) revert NotRunner();
        if (voted[id][msg.sender]) revert AlreadyVoted();
        voted[id][msg.sender] = true;
        bool yes = approve && reportHash == k.reportHash && loss == k.loss;
        if (yes) k.approvals += 1; else k.rejections += 1;
        emit ClaimVoted(id, msg.sender, yes, reportHash, loss);
        if (k.approvals >= quorum) {
            k.state = ClaimState.Approved;
            k.decidedAt = uint64(block.timestamp);
            entitlement[id] = _entitlement(id);
            emit ClaimStateChanged(id, ClaimState.Approved);
        } else if (k.rejections >= quorum) {
            _close(id, ClaimState.Rejected, false);
        }
    }

    /// Neither quorum within the vote window: the bond comes back.
    function expire(uint256 id) external {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Voting) revert WrongState(k.state);
        if (block.timestamp <= k.filedAt + voteWindow) revert NotYet(k.filedAt + voteWindow);
        _close(id, ClaimState.Expired, true);
    }

    function dispute(uint256 id, string calldata why) external payable {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Approved) revert WrongState(k.state);
        if (block.timestamp >= k.decidedAt + disputeWindow) revert TooLate();
        if (msg.value != disputeBond) revert Bond(disputeBond);
        bondsHeld += msg.value;
        k.state = ClaimState.Disputed;
        k.disputer = msg.sender;
        k.disputeBond = uint128(msg.value);
        emit Disputed(id, msg.sender, why);
        emit ClaimStateChanged(id, ClaimState.Disputed);
    }

    /// Governance decides a dispute: upheld = the claim stands (the disputer's bond goes to the pool, then
    /// the payout follows); overturned = the claim fails (the claimant's bond goes to the disputer, whose own comes back).
    function resolveDispute(uint256 id, bool claimStands) external onlyGov {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Disputed) revert WrongState(k.state);
        uint256 db = k.disputeBond;
        bondsHeld -= db;
        k.disputeBond = 0;
        if (claimStands) {
            k.state = ClaimState.Approved;
            k.decidedAt = uint64(block.timestamp) - disputeWindow; // payable now
            emit ClaimStateChanged(id, ClaimState.Approved);
        } else {
            uint256 cb = k.bond;
            bondsHeld -= cb;
            k.bond = 0;
            k.state = ClaimState.Overturned;
            claimOfCover[k.coverId] = 0;
            openClaims -= 1;
            emit ClaimStateChanged(id, ClaimState.Overturned);
            _send(k.disputer, db + cb);
        }
    }

    /// The claim's total entitlement: min(loss, the cover's amount, the target's cap, maxClaimBps of the pool).
    /// Fixed when the claim is approved (vote quorum); an upheld dispute keeps it.
    function _entitlement(uint256 id) private view returns (uint256 amount) {
        Claim storage k = claims[id];
        Cover storage c = covers[k.coverId];
        amount = k.loss;
        if (c.amount < amount) amount = c.amount;
        uint128 cap = targets[c.target].capPerClaim;
        if (cap < amount) amount = cap;
        uint256 byPool = (assets() * maxClaimBps) / 10000;
        if (byPool < amount) amount = byPool;
    }

    /// What payout(id) would pay now: what is left of the entitlement, at most what is left of today's cap
    /// and what the pool holds.
    function payoutOf(uint256 id) public view returns (uint256 amount) {
        amount = entitlement[id] - paidOut[id];
        uint256 pool = assets();
        if (pool < amount) amount = pool;
        uint128 today = uint64(block.timestamp / 1 days) == payDay ? paidToday : 0;
        uint256 dayLeft = dailyCap > today ? dailyCap - today : 0;
        if (dayLeft < amount) amount = dayLeft;
    }

    /// Anyone, after the dispute window of an approved claim: pays the holder what payoutOf says. The claim is
    /// closed (Paid, bond returned, cover used) only once the whole entitlement is paid; until then it stays
    /// Approved and later calls (e.g. on the next day, when the daily cap is used) pay the rest (HI-1).
    function payout(uint256 id) external {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Approved) revert WrongState(k.state);
        if (block.timestamp < k.decidedAt + disputeWindow) revert NotYet(k.decidedAt + disputeWindow);
        uint256 amount = payoutOf(id);
        uint256 left = entitlement[id] - paidOut[id];
        if (amount == 0 && left != 0) revert NothingToPay();
        uint64 today = uint64(block.timestamp / 1 days);
        if (payDay != today) { payDay = today; paidToday = 0; }
        paidToday += uint128(amount);
        paidOut[id] += amount;
        uint256 bond;
        if (amount == left) {
            Cover storage c = covers[k.coverId];
            c.claimed = true;
            if (c.endBlock == type(uint64).max) { c.endBlock = uint64(block.number); activeCover -= c.amount; }
            k.state = ClaimState.Paid;
            openClaims -= 1;
            bond = k.bond;
            bondsHeld -= bond;
            k.bond = 0;
            emit ClaimStateChanged(id, ClaimState.Paid);
        }
        emit PaidOut(id, k.claimant, amount);
        _send(k.claimant, amount + bond);
    }

    function _close(uint256 id, ClaimState s, bool refund) private {
        Claim storage k = claims[id];
        k.state = s;
        claimOfCover[k.coverId] = 0;
        openClaims -= 1;
        uint256 b = k.bond;
        bondsHeld -= b;     // refunded, or (rejected) left in the contract as pool money
        k.bond = 0;
        emit ClaimStateChanged(id, s);
        if (refund) _send(k.claimant, b);
    }

    function _send(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    function coverCount() external view returns (uint256) { return covers.length; }
    function claimCount() external view returns (uint256) { return claims.length; }
}

contracts/HumanAgentLabels.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ILabelWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

interface ILabelAgents {
    function activeAgentOf(address account) external view returns (uint256);
}

/// The read interface for hooks (faucets, DEX gates, ...).
interface ILabels {
    /// 0 = no label, 1 = human (passkey-verified), 2 = registered AI agent
    function labelOf(address account) external view returns (uint8);
}

/// @title LabelRegistry: "human" or "agent" labels for accounts (testnet)
/// @notice
///   AGENT: an account an active agent of AgentRegistry transacts from
///          (bonded, not unbonding). Read live from the registry, so it
///          follows registration, unbonding and slashing.
///   HUMAN: an account whose owner showed a passkey (WebAuthn) with user
///          verification (fingerprint, face or device PIN), in one of two ways:
///          - on chain: proveHumanP256 checks the assertion through
///            WebAuthnVerifier (the P-256 precompile 0x…0100); the passkey's
///            challenge commits to this account and its nonce;
///          - off chain: an attester governance approved (a volunteer runner)
///            verified the assertion and signs an EIP-712 HumanAttestation
///            that anyone submits with attestHuman.
///          One passkey (its public key hash) labels one account at a time;
///          moving it to another account drops the old one's label.
///   An agent account is labelled AGENT even if it once proved a passkey.
///
///   What a HUMAN label does NOT prove: that the person is unique. Anyone can
///   make many passkeys. It proves a person was present at a device when the
///   label was made (expires after humanTtl). Hooks must treat it as a
///   speed bump against simple bots, not as proof of personhood.
contract LabelRegistry is ILabels {
    uint8 public constant NONE = 0;
    uint8 public constant HUMAN = 1;
    uint8 public constant AGENT = 2;
    uint8 public constant BY_PASSKEY = 1;
    uint8 public constant BY_ATTESTER = 2;

    bytes32 public constant ATTESTATION_TYPEHASH = keccak256(
        "HumanAttestation(address account,bytes32 credentialHash,uint64 validUntil,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    struct Human {
        uint64 validUntil;
        uint8 method;
        bytes32 credentialHash;
        address attester; // 0 for an on-chain passkey proof
    }

    address public governance;
    ILabelAgents public agents;
    ILabelWebAuthn public webauthn;
    bytes32 public rpIdHash;  // sha256 of the hub's host name (0 = any site)
    uint64 public humanTtl;

    mapping(address => bool) public isAttester;
    mapping(address => Human) public humans;
    mapping(bytes32 => address) public credentialAccount;
    mapping(address => uint256) public nonces;

    event HumanLabelled(address indexed account, bytes32 indexed credentialHash, uint8 method, address attester, uint64 validUntil);
    event HumanRevoked(address indexed account, address by);
    event AttesterSet(address indexed attester, bool allowed);
    event ConfigSet(address agents, address webauthn, bytes32 rpIdHash, uint64 humanTtl);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotAttester();
    error BadPasskey();
    error BadSignature();
    error Expired();
    error BadTtl();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) {
        governance = governance_;
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    // ------------------------------------------------------------- reading

    function labelOf(address account) public view returns (uint8) {
        if (address(agents) != address(0) && agents.activeAgentOf(account) != 0) return AGENT;
        Human storage h = humans[account];
        if (h.validUntil >= block.timestamp && credentialAccount[h.credentialHash] == account) return HUMAN;
        return NONE;
    }

    function isHuman(address account) external view returns (bool) {
        return labelOf(account) == HUMAN;
    }

    function isAgent(address account) external view returns (bool) {
        return labelOf(account) == AGENT;
    }

    /// The 32-byte challenge the passkey must sign to label `account` now.
    function humanChallenge(address account) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY human label", block.chainid, address(this), account, nonces[account]));
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Labels"), keccak256("1"), block.chainid, address(this)));
    }

    function attestationDigest(address account, bytes32 credentialHash, uint64 validUntil, uint256 nonce, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(ATTESTATION_TYPEHASH, account, credentialHash, validUntil, nonce, deadline))));
    }

    // ------------------------------------------------------------- labelling

    /// On-chain path: msg.sender labels itself with a passkey assertion over humanChallenge(msg.sender).
    function proveHumanP256(uint256 x, uint256 y, ILabelWebAuthn.Assertion calldata assertion) external {
        if (!webauthn.verify(humanChallenge(msg.sender), assertion, x, y, rpIdHash, true)) revert BadPasskey();
        _label(msg.sender, keccak256(abi.encode(x, y)), BY_PASSKEY, address(0), uint64(block.timestamp) + humanTtl);
    }

    /// Off-chain path: an attester's EIP-712 HumanAttestation, submitted by anyone.
    function attestHuman(address account, bytes32 credentialHash, uint64 validUntil, uint256 deadline, bytes calldata sig) external {
        if (block.timestamp > deadline) revert Expired();
        if (validUntil > block.timestamp + humanTtl) revert BadTtl();
        address attester = _recover(attestationDigest(account, credentialHash, validUntil, nonces[account], deadline), sig);
        if (!isAttester[attester]) revert NotAttester();
        _label(account, credentialHash, BY_ATTESTER, attester, validUntil);
    }

    /// The account itself, governance or any attester can remove a human label.
    function revokeHuman(address account) external {
        if (msg.sender != account && msg.sender != governance && !isAttester[msg.sender]) revert NotAttester();
        Human storage h = humans[account];
        if (credentialAccount[h.credentialHash] == account) delete credentialAccount[h.credentialHash];
        delete humans[account];
        nonces[account]++;
        emit HumanRevoked(account, msg.sender);
    }

    // ------------------------------------------------------------- governance

    function setAttester(address a, bool allowed) external onlyGovernance {
        isAttester[a] = allowed;
        emit AttesterSet(a, allowed);
    }

    function setConfig(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) external onlyGovernance {
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _config(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) private {
        if (humanTtl_ == 0 || humanTtl_ > 400 days) revert BadTtl();
        agents = ILabelAgents(agents_);
        webauthn = ILabelWebAuthn(webauthn_);
        rpIdHash = rpIdHash_;
        humanTtl = humanTtl_;
        emit ConfigSet(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function _label(address account, bytes32 cred, uint8 method, address attester, uint64 until) private {
        if (cred == bytes32(0)) revert BadPasskey();
        address prev = credentialAccount[cred];
        if (prev != address(0) && prev != account) delete humans[prev]; // one passkey, one account
        Human storage old = humans[account];
        if (old.credentialHash != bytes32(0) && old.credentialHash != cred && credentialAccount[old.credentialHash] == account) {
            delete credentialAccount[old.credentialHash];
        }
        credentialAccount[cred] = account;
        humans[account] = Human({validUntil: until, method: method, credentialHash: cred, attester: attester});
        nonces[account]++;
        emit HumanLabelled(account, cred, method, attester, until);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(d, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }
}

/// @title VouchRegistry: an optional "vouched unique human" level on top of LabelRegistry (testnet)
/// @notice Levels (levelOf):
///           0 NONE           no HUMAN label (no label, or an AI agent);
///           1 PASSKEY_HUMAN  LabelRegistry's HUMAN: a person used a passkey. Says nothing about
///                            uniqueness: one person can make many passkeys;
///           2 VOUCHED_UNIQUE a passkey human that at least `vouchesNeeded` vouched-unique humans
///                            vouched for, each saying "I know this is one real person with one
///                            account here", and not suspended or banned.
///         A web of trust, free and without a server: no stake, no fee, no oracle. What
///         makes it Sybil-RESISTANT (not Sybil-proof):
///           - every vouch is rate-limited (one per `vouchCooldown` per voucher, at most
///             `maxActiveVouches` open at once) and only from accounts that have been unique
///             for `voucherMinAge`: a ring of k colluding real people can add at most
///             k·maxActiveVouches / vouchesNeeded fake identities, and those can vouch only
///             after voucherMinAge, so growth is slow and visible on chain;
///           - a vouch binds the vouchee's passkey (credential hash): moving the label to
///             another passkey voids it;
///           - accountability: `flagsToSuspend` distinct unique humans flagging an account
///             suspend it (level 1) until they withdraw or governance clears the flags;
///             governance bans an account it finds to be a duplicate (evidence hash on chain)
///             and every voucher of it gets a strike; `strikesToBan` strikes ban the voucher;
///           - the count is live: a vouch from an account that is banned, suspended, lost its
///             HUMAN label or its own unique status no longer counts.
///         Limits (docs/future/agents.md §25): a vouched account's own vouchers are read from
///         their stored status (one level deep; anyone can refresh() a stale one); the
///         bootstrap set is chosen by governance; collusion and bought vouches are not
///         prevented, only bounded and traceable. Full Sybil resistance is not solved here.
contract VouchRegistry {
    uint8 public constant NONE = 0;
    uint8 public constant PASSKEY_HUMAN = 1;
    uint8 public constant VOUCHED_UNIQUE = 2;
    uint256 public constant MAX_VOUCHERS = 32; // open vouches one account can hold (bounds the live count)

    LabelRegistry public immutable labels;
    address public governance;

    uint8 public vouchesNeeded;
    uint8 public maxActiveVouches;
    uint8 public flagsToSuspend;
    uint8 public strikesToBan;
    uint32 public vouchCooldown;
    uint32 public voucherMinAge;

    struct Person {
        bool genesis;       // the bootstrap set (governance)
        bool banned;
        uint8 activeGiven;  // open vouches this account gave
        uint8 strikes;      // vouched for accounts later banned
        uint64 uniqueSince; // 0 = not counted unique (refresh() sets and clears it)
        uint64 lastVouchAt;
        uint32 flagEpoch;   // clearFlags() starts a new epoch
        uint16 flags;       // distinct flaggers in this epoch
    }

    mapping(address => Person) public people;
    mapping(address => address[]) private vouchersOf_;                // vouchee -> its open vouchers
    mapping(address => mapping(address => bytes32)) public vouchCredential; // voucher => vouchee => passkey hash (0 = no vouch)
    mapping(address => mapping(uint256 => mapping(address => bool))) public flaggedBy; // account => epoch => flagger

    event Vouched(address indexed voucher, address indexed vouchee, bytes32 credentialHash);
    event Unvouched(address indexed voucher, address indexed vouchee);
    event Refreshed(address indexed account, uint8 level, uint256 vouches);
    event Flagged(address indexed account, address indexed by, uint256 flags);
    event Unflagged(address indexed account, address indexed by, uint256 flags);
    event FlagsCleared(address indexed account);
    event Banned(address indexed account, bytes32 evidenceHash);
    event Unbanned(address indexed account);
    event Struck(address indexed voucher, address indexed banned, uint256 strikes);
    event GenesisSet(address indexed account, bool on);
    event ParamsSet(uint8 vouchesNeeded, uint8 maxActiveVouches, uint32 vouchCooldown, uint32 voucherMinAge, uint8 flagsToSuspend, uint8 strikesToBan);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotUnique();
    error NotPasskeyHuman(address who);
    error TooSoon(uint256 next);
    error TooManyVouches();
    error AlreadyVouched();
    error NoVouch();
    error AlreadyFlagged();
    error NotFlagged();
    error Self();
    error IsBanned(address who);
    error BadParams();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(LabelRegistry labels_, address governance_) {
        labels = labels_;
        governance = governance_;
        _params(3, 5, 7 days, 30 days, 5, 2);
    }

    // ------------------------------------------------------------- reading

    /// 0 none (or an agent), 1 passkey human (not proven unique), 2 vouched unique human.
    function levelOf(address a) public view returns (uint8) {
        if (labels.labelOf(a) != 1) return NONE;
        Person storage p = people[a];
        if (p.banned || p.flags >= flagsToSuspend) return PASSKEY_HUMAN;
        if (p.genesis) return VOUCHED_UNIQUE;
        if (p.uniqueSince != 0 && validVouches(a) >= vouchesNeeded) return VOUCHED_UNIQUE;
        return PASSKEY_HUMAN;
    }

    /// Open vouches for `a` that count now: the voucher is not banned or suspended, still a passkey
    /// human, counted unique (stored status), and `a` still has the passkey it was vouched with.
    function validVouches(address a) public view returns (uint256 n) {
        (, , bytes32 cred,) = labels.humans(a);
        address[] storage vs = vouchersOf_[a];
        for (uint256 i = 0; i < vs.length; i++) {
            address v = vs[i];
            if (vouchCredential[v][a] != cred || !_countsAsVoucher(v)) continue;
            n++;
        }
    }

    function vouchersOf(address a) external view returns (address[] memory) {
        return vouchersOf_[a];
    }

    /// Everything the hub shows: level, valid vouches, vouches needed, unique since, flags, flags to
    /// suspend, banned, genesis, open vouches given, when this account may vouch next (0 = cannot).
    function status(address a) external view returns (uint256[10] memory s) {
        Person storage p = people[a];
        s[0] = levelOf(a);
        s[1] = validVouches(a);
        s[2] = vouchesNeeded;
        s[3] = p.uniqueSince;
        s[4] = p.flags;
        s[5] = flagsToSuspend;
        s[6] = p.banned ? 1 : 0;
        s[7] = p.genesis ? 1 : 0;
        s[8] = p.activeGiven;
        if (s[0] == VOUCHED_UNIQUE && p.activeGiven < maxActiveVouches) {
            uint256 next = _nextVouchAt(p);
            uint256 aged = p.genesis ? 0 : uint256(p.uniqueSince) + voucherMinAge;
            s[9] = next > aged ? next : aged;
        }
    }

    // ------------------------------------------------------------- vouching

    /// msg.sender, a vouched-unique human, vouches that `who` (a passkey human) is one real person
    /// with one account. Rate-limited; withdrawable with unvouch().
    function vouch(address who) external {
        if (who == msg.sender) revert Self();
        if (levelOf(msg.sender) != VOUCHED_UNIQUE) revert NotUnique();
        Person storage me = people[msg.sender];
        if (!me.genesis && block.timestamp < uint256(me.uniqueSince) + voucherMinAge) revert TooSoon(uint256(me.uniqueSince) + voucherMinAge);
        uint256 next = _nextVouchAt(me);
        if (block.timestamp < next) revert TooSoon(next);
        if (me.activeGiven >= maxActiveVouches) revert TooManyVouches();
        if (labels.labelOf(who) != 1) revert NotPasskeyHuman(who);
        if (people[who].banned) revert IsBanned(who);
        if (vouchCredential[msg.sender][who] != bytes32(0)) revert AlreadyVouched();
        if (vouchersOf_[who].length >= MAX_VOUCHERS) revert TooManyVouches();
        (, , bytes32 cred,) = labels.humans(who);
        vouchCredential[msg.sender][who] = cred;
        vouchersOf_[who].push(msg.sender);
        me.activeGiven++;
        me.lastVouchAt = uint64(block.timestamp);
        emit Vouched(msg.sender, who, cred);
    }

    function unvouch(address who) external {
        if (vouchCredential[msg.sender][who] == bytes32(0)) revert NoVouch();
        _dropVouch(msg.sender, who);
    }

    /// Recomputes `a`'s stored unique status from its live vouches (anyone may call; the vouchee calls
    /// it once it has enough vouches). Returns the level.
    function refresh(address a) public returns (uint8 level) {
        Person storage p = people[a];
        uint256 n = validVouches(a);
        bool unique = labels.labelOf(a) == 1 && !p.banned && (p.genesis || n >= vouchesNeeded);
        if (unique && p.uniqueSince == 0) p.uniqueSince = uint64(block.timestamp);
        if (!unique && !p.genesis) p.uniqueSince = 0;
        level = levelOf(a);
        emit Refreshed(a, level, n);
    }

    // ------------------------------------------------------------- accountability

    /// A vouched-unique human says `a` is not one real person with one account (a duplicate, a bot).
    function flag(address a) external {
        if (a == msg.sender) revert Self();
        if (levelOf(msg.sender) != VOUCHED_UNIQUE) revert NotUnique();
        Person storage p = people[a];
        if (flaggedBy[a][p.flagEpoch][msg.sender]) revert AlreadyFlagged();
        flaggedBy[a][p.flagEpoch][msg.sender] = true;
        p.flags++;
        emit Flagged(a, msg.sender, p.flags);
    }

    function unflag(address a) external {
        Person storage p = people[a];
        if (!flaggedBy[a][p.flagEpoch][msg.sender]) revert NotFlagged();
        flaggedBy[a][p.flagEpoch][msg.sender] = false;
        p.flags--;
        emit Unflagged(a, msg.sender, p.flags);
    }

    // ------------------------------------------------------------- governance

    /// The bootstrap set: accounts governance knows to be distinct people (a ceremony, a meetup).
    function setGenesis(address[] calldata accounts, bool on) external onlyGovernance {
        for (uint256 i = 0; i < accounts.length; i++) {
            Person storage p = people[accounts[i]];
            p.genesis = on;
            p.uniqueSince = on ? uint64(block.timestamp) : 0;
            emit GenesisSet(accounts[i], on);
        }
    }

    /// `a` was shown to be a duplicate or a bot (evidence published, its hash here): banned, and each
    /// of its open vouchers gets a strike (banned at strikesToBan).
    function ban(address a, bytes32 evidenceHash) external onlyGovernance {
        Person storage p = people[a];
        p.banned = true;
        p.uniqueSince = 0;
        address[] storage vs = vouchersOf_[a];
        for (uint256 i = 0; i < vs.length; i++) {
            Person storage v = people[vs[i]];
            if (v.strikes < type(uint8).max) v.strikes++;
            emit Struck(vs[i], a, v.strikes);
            if (v.strikes >= strikesToBan && !v.banned) {
                v.banned = true;
                v.uniqueSince = 0;
                emit Banned(vs[i], evidenceHash);
            }
        }
        emit Banned(a, evidenceHash);
    }

    function unban(address a) external onlyGovernance {
        people[a].banned = false;
        people[a].strikes = 0;
        emit Unbanned(a);
    }

    /// Ends a flagging campaign that governance found unfounded (a new epoch: old flags no longer count).
    function clearFlags(address a) external onlyGovernance {
        Person storage p = people[a];
        p.flagEpoch++;
        p.flags = 0;
        emit FlagsCleared(a);
    }

    function setParams(uint8 needed, uint8 maxActive, uint32 cooldown, uint32 minAge, uint8 suspendAt, uint8 banAt) external onlyGovernance {
        _params(needed, maxActive, cooldown, minAge, suspendAt, banAt);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _params(uint8 needed, uint8 maxActive, uint32 cooldown, uint32 minAge, uint8 suspendAt, uint8 banAt) private {
        if (needed < 2 || needed > 16 || maxActive == 0 || maxActive > 16 || suspendAt < 2 || banAt == 0 || minAge > 365 days || cooldown > 90 days) revert BadParams();
        vouchesNeeded = needed;
        maxActiveVouches = maxActive;
        vouchCooldown = cooldown;
        voucherMinAge = minAge;
        flagsToSuspend = suspendAt;
        strikesToBan = banAt;
        emit ParamsSet(needed, maxActive, cooldown, minAge, suspendAt, banAt);
    }

    function _countsAsVoucher(address v) private view returns (bool) {
        Person storage p = people[v];
        if (p.banned || p.flags >= flagsToSuspend || labels.labelOf(v) != 1) return false;
        return p.genesis || p.uniqueSince != 0;
    }

    function _nextVouchAt(Person storage p) private view returns (uint256) {
        return p.lastVouchAt == 0 ? block.timestamp : uint256(p.lastVouchAt) + vouchCooldown;
    }

    function _dropVouch(address voucher, address who) private {
        delete vouchCredential[voucher][who];
        address[] storage vs = vouchersOf_[who];
        for (uint256 i = 0; i < vs.length; i++) {
            if (vs[i] == voucher) {
                vs[i] = vs[vs.length - 1];
                vs.pop();
                break;
            }
        }
        if (people[voucher].activeGiven > 0) people[voucher].activeGiven--;
        emit Unvouched(voucher, who);
    }
}

/// @title LabelFaucet: a testnet faucet hook that reads labels
/// @notice Pays each label its own amount (e.g. humans 10, agents 1,
///         unlabelled 0) at most once per cooldown per account, and, for
///         humans, once per cooldown per passkey too, so moving one passkey
///         across accounts does not multiply the drip. Funded by anyone.
contract LabelFaucet {
    LabelRegistry public immutable labels;
    address public governance;
    uint256 public cooldown;
    uint256[3] public amountFor; // by label: NONE, HUMAN, AGENT
    mapping(address => uint256) public lastDrip;
    mapping(bytes32 => uint256) public lastDripCredential;

    event Dripped(address indexed to, uint8 label, uint256 amount);
    event ConfigSet(uint256 cooldown, uint256[3] amountFor);

    error NotGovernance();
    error NothingForLabel(uint8 label);
    error TooSoon();
    error TransferFailed();

    constructor(LabelRegistry labels_, address governance_, uint256 cooldown_, uint256[3] memory amountFor_) {
        labels = labels_;
        governance = governance_;
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    receive() external payable {}

    function setConfig(uint256 cooldown_, uint256[3] calldata amountFor_) external {
        if (msg.sender != governance) revert NotGovernance();
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    function drip() external returns (uint256 amount) {
        uint8 label = labels.labelOf(msg.sender);
        amount = amountFor[label];
        if (amount == 0) revert NothingForLabel(label);
        if (lastDrip[msg.sender] != 0 && block.timestamp < lastDrip[msg.sender] + cooldown) revert TooSoon();
        lastDrip[msg.sender] = block.timestamp;
        if (label == 1) {
            (,, bytes32 cred,) = labels.humans(msg.sender);
            if (lastDripCredential[cred] != 0 && block.timestamp < lastDripCredential[cred] + cooldown) revert TooSoon();
            lastDripCredential[cred] = block.timestamp;
        }
        if (amount > address(this).balance) amount = address(this).balance;
        emit Dripped(msg.sender, label, amount);
        (bool ok,) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title LabelSwapGate: a DEX-side hook that reads labels
/// @notice A router or pool calls check(trader, amountIn) before a swap.
///         Each label has its own cap per hour on the input amount (0 = no
///         swaps for that label, type(uint256).max = no cap). The default
///         testnet setting: humans uncapped, registered agents capped (they
///         can be held to account), unlabelled accounts capped lower.
contract LabelSwapGate {
    ILabels public immutable labels;
    address public governance;
    uint256[3] public hourlyCap;
    mapping(address => uint256) public windowStart;
    mapping(address => uint256) public usedInWindow;
    mapping(address => bool) public isCaller; // routers / pools allowed to count volume

    event CapsSet(uint256[3] hourlyCap);
    event CallerSet(address caller, bool allowed);

    error NotGovernance();
    error NotCaller();
    error OverCap(uint8 label, uint256 cap);

    constructor(ILabels labels_, address governance_, uint256[3] memory hourlyCap_) {
        labels = labels_;
        governance = governance_;
        hourlyCap = hourlyCap_;
        emit CapsSet(hourlyCap_);
    }

    function setCaps(uint256[3] calldata caps) external {
        if (msg.sender != governance) revert NotGovernance();
        hourlyCap = caps;
        emit CapsSet(caps);
    }

    function setCaller(address c, bool allowed) external {
        if (msg.sender != governance) revert NotGovernance();
        isCaller[c] = allowed;
        emit CallerSet(c, allowed);
    }

    /// Counts amountIn against the trader's hourly cap for its label; reverts when over.
    function check(address trader, uint256 amountIn) external returns (uint8 label) {
        if (!isCaller[msg.sender]) revert NotCaller();
        label = labels.labelOf(trader);
        uint256 cap = hourlyCap[label];
        if (cap == type(uint256).max) return label;
        if (block.timestamp >= windowStart[trader] + 1 hours) {
            windowStart[trader] = block.timestamp;
            usedInWindow[trader] = 0;
        }
        uint256 used = usedInWindow[trader] + amountIn;
        if (used > cap) revert OverCap(label, cap);
        usedInWindow[trader] = used;
    }
}

contracts/HyperlaneLane.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Minimal local copies of Hyperlane v3 interfaces (no Hyperlane package offline).
// Checked against hyperlane-xyz/hyperlane-monorepo at commit
// bc8cfcec461930ec005590bc838871f903a297a1 (main, 2026-10-21):
//   solidity/contracts/interfaces/IMailbox.sol             dispatch / quoteDispatch / localDomain
//   solidity/contracts/interfaces/IMessageRecipient.sol    handle(uint32, bytes32, bytes) payable
//   solidity/contracts/interfaces/IInterchainSecurityModule.sol  moduleType / verify, and
//     ISpecifiesInterchainSecurityModule.interchainSecurityModule()
// The Mailbox calls recipient.handle{value: msg.value}(origin, sender, body) after
// its ISM (the recipient's interchainSecurityModule(), or the Mailbox default when
// that is zero) verified the message.

interface IHyperlaneMailbox {
    function localDomain() external view returns (uint32);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    // With a custom post-dispatch hook (IPostDispatchHook, an address in the ABI) instead of the default hook.
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface IInterchainSecurityModule {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

interface IMessageRecipient {
    function handle(uint32 origin, bytes32 sender, bytes calldata message) external payable;
}

/// BridgeAirlock as a lane sees it.
interface IAirlockLane {
    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external pure returns (bytes32);
}

/// @title HyperlaneLane: Hyperlane as one of BridgeAirlock's lanes (ZETAPHY side)
/// @notice Independent of NeuroLane: what it attests is decided by Hyperlane's
///         Mailbox and the ISM (validator set) that secures it, not by Neuro
///         runners. It accepts a message only
///           - from the configured Mailbox (msg.sender),
///           - from the configured origin domain and origin sender (the source
///             chain's HyperlaneLockBox, or a router speaking for it),
///           - describing a deposit of the configured source chain and contract;
///         and each transfer once. It then attests to the airlock exactly the
///         fields NeuroLane attests for the same deposit, so both lanes produce
///         the same transfer id: (srcChainId, srcContract, srcNonce, sender, to, amount).
///         Body: abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce,
///         address sender, address to, uint256 amount), 192 bytes.
///         Governance (a multisig) sets the config and an optional custom ISM;
///         until the source is configured every message is refused.
contract HyperlaneLane is IMessageRecipient {
    IAirlockLane public immutable airlock;
    address public governance;
    address public mailbox;
    uint32 public originDomain;
    bytes32 public originSender;
    uint256 public srcChainId;
    address public srcContract;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule); zero = the Mailbox's default ISM.
    IInterchainSecurityModule public interchainSecurityModule;
    mapping(bytes32 => bool) public delivered;   // by transfer id: replay protection

    event ConfigSet(address mailbox, uint32 originDomain, bytes32 originSender, uint256 srcChainId, address srcContract);
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event Delivered(bytes32 indexed id, uint256 indexed srcNonce, address sender, address to, uint256 amount);

    error NotGovernance();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();

    constructor(IAirlockLane airlock_, address governance_, address mailbox_, uint32 originDomain_, bytes32 originSender_,
        uint256 srcChainId_, address srcContract_, IInterchainSecurityModule ism_)
    {
        require(address(airlock_) != address(0) && governance_ != address(0) && mailbox_ != address(0), "config");
        airlock = airlock_;
        governance = governance_;
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
        interchainSecurityModule = ism_;
        emit IsmSet(address(ism_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    /// The Mailbox decides what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return mailbox; }

    function setConfig(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) external onlyGov {
        require(mailbox_ != address(0), "mailbox");
        _config(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }

    function setInterchainSecurityModule(IInterchainSecurityModule ism) external onlyGov {
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != originDomain) revert WrongOrigin(origin);
        if (sender != originSender || sender == bytes32(0)) revert WrongSender(sender);
        if (body.length != 192) revert BadBody();
        (uint256 chain, address src, uint256 nonce, address from, address to, uint256 amount) =
            abi.decode(body, (uint256, address, uint256, address, address, uint256));
        if (chain != srcChainId || src != srcContract || src == address(0)) revert WrongSource();
        bytes32 id = airlock.transferId(chain, src, nonce, from, to, amount);
        if (delivered[id]) revert Replay(id);
        delivered[id] = true;
        emit Delivered(id, nonce, from, to, amount);
        airlock.attest(chain, src, nonce, from, to, amount);
    }

    function _config(address mailbox_, uint32 originDomain_, bytes32 originSender_, uint256 srcChainId_, address srcContract_) private {
        mailbox = mailbox_;
        originDomain = originDomain_;
        originSender = originSender_;
        srcChainId = srcChainId_;
        srcContract = srcContract_;
        emit ConfigSet(mailbox_, originDomain_, originSender_, srcChainId_, srcContract_);
    }
}

/// @title HyperlaneLockBox: the source-chain side, for both lanes at once
/// @notice Locks native coin, emits LockBox's `Locked` event (the Neuro runners
///         watch it, unchanged: `zetaphy bridge watch --lockbox <this>`) and
///         dispatches the same transfer through the Hyperlane Mailbox to the
///         HyperlaneLane on ZETAPHY. msg.value = amount + the Mailbox fee
///         (quoteLock). Like LockBox it has no refund path: a vetoed or held
///         transfer stays locked here.
///         `hook`: zero = the Mailbox's default hook. Otherwise every dispatch uses
///         this hook instead (e.g. the source chain's MerkleTreeHook alone, when the
///         default hook's gas paymaster does not quote the destination; the
///         Mailbox's required hook still runs). Set once, at deploy.
contract HyperlaneLockBox {
    IHyperlaneMailbox public immutable mailbox;
    uint32 public immutable destinationDomain;
    bytes32 public immutable recipient;      // HyperlaneLane on ZETAPHY
    address public immutable hook;           // zero = the Mailbox default hook
    uint256 public nonce;

    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);
    event Dispatched(uint256 indexed nonce, bytes32 messageId);

    constructor(IHyperlaneMailbox mailbox_, uint32 destinationDomain_, bytes32 recipient_, address hook_) {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0), "config");
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        recipient = recipient_;
        hook = hook_;
    }

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount);
    }

    /// The Mailbox fee for the next lock (pay amount + this).
    function quoteLock(address to, uint256 amount) external view returns (uint256) {
        bytes memory b = body(nonce, msg.sender, to, amount);
        if (hook == address(0)) return mailbox.quoteDispatch(destinationDomain, recipient, b);
        return mailbox.quoteDispatch(destinationDomain, recipient, b, "", hook);
    }

    function lock(address to, uint256 amount) external payable returns (bytes32 messageId) {
        require(amount > 0 && to != address(0) && msg.value >= amount, "lock");
        uint256 n = nonce++;
        emit Locked(n, msg.sender, to, amount);
        bytes memory b = body(n, msg.sender, to, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: msg.value - amount}(destinationDomain, recipient, b)
            : mailbox.dispatch{value: msg.value - amount}(destinationDomain, recipient, b, "", hook);
        emit Dispatched(n, messageId);
    }
}

contracts/HyperlaneLockBoxV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, EVM routes, version 2: both directions, one stack per source chain.
//
//   source chain (Sepolia, Base Sepolia, Arbitrum Sepolia, ...)       ZETAPHY
//   HyperlaneLockBoxV2 --lock: Hyperlane message------------------->  HyperlaneLane -> BridgeAirlock -> BridgeGuard mints
//                      <--release: Hyperlane message, verified by--   HyperlaneOutbox <- BridgeGuard burns (outbound route)
//                         OUR validator(s) for origin ZETAPHY
//
// Each source chain has its own BridgeGuard and so its own bridged token on ZETAPHY
// (docs/SAPHAN-MULTICHAIN.md): a hole in one source chain's route can only mint that
// route's token, which only that route's outbox can burn, and only that route's
// lockbox releases for it. Nobody can drain the ETH locked on chain B with a message
// or a token of chain A.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo
// at commit 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (main, 2026-10-28): IMailbox,
// IMessageRecipient, IInterchainSecurityModule and ISpecifiesInterchainSecurityModule. Named
// apart from HyperlaneLane.sol's copies (the build compiles every file in one unit).

interface ISaphanMailbox {
    function localDomain() external view returns (uint32);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// A message-id multisig ISM's validator set (Hyperlane's StaticMessageIdMultisigIsm; the argument is ignored there).
interface ISaphanValidatorIsm {
    function validatorsAndThreshold(bytes calldata message) external view returns (address[] memory, uint8);
}

/// BridgeGuard as an outbound adapter sees it: burns `amount` of the route's token from `from`.
interface IGuardOutbound {
    function outbound(bytes32 route, address from, uint256 amount) external;
}

/// @title HyperlaneLockBoxV2: the source-chain side, both directions
/// @notice Lock (source -> ZETAPHY): exactly HyperlaneLockBox's message and its `Locked`
///         event (the Neuro runners watch it, `zetaphy bridge watch --lockbox <this>`), so the
///         HyperlaneLane on ZETAPHY is unchanged. msg.value = amount + quoteLock(); the Mailbox
///         gets exactly the quote and anything above is sent back.
///
///         Release (ZETAPHY -> source): handle() takes a message only
///           - from the configured Mailbox (msg.sender), after the ISM this contract names
///             (interchainSecurityModule: a multisig ISM of OUR validators for origin ZETAPHY,
///             never the Mailbox default; set at deploy, changed only by governance),
///           - from origin domain ZETAPHY and the one HyperlaneOutbox of this route (sender),
///           - whose body names ZETAPHY's chain id and that outbox as the source, and this
///             chain and this contract as the destination,
///         and each message once. It never pays at once: the release is queued and can be
///         claimed (by anyone, paid to its receiver) after `releaseDelay`, while
///           - not vetoed (a guardian or governance vetoes during the delay or later),
///           - not paused (guardians pause; only governance unpauses),
///           - within the daily release limit (over it, the claim waits for the next day),
///           - within what this contract holds for locks (`locked`: locks minus releases), so
///             even a forged message can never take more than this route's own deposits.
///         A message is never refused for a limit or a pause: it is recorded, and the money
///         moves only when every check passes (nothing depends on the relayer retrying).
///
///         Roles: governance (the source chain's timelock: its multisig proposes, 48 h) changes
///         the ISM, raises limits, lifts vetoes, unpauses; guardians (a multisig) only reduce
///         risk, at once: pause, veto, lower the daily limit, lengthen the delay.
///
///         Escape hatch (docs/SAPHAN-SAFETY.md): ZETAPHY's SaphanCheckpointer for this route sends a
///         heartbeat at least daily (governance names it once: setCheckpointer). If nothing comes from
///         ZETAPHY for ESCAPE_AFTER, the route is ESCAPING: no new locks; and our validators (the same
///         ones whose ISM releases funds) may sign an exit root: a Merkle root of what each address is
///         owed (token balances on ZETAPHY at its last block, releases queued here and not claimed, locks
///         ZETAPHY never minted). Once it is set, each address takes its share here (escape), pro rata if
///         the backing is short; nothing else moves any more. A heartbeat before the root ends escaping.
contract HyperlaneLockBoxV2 {
    struct Release {
        address to;
        uint64 readyAt;      // zero: no such release
        bool claimed;
        bool vetoed;
        uint256 amount;
    }

    ISaphanMailbox public immutable mailbox;
    uint32 public immutable zetaphyDomain;   // ZETAPHY's Hyperlane domain (77390)
    uint256 public immutable zetaphyChainId; // ZETAPHY's EVM chain id, as the outbox writes it (77390)
    bytes32 public immutable recipient;      // HyperlaneLane on ZETAPHY (locks go there)
    bytes32 public immutable remoteSender;   // HyperlaneOutbox on ZETAPHY (the only sender of releases)
    address public immutable hook;           // zero = the Mailbox default hook, for locks

    uint64 public constant MAX_RELEASE_DELAY = 30 days;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero here: the Mailbox's
    /// default ISM is Hyperlane's, which does not know our validators for origin ZETAPHY.
    ISaphanIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;               // wei released per day (UTC day)
    uint256 public releasedToday;
    uint64 public day;
    uint64 public releaseDelay;              // seconds between a message and its claim

    uint256 public nonce;                    // locks
    uint256 public received;                 // release messages recorded (the relayer workflow compares it with the outbox's nonce)
    uint256 public locked;                   // backing: everything locked minus everything released
    /// Each lock's transfer id (keccak256 of its body = BridgeAirlock.transferId): the relayer workflow asks the
    /// HyperlaneLane on ZETAPHY whether the latest one arrived (delivered(id)) instead of running for days.
    mapping(uint256 => bytes32) public transferIds;
    mapping(bytes32 => Release) public releases; // by keccak256(body)

    // escape hatch
    uint64 public constant ESCAPE_AFTER = 14 days;
    bytes32 public constant HEARTBEAT_TAG = keccak256("saphan/heartbeat/v1");
    bytes32 public constant EXIT_TAG = keccak256("saphan/exit-root/v1");
    bytes32 public checkpointer;             // SaphanCheckpointer on ZETAPHY (zero: no heartbeat, no escape)
    address public proofVerifier;            // SaphanReleaseVerifier here (zero: no proof path)
    bool public requireProof;                // true: only proven releases (the Hyperlane path releases nothing)
    uint256 public zetaphySupply;            // token(X)'s total supply on ZETAPHY, as of the last heartbeat
    uint64 public supplyAt;                  // when that heartbeat came
    uint64 public lastHeard;                 // the last heartbeat or release from ZETAPHY
    uint64 public lastBeat;                  // the newest heartbeat's sequence number
    bytes32 public exitRoot;                 // set once, while escaping: what each address is owed
    uint256 public exitTotal;                // the sum the root owes
    uint256 public exitPool;                 // what this lockbox held for locks when the root was set
    mapping(address => bool) public escaped;

    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);
    event Dispatched(uint256 indexed nonce, bytes32 messageId);
    event ReleaseQueued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event ReleaseVetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event ReleaseDelaySet(uint64 delay);
    event CheckpointerSet(bytes32 checkpointer);
    event Heartbeat(uint64 indexed seq, uint64 zetaphyTime);
    event ExitRootSet(bytes32 root, uint256 total, uint256 pool);
    event Escaped(address indexed who, uint256 owed, uint256 paid);
    event ProofVerifierSet(address verifier, bool required);
    event Reserves(uint256 locked, uint256 zetaphySupply);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoRelease();
    error AlreadyClaimed();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error OverBacking(uint256 locked);
    error PayFailed();
    error Fee(uint256 needed);
    error Escaping();
    error NotEscaping();
    error ExitDone();
    error BadSignatures();
    error BadProof();
    error NotVerifier();
    error ProofRequired();

    constructor(ISaphanMailbox mailbox_, uint32 zetaphyDomain_, uint256 zetaphyChainId_, bytes32 recipient_, bytes32 remoteSender_,
        address hook_, ISaphanIsm ism_, address governance_, address guardian_, uint256 dailyLimit_, uint64 releaseDelay_)
    {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0) && remoteSender_ != bytes32(0) && zetaphyChainId_ != 0
            && address(ism_) != address(0) && governance_ != address(0) && releaseDelay_ <= MAX_RELEASE_DELAY, "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        zetaphyChainId = zetaphyChainId_;
        recipient = recipient_;
        remoteSender = remoteSender_;
        hook = hook_;
        interchainSecurityModule = ism_;
        governance = governance_;
        dailyLimit = dailyLimit_;
        releaseDelay = releaseDelay_;
        emit IsmSet(address(ism_));
        emit GovernanceSet(governance_);
        emit DailyLimitSet(dailyLimit_);
        emit ReleaseDelaySet(releaseDelay_);
        if (guardian_ != address(0)) { guardian[guardian_] = true; emit GuardianSet(guardian_, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }

    // ---------------------------------------------------------------- lock (source -> ZETAPHY)

    /// The same body as HyperlaneLockBox (192 bytes), so the HyperlaneLane on ZETAPHY is unchanged.
    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount);
    }

    /// The Mailbox fee for the next lock (pay amount + this).
    function quoteLock(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function lock(address to, uint256 amount) external payable returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        if (escaping() || exitRoot != bytes32(0)) revert Escaping();
        require(amount > 0 && to != address(0) && msg.value >= amount, "lock");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < amount + fee) revert Fee(amount + fee);
        locked += amount;
        transferIds[n] = keccak256(b);
        emit Locked(n, msg.sender, to, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(zetaphyDomain, recipient, b)
            : mailbox.dispatch{value: fee}(zetaphyDomain, recipient, b, "", hook);
        emit Dispatched(n, messageId);
        uint256 extra = msg.value - amount - fee;
        if (extra > 0) {
            (bool ok, ) = msg.sender.call{value: extra}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(zetaphyDomain, recipient, b) : mailbox.quoteDispatch(zetaphyDomain, recipient, b, "", hook);
    }

    // ---------------------------------------------------------------- release (ZETAPHY -> source)

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    /// Body (256 bytes): abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce,
    /// address sender, address to, uint256 amount, uint256 dstChainId, address dstContract).
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != zetaphyDomain) revert WrongOrigin(origin);
        if (exitRoot != bytes32(0)) revert ExitDone(); // after the exit root, nothing from ZETAPHY counts any more
        if (sender == checkpointer && checkpointer != bytes32(0)) { _heartbeat(sender, b); return; }
        if (sender != remoteSender) revert WrongSender(sender);
        if (requireProof) revert ProofRequired();   // releases come only through the verifier (math, not signers)
        _queue(b);
    }

    /// The proof path (SaphanReleaseVerifier, set by governance): the same release body, proven from ZETAPHY's state
    /// by a STARK light client; queued exactly like a Hyperlane message (the same id: each body once, by either path).
    function queueProven(bytes calldata b) external {
        if (msg.sender != proofVerifier || proofVerifier == address(0)) revert NotVerifier();
        if (exitRoot != bytes32(0)) revert ExitDone();
        _queue(b);
    }

    function _queue(bytes calldata b) private {
        lastHeard = uint64(block.timestamp);
        if (b.length != 256) revert BadBody();
        (uint256 srcChain, address src, uint256 n, address from, address to, uint256 amount, uint256 dstChain, address dst) =
            abi.decode(b, (uint256, address, uint256, address, address, uint256, uint256, address));
        if (srcChain != zetaphyChainId || bytes32(uint256(uint160(src))) != remoteSender) revert WrongSource();
        if (dstChain != block.chainid || dst != address(this)) revert WrongDestination();
        if (to == address(0) || amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (releases[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + releaseDelay;
        releases[id] = Release(to, readyAt, false, false, amount);
        received += 1;
        emit ReleaseQueued(id, n, from, to, amount, readyAt);
    }

    /// Heartbeat body (192 bytes): abi.encode(HEARTBEAT_TAG, ZETAPHY's chain id, the checkpointer, seq, ZETAPHY time,
    /// token(X)'s total supply on ZETAPHY). The supply is the proof of reserves: every heartbeat records it next to
    /// `locked` (reserves(): what backs each bridged coin).
    function _heartbeat(bytes32 sender, bytes calldata b) private {
        if (b.length != 192) revert BadBody();
        (bytes32 tag, uint256 chain, address src, uint64 seq, uint64 t, uint256 supply) = abi.decode(b, (bytes32, uint256, address, uint64, uint64, uint256));
        if (tag != HEARTBEAT_TAG || chain != zetaphyChainId || bytes32(uint256(uint160(src))) != sender) revert WrongSource();
        if (seq <= lastBeat) revert Replay(bytes32(uint256(seq)));
        lastBeat = seq;
        lastHeard = uint64(block.timestamp);
        zetaphySupply = supply;
        supplyAt = uint64(block.timestamp);
        emit Heartbeat(seq, t);
        emit Reserves(locked, supply);
    }

    /// Proof of reserves: what this lockbox holds for locks, token(X)'s supply on ZETAPHY at the last heartbeat, and
    /// whether the first covers the second (bps: locked / supply x 10000; 10000 or more = fully backed).
    function reserves() external view returns (uint256 held, uint256 supply, uint64 asOf, uint256 bps) {
        held = locked;
        supply = zetaphySupply;
        asOf = supplyAt;
        bps = supply == 0 ? type(uint256).max : held * 10000 / supply;
    }

    /// Anyone: pays a queued release to its receiver once every check passes.
    function claim(bytes32 id) external {
        Release storage r = releases[id];
        if (exitRoot != bytes32(0)) revert ExitDone(); // the exit root counts unclaimed releases
        if (r.readyAt == 0) revert NoRelease();
        if (r.claimed) revert AlreadyClaimed();
        if (r.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < r.readyAt) revert NotReady(r.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; releasedToday = 0; }
        uint256 amount = r.amount;
        if (releasedToday + amount > dailyLimit) revert OverLimit(dailyLimit > releasedToday ? dailyLimit - releasedToday : 0);
        if (amount > locked) revert OverBacking(locked);
        r.claimed = true;
        releasedToday += amount;
        locked -= amount;
        emit Released(id, r.to, amount);
        (bool ok, ) = r.to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    /// What can still be released today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? releasedToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- escape hatch

    /// True when a checkpointer is named and nothing has come from ZETAPHY for ESCAPE_AFTER.
    function escaping() public view returns (bool) {
        return checkpointer != bytes32(0) && lastHeard != 0 && block.timestamp > uint256(lastHeard) + ESCAPE_AFTER;
    }

    /// What our validators sign for an exit root (EIP-191 personal message of this digest).
    function exitDigest(bytes32 root, uint256 total) public view returns (bytes32) {
        return keccak256(abi.encode(EXIT_TAG, block.chainid, address(this), root, total, lastHeard));
    }

    /// Anyone, while escaping: the exit root, signed by at least the threshold of the validators of this lockbox's
    /// ISM (signatures ordered by signer, ascending: no signer twice). Once.
    function submitExitRoot(bytes32 root, uint256 total, bytes[] calldata sigs) external {
        if (!escaping()) revert NotEscaping();
        if (exitRoot != bytes32(0)) revert ExitDone();
        if (root == bytes32(0) || total == 0) revert BadBody();
        bytes32 m = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", exitDigest(root, total)));
        exitRoot = root;
        exitTotal = total;
        exitPool = locked;
        emit ExitRootSet(root, total, locked);
        // the signatures, checked last against the ISM's validators (too few good ones: the whole call reverts)
        (address[] memory vals, uint8 threshold) = ISaphanValidatorIsm(address(interchainSecurityModule)).validatorsAndThreshold("");
        address last;
        uint256 good;
        for (uint256 i = 0; i < sigs.length; i++) {
            address who = _recover(m, sigs[i]);
            if (who <= last) revert BadSignatures();
            last = who;
            for (uint256 j = 0; j < vals.length; j++) if (vals[j] == who) { good++; break; }
        }
        if (threshold == 0 || good < threshold) revert BadSignatures();
    }

    /// The caller's share of the exit: `owed` as in the root (leaf = keccak256(keccak256(abi.encode(caller, owed))),
    /// sorted-pair Merkle proof), paid in full when the backing covers the root's total, else pro rata. Once.
    function escape(uint256 owed, bytes32[] calldata proof) external {
        if (exitRoot == bytes32(0)) revert NotEscaping();
        if (escaped[msg.sender]) revert AlreadyClaimed();
        bytes32 node = keccak256(bytes.concat(keccak256(abi.encode(msg.sender, owed))));
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 p = proof[i];
            node = node < p ? keccak256(abi.encode(node, p)) : keccak256(abi.encode(p, node));
        }
        if (node != exitRoot) revert BadProof();
        escaped[msg.sender] = true;
        uint256 pay = exitTotal <= exitPool ? owed : owed * exitPool / exitTotal;
        locked -= pay;
        emit Escaped(msg.sender, owed, pay);
        (bool ok, ) = msg.sender.call{value: pay}("");
        if (!ok) revert PayFailed();
    }

    function _recover(bytes32 m, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignatures();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s_ = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        // low-s only (no malleable second form)
        if (uint256(s_) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0 || (v != 27 && v != 28)) revert BadSignatures();
        address who = ecrecover(m, v, r, s_);
        if (who == address(0)) revert BadSignatures();
        return who;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a release that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Release storage r = releases[id];
        if (r.readyAt == 0) revert NoRelease();
        if (r.claimed) revert AlreadyClaimed();
        r.vetoed = true;
        emit ReleaseVetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseReleaseDelay(uint64 d) external onlyGuardian {
        require(d > releaseDelay && d <= MAX_RELEASE_DELAY, "raise only");
        releaseDelay = d;
        emit ReleaseDelaySet(d);
    }

    // ---------------------------------------------------------------- governance (the source chain's timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Release storage r = releases[id];
        if (r.readyAt == 0) revert NoRelease();
        r.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setReleaseDelay(uint64 d) external onlyGov {
        require(d <= MAX_RELEASE_DELAY, "delay");
        releaseDelay = d;
        emit ReleaseDelaySet(d);
    }

    /// The proof path (SaphanReleaseVerifier) and whether releases need it. requireProof needs a verifier.
    function setProofVerifier(address v, bool required) external onlyGov {
        require(!required || v != address(0), "verifier");
        proofVerifier = v;
        requireProof = required;
        emit ProofVerifierSet(v, required);
    }

    /// The route's SaphanCheckpointer on ZETAPHY (its heartbeats keep the route out of escape). Starting with it
    /// counts as hearing from ZETAPHY now; zero turns the escape hatch off.
    /// Never while escaping: governance cannot call off an escape that has begun.
    function setCheckpointer(bytes32 c) external onlyGov {
        if (escaping() || exitRoot != bytes32(0)) revert Escaping();
        checkpointer = c;
        lastHeard = uint64(block.timestamp);
        emit CheckpointerSet(c);
    }

    /// A new ISM (e.g. more of our validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title HyperlaneOutbox: the ZETAPHY side of the way back (ZETAPHY -> one source chain)
/// @notice send(to, amount) burns `amount` of the route's bridged token from the caller through
///         BridgeGuard (its outbound route for this outbox: daily limit, hard cap, pause,
///         vaccine) and dispatches a release to the source chain's HyperlaneLockBoxV2 through
///         ZETAPHY's Mailbox. Everything it may do is fixed at deploy (no admin): which guard
///         route burns, which domain, chain and lockbox it sends to. Closing it is the guard's:
///         a guardian pauses, governance disables the outbound route.
///         Body (256 bytes): abi.encode(block.chainid, this, nonce, sender, to, amount,
///         destinationChainId, the lockbox): the lockbox checks every field.
contract HyperlaneOutbox {
    IGuardOutbound public immutable guard;
    bytes32 public immutable route;              // this outbox's outbound route in the guard
    ISaphanMailbox public immutable mailbox;     // ZETAPHY's Mailbox
    uint32 public immutable destinationDomain;   // the source chain's Hyperlane domain
    uint256 public immutable destinationChainId; // the source chain's EVM chain id
    bytes32 public immutable recipient;          // the source chain's HyperlaneLockBoxV2
    address public immutable hook;               // zero = the Mailbox default hook
    uint256 public nonce;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);

    error Fee(uint256 needed);
    error PayFailed();

    constructor(IGuardOutbound guard_, bytes32 route_, ISaphanMailbox mailbox_, uint32 destinationDomain_, uint256 destinationChainId_,
        bytes32 recipient_, address hook_)
    {
        require(address(guard_) != address(0) && address(mailbox_) != address(0) && recipient_ != bytes32(0) && destinationChainId_ != 0, "config");
        guard = guard_;
        route = route_;
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        destinationChainId = destinationChainId_;
        recipient = recipient_;
        hook = hook_;
    }

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, destinationChainId, address(uint160(uint256(recipient))));
    }

    /// The Mailbox fee for the next send (msg.value of send).
    function quoteSend(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function send(address to, uint256 amount) external payable returns (bytes32 messageId) {
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        guard.outbound(route, msg.sender, amount); // burns; reverts when closed, paused, over a limit or held
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(destinationDomain, recipient, b)
            : mailbox.dispatch{value: fee}(destinationDomain, recipient, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(destinationDomain, recipient, b) : mailbox.quoteDispatch(destinationDomain, recipient, b, "", hook);
    }
}

contracts/ImmuneGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// The Web3 immune system's consumer side (docs/future/immune-network.md).
//
// IImmuneFeed is what every immune feed answers, on every EVM chain:
//   - ImmuneRegistry on ZETAPHY (where flags are made, by k-of-n bonded runner agreement in NeuroJobs);
//   - ImmuneMirror on every other EVM chain (written only by ZETAPHY's ImmuneBroadcaster through Hyperlane).
// A protocol on any chain adds `notFlagged(to)` (ImmuneGuard) to its router, withdrawal or bridge exit; a wallet or
// dapp calls isFlagged off-chain (zetaphy-network/src/immune/sdk.js); a circuit breaker (any chain, any vendor)
// watches the ThreatFlag event or polls isFlagged and decides for itself what to pause. The feed never pauses
// anything by itself.

/// @title IImmuneFeed: the interface every immune feed (registry or mirror) exposes
interface IImmuneFeed {
    /// A flag set (flagged = true) or lifted (cleared, expired, overturned on appeal) for (chainId, subject).
    /// chainId 0: the subject is an externally owned account flagged on EVERY EVM chain (the same key signs everywhere).
    event ThreatFlag(uint256 indexed chainId, address indexed subject, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    /// The same for a code hash (EXTCODEHASH): every copy of the code, on every EVM chain.
    event CodeThreatFlag(bytes32 indexed codeHash, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);

    /// Is `subject` on the EVM chain `chainId` flagged now (unexpired)? Checks the chain's own key and the
    /// every-EVM-chain key of an externally owned account. severity: 1 info, 2 suspicious, 3 high, 4 critical
    /// (an active exploit or drainer). evidenceHash: sha256 of the evidence bundle (IPFS CIDv1 raw, see the docs).
    function isFlagged(uint256 chainId, address subject) external view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    /// Is code with this EXTCODEHASH flagged (every copy, every chain)?
    function isCodeFlagged(bytes32 codeHash) external view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    /// False while the feed is paused or has never been written (consumers decide: fail open or closed).
    function live() external view returns (bool);
}

/// @title ImmuneCheck: a bounded, non-reverting read of an immune feed
library ImmuneCheck {
    /// Gas a single feed read may use (a broken or hostile feed cannot eat the caller's gas).
    uint256 internal constant READ_GAS = 60_000;

    /// The worst flag on `who` here: its address on this chain (and every EVM chain) and its code.
    /// ok = false when the feed could not be read (reverted, no code, out of gas, malformed answer).
    function worst(IImmuneFeed feed, address who) internal view returns (bool ok, bool flagged, uint8 severity, bytes32 evidenceHash) {
        (bool ok1, bool f1, uint8 s1, bytes32 e1) = _read(address(feed), abi.encodeCall(IImmuneFeed.isFlagged, (block.chainid, who)));
        ok = ok1;
        if (f1) { flagged = true; severity = s1; evidenceHash = e1; }
        bytes32 h = who.codehash;
        if (h != bytes32(0) && h != keccak256("")) {
            (bool ok2, bool f2, uint8 s2, bytes32 e2) = _read(address(feed), abi.encodeCall(IImmuneFeed.isCodeFlagged, (h)));
            ok = ok && ok2;
            if (f2 && s2 > severity) { flagged = true; severity = s2; evidenceHash = e2; }
        }
    }

    function live(IImmuneFeed feed) internal view returns (bool) {
        if (address(feed).code.length == 0) return false;
        (bool ok, bytes memory r) = address(feed).staticcall{gas: READ_GAS}(abi.encodeCall(IImmuneFeed.live, ()));
        return ok && r.length >= 32 && abi.decode(r, (bool));
    }

    function _read(address feed, bytes memory data) private view returns (bool ok, bool flagged, uint8 severity, bytes32 evidenceHash) {
        if (feed.code.length == 0) return (false, false, 0, 0);
        (bool s, bytes memory r) = feed.staticcall{gas: READ_GAS}(data);
        if (!s || r.length != 128) return (false, false, 0, 0);
        (uint256 f, uint256 sev, , bytes32 e) = abi.decode(r, (uint256, uint256, uint256, bytes32));
        if (f > 1 || sev > 255) return (false, false, 0, 0);
        return (true, f == 1, uint8(sev), e);
    }
}

/// @title ImmuneGuard: `notFlagged(to)` for routers, withdrawals and bridges on any EVM chain
/// @notice Inherit, pass the feed on this chain (ImmuneMirror, or ImmuneRegistry on ZETAPHY), the lowest severity
///         that refuses (3 = high is the suggested default: 1-2 are warnings for wallets), and whether a feed that
///         cannot be read refuses too (failClosed). Fail-open is the default: a paused or broken mirror must not
///         freeze a protocol; a protocol holding much value may choose fail-closed for its exits.
abstract contract ImmuneGuard {
    IImmuneFeed public immutable immuneFeed;
    uint8 public immutable immuneMinSeverity;
    bool public immutable immuneFailClosed;

    error ImmuneFlagged(address who, uint8 severity, bytes32 evidenceHash);
    error ImmuneFeedDown();

    constructor(IImmuneFeed feed, uint8 minSeverity, bool failClosed) {
        require(minSeverity >= 1 && minSeverity <= 4, "severity");
        immuneFeed = feed;
        immuneMinSeverity = minSeverity;
        immuneFailClosed = failClosed;
    }

    modifier notFlagged(address who) {
        _immuneCheck(who);
        _;
    }

    function _immuneCheck(address who) internal view {
        if (address(immuneFeed) == address(0)) return;
        (bool ok, bool flagged, uint8 severity, bytes32 evidenceHash) = ImmuneCheck.worst(immuneFeed, who);
        if (flagged && severity >= immuneMinSeverity) revert ImmuneFlagged(who, severity, evidenceHash);
        if (immuneFailClosed && (!ok || !ImmuneCheck.live(immuneFeed))) revert ImmuneFeedDown();
    }
}

/// @title ImmuneGuardedRouter: the reference integration (a payout router / withdrawal exit)
/// @notice Pays out native coin it holds to `to`, refusing destinations the immune feed flags at or above the
///         router's severity. A real router, vault or bridge adds the same modifier to its own exits.
contract ImmuneGuardedRouter is ImmuneGuard {
    address public immutable owner;
    event Sent(address indexed to, uint256 amount);

    constructor(IImmuneFeed feed, uint8 minSeverity, bool failClosed) ImmuneGuard(feed, minSeverity, failClosed) {
        owner = msg.sender;
    }

    receive() external payable {}

    function send(address payable to, uint256 amount) external notFlagged(to) {
        require(msg.sender == owner, "owner");
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "send failed");
        emit Sent(to, amount);
    }
}

contracts/ImmuneMirror.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// The Web3 immune system on every other EVM chain (docs/future/immune-network.md): the mirror of ZETAPHY's
// ImmuneRegistry, written only by ZETAPHY's ImmuneBroadcaster through Hyperlane (a message-id multisig ISM of OUR
// validators for origin ZETAPHY, as NeuroOracle and the Saphan routes). It answers IImmuneFeed (ImmuneGuard.sol):
// routers, vaults and bridges add ImmuneGuard's notFlagged(to); wallets call isFlagged; circuit breakers watch
// ThreatFlag / CodeThreatFlag or poll isFlagged and decide for themselves.

interface IIMIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// One key as mirrored (ImmuneRegistry.sol ImmuneItem; the same ABI layout).
struct MirrorItem {
    bytes32 key;
    uint32 round;
    bool flagged;
    uint8 keyType;         // 1 an account on chainId, 2 an EVM address on every chain, 3 code
    uint64 chainId;
    bytes32 subject;
    uint8 kind;
    uint8 severity;
    uint64 since;
    uint64 expiresAt;
    bytes32 evidenceHash;
    bytes32 vaccine;
}

/// @title ImmuneMirror: ZETAPHY's immune flags on this chain
/// @notice A key keeps the newest state by round (out-of-order or replayed deliveries change nothing). While paused
///         (a guardian pauses; governance unpauses) handle reverts, so messages wait at the Mailbox, every view
///         answers "not flagged" and live() is false: consumers choose fail-open or fail-closed (ImmuneGuard).
///         Flags end at their expiresAt here too, even if no lift message arrives.
contract ImmuneMirror {
    struct Entry {
        uint32 round;
        bool flagged;
        uint8 keyType;
        uint8 kind;
        uint8 severity;
        uint64 since;
        uint64 expiresAt;
        uint64 mirroredAt;
        bytes32 evidenceHash;
        bytes32 vaccine;
    }

    uint8 public constant KIND_IMMUNE = 4;
    address public immutable mailbox;
    uint32 public immutable zetaphyDomain;
    uint256 public immutable zetaphyChainId;
    bytes32 public immutable remoteSender;    // ImmuneBroadcaster on ZETAPHY
    IIMIsm public interchainSecurityModule;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;

    mapping(bytes32 => Entry) public entries;
    bytes32[] public keys;
    uint256 public flaggedNow;
    uint256 public messages;
    uint64 public lastUpdate;

    event ThreatFlag(uint256 indexed chainId, address indexed subject, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event CodeThreatFlag(bytes32 indexed codeHash, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event AccountThreatFlag(uint256 indexed chainId, bytes32 indexed account, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event Stale(bytes32 indexed key, uint32 round, uint32 have);
    event Paused(address by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);

    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error BadKind(uint8 kind);
    error IsPaused();
    error NoValue();
    error NotGovernance();
    error NotGuardian();

    constructor(address mailbox_, uint32 zetaphyDomain_, uint256 zetaphyChainId_, bytes32 remoteSender_, IIMIsm ism_, address governance_, address guardian_) {
        require(mailbox_ != address(0) && remoteSender_ != bytes32(0) && address(ism_) != address(0) && governance_ != address(0) && zetaphyChainId_ != 0, "zero");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        zetaphyChainId = zetaphyChainId_;
        remoteSender = remoteSender_;
        interchainSecurityModule = ism_;
        governance = governance_;
        if (guardian_ != address(0)) { guardian[guardian_] = true; emit GuardianSet(guardian_, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setIsm(IIMIsm ism) external onlyGov { require(address(ism) != address(0), "zero"); interchainSecurityModule = ism; emit IsmSet(address(ism)); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    function pause() external { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); paused = true; emit Paused(msg.sender); }
    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    // ---------------------------------------------------------------- Hyperlane

    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (paused) revert IsPaused();
        if (origin != zetaphyDomain) revert WrongOrigin(origin);
        if (sender != remoteSender) revert WrongSender(sender);
        (uint8 kind, uint256 src) = abi.decode(b[:64], (uint8, uint256));
        if (src != zetaphyChainId) revert WrongSource();
        if (kind != KIND_IMMUNE) revert BadKind(kind);
        ( , , MirrorItem[] memory items) = abi.decode(b, (uint8, uint256, MirrorItem[]));
        messages += 1;
        lastUpdate = uint64(block.timestamp);
        for (uint256 i = 0; i < items.length; ++i) _apply(items[i]);
    }

    function _apply(MirrorItem memory it) private {
        Entry storage m = entries[it.key];
        if (it.round <= m.round) { emit Stale(it.key, it.round, m.round); return; }
        if (m.round == 0) keys.push(it.key);
        if (it.flagged && !m.flagged) flaggedNow += 1;
        else if (!it.flagged && m.flagged) flaggedNow -= 1;
        entries[it.key] = Entry(it.round, it.flagged, it.keyType, it.kind, it.severity, it.since, it.expiresAt, uint64(block.timestamp), it.evidenceHash, it.vaccine);
        if (it.keyType == 3) emit CodeThreatFlag(it.subject, it.flagged, it.severity, it.since, it.evidenceHash);
        else if (uint256(it.subject) >> 160 == 0) emit ThreatFlag(it.chainId, address(uint160(uint256(it.subject))), it.flagged, it.severity, it.since, it.evidenceHash);
        else emit AccountThreatFlag(it.chainId, it.subject, it.flagged, it.severity, it.since, it.evidenceHash);
    }

    // ---------------------------------------------------------------- keys (ThreatRegistry's derivations)

    function codeKey(bytes32 codeHash) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.code", codeHash)); }
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.address", chainId, who)); }
    function accountKey(uint256 chainId, bytes32 account) public pure returns (bytes32) {
        if (uint256(account) >> 160 == 0) return addressKey(chainId, address(uint160(uint256(account))));
        return keccak256(abi.encode("zetaphy.threat.account", chainId, account));
    }

    // ---------------------------------------------------------------- IImmuneFeed

    function _view(bytes32 key) private view returns (bool, uint8, uint64, bytes32) {
        Entry storage m = entries[key];
        if (paused || !m.flagged || block.timestamp >= m.expiresAt) return (false, 0, 0, bytes32(0));
        return (true, m.severity, m.since, m.evidenceHash);
    }

    function isFlagged(uint256 chainId, address subject) public view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash) {
        (flagged, severity, since, evidenceHash) = _view(addressKey(chainId, subject));
        (bool f2, uint8 s2, uint64 t2, bytes32 e2) = _view(addressKey(0, subject));
        if (f2 && (!flagged || s2 > severity)) (flagged, severity, since, evidenceHash) = (f2, s2, t2, e2);
    }

    function isAccountFlagged(uint256 chainId, bytes32 account) external view returns (bool, uint8, uint64, bytes32) { return _view(accountKey(chainId, account)); }
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, uint8, uint64, bytes32) {
        if (codeHash == bytes32(0) || codeHash == keccak256("")) return (false, 0, 0, bytes32(0));
        return _view(codeKey(codeHash));
    }
    function live() external view returns (bool) { return !paused && lastUpdate != 0; }

    /// What a router or a DEX asks about an address on THIS chain: its address (here and every EVM chain) or its code.
    function check(address who) external view returns (bool flagged, uint8 severity, bytes32 evidenceHash) {
        (flagged, severity, , evidenceHash) = isFlagged(block.chainid, who);
        (bool f2, uint8 s2, , bytes32 e2) = isCodeFlagged(who.codehash);
        if (f2 && (!flagged || s2 > severity)) (flagged, severity, evidenceHash) = (true, s2, e2);
    }

    function keyCount() external view returns (uint256) { return keys.length; }

    /// The mirrored round of each key (0: never): the coverage meter compares them with ZETAPHY's.
    function roundsOf(bytes32[] calldata ks) external view returns (uint32[] memory out) {
        out = new uint32[](ks.length);
        for (uint256 i = 0; i < ks.length; ++i) out[i] = entries[ks[i]].round;
    }

    /// The vaccine hash shipped with a key's flag (sentinels on this chain fetch the vaccine by it from the feed).
    function vaccineOf(bytes32 key) external view returns (bytes32) { return entries[key].vaccine; }
}

contracts/ImmuneRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// The Web3 immune system, ZETAPHY side (docs/future/immune-network.md).
//
//   sentinels (every chain) --finding + evidence bundle--> NeuroJobs job (chain "immune")
//   k-of-n bonded runners re-run the detector on the evidence, commit-reveal the finding's hash
//   ImmuneRegistry.attest(jobId, finding): flagged here once the quorum agreed (provisional while the job's
//       challenge window is open; a challenge that overturns it slashes the runners in NeuroJobs and lift() clears it)
//   ImmuneBroadcaster.broadcast(keys): one call, every chain's ImmuneMirror (Hyperlane), batched and gas-bounded;
//       pushIbc for the CosmWasm mirror on Osmosis (ibc-hooks)
//
// Nobody can flag without the runners' quorum: governance can only protect keys (never flag), and a flag ends by
// itself (ttl), by a NeuroJobs "immune-clear" job (appeal), by a challenge that overturns its verdict, or by
// governance protecting the key (on ThreatRegistry, read here, or here).

interface IIRJobs {
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function assurance(uint256 id) external view returns (uint8 agreedBy, uint8 state, uint64 challengeUntil, bool settled);
}

interface IIRThreats {
    function protectedKey(bytes32 key) external view returns (bool);
}

interface IIRMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
}

interface IIRIcs20 {
    struct Height { uint64 revisionNumber; uint64 revisionHeight; }
    function transfer(string calldata sourcePort, string calldata sourceChannel, string calldata denom, uint256 amount, address sender,
        string calldata receiver, Height calldata timeoutHeight, uint64 timeoutTimestamp, string calldata memo) external returns (uint64 nextSequence);
}

/// What the runners agree on: its keccak256 (findingHash) is the NeuroJobs verdict.
struct ImmuneFinding {
    uint64 chainId;        // where it was seen: an EVM chain id, or the Hyperlane domain of a non-EVM chain
    bytes32 subject;       // EVM: the address, left-padded; Solana: the 32-byte account; Cosmos: the account bytes, left-padded
    bytes32 codeHash;      // EVM code (EXTCODEHASH) flagged on every chain too; 0: none
    uint8 kind;            // 1 exploit contract, 2 attacker, 3 drainer, 4 malicious spender, 5 scam clone, 6 compromised
    uint8 severity;        // 1 info, 2 suspicious, 3 high, 4 critical
    bool everyChain;       // an externally owned account: flagged on every EVM chain (the same key signs everywhere)
    uint32 ttl;            // seconds the flag holds unless renewed (MIN_TTL..MAX_TTL)
    bytes32 evidenceHash;  // sha256 of the evidence bundle (IPFS CIDv1 raw sha2-256)
    bytes32 vaccine;       // sha256 of the vaccine (the derived detector) shared with the flag; 0: none
}

/// One key as stored here and as mirrored.
struct ImmuneItem {
    bytes32 key;
    uint32 round;          // bumps on every flag, renewal and lift: the newest round wins on the mirrors
    bool flagged;
    uint8 keyType;         // 1 an account on chainId, 2 an EVM address on every chain (chainId 0), 3 code
    uint64 chainId;
    bytes32 subject;       // the account (keyType 1, 2) or the code hash (3)
    uint8 kind;
    uint8 severity;
    uint64 since;
    uint64 expiresAt;
    bytes32 evidenceHash;
    bytes32 vaccine;
}

/// @title ImmuneRegistry: flags made only by a quorum of bonded NeuroJobs runners
contract ImmuneRegistry {
    bytes32 public constant CHAIN_FLAG = "immune";
    bytes32 public constant CHAIN_CLEAR = "immune-clear";
    uint32 public constant MIN_TTL = 1 days;
    uint32 public constant MAX_TTL = 180 days;
    uint8 private constant DONE = 2;          // NeuroJobs Status.Done
    uint8 private constant CHALLENGE_OPEN = 1; // NeuroJobs ChallengeState.Open

    struct Entry {
        ImmuneItem item;
        uint256 jobId;     // the job whose verdict set it
        bytes32 verdict;   // that verdict (a challenge that changes it lifts the flag)
    }

    IIRJobs public immutable jobs;
    IIRThreats public immutable threats;     // ThreatRegistry: its protected keys are protected here too (zero: none)
    uint8 public immutable minAgreed;        // runners that must have revealed the same verdict
    address public governance;

    mapping(bytes32 => Entry) private _e;
    mapping(bytes32 => bool) public protectedKey;
    mapping(uint256 => bool) public usedJob;
    bytes32[] public history;                // every key flagged, renewed or lifted, in order (coverage, feed)
    uint256 public flaggedNow;

    event ThreatFlag(uint256 indexed chainId, address indexed subject, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event CodeThreatFlag(bytes32 indexed codeHash, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event AccountThreatFlag(uint256 indexed chainId, bytes32 indexed account, bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    event Attested(bytes32 indexed key, uint256 indexed jobId, uint32 round, uint8 kind, uint8 severity, uint64 expiresAt, bytes32 evidenceHash, bytes32 vaccine, bool provisional);
    event Lifted(bytes32 indexed key, uint32 round, uint8 why); // 1 appeal (clear job), 2 verdict overturned, 3 expired, 4 protected
    event ProtectedSet(bytes32 indexed key, bool on);
    event GovernanceSet(address governance);

    error NotGovernance();
    error JobUsed(uint256 jobId);
    error NotAgreed(uint256 jobId);
    error WrongJob(uint256 jobId);
    error BadFinding();
    error AllProtected();
    error NotFlagged(bytes32 key);
    error Stands(bytes32 key);

    constructor(IIRJobs jobs_, IIRThreats threats_, uint8 minAgreed_, address governance_) {
        require(address(jobs_) != address(0) && governance_ != address(0) && minAgreed_ >= 2, "bad");
        jobs = jobs_;
        threats = threats_;
        minAgreed = minAgreed_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }

    /// Governance vouches for keys (e.g. a bridge's own contracts): never flagged; protecting a flagged key lifts it.
    /// Governance cannot flag anything.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; ++i) {
            protectedKey[keys[i]] = on;
            emit ProtectedSet(keys[i], on);
            if (on && _e[keys[i]].item.flagged) _lift(keys[i], 4);
        }
    }

    // ---------------------------------------------------------------- keys (ThreatRegistry's derivations)

    function codeKey(bytes32 codeHash) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.code", codeHash)); }
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.address", chainId, who)); }
    /// A non-EVM account (Solana, Cosmos): its bytes, left-padded to 32.
    function accountKey(uint256 chainId, bytes32 account) public pure returns (bytes32) {
        if (uint256(account) >> 160 == 0) return addressKey(chainId, address(uint160(uint256(account))));
        return keccak256(abi.encode("zetaphy.threat.account", chainId, account));
    }

    function isProtected(bytes32 key) public view returns (bool) {
        if (protectedKey[key]) return true;
        if (address(threats) == address(0)) return false;
        try threats.protectedKey(key) returns (bool p) { return p; } catch { return false; }
    }

    // ---------------------------------------------------------------- what the runners sign

    function findingHash(ImmuneFinding calldata f) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.immune.finding.v1", f));
    }

    /// The verdict a clear (appeal) job must reach for `key` at its current round.
    function clearHash(bytes32 key, uint32 round) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.immune.clear.v1", key, round));
    }

    /// The job's verdict, after checking it is an agreed one of chain `chain` with no challenge running.
    function _agreed(uint256 jobId, bytes32 chain) private view returns (bytes32 result, bool settled) {
        if (usedJob[jobId]) revert JobUsed(jobId);
        (, , uint8 status, bytes32 c, , , bytes32 r, , , ) = jobs.getJob(jobId);
        if (c != chain) revert WrongJob(jobId);
        (uint8 agreedBy, uint8 state, , bool s) = jobs.assurance(jobId);
        if (status != DONE || agreedBy < minAgreed || state == CHALLENGE_OPEN) revert NotAgreed(jobId);
        return (r, s);
    }

    // ---------------------------------------------------------------- flag, renew, lift

    /// Records a finding the runners agreed on (job `jobId`, chain "immune", verdict findingHash(f)). Anyone may call.
    /// Provisional while the job's challenge window is open (the flag already shows: the network warns at once).
    function attest(uint256 jobId, ImmuneFinding calldata f) external returns (uint256 keysSet) {
        (bytes32 result, bool settled) = _agreed(jobId, CHAIN_FLAG);
        if (result != findingHash(f)) revert WrongJob(jobId);
        if (f.kind == 0 || f.kind > 6 || f.severity == 0 || f.severity > 4 || f.ttl < MIN_TTL || f.ttl > MAX_TTL
            || f.evidenceHash == bytes32(0) || f.subject == bytes32(0) || f.chainId == 0) revert BadFinding();
        bool evm = uint256(f.subject) >> 160 == 0;
        if (f.everyChain && !evm) revert BadFinding();
        usedJob[jobId] = true;
        if (_flag(accountKey(f.chainId, f.subject), 1, f.chainId, f.subject, f, jobId, result, settled)) keysSet++;
        if (f.everyChain && _flag(addressKey(0, address(uint160(uint256(f.subject)))), 2, 0, f.subject, f, jobId, result, settled)) keysSet++;
        if (f.codeHash != bytes32(0) && f.codeHash != keccak256("") && _flag(codeKey(f.codeHash), 3, 0, f.codeHash, f, jobId, result, settled)) keysSet++;
        if (keysSet == 0) revert AllProtected();
    }

    function _flag(bytes32 key, uint8 keyType, uint64 chainId, bytes32 subject, ImmuneFinding calldata f, uint256 jobId, bytes32 verdict, bool settled) private returns (bool) {
        if (isProtected(key)) return false;
        Entry storage e = _e[key];
        ImmuneItem storage it = e.item;
        bool active = it.flagged && block.timestamp < it.expiresAt;
        if (!it.flagged) flaggedNow += 1;
        it.key = key;
        it.round += 1;
        it.flagged = true;
        it.keyType = keyType;
        it.chainId = chainId;
        it.subject = subject;
        it.kind = f.kind;
        it.severity = f.severity;
        if (!active) it.since = uint64(block.timestamp);
        it.expiresAt = uint64(block.timestamp) + f.ttl;
        it.evidenceHash = f.evidenceHash;
        it.vaccine = f.vaccine;
        e.jobId = jobId;
        e.verdict = verdict;
        history.push(key);
        emit Attested(key, jobId, it.round, f.kind, f.severity, it.expiresAt, f.evidenceHash, f.vaccine, !settled);
        _announce(it);
        return true;
    }

    /// Appeal: a NeuroJobs job of chain "immune-clear" whose runners agreed on clearHash(key, round) lifts the flag.
    function clear(uint256 jobId, bytes32 key) external {
        (bytes32 result, ) = _agreed(jobId, CHAIN_CLEAR);
        ImmuneItem storage it = _e[key].item;
        if (!it.flagged) revert NotFlagged(key);
        if (result != clearHash(key, it.round)) revert WrongJob(jobId);
        usedJob[jobId] = true;
        _lift(key, 1);
    }

    /// Lifts a flag that no longer stands: its verdict was overturned by a NeuroJobs challenge (the runners who
    /// gave it were slashed there), it expired, or the key is protected. Anyone may call (the broadcaster then
    /// carries the lift to every mirror). Returns why (2, 3, 4).
    function lift(bytes32 key) external returns (uint8 why) {
        Entry storage e = _e[key];
        if (!e.item.flagged) revert NotFlagged(key);
        (, , , , , , bytes32 r, , , ) = jobs.getJob(e.jobId);
        if (r != e.verdict) why = 2;
        else if (block.timestamp >= e.item.expiresAt) why = 3;
        else if (isProtected(key)) why = 4;
        else revert Stands(key);
        _lift(key, why);
    }

    function _lift(bytes32 key, uint8 why) private {
        ImmuneItem storage it = _e[key].item;
        it.flagged = false;
        it.round += 1;
        flaggedNow -= 1;
        history.push(key);
        emit Lifted(key, it.round, why);
        _announce(it);
    }

    function _announce(ImmuneItem storage it) private {
        bool f = it.flagged;
        if (it.keyType == 3) emit CodeThreatFlag(it.subject, f, it.severity, it.since, it.evidenceHash);
        else if (uint256(it.subject) >> 160 == 0) emit ThreatFlag(it.chainId, address(uint160(uint256(it.subject))), f, it.severity, it.since, it.evidenceHash);
        else emit AccountThreatFlag(it.chainId, it.subject, f, it.severity, it.since, it.evidenceHash);
    }

    // ---------------------------------------------------------------- views (IImmuneFeed, as on every mirror)

    function itemOf(bytes32 key) external view returns (ImmuneItem memory) { return _e[key].item; }
    function jobOf(bytes32 key) external view returns (uint256 jobId, bytes32 verdict) { return (_e[key].jobId, _e[key].verdict); }

    function _view(bytes32 key) private view returns (bool, uint8, uint64, bytes32) {
        ImmuneItem storage it = _e[key].item;
        if (!it.flagged || block.timestamp >= it.expiresAt) return (false, 0, 0, bytes32(0));
        return (true, it.severity, it.since, it.evidenceHash);
    }

    function isFlagged(uint256 chainId, address subject) external view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash) {
        (flagged, severity, since, evidenceHash) = _view(addressKey(chainId, subject));
        (bool f2, uint8 s2, uint64 t2, bytes32 e2) = _view(addressKey(0, subject));
        if (f2 && (!flagged || s2 > severity)) (flagged, severity, since, evidenceHash) = (f2, s2, t2, e2);
    }

    function isAccountFlagged(uint256 chainId, bytes32 account) external view returns (bool, uint8, uint64, bytes32) { return _view(accountKey(chainId, account)); }
    function isCodeFlagged(bytes32 codeHash) external view returns (bool, uint8, uint64, bytes32) { return _view(codeKey(codeHash)); }
    function live() external pure returns (bool) { return true; }
    /// True while the verdict behind the flag can still be challenged in NeuroJobs.
    function provisional(bytes32 key) external view returns (bool) {
        (, , , bool settled) = jobs.assurance(_e[key].jobId);
        return _e[key].item.flagged && !settled;
    }

    function historyCount() external view returns (uint256) { return history.length; }

    /// A page of the history with each key's current round and state (the coverage meter and the feed builder).
    function snapshot(uint256 start, uint256 n) external view returns (bytes32[] memory keys, uint32[] memory rounds, bool[] memory flagged) {
        uint256 total = history.length;
        uint256 end = start + n > total ? total : start + n;
        uint256 len = end > start ? end - start : 0;
        keys = new bytes32[](len);
        rounds = new uint32[](len);
        flagged = new bool[](len);
        for (uint256 i = 0; i < len; ++i) {
            ImmuneItem storage it = _e[history[start + i]].item;
            keys[i] = it.key;
            rounds[i] = it.round;
            flagged[i] = it.flagged;
        }
    }
}

interface IIRRegistry {
    function itemOf(bytes32 key) external view returns (ImmuneItem memory);
}

/// @title ImmuneBroadcaster: one flag on ZETAPHY -> every mirror, batched and gas-bounded
/// @notice Holds no key and decides nothing: it sends the registry's own state of the keys at the time of the call.
///         Anyone may call broadcast (a sentinel, a runner, a GitHub Actions schedule), paying the Hyperlane fees.
///         One call sends at most MAX_ITEMS keys to each of at most MAX_DOMAINS routes, and to each route only the
///         keys it still lacks (by round), so a call's gas is bounded and nothing is sent twice.
contract ImmuneBroadcaster {
    uint8 public constant KIND_IMMUNE = 4;
    uint256 public constant MAX_ITEMS = 24;
    uint256 public constant MAX_DOMAINS = 16;
    address public constant ICS20 = 0x0000000000000000000000000000000000000802;

    IIRRegistry public immutable registry;
    IIRMailbox public immutable mailbox;
    address public governance;

    mapping(uint32 => bytes32) public receivers;
    uint32[] public domains;
    /// the round last sent per destination and key (0: never)
    mapping(uint32 => mapping(bytes32 => uint32)) public sentRound;

    string public ibcChannel;
    string public ibcContract;
    uint64 public ibcTimeout = 600;

    event Broadcast(uint32 indexed domain, bytes32 messageId, uint256 items);
    event PushedIbc(string channel, uint64 sequence, uint256 items);
    event ReceiverSet(uint32 indexed domain, bytes32 receiver);
    event IbcRouteSet(string channel, string contractAddr, uint64 timeout);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NoRoute(uint32 domain);
    error TooMany();
    error NothingToSend();
    error Fee(uint256 needed);
    error RefundFailed();
    error BadInput();

    constructor(IIRRegistry registry_, IIRMailbox mailbox_, address governance_) {
        require(address(registry_) != address(0) && address(mailbox_) != address(0) && governance_ != address(0), "zero");
        registry = registry_;
        mailbox = mailbox_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }

    /// The ImmuneMirror on `domain` (zero removes the route; at most MAX_DOMAINS routes).
    function setReceiver(uint32 domain, bytes32 receiver) external onlyGov {
        if (receiver != bytes32(0) && receivers[domain] == bytes32(0)) {
            bool known;
            for (uint256 i = 0; i < domains.length; ++i) if (domains[i] == domain) known = true;
            if (!known) {
                if (domains.length >= MAX_DOMAINS) revert TooMany();
                domains.push(domain);
            }
        }
        receivers[domain] = receiver;
        emit ReceiverSet(domain, receiver);
    }

    function domainCount() external view returns (uint256) { return domains.length; }

    function setIbcRoute(string calldata channel, string calldata contractAddr, uint64 timeout) external onlyGov {
        bytes memory c = bytes(channel);
        if (c.length > 0 && (c.length > 20 || !_plain(c) || !_plain(bytes(contractAddr)) || bytes(contractAddr).length > 100 || timeout < 60 || timeout > 1 days)) revert BadInput();
        ibcChannel = channel;
        ibcContract = contractAddr;
        ibcTimeout = timeout;
        emit IbcRouteSet(channel, contractAddr, timeout);
    }

    // ---------------------------------------------------------------- what would be sent

    function _items(uint32 domain, bytes32[] calldata keys) private view returns (ImmuneItem[] memory out) {
        if (keys.length > MAX_ITEMS) revert TooMany();
        ImmuneItem[] memory all = new ImmuneItem[](keys.length);
        uint256 n;
        for (uint256 i = 0; i < keys.length; ++i) {
            ImmuneItem memory it = registry.itemOf(keys[i]);
            if (it.round == 0 || sentRound[domain][keys[i]] >= it.round) continue;
            bool dup;
            for (uint256 j = 0; j < n; ++j) if (all[j].key == it.key) dup = true;
            if (!dup) all[n++] = it;
        }
        out = new ImmuneItem[](n);
        for (uint256 i = 0; i < n; ++i) out[i] = all[i];
    }

    /// Which of `keys` `domain` still lacks (never flagged keys: false).
    function pending(uint32 domain, bytes32[] calldata keys) external view returns (bool[] memory out) {
        out = new bool[](keys.length);
        for (uint256 i = 0; i < keys.length; ++i) {
            ImmuneItem memory it = registry.itemOf(keys[i]);
            out[i] = it.round != 0 && sentRound[domain][keys[i]] < it.round;
        }
    }

    function body(uint32 domain, bytes32[] calldata keys) public view returns (bytes memory) {
        ImmuneItem[] memory items = _items(domain, keys);
        if (items.length == 0) return "";
        return abi.encode(KIND_IMMUNE, block.chainid, items);
    }

    /// The fee broadcast(keys) needs: the sum over every route that lacks one of the keys.
    function quote(bytes32[] calldata keys) external view returns (uint256 total) {
        for (uint256 i = 0; i < domains.length; ++i) {
            uint32 d = domains[i];
            bytes32 r = receivers[d];
            if (r == bytes32(0)) continue;
            bytes memory b = body(d, keys);
            if (b.length != 0) total += mailbox.quoteDispatch(d, r, b);
        }
    }

    // ---------------------------------------------------------------- send

    /// The registry's current state of `keys` (at most MAX_ITEMS) to every route that lacks it, one message each.
    /// msg.value pays the fees (quote); the rest is sent back.
    function broadcast(bytes32[] calldata keys) external payable returns (uint256 messages) {
        uint256 left = msg.value;
        for (uint256 i = 0; i < domains.length; ++i) {
            uint32 d = domains[i];
            bytes32 r = receivers[d];
            if (r == bytes32(0)) continue;
            (uint256 fee, ) = _send(d, r, keys, left);
            if (fee == type(uint256).max) continue;
            left -= fee;
            messages++;
        }
        if (messages == 0) revert NothingToSend();
        if (left > 0) {
            (bool ok, ) = msg.sender.call{value: left}("");
            if (!ok) revert RefundFailed();
        }
    }

    /// The same to one route.
    function pushTo(uint32 domain, bytes32[] calldata keys) external payable returns (bytes32 id) {
        bytes32 r = receivers[domain];
        if (r == bytes32(0)) revert NoRoute(domain);
        uint256 fee;
        (fee, id) = _send(domain, r, keys, msg.value);
        if (fee == type(uint256).max) revert NothingToSend();
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert RefundFailed();
        }
    }

    /// Sends what `domain` lacks; returns the fee paid (max: nothing to send).
    function _send(uint32 d, bytes32 r, bytes32[] calldata keys, uint256 budget) private returns (uint256 fee, bytes32 id) {
        ImmuneItem[] memory items = _items(d, keys);
        if (items.length == 0) return (type(uint256).max, bytes32(0));
        bytes memory b = abi.encode(KIND_IMMUNE, block.chainid, items);
        fee = mailbox.quoteDispatch(d, r, b);
        if (budget < fee) revert Fee(fee);
        for (uint256 j = 0; j < items.length; ++j) sentRound[d][items[j].key] = items[j].round;
        id = mailbox.dispatch{value: fee}(d, r, b);
        emit Broadcast(d, id, items.length);
    }

    // ---------------------------------------------------------------- IBC (the CosmWasm mirror on Osmosis)

    /// The ICS-20 memo pushIbc sends, in the format of the CosmWasm NeuroOracle mirror (cosmwasm/neuro-oracle-osmo):
    /// one instance of it, whose hook sender is THIS contract's, is the immune mirror there. reason = severity;
    /// enforced_from = since for severity >= 3 (refuse), else expiresAt (warn only); held_from = since.
    function ibcMemo(bytes32[] calldata keys) public view returns (string memory) {
        if (keys.length == 0) revert NothingToSend();
        if (keys.length > MAX_ITEMS) revert TooMany();
        bytes memory s = abi.encodePacked('{"wasm":{"contract":"', ibcContract, '","msg":{"mirror":{"src_chain":', _u(block.chainid), ',"items":[');
        for (uint256 i = 0; i < keys.length; ++i) {
            ImmuneItem memory it = registry.itemOf(keys[i]);
            bool on = it.flagged && block.timestamp < it.expiresAt;
            s = abi.encodePacked(s, i == 0 ? "" : ",", '{"key":"', _hex(keys[i]), '","round":', _u(it.round), ',"flagged":', on ? "true" : "false",
                ',"reason":', _u(on ? it.severity : 0), ',"enforced_from":', _u(!on ? 0 : it.severity >= 3 ? it.since : it.expiresAt),
                ',"held_from":', _u(on ? it.since : 0), "}");
        }
        return string(abi.encodePacked(s, "]}}}}"));
    }

    function pushIbc(bytes32[] calldata keys) external payable returns (uint64 seq) {
        if (bytes(ibcChannel).length == 0) revert NoRoute(0);
        if (msg.value == 0) revert Fee(1);
        string memory memo = ibcMemo(keys);
        seq = IIRIcs20(ICS20).transfer("transfer", ibcChannel, "azetaphy", msg.value, address(this), ibcContract,
            IIRIcs20.Height(0, 0), uint64(block.timestamp + ibcTimeout) * 1e9, memo);
        emit PushedIbc(ibcChannel, seq, keys.length);
    }

    function _plain(bytes memory b) private pure returns (bool) {
        for (uint256 i = 0; i < b.length; ++i) {
            bytes1 c = b[i];
            if (!((c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-")) return false;
        }
        return true;
    }

    function _u(uint256 v) private pure returns (bytes memory out) {
        if (v == 0) return "0";
        uint256 n;
        for (uint256 x = v; x != 0; x /= 10) ++n;
        out = new bytes(n);
        for (; v != 0; v /= 10) out[--n] = bytes1(uint8(48 + (v % 10)));
    }

    function _hex(bytes32 v) private pure returns (bytes memory out) {
        bytes16 h = "0123456789abcdef";
        out = new bytes(64);
        for (uint256 i = 0; i < 32; ++i) {
            out[2 * i] = h[uint8(v[i]) >> 4];
            out[2 * i + 1] = h[uint8(v[i]) & 0x0f];
        }
    }
}

contracts/IntentExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IIntentERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

/// The outbound side of a bridge as BRIDGE intents call it: ZETAPHY's HyperlaneOutbox
/// (send(to, amount) burns `amount` from the caller and dispatches it to the other chain).
interface IIntentBridge {
    function send(address to, uint256 amount) external payable returns (bytes32);
}

/// @title IntentExecutor: Proof of Intent (testnet)
/// @notice A user signs WHAT they want (an intent with limits), not HOW. Anyone (an
///         off-chain AI or compiler, "the solver") turns it into calls and submits them
///         here. This contract runs the calls and then checks the effects on chain:
///           - the user's tokenIn balance went down by at most maxIn,
///           - the recipient's tokenOut balance went up by at least minOut,
///           - this contract keeps nothing (leftover tokenIn back to the user,
///             any tokenOut it holds on to the recipient),
///           - the deadline (expiry) has not passed, the nonce is unused,
///           - the user's own daily spend cap for tokenIn (setSpendCap), if set,
///           - every call went to a contract the user listed (targetsHash),
///             never to tokenIn, tokenOut, the user or this contract, with no
///             value, and never with approve or a transfer-like selector
///             (_transferLike: transferFrom, permit, safeTransferFrom of
///             ERC-721/1155, DAI move/pull, ERC-777 send, transferAndCall...),
///         and reverts everything otherwise. The solver cannot take more than
///         the user signed for, whatever calls it sends.
///
///         Kinds: SEND, SWAP, STAKE (above); APPROVE: a capped, expiring
///         allowance (the spender = recipient may pull up to maxIn of tokenIn
///         until the deadline, through spendAllowance; an ERC-20 approve can
///         neither expire nor be counted against a daily cap); BRIDGE: exactly
///         maxIn of tokenIn sent through the ONE listed bridge (HyperlaneOutbox
///         style send(recipient, amount)); the recipient is on the other chain,
///         so delivery there is the bridge's job, not checked here.
///
///         simulate(intent, plan) runs the same checks and calls without a
///         signature and always reverts with Simulated(spent, received) (or the
///         reason it would fail): an eth_call preview before the user signs.
///
///         Signatures: EIP-712 by the user's ECDSA key (sigType 0), or the
///         same EIP-712 digest signed with an ML-DSA-44 key whose keccak256
///         the user registered with setPqKey (sigType 1), checked by
///         ZETAPHY's precompile at 0x…0900.
///
///         Tokens are ERC-20 (the native coin is an ERC-20 at
///         0xEeee…EEeE on ZETAPHY). Approve this contract for at most what
///         you sign for; approve a fresh amount per intent.
contract IntentExecutor {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    uint8 public constant SEND = 1;
    uint8 public constant SWAP = 2;
    uint8 public constant STAKE = 3;
    uint8 public constant APPROVE = 4;
    uint8 public constant BRIDGE = 5;
    uint256 public constant MAX_CALLS = 8;
    uint256 public constant CAP_WINDOW = 1 days;

    // Selectors a solver call may never use: the executor does its own (temporary) approval of `spender`.
    bytes4 private constant APPROVE_SEL = 0x095ea7b3;

    struct Intent {
        address user;
        uint8 kind;
        address tokenIn;
        uint256 maxIn;
        address tokenOut;
        uint256 minOut;
        address recipient;
        bytes32 targetsHash; // keccak256(abi.encode(address[] targets)); 0 for SEND and APPROVE
        uint256 nonce;
        uint256 deadline;
    }

    struct Call {
        address target;
        bytes data;
    }

    struct Cap {
        uint256 perDay;  // 0 = no daily cap (each intent's maxIn still applies)
        uint256 spent;   // in the current window
        uint64 windowStart;
    }

    bytes32 public constant INTENT_TYPEHASH = keccak256(
        "Intent(address user,uint8 kind,address tokenIn,uint256 maxIn,address tokenOut,uint256 minOut,address recipient,bytes32 targetsHash,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    mapping(address => mapping(uint256 => bool)) public nonceUsed;
    mapping(address => bytes32) public pqKeyOf;
    mapping(address => mapping(address => Cap)) public caps;     // user => token => daily cap
    mapping(bytes32 => uint256) public allowanceSpent;           // APPROVE intent hash => pulled so far
    uint256 private locked = 1;

    event IntentExecuted(address indexed user, uint256 indexed nonce, bytes32 indexed intentHash, address solver, uint256 spent, uint256 received);
    event AllowanceSpent(address indexed user, uint256 indexed nonce, bytes32 indexed intentHash, address spender, address to, uint256 amount, uint256 left);
    event NonceCancelled(address indexed user, uint256 nonce);
    event PqKeySet(address indexed user, bytes32 keyHash);
    event SpendCapSet(address indexed user, address indexed token, uint256 perDay);

    error Expired();
    error NonceUsed();
    error BadSignature();
    error BadIntent();
    error TargetNotAllowed(address target);
    error ForbiddenCall(address target);
    error CallFailed(uint256 index, bytes reason);
    error SpentTooMuch(uint256 spent, uint256 maxIn);
    error ReceivedTooLittle(uint256 received, uint256 minOut);
    error OverDailyCap(address token, uint256 spent, uint256 perDay);
    error NotSpender();
    error AllowanceExceeded(uint256 wanted, uint256 left);
    error Leftover();
    error TokenFailed();
    error Reentrancy();
    error Simulated(uint256 spent, uint256 received);

    modifier nonReentrant() {
        if (locked != 1) revert Reentrancy();
        locked = 2;
        _;
        locked = 1;
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY IntentExecutor"), keccak256("1"), block.chainid, address(this)));
    }

    function intentHash(Intent calldata i) public pure returns (bytes32) {
        return keccak256(abi.encode(INTENT_TYPEHASH, i.user, i.kind, i.tokenIn, i.maxIn, i.tokenOut, i.minOut,
            i.recipient, i.targetsHash, i.nonce, i.deadline));
    }

    /// The EIP-712 digest the user signs (eth_signTypedData_v4 gives the same).
    function digest(Intent calldata i) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), intentHash(i)));
    }

    /// Registers (or with 0 removes) the ML-DSA-44 key that may sign this account's intents.
    function setPqKey(bytes32 keyHash) external {
        pqKeyOf[msg.sender] = keyHash;
        emit PqKeySet(msg.sender, keyHash);
    }

    function cancel(uint256 nonce) external {
        nonceUsed[msg.sender][nonce] = true;
        emit NonceCancelled(msg.sender, nonce);
    }

    /// The caller's own cap on how much of `token` all its intents together may spend per day
    /// (rolling from the first spend of a window; 0 removes it). Applies to every kind.
    function setSpendCap(address token, uint256 perDay) external {
        caps[msg.sender][token].perDay = perDay;
        emit SpendCapSet(msg.sender, token, perDay);
    }

    /// What `user` may still spend of `token` today under its cap (type(uint256).max = no cap).
    function capLeft(address user, address token) external view returns (uint256) {
        Cap storage c = caps[user][token];
        if (c.perDay == 0) return type(uint256).max;
        uint256 spent = block.timestamp >= c.windowStart + CAP_WINDOW ? 0 : c.spent;
        return spent >= c.perDay ? 0 : c.perDay - spent;
    }

    /// How the user signed: sigType 0 = ECDSA (65 bytes r‖s‖v), 1 = ML-DSA-44 (pqPublicKey + sig).
    struct Auth {
        uint8 sigType;
        bytes sig;
        bytes pqPublicKey;
    }

    /// What the solver does: calls to `targets` only (must hash to intent.targetsHash);
    /// `spender` (one of the targets, or 0) is approved for the pulled tokenIn during the calls.
    /// BRIDGE: targets = [the bridge], no calls (the executor makes the one call itself).
    struct Plan {
        address[] targets;
        address spender;
        Call[] calls;
    }

    function execute(Intent calldata intent, Auth calldata auth, Plan calldata plan)
        external nonReentrant returns (uint256 spent, uint256 received)
    {
        _checkSig(intent, auth);
        (spent, received) = _execute(intent, plan);
        emit IntentExecuted(intent.user, intent.nonce, intentHash(intent), msg.sender, spent, received);
    }

    /// A dry run for eth_call before signing: everything execute does except the signature,
    /// then a revert with Simulated(spent, received) (or the error it would fail with).
    /// It always reverts, so it never changes state. Needs the user's approval of this
    /// contract, as the real run does.
    function simulate(Intent calldata intent, Plan calldata plan) external {
        if (locked != 1) revert Reentrancy();
        locked = 2; // the revert below undoes this too
        (uint256 spent, uint256 received) = intent.kind == APPROVE ? (_checkApprove(intent), 0) : _execute(intent, plan);
        revert Simulated(spent, received);
    }

    /// APPROVE intents: the spender (intent.recipient) pulls `amount` of tokenIn from the user to
    /// `to`, within maxIn in total, before the deadline, under the user's daily cap. cancel(nonce)
    /// ends the allowance.
    function spendAllowance(Intent calldata intent, Auth calldata auth, address to, uint256 amount)
        external nonReentrant returns (uint256 left)
    {
        if (msg.sender != intent.recipient) revert NotSpender();
        _checkApprove(intent);
        _checkSig(intent, auth);
        bytes32 h = intentHash(intent);
        uint256 used = allowanceSpent[h];
        if (amount == 0 || to == address(0) || amount > intent.maxIn - used) revert AllowanceExceeded(amount, intent.maxIn - used);
        allowanceSpent[h] = used + amount;
        _count(intent.user, intent.tokenIn, amount);
        _safe(intent.tokenIn, abi.encodeCall(IIntentERC20.transferFrom, (intent.user, to, amount)));
        left = intent.maxIn - used - amount;
        emit AllowanceSpent(intent.user, intent.nonce, h, msg.sender, to, amount, left);
    }

    /// What an APPROVE intent still allows (0 once expired or cancelled).
    function allowanceLeft(Intent calldata intent) external view returns (uint256) {
        if (intent.kind != APPROVE || block.timestamp > intent.deadline || nonceUsed[intent.user][intent.nonce]) return 0;
        return intent.maxIn - allowanceSpent[intentHash(intent)];
    }

    // ------------------------------------------------------------- internals

    function _execute(Intent calldata intent, Plan calldata plan) private returns (uint256 spent, uint256 received) {
        if (block.timestamp > intent.deadline) revert Expired();
        if (nonceUsed[intent.user][intent.nonce]) revert NonceUsed();
        if (intent.user == address(0) || intent.recipient == address(0) || intent.maxIn == 0) revert BadIntent();
        nonceUsed[intent.user][intent.nonce] = true;

        uint256 userBefore = IIntentERC20(intent.tokenIn).balanceOf(intent.user);
        uint256 recvBefore = intent.kind == BRIDGE ? 0 : IIntentERC20(intent.tokenOut).balanceOf(intent.recipient);

        if (intent.kind == SEND) {
            // to oneself nothing would move: refuse rather than pretend
            if (intent.tokenIn != intent.tokenOut || plan.calls.length != 0 || intent.minOut > intent.maxIn
                || intent.recipient == intent.user) revert BadIntent();
            _safe(intent.tokenIn, abi.encodeCall(IIntentERC20.transferFrom, (intent.user, intent.recipient, intent.minOut)));
        } else if (intent.kind == SWAP || intent.kind == STAKE) {
            _runPlan(intent, plan);
        } else if (intent.kind == BRIDGE) {
            received = _bridge(intent, plan);
        } else {
            revert BadIntent();
        }

        spent = _moved(IIntentERC20(intent.tokenIn).balanceOf(intent.user), userBefore);
        if (spent > intent.maxIn) revert SpentTooMuch(spent, intent.maxIn);
        _count(intent.user, intent.tokenIn, spent);
        if (intent.kind != BRIDGE) {
            received = _moved(recvBefore, IIntentERC20(intent.tokenOut).balanceOf(intent.recipient));
            if (received < intent.minOut) revert ReceivedTooLittle(received, intent.minOut);
        }
    }

    /// The fields an APPROVE intent must have; returns 0 (nothing moves when it is signed).
    function _checkApprove(Intent calldata intent) private view returns (uint256) {
        if (intent.kind != APPROVE || intent.tokenIn != intent.tokenOut || intent.minOut != 0 || intent.targetsHash != bytes32(0)
            || intent.maxIn == 0 || intent.user == address(0) || intent.recipient == address(0) || intent.recipient == intent.user) revert BadIntent();
        if (block.timestamp > intent.deadline) revert Expired();
        if (nonceUsed[intent.user][intent.nonce]) revert NonceUsed();
        return 0;
    }

    /// BRIDGE: pull maxIn, let the one listed bridge take exactly maxIn for intent.recipient.
    function _bridge(Intent calldata intent, Plan calldata plan) private returns (uint256 sent) {
        if (intent.tokenIn != intent.tokenOut || intent.minOut != intent.maxIn || plan.calls.length != 0 || plan.targets.length != 1) revert BadIntent();
        if (keccak256(abi.encode(plan.targets)) != intent.targetsHash) revert BadIntent();
        address bridge = plan.targets[0];
        if (bridge == intent.tokenIn || bridge == intent.user || bridge == address(this) || bridge == address(0)) revert ForbiddenCall(bridge);
        IIntentERC20 tin = IIntentERC20(intent.tokenIn);
        uint256 before = tin.balanceOf(address(this));
        _safe(address(tin), abi.encodeCall(IIntentERC20.transferFrom, (intent.user, address(this), intent.maxIn)));
        _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (bridge, intent.maxIn)));
        try IIntentBridge(bridge).send(intent.recipient, intent.maxIn) {} catch (bytes memory reason) { revert CallFailed(0, reason); }
        _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (bridge, 0)));
        uint256 nowBal = tin.balanceOf(address(this));
        if (nowBal != before) revert Leftover(); // the bridge took exactly maxIn: nothing back, nothing kept
        sent = intent.maxIn;
    }

    /// Counts `amount` against the user's daily cap for `token`, if the user set one.
    function _count(address user, address token, uint256 amount) private {
        Cap storage c = caps[user][token];
        if (c.perDay == 0 || amount == 0) return;
        if (block.timestamp >= c.windowStart + CAP_WINDOW) {
            c.windowStart = uint64(block.timestamp);
            c.spent = 0;
        }
        uint256 s = c.spent + amount;
        if (s > c.perDay) revert OverDailyCap(token, s, c.perDay);
        c.spent = s;
    }

    /// hi - lo when hi > lo, else 0 (how far a balance moved).
    function _moved(uint256 lo, uint256 hi) private pure returns (uint256) {
        return hi > lo ? hi - lo : 0;
    }

    function _runPlan(Intent calldata intent, Plan calldata plan) private {
        if (intent.tokenIn == intent.tokenOut || plan.calls.length == 0 || plan.calls.length > MAX_CALLS) revert BadIntent();
        if (keccak256(abi.encode(plan.targets)) != intent.targetsHash) revert BadIntent();
        IIntentERC20 tin = IIntentERC20(intent.tokenIn);
        IIntentERC20 tout = IIntentERC20(intent.tokenOut);
        uint256 inBefore = tin.balanceOf(address(this));
        uint256 outBefore = tout.balanceOf(address(this));
        _safe(address(tin), abi.encodeCall(IIntentERC20.transferFrom, (intent.user, address(this), intent.maxIn)));
        if (plan.spender != address(0)) {
            _allowed(plan.spender, plan.targets, intent);
            _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (plan.spender, intent.maxIn)));
        }
        for (uint256 k = 0; k < plan.calls.length; k++) _call(k, plan.calls[k], plan.targets, intent);
        if (plan.spender != address(0)) _safe(address(tin), abi.encodeCall(IIntentERC20.approve, (plan.spender, 0)));
        // leftovers: tokenIn back to the user, tokenOut on to the recipient
        uint256 inNow = tin.balanceOf(address(this));
        if (inNow > inBefore) _safe(address(tin), abi.encodeCall(IIntentERC20.transfer, (intent.user, inNow - inBefore)));
        uint256 outNow = tout.balanceOf(address(this));
        if (outNow > outBefore) _safe(address(tout), abi.encodeCall(IIntentERC20.transfer, (intent.recipient, outNow - outBefore)));
        if (tin.balanceOf(address(this)) != inBefore || tout.balanceOf(address(this)) != outBefore) revert Leftover();
    }

    function _call(uint256 k, Call calldata c, address[] calldata targets, Intent calldata intent) private {
        _allowed(c.target, targets, intent);
        if (c.data.length >= 4) {
            bytes4 sel = bytes4(c.data[0:4]);
            // approve, and every transfer-like selector (_transferLike: transferFrom, permit, ERC-721/1155
            // safeTransferFrom, DAI move/pull, ERC-777 send, transferAndCall, Permit2, ...): a listed target
            // must never pull what a user approved to this contract
            if (sel == APPROVE_SEL || _transferLike(sel)) {
                revert ForbiddenCall(c.target);
            }
        }
        (bool ok, bytes memory ret) = c.target.call(c.data);
        if (!ok) revert CallFailed(k, ret);
    }

    /// Selectors that move tokens out of an account, or authorise someone else to, other than a plain
    /// ERC-20 transfer / approve (the same list as AgentPolicyWallet.isTransferLike). A target the user
    /// listed must never use what the user approved to this contract through one of them.
    function _transferLike(bytes4 s) private pure returns (bool) {
        return s == 0x23b872dd // transferFrom(address,address,uint256)               ERC-20 / ERC-721
            || s == 0x39509351 // increaseAllowance(address,uint256)
            || s == 0xa22cb465 // setApprovalForAll(address,bool)                      ERC-721 / ERC-1155
            || s == 0xd505accf // permit(address,address,uint256,uint256,uint8,bytes32,bytes32) EIP-2612
            || s == 0x42842e0e // safeTransferFrom(address,address,uint256)           ERC-721
            || s == 0xb88d4fde // safeTransferFrom(address,address,uint256,bytes)     ERC-721
            || s == 0xf242432a // safeTransferFrom(address,address,uint256,uint256,bytes) ERC-1155
            || s == 0x2eb2c2d6 // safeBatchTransferFrom(address,address,uint256[],uint256[],bytes) ERC-1155
            || s == 0x9bd9bbc6 // send(address,uint256,bytes)                         ERC-777
            || s == 0x62ad1b83 // operatorSend(address,address,uint256,bytes,bytes)   ERC-777
            || s == 0x959b8c3f // authorizeOperator(address)                          ERC-777
            || s == 0x4000aea0 // transferAndCall(address,uint256,bytes)              ERC-677 / ERC-1363
            || s == 0x1296ee62 // transferAndCall(address,uint256)                    ERC-1363
            || s == 0xd8fbe994 // transferFromAndCall(address,address,uint256)        ERC-1363
            || s == 0xc1d34b89 // transferFromAndCall(address,address,uint256,bytes)  ERC-1363
            || s == 0x3177029f // approveAndCall(address,uint256)                     ERC-1363
            || s == 0xcae9ca51 // approveAndCall(address,uint256,bytes)               ERC-1363
            || s == 0xbb35783b // move(address,address,uint256)                      DAI
            || s == 0xf2d5d56b // pull(address,uint256)                              DAI
            || s == 0xb753a98c // push(address,uint256)                              DAI
            || s == 0x8fcbaf0c // permit(address,address,uint256,uint256,bool,uint8,bytes32,bytes32) DAI
            || s == 0x2b67b570 // permit(address,((address,uint160,uint48,uint48),address,uint256),bytes) Permit2
            || s == 0x2a2d80d1 // permit(address,((address,uint160,uint48,uint48)[],address,uint256),bytes) Permit2
            || s == 0x87517c45 // approve(address,address,uint160,uint48)             Permit2
            || s == 0x36c78516 // transferFrom(address,address,uint160,address)       Permit2
            || s == 0x42966c68 // burn(uint256)
            || s == 0x9dc29fac // burn(address,uint256)
            || s == 0x79cc6790; // burnFrom(address,uint256)
    }

    /// A call target must be listed, and never tokenIn, the user, this contract or 0. tokenOut is
    /// refused too, except for STAKE, where the vault is both the target and the receipt token
    /// (ERC-4626 style); the balance checks still hold there.
    function _allowed(address t, address[] calldata targets, Intent calldata intent) private view {
        if (t == intent.tokenIn || t == intent.user || t == address(this) || t == address(0)) revert ForbiddenCall(t);
        if (t == intent.tokenOut && intent.kind != STAKE) revert ForbiddenCall(t);
        for (uint256 i = 0; i < targets.length; i++) if (targets[i] == t) return;
        revert TargetNotAllowed(t);
    }

    function _checkSig(Intent calldata intent, Auth calldata auth) private view {
        bytes32 d = digest(intent);
        if (auth.sigType == 0) {
            bytes calldata sig = auth.sig;
            if (sig.length != 65) revert BadSignature();
            uint8 v = uint8(sig[64]);
            if (v < 27) v += 27;
            if (uint256(bytes32(sig[32:64])) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
            address got = ecrecover(d, v, bytes32(sig[0:32]), bytes32(sig[32:64]));
            if (got == address(0) || got != intent.user) revert BadSignature();
        } else if (auth.sigType == 1) {
            bytes32 kh = pqKeyOf[intent.user];
            if (kh == bytes32(0) || keccak256(auth.pqPublicKey) != kh) revert BadSignature();
            (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), d, auth.pqPublicKey, auth.sig));
            if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadSignature();
        } else {
            revert BadSignature();
        }
    }

    /// ERC-20 call that accepts tokens returning nothing (USDT style) but not false or a revert.
    function _safe(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool))) || (ret.length == 0 && token.code.length == 0)) revert TokenFailed();
    }
}

