// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IMockRecipient {
    function handle(uint32 origin, bytes32 sender, bytes calldata message) external payable;
}

/// @title MockMailbox: TEST ONLY stand-in for a Hyperlane v3 Mailbox
/// @notice dispatch() records the message (and charges `fee`); deliver() plays
///         the relayer + ISM on the destination: it calls handle() as the real
///         Mailbox does after its ISM verified the message. Anyone may deliver
///         anything here: it stands for a Mailbox, never use it on a real chain.
contract MockMailbox {
    uint32 public immutable localDomain;
    uint256 public fee;
    uint32 public nonce;

    address public lastHook;   // the custom hook of the last dispatch (zero = default)

    event Dispatch(address indexed sender, uint32 indexed destination, bytes32 indexed recipient, bytes message);

    constructor(uint32 localDomain_) { localDomain = localDomain_; }

    function setFee(uint256 f) external { fee = f; }

    function quoteDispatch(uint32, bytes32, bytes calldata) external view returns (uint256) { return fee; }

    function quoteDispatch(uint32, bytes32, bytes calldata, bytes calldata, address) external view returns (uint256) { return fee; }

    function dispatch(uint32 destination, bytes32 recipient, bytes calldata body, bytes calldata, address hook) external payable returns (bytes32 id) {
        lastHook = hook;
        return _dispatch(destination, recipient, body);
    }

    function dispatch(uint32 destination, bytes32 recipient, bytes calldata body) external payable returns (bytes32 id) {
        lastHook = address(0);
        return _dispatch(destination, recipient, body);
    }

    function _dispatch(uint32 destination, bytes32 recipient, bytes calldata body) private returns (bytes32 id) {
        require(msg.value >= fee, "fee");
        id = keccak256(abi.encode(localDomain, nonce++, msg.sender, destination, recipient, body));
        emit Dispatch(msg.sender, destination, recipient, body);
    }

    function deliver(uint32 origin, bytes32 sender, address recipient, bytes calldata body) external {
        IMockRecipient(recipient).handle(origin, sender, body);
    }
}

contracts/ModelEpochs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ModelEpochs: which Neuro model is in force at which block height (testnet)
/// @notice Binds a Neuro model version to chain state. Each version is the
///         sha256 of a manifest file (zetaphy-neuro/ml/manifest.json: the
///         model's and the federated head's file hashes), the height it takes
///         effect at, and where to fetch the manifest.
///
///         Rules that make the choice deterministic for every node and browser:
///           - activation heights strictly increase and sit on epoch
///             boundaries (activation % epochLength == 0);
///           - a version may only be scheduled at least minDelay (>= 1)
///             blocks ahead: activation >= block.number + minDelay;
///           - only a version still in the future may be cancelled, and only
///             the latest one (versions are never edited or reordered).
///         So the version in force at height h (the last one with
///         activation <= h, versionAt(h)) is fixed as soon as block h-1 is
///         committed: whoever reads the registry at any later state gets the
///         same answer for h.
///
///         Governance is the chain's gov module (a MsgEVMCall proposal) or a
///         timelock / SimpleMultisig. A guardian may cancel a pending version
///         (a veto that only ever keeps the version already in force), never
///         schedule one.
contract ModelEpochs {
    struct Version {
        bytes32 hash;
        uint64 activation;
        uint64 scheduledAt;
        string uri;
    }

    uint256 public constant MAX_URI = 256;
    uint64 public constant MAX_DELAY = 1_000_000;

    address public governance;
    mapping(address => bool) public guardian;
    uint64 public immutable epochLength;
    uint64 public minDelay;
    Version[] private _versions;

    event GovernanceChanged(address governance);
    event GuardianSet(address indexed who, bool allowed);
    event MinDelay(uint64 blocks);
    event Scheduled(uint256 indexed index, bytes32 indexed hash, uint64 activation, string uri);
    event Cancelled(uint256 indexed index, bytes32 indexed hash, address by);

    error NotGovernance();
    error NotGuardian();
    error BadValue();
    error TooSoon();
    error NotPending();

    constructor(address governance_, uint64 epochLength_, uint64 minDelay_) {
        if (governance_ == address(0) || epochLength_ == 0) revert BadValue();
        if (minDelay_ == 0 || minDelay_ > MAX_DELAY) revert BadValue();
        governance = governance_;
        epochLength = epochLength_;
        minDelay = minDelay_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    function setGuardian(address who, bool allowed) external onlyGovernance {
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    function setMinDelay(uint64 blocks) external onlyGovernance {
        if (blocks == 0 || blocks > MAX_DELAY) revert BadValue();
        minDelay = blocks;
        emit MinDelay(blocks);
    }

    /// Schedules a new version, in force from `activation` on.
    function schedule(bytes32 hash, uint64 activation, string calldata uri) external onlyGovernance returns (uint256 index) {
        if (hash == bytes32(0) || activation % epochLength != 0) revert BadValue();
        uint256 len = bytes(uri).length;
        if (len == 0 || len > MAX_URI) revert BadValue();
        if (uint256(activation) < block.number + minDelay) revert TooSoon();
        uint256 n = _versions.length;
        if (n > 0 && activation <= _versions[n - 1].activation) revert BadValue();
        _versions.push(Version(hash, activation, uint64(block.number), uri));
        emit Scheduled(n, hash, activation, uri);
        return n;
    }

    /// Cancels the latest version while it is still in the future.
    function cancelLast() external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        uint256 n = _versions.length;
        if (n == 0 || _versions[n - 1].activation <= block.number) revert NotPending();
        Version storage v = _versions[n - 1];
        emit Cancelled(n - 1, v.hash, msg.sender);
        _versions.pop();
    }

    function count() external view returns (uint256) {
        return _versions.length;
    }

    function versionByIndex(uint256 i) external view returns (bytes32 hash, uint64 activation, uint64 scheduledAt, string memory uri) {
        Version storage v = _versions[i];
        return (v.hash, v.activation, v.scheduledAt, v.uri);
    }

    /// The version in force at `height`: the last one with activation <= height.
    /// found = false before the first version (Neuro then runs on its rules only).
    function versionAt(uint256 height) public view returns (bool found, uint256 index, bytes32 hash, uint64 activation, string memory uri) {
        uint256 lo = 0;
        uint256 hi = _versions.length;
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (_versions[mid].activation <= height) lo = mid + 1;
            else hi = mid;
        }
        if (lo == 0) return (false, 0, bytes32(0), 0, "");
        Version storage v = _versions[lo - 1];
        return (true, lo - 1, v.hash, v.activation, v.uri);
    }

    /// The version in force at the current block.
    function current() external view returns (bool found, uint256 index, bytes32 hash, uint64 activation, string memory uri) {
        return versionAt(block.number);
    }
}

contracts/ModelRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ModelRegistry: which AI models, skills, prompts and rule sets ZETAPHY trusts (testnet)
/// @notice One record per (id, version): the sha256 of its manifest, the Merkle
///         root of its chunks (sha256 per chunk, see docs/future/browser-ai.md),
///         its size and chunk size, its license (SPDX id), its author and its
///         status. A browser or runner that downloads a model from ANY mirror
///         (this project's site, GitHub Releases, an IPFS gateway, another
///         browser over WebRTC) checks the manifest against manifestHash and
///         every chunk against chunkRoot, so a mirror can only refuse to serve,
///         never serve something else.
///
///         Who changes what (the same split as every other ZETAPHY contract,
///         see ZetaphyTimelock):
///           - governance (ZetaphyTimelock: every change waits its delay in
///             public, e.g. 48 h): publish a release, set any status
///             (Active, Suspended, Deprecated, Revoked), name guardians, hand
///             governance on;
///           - a guardian: suspend(id, version) only, at once. Suspending only
///             reduces risk (loaders stop using that release); only governance
///             makes it Active again.
///         Revoked is final: a revoked release can never be used again (a fixed
///         model is a new version).
///
///         Ids: idOf(kind, name) = keccak256("zetaphy.registry", kind, name),
///         e.g. idOf(Model, "neuro-ml-gbdt"). Versions of an id only go up.
contract ModelRegistry {
    enum Kind { None, Model, Skill, Prompt, Ruleset }
    enum Status { None, Active, Suspended, Deprecated, Revoked }

    struct Release {
        Kind kind;
        Status status;
        uint32 chunkSize;     // bytes per chunk (the last one may be shorter)
        uint64 size;          // bytes of the whole artifact
        uint64 publishedAt;
        uint64 updatedAt;
        bytes32 manifestHash; // sha256 of the manifest file's exact bytes
        bytes32 chunkRoot;    // Merkle root over the chunks' sha256 (leaf/node domain-separated)
        address author;
        string license;       // SPDX id, printable ASCII, 1..MAX_LICENSE bytes
    }

    uint256 public constant MAX_LICENSE = 64;
    uint32 public constant MIN_CHUNK = 1024;
    uint32 public constant MAX_CHUNK = 64 * 1024 * 1024;

    address public governance;
    mapping(address => bool) public guardian;

    mapping(bytes32 => Kind) public kindOf;
    mapping(bytes32 => uint32) public latestVersion;
    mapping(bytes32 => mapping(uint32 => Release)) private _releases;
    bytes32[] private _ids;

    event Published(bytes32 indexed id, uint32 indexed version, Kind kind, bytes32 manifestHash, bytes32 chunkRoot, uint64 size, uint32 chunkSize, address author, string license);
    event StatusChanged(bytes32 indexed id, uint32 indexed version, Status status, address indexed by);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);

    error NotGovernance();
    error NotGuardian();
    error BadValue();
    error BadVersion();
    error KindMismatch();
    error UnknownRelease();
    error Final();

    constructor(address governance_) {
        if (governance_ == address(0)) revert BadValue();
        governance = governance_;
        emit GovernanceSet(governance_);
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        if (g == address(0)) revert BadValue();
        governance = g;
        emit GovernanceSet(g);
    }

    function setGuardian(address who, bool on) external onlyGov {
        if (who == address(0)) revert BadValue();
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// The id of a named entry of a kind.
    function idOf(Kind kind, string calldata name) external pure returns (bytes32) {
        return keccak256(abi.encodePacked("zetaphy.registry", uint8(kind), name));
    }

    function _checkLicense(string calldata license) private pure {
        bytes calldata b = bytes(license);
        if (b.length == 0 || b.length > MAX_LICENSE) revert BadValue();
        for (uint256 i; i < b.length; i++) if (b[i] < 0x21 || b[i] > 0x7e) revert BadValue();
    }

    /// Governance (the timelock) publishes a new version of an id. It starts Active.
    function publish(
        bytes32 id, Kind kind, uint32 version, bytes32 manifestHash, bytes32 chunkRoot,
        uint64 size, uint32 chunkSize, address author, string calldata license
    ) external onlyGov {
        if (id == bytes32(0) || kind == Kind.None || manifestHash == bytes32(0) || chunkRoot == bytes32(0)) revert BadValue();
        if (size == 0 || chunkSize < MIN_CHUNK || chunkSize > MAX_CHUNK || author == address(0)) revert BadValue();
        _checkLicense(license);
        Kind known = kindOf[id];
        if (known == Kind.None) { kindOf[id] = kind; _ids.push(id); }
        else if (known != kind) revert KindMismatch();
        if (version <= latestVersion[id]) revert BadVersion();
        latestVersion[id] = version;
        _releases[id][version] = Release(kind, Status.Active, chunkSize, size, uint64(block.timestamp), uint64(block.timestamp),
            manifestHash, chunkRoot, author, license);
        emit Published(id, version, kind, manifestHash, chunkRoot, size, chunkSize, author, license);
        emit StatusChanged(id, version, Status.Active, msg.sender);
    }

    /// Governance sets any status except None; Revoked is final.
    function setStatus(bytes32 id, uint32 version, Status status) external onlyGov {
        if (status == Status.None) revert BadValue();
        _setStatus(id, version, status);
    }

    /// A guardian (or governance) suspends an Active release at once.
    function suspend(bytes32 id, uint32 version) external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        if (_releases[id][version].status != Status.Active) revert BadValue();
        _setStatus(id, version, Status.Suspended);
    }

    function _setStatus(bytes32 id, uint32 version, Status status) private {
        Release storage r = _releases[id][version];
        if (r.status == Status.None) revert UnknownRelease();
        if (r.status == Status.Revoked) revert Final();
        r.status = status;
        r.updatedAt = uint64(block.timestamp);
        emit StatusChanged(id, version, status, msg.sender);
    }

    function release(bytes32 id, uint32 version) external view returns (Release memory) {
        return _releases[id][version];
    }

    /// The latest version of an id and its record (version 0 and an empty record: unknown id).
    function latest(bytes32 id) external view returns (uint32 version, Release memory r) {
        version = latestVersion[id];
        r = _releases[id][version];
    }

    /// True when (id, version) is Active and has exactly these hashes: what a loader asks.
    function isUsable(bytes32 id, uint32 version, bytes32 manifestHash, bytes32 chunkRoot) external view returns (bool) {
        Release storage r = _releases[id][version];
        return r.status == Status.Active && r.manifestHash == manifestHash && r.chunkRoot == chunkRoot;
    }

    function idCount() external view returns (uint256) {
        return _ids.length;
    }

    function idAt(uint256 i) external view returns (bytes32) {
        return _ids[i];
    }
}

contracts/NeuroAttest.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// "Neuro-checked" certificates and a hash anchor (docs/future/crosschain-assist.md, items 19 and 30).
//
// NeuroAttest: a minimal EAS-like attestation registry with one schema, "zetaphy.neuro-checked.v1":
// a token (subject, on this chain) was checked by Neuro, with the report's hash (Neuro's verdict hash,
// zetaphy-neuro/src/verdict.js), the skill id of the Neuro code that made it (zetaphy-network/src/skill.js)
// and the AI model, if any (a short name; "rules" when only the rules ran). Two ways in:
//   - attestFromJob(jobId, token): anyone, for a NeuroJobs job on chain "zetaphy" about that token whose
//     verdict is settled (2-of-3 runners agreed, no challenge open or possible): the attester is NeuroJobs
//     itself, the report hash is the job's verdict, the skill the job's. Nobody's word is needed.
//   - attest(...): an attester governance approved (the launch tools' deployer key, testnet), for a token
//     it just created and checked; the badge says who attested.
// Governance (the chain's gov module through MsgEVMCall, or the timelock) revokes any attestation with a
// reason; an attester may revoke its own. A certificate says "Neuro checked this code and here is the
// report", never "safe": wallets and the DEX show it next to the report and any ThreatRegistry flag.
//
// NeuroAnchor: anyone anchors a 32-byte hash once; the first block and time stay (the PQ attestation archive
// of item 30 anchors its hash here, so an archive can be shown to have existed by then).

interface INAJobs {
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function jobInfo(uint256 id) external view returns (bytes32 skill, uint256 bodies, uint256 drawn, uint64 settleAt, bytes32 rand);
    function assurance(uint256 id) external view returns (uint8 agreedBy, uint8 state, uint64 challengeUntil, bool settled);
}

contract NeuroAttest {
    bytes32 public constant SCHEMA = keccak256("zetaphy.neuro-checked.v1");
    bytes32 public constant ZETAPHY_CHAIN = "zetaphy";   // NeuroJobs' chain id for this chain
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_REASON = 200;

    struct Attestation {
        bytes32 schema;
        address subject;      // the token (on this chain)
        address attester;     // NeuroJobs for attestFromJob, else the approved attester
        uint64 time;
        uint64 revokedAt;     // 0: valid
        bytes32 reportHash;   // Neuro's verdict hash of the report
        bytes32 skill;        // the Neuro skill id (code version) that made it
        bytes32 model;        // AI model (short name as bytes32), "rules" when none
        uint256 jobId;        // the NeuroJobs job (attestFromJob; attester == jobs), else 0
        string uri;           // where the report can be read (at most MAX_URI bytes)
    }

    INAJobs public immutable jobs;        // zero: attestFromJob off
    address public governance;
    mapping(address => bool) public attester;
    Attestation[] private _all;           // uid = index + 1
    mapping(address => uint256) public latestOf;    // subject -> newest uid
    mapping(uint256 => bool) public jobUsed;
    mapping(uint256 => string) public revokeReason;

    event Attested(uint256 indexed uid, address indexed subject, address indexed attester, bytes32 reportHash, bytes32 skill, bytes32 model, uint256 jobId);
    event Revoked(uint256 indexed uid, address indexed by, string reason);
    event AttesterSet(address indexed who, bool on);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotAttester();
    error NoSuchAttestation();
    error AlreadyRevoked();
    error TooLong();
    error NotSettled(uint256 jobId);
    error WrongJob(uint256 jobId);
    error JobUsed(uint256 jobId);
    error NoReport();

    constructor(INAJobs jobs_, address governance_) {
        require(governance_ != address(0), "zero");
        jobs = jobs_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }
    function setAttester(address who, bool on) external onlyGov { attester[who] = on; emit AttesterSet(who, on); }

    /// An approved attester certifies `subject` (a token it created and ran Neuro on).
    function attest(address subject, bytes32 reportHash, bytes32 skill, bytes32 model, string calldata uri) external returns (uint256) {
        if (!attester[msg.sender]) revert NotAttester();
        if (skill == bytes32(0)) revert NoReport();
        return _attest(subject, msg.sender, reportHash, skill, model, 0, uri);
    }

    /// Anyone: a settled NeuroJobs verdict on chain "zetaphy" about `subject` becomes its certificate.
    function attestFromJob(uint256 jobId, address subject) external returns (uint256) {
        if (address(jobs) == address(0)) revert NotSettled(jobId);
        if (jobUsed[jobId]) revert JobUsed(jobId);
        (, , , bool settled) = jobs.assurance(jobId);
        if (!settled) revert NotSettled(jobId);
        (, , , bytes32 chain, string memory target, , bytes32 result, , , ) = jobs.getJob(jobId);
        if (chain != ZETAPHY_CHAIN || keccak256(_lower(bytes(target))) != keccak256(_addr(subject))) revert WrongJob(jobId);
        (bytes32 skill, , , , ) = jobs.jobInfo(jobId);
        jobUsed[jobId] = true;
        return _attest(subject, address(jobs), result, skill, "rules", jobId, "");
    }

    function _attest(address subject, address by, bytes32 reportHash, bytes32 skill, bytes32 model, uint256 jobId, string memory uri) private returns (uint256 uid) {
        if (reportHash == bytes32(0) || subject == address(0)) revert NoReport();
        if (bytes(uri).length > MAX_URI) revert TooLong();
        _all.push(Attestation(SCHEMA, subject, by, uint64(block.timestamp), 0, reportHash, skill, model, jobId, uri));
        uid = _all.length;
        latestOf[subject] = uid;
        emit Attested(uid, subject, by, reportHash, skill, model, jobId);
    }

    /// Governance revokes any attestation; an attester its own.
    function revoke(uint256 uid, string calldata reason) external {
        Attestation storage a = _get(uid);
        if (msg.sender != governance && !(msg.sender == a.attester && attester[msg.sender])) revert NotGovernance();
        if (a.revokedAt != 0) revert AlreadyRevoked();
        if (bytes(reason).length > MAX_REASON) revert TooLong();
        a.revokedAt = uint64(block.timestamp);
        revokeReason[uid] = reason;
        emit Revoked(uid, msg.sender, reason);
    }

    function _get(uint256 uid) private view returns (Attestation storage) {
        if (uid == 0 || uid > _all.length) revert NoSuchAttestation();
        return _all[uid - 1];
    }

    function getAttestation(uint256 uid) external view returns (Attestation memory) { return _get(uid); }
    function count() external view returns (uint256) { return _all.length; }

    /// The badge: the subject's newest attestation, if it is not revoked.
    /// (checked, uid, reportHash, skill, model, attester, time)
    function badge(address subject) external view returns (bool checked, uint256 uid, bytes32 reportHash, bytes32 skill, bytes32 model, address by, uint64 time) {
        uid = latestOf[subject];
        if (uid == 0) return (false, 0, 0, 0, 0, address(0), 0);
        Attestation storage a = _all[uid - 1];
        return (a.revokedAt == 0, uid, a.reportHash, a.skill, a.model, a.attester, a.time);
    }

    function _lower(bytes memory b) private pure returns (bytes memory) {
        for (uint256 i = 0; i < b.length; ++i) if (b[i] >= "A" && b[i] <= "Z") b[i] = bytes1(uint8(b[i]) + 32);
        return b;
    }

    function _addr(address a) private pure returns (bytes memory out) {
        bytes16 h = "0123456789abcdef";
        out = new bytes(42);
        out[0] = "0";
        out[1] = "x";
        for (uint256 i = 0; i < 20; ++i) {
            uint8 c = uint8(uint160(a) >> (8 * (19 - i)));
            out[2 + 2 * i] = h[c >> 4];
            out[3 + 2 * i] = h[c & 0x0f];
        }
    }
}

/// @title NeuroAnchor: the first time a hash was seen on ZETAPHY
contract NeuroAnchor {
    struct Anchor { uint64 time; uint64 blockNumber; address by; }
    mapping(bytes32 => Anchor) public anchors;
    event Anchored(bytes32 indexed hash, address indexed by, uint64 time);
    error AlreadyAnchored(uint64 time);
    error Zero();

    function anchor(bytes32 h) external {
        if (h == bytes32(0)) revert Zero();
        if (anchors[h].time != 0) revert AlreadyAnchored(anchors[h].time);
        anchors[h] = Anchor(uint64(block.timestamp), uint64(block.number), msg.sender);
        emit Anchored(h, msg.sender, uint64(block.timestamp));
    }

    /// (time, block, by) of the first anchor; time 0: never anchored.
    function anchoredAt(bytes32 h) external view returns (uint64, uint64, address) {
        Anchor storage a = anchors[h];
        return (a.time, a.blockNumber, a.by);
    }
}

contracts/NeuroControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title NeuroControl: the governance knobs of Neuro (testnet)
/// @notice One place where the vote steers Neuro, separate from the coin:
///           - paused(): the Neuro stop button. NeuroJobs takes no new
///             requests or commits and runners stop taking jobs. It never
///             touches coin transfers, staking, bridges or withdrawals.
///             A guardian may pull it at once; only governance releases it.
///           - skills: a skill id (sha256 of Neuro's code, `zetaphy neuro
///             skill-id`) must be approved by a vote before jobs use it;
///             new jobs record activeSkill().
///           - the defender roster: runners governance allows to sit in the
///             4 defender seats of NeuroJobs (filled by its regrow()).
///           - release(runner): lets a quarantined runner work again.
///           - maxBodies: the cap on elastic bodies; maxRegrowPerHour: the
///             cap on refilling defender seats after an attack.
///           - communityFund: receives 5% of every job fee. The burned 5%
///             goes to BURN, an address nobody has a key for: it is locked
///             forever (still counted in the bank supply, never spendable).
///           - chains: the chain keys ("bsc", "eth", ...) NeuroJobs takes
///             requests for. A request for any other chain reverts, so fake
///             requests for chains no runner reads cannot inflate the bodies.
///             `zetaphy deploy` seeds it with the chains the runner supports.
///           - challenges: challengeBond (the least bond to challenge a
///             verdict; NeuroJobs asks max(2 x fee, this)), challengeWindow
///             (seconds after a quorum in which anyone may challenge; 0 =
///             NeuroJobs' jobTimeout) and defenderTimeout (a defender silent
///             longer than this loses its seat at the next regrow).
///         Governance is the chain's gov module (its EVM address, called
///         through a MsgEVMCall proposal: zetaphy-chain/gov.sh neuro ...) or
///         a SimpleMultisig.
///
///         Small read interface used by other contracts:
///           paused() returns (bool)
///           activeSkill() returns (bytes32)
///           defenderApproved(address) returns (bool)
///           releasedAt(address) returns (uint64)
///           maxBodies() / maxRegrowPerHour() returns (uint256)
///           communityFund() returns (address)
///           chainAllowed(bytes32) returns (bool)
///           challengeBond() / challengeWindow() / defenderTimeout() returns (uint256)
contract NeuroControl {
    /// Locked forever: no key exists for it.
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Bodies never go below the four defender seats.
    uint256 public constant MIN_BODIES = 4;
    uint256 public constant MAX_BODIES = 1000;
    uint256 public constant MAX_ROSTER = 32;
    uint256 public constant MAX_CHAINS_PER_CALL = 64;
    /// Bounds of the challenge window and the defender timeout (seconds).
    uint256 public constant MIN_WINDOW = 60;
    uint256 public constant MAX_WINDOW = 7 days;

    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;

    mapping(bytes32 => bool) public skillApproved;
    bytes32 public activeSkill;

    mapping(address => bool) public defenderApproved;
    address[] private _roster;

    /// When governance last released a runner from quarantine; a quarantine
    /// that started after this still holds.
    mapping(address => uint64) public releasedAt;

    uint256 public maxBodies;
    uint256 public maxRegrowPerHour;
    address public communityFund;

    /// Chain keys (bytes32 of e.g. "bsc") NeuroJobs accepts requests for.
    mapping(bytes32 => bool) public chainAllowed;

    /// Least challenge bond (NeuroJobs asks max(2 x job fee, this)).
    uint256 public challengeBond = 1 ether;
    /// Seconds after a quorum in which a verdict may be challenged; 0 = NeuroJobs' jobTimeout.
    uint256 public challengeWindow;
    /// A defender whose last heartbeat (or commit/reveal) is older than this loses its seat.
    uint256 public defenderTimeout = 6 hours;

    event GovernanceChanged(address governance);
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event SkillApproved(bytes32 indexed id);
    event SkillRevoked(bytes32 indexed id);
    event ActiveSkill(bytes32 indexed id);
    event DefenderApproved(address indexed runner);
    event DefenderRemoved(address indexed runner);
    event Released(address indexed runner);
    event MaxBodies(uint256 value);
    event MaxRegrowPerHour(uint256 value);
    event CommunityFund(address fund);
    event ChainApproved(bytes32 indexed chain);
    event ChainRemoved(bytes32 indexed chain);
    event ChallengeBond(uint256 value);
    event ChallengeWindow(uint256 value);
    event DefenderTimeout(uint256 value);

    error NotGovernance();
    error NotGuardian();
    error BadValue();
    error NotApproved();
    error SkillInUse();

    constructor(address governance_, address communityFund_, uint256 maxBodies_, uint256 maxRegrowPerHour_) {
        if (governance_ == address(0) || communityFund_ == address(0)) revert BadValue();
        if (maxBodies_ < MIN_BODIES || maxBodies_ > MAX_BODIES || maxRegrowPerHour_ == 0) revert BadValue();
        governance = governance_;
        communityFund = communityFund_;
        maxBodies = maxBodies_;
        maxRegrowPerHour = maxRegrowPerHour_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- stop button ----

    /// A guardian (or governance) stops Neuro at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Only a vote starts it again.
    function unpause() external onlyGovernance {
        paused = false;
        emit Unpaused();
    }

    function setGuardian(address who, bool allowed) external onlyGovernance {
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- skills ----

    function approveSkill(bytes32 id) external onlyGovernance {
        if (id == bytes32(0)) revert BadValue();
        skillApproved[id] = true;
        emit SkillApproved(id);
    }

    /// The active skill cannot be revoked: switch first (or pause).
    function revokeSkill(bytes32 id) external onlyGovernance {
        if (id == activeSkill) revert SkillInUse();
        skillApproved[id] = false;
        emit SkillRevoked(id);
    }

    function setActiveSkill(bytes32 id) external onlyGovernance {
        if (!skillApproved[id]) revert NotApproved();
        activeSkill = id;
        emit ActiveSkill(id);
    }

    // ---- defenders and quarantine ----

    function approveDefender(address runner) external onlyGovernance {
        if (runner == address(0) || defenderApproved[runner] || _roster.length == MAX_ROSTER) revert BadValue();
        defenderApproved[runner] = true;
        _roster.push(runner);
        emit DefenderApproved(runner);
    }

    /// Its seat (if any) is vacated by the next NeuroJobs.regrow().
    function removeDefender(address runner) external onlyGovernance {
        if (!defenderApproved[runner]) revert NotApproved();
        defenderApproved[runner] = false;
        for (uint256 i = 0; i < _roster.length; i++) {
            if (_roster[i] == runner) {
                _roster[i] = _roster[_roster.length - 1];
                _roster.pop();
                break;
            }
        }
        emit DefenderRemoved(runner);
    }

    function roster() external view returns (address[] memory) {
        return _roster;
    }

    function release(address runner) external onlyGovernance {
        releasedAt[runner] = uint64(block.timestamp);
        emit Released(runner);
    }

    // ---- sizes and money ----

    function setMaxBodies(uint256 n) external onlyGovernance {
        if (n < MIN_BODIES || n > MAX_BODIES) revert BadValue();
        maxBodies = n;
        emit MaxBodies(n);
    }

    function setMaxRegrowPerHour(uint256 n) external onlyGovernance {
        if (n == 0 || n > MAX_ROSTER) revert BadValue();
        maxRegrowPerHour = n;
        emit MaxRegrowPerHour(n);
    }

    function setCommunityFund(address fund) external onlyGovernance {
        if (fund == address(0)) revert BadValue();
        communityFund = fund;
        emit CommunityFund(fund);
    }

    // ---- challenges and defender liveness ----

    function setChallengeBond(uint256 amount) external onlyGovernance {
        if (amount == 0) revert BadValue();
        challengeBond = amount;
        emit ChallengeBond(amount);
    }

    /// 0 goes back to NeuroJobs' jobTimeout.
    function setChallengeWindow(uint256 secs) external onlyGovernance {
        if (secs != 0 && (secs < MIN_WINDOW || secs > MAX_WINDOW)) revert BadValue();
        challengeWindow = secs;
        emit ChallengeWindow(secs);
    }

    function setDefenderTimeout(uint256 secs) external onlyGovernance {
        if (secs < MIN_WINDOW || secs > MAX_WINDOW) revert BadValue();
        defenderTimeout = secs;
        emit DefenderTimeout(secs);
    }

    // ---- chains NeuroJobs takes requests for ----

    function approveChain(bytes32 chain) public onlyGovernance {
        if (chain == bytes32(0)) revert BadValue();
        chainAllowed[chain] = true;
        emit ChainApproved(chain);
    }

    /// Several at once (used at deploy to seed the runner's chain list).
    function approveChains(bytes32[] calldata chains) external onlyGovernance {
        if (chains.length == 0 || chains.length > MAX_CHAINS_PER_CALL) revert BadValue();
        for (uint256 i = 0; i < chains.length; i++) approveChain(chains[i]);
    }

    /// Jobs already requested for it keep running; new requests are refused.
    function removeChain(bytes32 chain) external onlyGovernance {
        if (!chainAllowed[chain]) revert NotApproved();
        chainAllowed[chain] = false;
        emit ChainRemoved(chain);
    }
}

contracts/NeuroIdentity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

/// NeuroJobs' runner record (the only part of NeuroJobs this registry reads).
interface IClaimRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title NeuroIdentity: one contract = one on-chain identity (ERC-8004 Identity Registry)
/// @notice An ERC-8004 ("Trustless Agents") Identity Registry: an ERC-721 whose
///         tokenId is the agentId and whose tokenURI (agentURI) resolves to the
///         agent registration file. On top of the plain ERC-8004 `register()`
///         calls, it gives every analysed contract, on any chain Neuro reads,
///         exactly one agent: "the Neuro of that contract".
///
///         Rules for a contract's identity (registerTarget / claim):
///         - Anyone may register a target. The identity is keyed by the target
///           (CAIP-10 style `namespace:reference:account`), so each target has
///           at most one, and the registry records who registered it.
///         - A new identity is held by this registry itself, so nobody (not the
///           registrant, not the admin) can edit, move or speak for it. Its
///           agentURI is built on-chain and points only at Neuro's report for
///           that target. A squatter therefore gains nothing: registering just
///           makes the Neuro report discoverable.
///         - The target's real owner can take control with proof. For a
///           contract on this chain: a call from the contract itself, or from
///           the address its `owner()` returns. Control follows the contract:
///           whoever can prove it now can claim again, even after a transfer.
///         - A target on another chain is claimed with `claimRemote`: its owner
///           (owner()/getOwner()/EIP-1967 admin on EVM, mint or upgrade
///           authority on Solana, ...) signs a consent off-chain, and at least
///           `claimQuorum` bonded Neuro runners (NeuroJobs: active,
///           agreed >= claimMinAgreed, rejected <= agreed, the bar ThreatRegistry
///           uses) attest with EIP-712 signatures that this key is the target's
///           owner on its chain right now. For an EVM owner the consent itself
///           is also checked here (ecrecover). Trust: the runners' quorum is
///           trusted to have read the owner correctly; for a non-EVM owner
///           (ed25519, ...) it is also trusted to have checked the consent
///           signature. Each claim uses the agent's `claimNonce`, so
///           attestations cannot be replayed.
///         - A remote claim only PROPOSES the takeover. It runs after
///           `claimDelay` (`finalizeClaim`, anyone may call it). Until then the
///           current holder (if the identity is claimed) or any ONE runner that
///           meets the bar can `contestClaim`, which cancels it; the claimant
///           must then gather fresh signatures. One honest runner (or the real
///           holder) is therefore enough to stop a colluding quorum. The price:
///           one rogue runner can also delay an honest claim, which fails safe
///           (the identity stays where it is).
///         - One spelling per target on chain: EVM/Move hex is lowercase, TON
///           friendly addresses (base64url, bounceable or not, testnet flag)
///           are converted to raw `0:hex` / `-1:hex` after their CRC16 check,
///           and a Bitcoin rune loses its spacers (• or .) and must be A-Z.
///         - A claimed identity behaves as a normal ERC-8004 agent (custom
///           agentURI, metadata, agentWallet, transfer). `neuroURI()` and
///           `getTarget()` still show what the identity is about, whatever its
///           owner writes in the agentURI.
///         - Nothing can be transferred to this registry. "Held by the
///           registry" therefore always means "never claimed, agentURI is
///           Neuro's own file": a claimed owner cannot set a custom URI and then
///           hand the token back to pass it off as an unclaimed identity.
contract NeuroIdentity {
    // ---------------------------------------------------------------- types

    struct MetadataEntry {
        string metadataKey;
        bytes metadataValue;
    }

    struct Target {
        string chain;        // Neuro chain key, e.g. "bsc"
        string account;      // canonical address / token id on that chain
        address registeredBy;
        uint64 registeredAt;
    }

    struct Chain {
        string caip2;        // e.g. "eip155:56"
        uint8 rule;          // RULE_*: how strictly the account is checked
        bool exists;
    }

    uint8 public constant RULE_TEXT = 0;      // [A-Za-z0-9._:-] and %XX (uppercase hex)
    uint8 public constant RULE_LOWER = 1;     // [a-z0-9._:-] only (bech32, NEAR, Starknet hex)
    uint8 public constant RULE_EVM = 2;       // 0x + 40 lowercase hex
    uint8 public constant RULE_MOVE = 3;      // 0x + 64 lowercase hex [::module::Name] (Sui, Aptos)
    uint8 public constant RULE_BASE58 = 4;    // 32-44 base58 characters (Solana)
    uint8 public constant RULE_TON = 5;       // stored raw: "0:" / "-1:" + 64 lowercase hex (friendly form converted)
    uint8 public constant RULE_RUNE = 6;      // stored A-Z only, 1-28 letters (spacers removed)

    string public constant name = "Neuro Agent Identity";
    string public constant symbol = "NEURO";
    string public constant REGISTRATION_TYPE = "https://eips.ethereum.org/EIPS/eip-8004#registration-v1";

    // ------------------------------------------------------------- storage

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    /// Last agentId handed out. Ids start at 1, so 0 means "none" (and "broadcast" in Neuro messages).
    uint256 public lastId;
    mapping(uint256 => string) private _uris;
    mapping(uint256 => mapping(string => bytes)) private _metadata;
    mapping(uint256 => Target) private _targets;
    /// keccak256(bytes(caip10)) => agentId
    mapping(bytes32 => uint256) public agentOfTarget;

    mapping(string => Chain) private _chains;
    string[] public chainKeys;
    bytes32 public immutable localCaip2Hash; // keccak256("eip155:<this chain id>")

    address public admin;
    string public webBase;   // Neuro web, e.g. "https://neuro.example/web/"
    string public imageURI;

    /// NeuroJobs (runner records) for claimRemote; zero = remote claims off. Fixed at deploy:
    /// whoever could change it could pick the runners and take any identity.
    IClaimRunners public immutable claimRunners;
    /// Runner attestations a remote claim needs.
    uint256 public immutable claimQuorum;
    /// Accepted verdicts (NeuroJobs `agreed`) a runner needs before it may attest or contest a remote claim.
    uint32 public immutable claimMinAgreed;
    /// Seconds a remote claim waits (contest window) before `finalizeClaim` can run it.
    uint64 public immutable claimDelay;
    struct PendingClaim { address newOwner; uint64 readyAt; }
    /// The remote claim waiting for its contest window to end (readyAt 0 = none).
    mapping(uint256 => PendingClaim) public pendingClaim;
    /// Bumped by every claim (local or remote): attestations and consents name it, so each is used once.
    mapping(uint256 => uint256) public claimNonce;
    /// Spelling rules (NeuroTargets), created by the constructor.
    NeuroTargets public immutable targetFormat;

    // -------------------------------------------------------------- events

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    // ERC-4906
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);
    // ERC-8004
    event Registered(uint256 indexed agentId, string agentURI, address indexed owner);
    event MetadataSet(uint256 indexed agentId, string indexed indexedMetadataKey, string metadataKey, bytes metadataValue);
    event URIUpdated(uint256 indexed agentId, string newURI, address indexed updatedBy);
    // Neuro
    event TargetRegistered(uint256 indexed agentId, bytes32 indexed targetHash, string target, address indexed registeredBy);
    event Claimed(uint256 indexed agentId, address indexed by, address indexed previousOwner);
    event RemoteClaimProposed(uint256 indexed agentId, address indexed newOwner, bytes ownerKey, address[] runners, uint64 readyAt);
    event RemoteClaimContested(uint256 indexed agentId, address indexed by, address indexed newOwner);
    event RemoteClaimFinalized(uint256 indexed agentId, address indexed newOwner);
    event ChainAdded(string key, string caip2, uint8 rule);
    event WebBaseSet(string webBase, string imageURI);
    event AdminSet(address admin);

    error NotAuthorized();
    error Nonexistent();
    error ReservedKey();
    error BadWallet();
    error Expired();
    error DeadlineTooFar();
    error InvalidSignature();
    error UnknownChain();
    error BadAccount();
    error BadValue();
    error ChainExists();
    error AlreadyRegistered(uint256 agentId);
    error NotTarget();
    error NotLocal();
    error NotTargetOwner();
    error AlreadyHolder();
    error UnsafeRecipient();
    error RegistryCustody();
    error RemoteClaimsOff();
    error NotRemote();
    error BadNonce();
    error NotRunner(address signer);
    error Quorum(uint256 have, uint256 need);
    error ClaimPending();
    error NoPendingClaim();
    error ClaimNotReady(uint64 readyAt);
    error ContestClosed();

    bytes32 private constant AGENT_WALLET_SET_TYPEHASH =
        keccak256("AgentWalletSet(uint256 agentId,address newWallet,address owner,uint256 deadline)");
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant NAME_HASH = keccak256("ERC8004IdentityRegistry");
    bytes32 private constant VERSION_HASH = keccak256("1");
    uint256 private constant MAX_DEADLINE_DELAY = 5 minutes;
    /// A remote claim gathers several runners' signatures: allow up to a day.
    uint256 private constant MAX_CLAIM_DELAY = 1 days;
    bytes32 private constant CONSENT_TYPEHASH = keccak256(
        "RemoteClaimConsent(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant ATTEST_TYPEHASH = keccak256(
        "RemoteClaimAttestation(uint256 agentId,address newOwner,string target,bytes ownerKey,uint256 nonce,uint256 deadline)");
    bytes32 private constant KEY_WALLET = keccak256("agentWallet");
    bytes32 private constant KEY_TARGET = keccak256("neuro.target");
    bytes32 private constant KEY_REGISTERED_BY = keccak256("neuro.registeredBy");

    constructor(string memory webBase_, string memory image_, string[] memory keys, string[] memory caip2s, uint8[] memory rules,
        address runners_, uint256 quorum_, uint32 minAgreed_, uint64 claimDelay_) {
        if (keys.length != caip2s.length || keys.length != rules.length) revert BadValue();
        // remote claims on: a quorum, a runner bar and a contest window of 1 hour to 30 days
        if (runners_ != address(0) && (quorum_ == 0 || minAgreed_ == 0 || claimDelay_ < 1 hours || claimDelay_ > 30 days)) revert BadValue();
        claimRunners = IClaimRunners(runners_);
        targetFormat = new NeuroTargets();
        claimQuorum = quorum_;
        claimMinAgreed = minAgreed_;
        claimDelay = claimDelay_;
        admin = msg.sender;
        localCaip2Hash = keccak256(bytes(string.concat("eip155:", _toString(block.chainid))));
        _setWeb(webBase_, image_);
        for (uint256 i; i < keys.length; i++) _addChain(keys[i], caip2s[i], rules[i]);
    }

    // ============================================================ ERC-165

    function supportsInterface(bytes4 id) external pure returns (bool) {
        return id == 0x01ffc9a7    // ERC-165
            || id == 0x80ac58cd    // ERC-721
            || id == 0x5b5e139f    // ERC-721 Metadata
            || id == 0x49064906;   // ERC-4906 (metadata update events)
    }

    // ============================================================ ERC-721

    function balanceOf(address owner) external view returns (uint256) {
        if (owner == address(0)) revert BadValue();
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address o) {
        o = _owners[tokenId];
        if (o == address(0)) revert Nonexistent();
    }

    function approve(address to, uint256 tokenId) external {
        address o = ownerOf(tokenId);
        if (msg.sender != o && !_operatorApprovals[o][msg.sender]) revert NotAuthorized();
        _tokenApprovals[tokenId] = to;
        emit Approval(o, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        ownerOf(tokenId);
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external {
        if (operator == address(0)) revert BadValue();
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        address o = ownerOf(tokenId);
        if (o != from) revert NotAuthorized();
        if (!_isAuthorized(o, msg.sender, tokenId)) revert NotAuthorized();
        if (to == address(0)) revert BadValue();
        // Custody is only for never-claimed identities (see the contract notes).
        if (to == address(this)) revert RegistryCustody();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    /// agentURI. A custom URI set by a claimed owner wins; otherwise a Neuro
    /// identity resolves to its on-chain registration file (`neuroURI`).
    function tokenURI(uint256 agentId) external view returns (string memory) {
        ownerOf(agentId);
        if (bytes(_uris[agentId]).length > 0) return _uris[agentId];
        if (bytes(_targets[agentId].chain).length > 0) return neuroURI(agentId);
        return "";
    }

    function _isAuthorized(address owner, address spender, uint256 tokenId) internal view returns (bool) {
        return spender != address(0)
            && (spender == owner || _operatorApprovals[owner][spender] || _tokenApprovals[tokenId] == spender);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        delete _tokenApprovals[tokenId];
        // ERC-8004: the verified agentWallet does not follow the token to a new owner.
        if (_metadata[tokenId]["agentWallet"].length > 0) {
            delete _metadata[tokenId]["agentWallet"];
            emit MetadataSet(tokenId, "agentWallet", "agentWallet", "");
        }
        unchecked {
            _balances[from] -= 1;
            _balances[to] += 1;
        }
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function _mint(address to, uint256 tokenId) internal {
        unchecked { _balances[to] += 1; }
        _owners[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
    }

    // ===================================================== ERC-8004 identity

    function register() external returns (uint256 agentId) {
        agentId = _registerPlain("");
    }

    function register(string calldata agentURI) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
    }

    function register(string calldata agentURI, MetadataEntry[] calldata metadata) external returns (uint256 agentId) {
        agentId = _registerPlain(agentURI);
        for (uint256 i; i < metadata.length; i++) {
            _requireFreeKey(metadata[i].metadataKey);
            _metadata[agentId][metadata[i].metadataKey] = metadata[i].metadataValue;
            emit MetadataSet(agentId, metadata[i].metadataKey, metadata[i].metadataKey, metadata[i].metadataValue);
        }
    }

    function _registerPlain(string memory agentURI) internal returns (uint256 agentId) {
        agentId = ++lastId;
        _metadata[agentId]["agentWallet"] = abi.encodePacked(msg.sender);
        _mint(msg.sender, agentId);
        if (bytes(agentURI).length > 0) _uris[agentId] = agentURI;
        emit Registered(agentId, agentURI, msg.sender);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(msg.sender));
        if (msg.sender.code.length > 0) {
            // _safeMint semantics: a contract registrant must accept ERC-721 tokens.
            try IERC721Receiver(msg.sender).onERC721Received(msg.sender, address(0), agentId, "") returns (bytes4 r) {
                if (r != IERC721Receiver.onERC721Received.selector) revert UnsafeRecipient();
            } catch {
                revert UnsafeRecipient();
            }
        }
    }

    function setAgentURI(uint256 agentId, string calldata newURI) external {
        _onlyAuthorized(agentId);
        _uris[agentId] = newURI;
        emit URIUpdated(agentId, newURI, msg.sender);
        emit MetadataUpdate(agentId);
    }

    function getMetadata(uint256 agentId, string memory metadataKey) external view returns (bytes memory) {
        bytes32 k = keccak256(bytes(metadataKey));
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length > 0) {
            if (k == KEY_TARGET) return bytes(_caip10(t));
            if (k == KEY_REGISTERED_BY) return abi.encodePacked(t.registeredBy);
        }
        return _metadata[agentId][metadataKey];
    }

    function setMetadata(uint256 agentId, string memory metadataKey, bytes memory metadataValue) external {
        _onlyAuthorized(agentId);
        _requireFreeKey(metadataKey);
        _metadata[agentId][metadataKey] = metadataValue;
        emit MetadataSet(agentId, metadataKey, metadataKey, metadataValue);
    }

    function getAgentWallet(uint256 agentId) external view returns (address) {
        bytes memory w = _metadata[agentId]["agentWallet"];
        if (w.length < 20) return address(0);
        return address(bytes20(w));
    }

    function setAgentWallet(uint256 agentId, address newWallet, uint256 deadline, bytes calldata signature) external {
        address owner = _onlyAuthorized(agentId);
        if (newWallet == address(0)) revert BadWallet();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_DEADLINE_DELAY) revert DeadlineTooFar();
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(AGENT_WALLET_SET_TYPEHASH, agentId, newWallet, owner, deadline))));
        if (_recover(digest, signature) != newWallet) {
            (bool ok, bytes memory res) = newWallet.staticcall(abi.encodeWithSelector(0x1626ba7e, digest, signature));
            if (!(ok && res.length >= 32 && bytes4(abi.decode(res, (bytes32))) == 0x1626ba7e)) revert InvalidSignature();
        }
        _metadata[agentId]["agentWallet"] = abi.encodePacked(newWallet);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(newWallet));
    }

    function unsetAgentWallet(uint256 agentId) external {
        _onlyAuthorized(agentId);
        delete _metadata[agentId]["agentWallet"];
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
    }

    /// As in the ERC-8004 reference implementation.
    function isAuthorizedOrOwner(address spender, uint256 agentId) external view returns (bool) {
        return _isAuthorized(ownerOf(agentId), spender, agentId);
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this)));
    }

    function getVersion() external pure returns (string memory) {
        return "neuro-1 (ERC-8004 identity v2.0.0 interface)";
    }

    function _onlyAuthorized(uint256 agentId) internal view returns (address owner) {
        owner = ownerOf(agentId);
        if (!_isAuthorized(owner, msg.sender, agentId)) revert NotAuthorized();
    }

    function _requireFreeKey(string memory key) internal pure {
        bytes32 k = keccak256(bytes(key));
        if (k == KEY_WALLET || k == KEY_TARGET || k == KEY_REGISTERED_BY) revert ReservedKey();
    }

    function _recover(bytes32 digest, bytes calldata sig) internal pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        if (v != 27 && v != 28) return address(0);
        return ecrecover(digest, v, r, s);
    }

    // ===================================================== Neuro: 1 contract = 1 identity

    /// Registers the Neuro of `account` on Neuro chain `chain` (e.g. "bsc").
    /// Anyone may call it; the identity stays held by this registry until the
    /// target's owner claims it. Reverts AlreadyRegistered(id) if it exists.
    function registerTarget(string calldata chain, string calldata typed) external returns (uint256 agentId) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        string memory account = _canonical(bytes(typed), c.rule);
        string memory caip10 = string.concat(c.caip2, ":", account);
        bytes32 h = keccak256(bytes(caip10));
        if (agentOfTarget[h] != 0) revert AlreadyRegistered(agentOfTarget[h]);
        agentId = ++lastId;
        agentOfTarget[h] = agentId;
        _targets[agentId] = Target(chain, account, msg.sender, uint64(block.timestamp));
        _mint(address(this), agentId);
        emit Registered(agentId, neuroURI(agentId), address(this));
        emit MetadataSet(agentId, "agentWallet", "agentWallet", "");
        emit TargetRegistered(agentId, h, caip10, msg.sender);
    }

    /// Takes control of a ZETAPHY contract's identity: callable by the target
    /// contract itself or by the address its `owner()` returns right now.
    function claim(uint256 agentId) external {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        if (keccak256(bytes(_chains[t.chain].caip2)) != localCaip2Hash) revert NotLocal();
        address target = _parseAddress(bytes(t.account));
        bool ok = msg.sender == target;
        if (!ok && target.code.length > 0) {
            (bool s, bytes memory r) = target.staticcall(abi.encodeWithSignature("owner()"));
            ok = s && r.length >= 32 && abi.decode(r, (uint256)) == uint256(uint160(msg.sender));
        }
        if (!ok) revert NotTargetOwner();
        _takeOver(agentId, msg.sender);
    }

    /// PROPOSES that `newOwner` takes control of the identity of a target on
    /// ANOTHER chain. Anyone may submit it; the signatures decide. The takeover
    /// runs with `finalizeClaim` after `claimDelay`, unless contested first.
    /// @param ownerKey   the target's owner/authority on its chain, as bytes
    ///                   (20-byte address on EVM, 32-byte ed25519 key on Solana, ...)
    /// @param ownerSig   for an EVM target: the owner's EIP-712 RemoteClaimConsent
    ///                   signature, checked here. Otherwise ignored (the runners checked it).
    /// @param attestations 65-byte EIP-712 RemoteClaimAttestation signatures by
    ///                   distinct runners, sorted by signer address (ascending).
    function claimRemote(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline,
        bytes calldata ownerSig, bytes[] calldata attestations) external {
        if (address(claimRunners) == address(0)) revert RemoteClaimsOff();
        if (pendingClaim[agentId].readyAt != 0) revert ClaimPending();
        (bytes memory fields, bool evmOwner) = _claimFields(agentId, newOwner, ownerKey, deadline);
        // An EVM owner proves its consent here, so the runners cannot move the
        // identity for a real owner who never asked.
        if (evmOwner && (ownerKey.length != 20 || _recover(_typed(CONSENT_TYPEHASH, fields), ownerSig) != address(bytes20(ownerKey)))) {
            revert InvalidSignature();
        }
        address[] memory runners = _runnerQuorum(_typed(ATTEST_TYPEHASH, fields), attestations);
        if (_owners[agentId] == newOwner) revert AlreadyHolder();
        claimNonce[agentId]++; // these signatures are spent, whether the claim runs or is contested
        uint64 readyAt = uint64(block.timestamp) + claimDelay;
        pendingClaim[agentId] = PendingClaim(newOwner, readyAt);
        emit RemoteClaimProposed(agentId, newOwner, ownerKey, runners, readyAt);
    }

    /// Runs a remote claim whose contest window has passed. Anyone may call it.
    function finalizeClaim(uint256 agentId) external {
        PendingClaim memory p = pendingClaim[agentId];
        if (p.readyAt == 0) revert NoPendingClaim();
        if (block.timestamp < p.readyAt) revert ClaimNotReady(p.readyAt);
        delete pendingClaim[agentId];
        emit RemoteClaimFinalized(agentId, p.newOwner);
        if (_owners[agentId] != p.newOwner) _takeOver(agentId, p.newOwner);
    }

    /// Cancels a pending remote claim during its window. Callable by the
    /// current holder (owner/operator of a claimed identity) or by any one
    /// runner that meets the attestation bar.
    function contestClaim(uint256 agentId) external {
        PendingClaim memory p = pendingClaim[agentId];
        if (p.readyAt == 0) revert NoPendingClaim();
        if (block.timestamp >= p.readyAt) revert ContestClosed();
        address holder = _owners[agentId];
        if (!(holder != address(this) && _isAuthorized(holder, msg.sender, agentId)) && !_goodRunner(msg.sender)) revert NotAuthorized();
        delete pendingClaim[agentId];
        emit RemoteClaimContested(agentId, msg.sender, p.newOwner);
    }

    /// A runner in good standing: active, agreed >= claimMinAgreed, rejected <= agreed.
    function _goodRunner(address r) internal view returns (bool) {
        if (address(claimRunners) == address(0)) return false;
        (, , bool active, uint32 agreed, uint32 rejected) = claimRunners.workers(r);
        return active && agreed >= claimMinAgreed && rejected <= agreed;
    }

    /// The signed fields of a remote claim (EIP-712: string and bytes members
    /// hashed, static words after the typehash), and whether the target is EVM.
    function _claimFields(uint256 agentId, address newOwner, bytes calldata ownerKey, uint256 deadline)
        internal view returns (bytes memory, bool)
    {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        Chain storage c = _chains[t.chain];
        if (keccak256(bytes(c.caip2)) == localCaip2Hash) revert NotRemote();
        if (newOwner == address(0) || newOwner == address(this) || ownerKey.length == 0 || ownerKey.length > 64) revert BadValue();
        if (block.timestamp > deadline) revert Expired();
        if (deadline > block.timestamp + MAX_CLAIM_DELAY) revert DeadlineTooFar();
        return (abi.encode(agentId, newOwner, keccak256(bytes(_caip10(t))), keccak256(ownerKey), claimNonce[agentId], deadline), c.rule == RULE_EVM);
    }

    /// Signers of `digest`: distinct, ascending, each a runner in good standing, at least claimQuorum of them.
    function _runnerQuorum(bytes32 digest, bytes[] calldata sigs) internal view returns (address[] memory signers) {
        if (sigs.length < claimQuorum) revert Quorum(sigs.length, claimQuorum);
        signers = new address[](sigs.length);
        address last;
        for (uint256 i; i < sigs.length; i++) {
            address r = _recover(digest, sigs[i]);
            if (r <= last) revert InvalidSignature(); // zero, unsorted or repeated
            if (!_goodRunner(r)) revert NotRunner(r);
            signers[i] = last = r;
        }
    }

    function _typed(bytes32 typehash, bytes memory fields) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), keccak256(abi.encodePacked(typehash, fields))));
    }

    function _takeOver(uint256 agentId, address to) internal {
        address prev = _owners[agentId];
        if (prev == to) revert AlreadyHolder();
        claimNonce[agentId]++;
        _transfer(prev, to, agentId);
        _metadata[agentId]["agentWallet"] = abi.encodePacked(to);
        emit MetadataSet(agentId, "agentWallet", "agentWallet", abi.encodePacked(to));
        emit Claimed(agentId, to, prev);
        emit MetadataUpdate(agentId);
    }

    /// agentId of a target, 0 if none (or if the chain is unknown). Any accepted
    /// spelling works (e.g. a TON friendly address, a rune with spacers).
    function agentIdOf(string calldata chain, string calldata account) external view returns (uint256) {
        Chain storage c = _chains[chain];
        if (!c.exists) return 0;
        (bool ok, string memory a) = targetFormat.canonical(bytes(account), c.rule);
        if (!ok) return 0;
        return agentOfTarget[keccak256(bytes(string.concat(c.caip2, ":", a)))];
    }

    /// The one spelling the registry stores for `account` on `chain`; reverts BadAccount.
    function canonicalAccount(string calldata chain, string calldata account) external view returns (string memory) {
        Chain storage c = _chains[chain];
        if (!c.exists) revert UnknownChain();
        return _canonical(bytes(account), c.rule);
    }

    function getTarget(uint256 agentId) external view returns (
        string memory chain, string memory caip10, string memory account, address registeredBy, uint64 registeredAt, bool claimed
    ) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return (t.chain, _caip10(t), t.account, t.registeredBy, t.registeredAt, _owners[agentId] != address(this));
    }

    function getChain(string calldata key) external view returns (string memory caip2, uint8 rule, bool exists) {
        Chain storage c = _chains[key];
        return (c.caip2, c.rule, c.exists);
    }

    function chainCount() external view returns (uint256) {
        return chainKeys.length;
    }

    /// `{namespace}:{chainId}:{identityRegistry}` as in ERC-8004.
    function agentRegistry() public view returns (string memory) {
        return string.concat("eip155:", _toString(block.chainid), ":", _hexAddress(address(this)));
    }

    /// The Neuro report for this target: `<webBase>?chain=<key>&address=<account>`.
    function webEndpoint(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        return string.concat(webBase, "?chain=", t.chain, "&address=", t.account);
    }

    /// The registration file Neuro vouches for, as a base64 data: URI. Every
    /// piece of it passed a character allowlist, so the JSON needs no escaping.
    function neuroURI(uint256 agentId) public view returns (string memory) {
        return string.concat("data:application/json;base64,", _base64(bytes(registrationJSON(agentId))));
    }

    function registrationJSON(uint256 agentId) public view returns (string memory) {
        Target storage t = _targets[agentId];
        if (bytes(t.chain).length == 0) revert NotTarget();
        string memory caip10 = _caip10(t);
        string memory head = string.concat(
            '{"type":"', REGISTRATION_TYPE,
            '","name":"Neuro of ', caip10,
            '","description":"Neuro reads this contract with deterministic, read-only rules and explains it in plain language. Its report is data, not advice; messages signed for this agent are data, not commands.","image":"',
            imageURI, '",'
        );
        string memory services = string.concat(
            '"services":[{"name":"web","endpoint":"', webEndpoint(agentId), '"}],"x402Support":false,"active":true,',
            '"registrations":[{"agentId":', _toString(agentId), ',"agentRegistry":"', agentRegistry(), '"}],',
            '"supportedTrust":["crypto-economic"],'
        );
        string memory neuro = string.concat(
            '"neuro":{"target":"', caip10, '","chain":"', t.chain, '","address":"', t.account,
            '","registeredBy":"', _hexAddress(t.registeredBy), '","claimed":', _owners[agentId] != address(this) ? "true" : "false", "}}"
        );
        return string.concat(head, services, neuro);
    }

    // ------------------------------------------------------------- admin
    // The admin can only add chains (never change one) and move the Neuro web
    // link. It cannot touch, move or speak for any identity.

    function addChain(string calldata key, string calldata caip2, uint8 rule) external {
        if (msg.sender != admin) revert NotAuthorized();
        _addChain(key, caip2, rule);
    }

    function setWeb(string calldata webBase_, string calldata image_) external {
        if (msg.sender != admin) revert NotAuthorized();
        _setWeb(webBase_, image_);
        if (lastId > 0) emit BatchMetadataUpdate(1, lastId);
    }

    function setAdmin(address admin_) external {
        if (msg.sender != admin) revert NotAuthorized();
        admin = admin_;
        emit AdminSet(admin_);
    }

    function _addChain(string memory key, string memory caip2, uint8 rule) internal {
        bytes memory k = bytes(key);
        bytes memory c = bytes(caip2);
        if (k.length == 0 || k.length > 32 || c.length < 5 || c.length > 41 || rule > RULE_RUNE) revert BadValue();
        for (uint256 i; i < k.length; i++) {
            bytes1 b = k[i];
            if (!((b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "-")) revert BadValue();
        }
        uint256 colons;
        for (uint256 i; i < c.length; i++) {
            bytes1 b = c[i];
            if (b == ":") { colons++; continue; }
            if (!_alnum(b) && b != "-" && b != "_") revert BadValue();
        }
        if (colons != 1) revert BadValue();
        if (_chains[key].exists) revert ChainExists();
        _chains[key] = Chain(caip2, rule, true);
        chainKeys.push(key);
        emit ChainAdded(key, caip2, rule);
    }

    function _setWeb(string memory webBase_, string memory image_) internal {
        if (bytes(webBase_).length == 0) revert BadValue();
        _checkUrl(bytes(webBase_));
        _checkUrl(bytes(image_));
        webBase = webBase_;
        imageURI = image_;
        emit WebBaseSet(webBase_, image_);
    }

    // ------------------------------------------------------------- helpers

    /// Printable ASCII without quotes, backslash, angle brackets or spaces, at most 200 bytes.
    function _checkUrl(bytes memory u) internal pure {
        if (u.length > 200) revert BadValue();
        for (uint256 i; i < u.length; i++) {
            bytes1 b = u[i];
            if (b <= 0x20 || b >= 0x7f || b == '"' || b == "\\" || b == "<" || b == ">" || b == "`") revert BadValue();
        }
    }

    function _canonical(bytes memory a, uint8 rule) internal view returns (string memory) {
        (bool ok, string memory out) = targetFormat.canonical(a, rule);
        if (!ok) revert BadAccount();
        return out;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    /// Hex digit value, or 255. `upper` picks which letter case is accepted.
    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }

    function _parseAddress(bytes memory a) internal pure returns (address) {
        uint160 v;
        for (uint256 i = 2; i < 42; i++) v = v * 16 + _hexVal(a[i], false);
        return address(v);
    }

    function _caip10(Target storage t) internal view returns (string memory) {
        return string.concat(_chains[t.chain].caip2, ":", t.account);
    }

    function _toString(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 x = v; x != 0; x /= 10) len++;
        bytes memory out = new bytes(len);
        while (v != 0) { out[--len] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(out);
    }

    function _hexAddress(address a) internal pure returns (string memory) {
        bytes memory out = new bytes(42);
        out[0] = "0";
        out[1] = "x";
        bytes16 digits = "0123456789abcdef";
        uint160 v = uint160(a);
        for (uint256 i = 41; i > 1; i--) { out[i] = digits[v & 15]; v >>= 4; }
        return string(out);
    }

    function _base64(bytes memory data) internal pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 n = data.length;
        if (n == 0) return "";
        bytes memory out = new bytes(4 * ((n + 2) / 3));
        uint256 j;
        for (uint256 i; i < n; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < n ? uint8(data[i + 1]) : 0;
            uint256 c = i + 2 < n ? uint8(data[i + 2]) : 0;
            uint256 triple = (a << 16) | (b << 8) | c;
            out[j++] = table[(triple >> 18) & 63];
            out[j++] = table[(triple >> 12) & 63];
            out[j++] = i + 1 < n ? table[(triple >> 6) & 63] : bytes1("=");
            out[j++] = i + 2 < n ? table[triple & 63] : bytes1("=");
        }
        return string(out);
    }
}

/// @title NeuroTargets: the one spelling of a target account (NeuroIdentity's helper)
/// @notice Pure functions, split out so NeuroIdentity stays under the 24,576-byte
///         code limit. NeuroIdentity creates its own copy in its constructor.
contract NeuroTargets {
    uint8 internal constant RULE_TEXT = 0;
    uint8 internal constant RULE_LOWER = 1;
    uint8 internal constant RULE_EVM = 2;
    uint8 internal constant RULE_MOVE = 3;
    uint8 internal constant RULE_BASE58 = 4;
    uint8 internal constant RULE_TON = 5;
    uint8 internal constant RULE_RUNE = 6;

    /// (true, the one spelling) or (false, "") if `a` is not an account of that rule.
    function canonical(bytes memory a, uint8 rule) external pure returns (bool, string memory) {
        if (rule == RULE_TON) return _tonRaw(a);
        if (rule == RULE_RUNE) return _runeName(a);
        if (a.length > 128 || !_accountOk(a, rule)) return (false, "");
        return (true, string(a));
    }

    /// TON: raw `0:` / `-1:` + 64 hex (either case, stored lowercase), or the
    /// 48-character friendly form (base64 or base64url; bounceable 0x11 or
    /// non-bounceable 0x51, optionally | 0x80 testnet) with a valid CRC16.
    function _tonRaw(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(67);
        uint256 n;
        bytes memory hash;
        if (a.length == 48) {
            bytes memory d = new bytes(36);
            for (uint256 i; i < 48; i += 4) {
                uint256 w;
                for (uint256 j; j < 4; j++) {
                    uint8 v = _b64(a[i + j]);
                    if (v > 63) return (false, "");
                    w = (w << 6) | v;
                }
                uint256 k = (i / 4) * 3;
                d[k] = bytes1(uint8(w >> 16));
                d[k + 1] = bytes1(uint8(w >> 8));
                d[k + 2] = bytes1(uint8(w));
            }
            uint8 tag = uint8(d[0]) & 0x7f; // 0x80 = testnet only
            if (tag != 0x11 && tag != 0x51) return (false, "");
            uint256 crc;
            for (uint256 i; i < 34; i++) {
                crc ^= uint256(uint8(d[i])) << 8;
                for (uint256 b; b < 8; b++) crc = crc & 0x8000 != 0 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
            }
            if (crc != (uint256(uint8(d[34])) << 8 | uint8(d[35]))) return (false, "");
            if (d[1] == 0x00) { out[0] = "0"; n = 1; }
            else if (d[1] == 0xff) { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) hash[i] = d[i + 2];
        } else {
            if (a.length == 66 && a[0] == "0" && a[1] == ":") { out[0] = "0"; n = 1; }
            else if (a.length == 67 && a[0] == "-" && a[1] == "1" && a[2] == ":") { out[0] = "-"; out[1] = "1"; n = 2; }
            else return (false, "");
            hash = new bytes(32);
            for (uint256 i; i < 32; i++) {
                uint8 hi = _hexAny(a[n + 1 + 2 * i]);
                uint8 lo = _hexAny(a[n + 2 + 2 * i]);
                if (hi > 15 || lo > 15) return (false, "");
                hash[i] = bytes1(hi * 16 + lo);
            }
        }
        out[n] = ":";
        bytes16 digits = "0123456789abcdef";
        for (uint256 i; i < 32; i++) {
            out[n + 1 + 2 * i] = digits[uint8(hash[i]) >> 4];
            out[n + 2 + 2 * i] = digits[uint8(hash[i]) & 15];
        }
        assembly { mstore(out, add(n, 65)) }
        return (true, string(out));
    }

    /// Rune name: spacers (U+2022 "•" as UTF-8 or %E2%80%A2, and ".") are
    /// dropped; what is left must be 1-28 letters A-Z.
    function _runeName(bytes memory a) internal pure returns (bool, string memory) {
        bytes memory out = new bytes(a.length);
        uint256 n;
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (b >= "A" && b <= "Z") { out[n++] = b; continue; }
            if (b == ".") continue;
            if (b == 0xe2 && i + 2 < a.length && a[i + 1] == 0x80 && a[i + 2] == 0xa2) { i += 2; continue; }
            if (b == "%" && i + 8 < a.length && keccak256(abi.encodePacked(a[i + 1], a[i + 2], a[i + 3], a[i + 4], a[i + 5], a[i + 6], a[i + 7], a[i + 8]))
                == keccak256("E2%80%A2")) { i += 8; continue; }
            return (false, "");
        }
        if (n == 0 || n > 28) return (false, "");
        assembly { mstore(out, n) }
        return (true, string(out));
    }

    function _b64(bytes1 c) internal pure returns (uint8) {
        if (c >= "A" && c <= "Z") return uint8(c) - 65;
        if (c >= "a" && c <= "z") return uint8(c) - 71;
        if (c >= "0" && c <= "9") return uint8(c) + 4;
        if (c == "-" || c == "+") return 62;
        if (c == "_" || c == "/") return 63;
        return 255;
    }

    function _hexAny(bytes1 b) internal pure returns (uint8) {
        uint8 v = _hexVal(b, false);
        return v < 16 ? v : _hexVal(b, true);
    }

    /// The account checks of the other rules: the input must already be the one spelling.
    function _accountOk(bytes memory a, uint8 rule) internal pure returns (bool) {
        if (a.length == 0 || a.length > 128) return false;
        if (rule == RULE_EVM) {
            if (a.length != 42 || a[0] != "0" || a[1] != "x") return false;
            for (uint256 i = 2; i < 42; i++) if (_hexVal(a[i], false) > 15) return false;
            return true;
        }
        if (rule == RULE_MOVE) return _moveOk(a);
        if (rule == RULE_BASE58) {
            if (a.length < 32 || a.length > 44) return false;
            for (uint256 i; i < a.length; i++) {
                bytes1 b = a[i];
                if (!_alnum(b) || b == "0" || b == "O" || b == "I" || b == "l") return false;
            }
            return true;
        }
        for (uint256 i; i < a.length; i++) {
            bytes1 b = a[i];
            if (_safeLower(b)) continue;
            if (rule == RULE_TEXT) {
                if (b >= "A" && b <= "Z") continue;
                // %XX with uppercase hex, the one canonical spelling of an escaped byte;
                // a byte that needs no escape (e.g. %41 for "A") is a second spelling, so refused
                if (b == "%" && i + 2 < a.length && _hexVal(a[i + 1], true) < 16 && _hexVal(a[i + 2], true) < 16) {
                    bytes1 d = bytes1(_hexVal(a[i + 1], true) * 16 + _hexVal(a[i + 2], true));
                    if (_safeLower(d) || (d >= "A" && d <= "Z")) return false;
                    i += 2;
                    continue;
                }
            }
            return false;
        }
        return true;
    }

    /// Move: "0x" + 64 lowercase hex (the padded address), optionally followed
    /// by "::module::Name" with identifiers [A-Za-z_][A-Za-z0-9_]*.
    function _moveOk(bytes memory a) internal pure returns (bool) {
        if (a.length < 66 || a[0] != "0" || a[1] != "x") return false;
        for (uint256 j = 2; j < 66; j++) if (_hexVal(a[j], false) > 15) return false;
        if (a.length == 66) return true;
        uint256 i = 66;
        for (uint256 part; part < 2; part++) {
            if (i + 2 >= a.length || a[i] != ":" || a[i + 1] != ":") return false;
            i += 2;
            bytes1 f = a[i];
            if (!((f >= "a" && f <= "z") || (f >= "A" && f <= "Z") || f == "_")) return false;
            while (i < a.length && a[i] != ":") {
                if (!_alnum(a[i]) && a[i] != "_") return false;
                i++;
            }
        }
        return i == a.length;
    }

    function _safeLower(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "0" && b <= "9") || b == "." || b == "_" || b == ":" || b == "-";
    }

    function _hexVal(bytes1 b, bool upper) internal pure returns (uint8) {
        if (b >= "0" && b <= "9") return uint8(b) - 48;
        if (!upper && b >= "a" && b <= "f") return uint8(b) - 87;
        if (upper && b >= "A" && b <= "F") return uint8(b) - 55;
        return 255;
    }

    function _alnum(bytes1 b) internal pure returns (bool) {
        return (b >= "a" && b <= "z") || (b >= "A" && b <= "Z") || (b >= "0" && b <= "9");
    }
}

contracts/NeuroJobs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// What NeuroJobs reads from NeuroControl (contracts/NeuroControl.sol).
interface INeuroKnobs {
    function paused() external view returns (bool);
    function activeSkill() external view returns (bytes32);
    function defenderApproved(address) external view returns (bool);
    function roster() external view returns (address[] memory);
    function releasedAt(address) external view returns (uint64);
    function maxBodies() external view returns (uint256);
    function maxRegrowPerHour() external view returns (uint256);
    function communityFund() external view returns (address);
    function chainAllowed(bytes32) external view returns (bool);
    function challengeBond() external view returns (uint256);
    function challengeWindow() external view returns (uint256);
    function defenderTimeout() external view returns (uint256);
}

/// @title NeuroJobsBase: storage, rules and helpers shared by NeuroJobs and
///        its challenge logic (NeuroJobsChallenges, reached by delegatecall,
///        so both see the same storage). See NeuroJobs for the rules.
abstract contract NeuroJobsBase {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    /// Share of the bond a runner loses for a verdict the quorum rejected,
    /// or for committing and then never revealing (basis points).
    uint16 public constant PENALTY_BPS = 1000;
    /// Fee split (basis points of the fee); the runners get the rest (90%).
    uint16 public constant BURN_BPS = 500;
    uint16 public constant COMMUNITY_BPS = 500;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    /// Defender seats; also the fewest bodies there ever are.
    uint8 public constant DEFENDERS = 4;
    /// Requests per minute one body is expected to handle.
    uint256 public constant CAPACITY_PER_BODY = 6;
    /// Minutes for the extra bodies to fade out after the last busy minute.
    uint256 public constant DECAY_MINUTES = 30;
    /// Strikes within the last STRIKE_WINDOW judged seats that put a runner in quarantine (K).
    uint8 public constant QUARANTINE_AFTER = 2;
    uint8 public constant STRIKE_WINDOW = 5;
    /// Share of a failed or expired job's fee that is burned instead of refunded.
    uint16 public constant FAIL_BURN_BPS = 500;
    /// Longest target: a Move coin type (66-char address + two 128-char names + separators).
    uint256 public constant MAX_TARGET = 330;
    /// Share of its bond a round-1 runner loses when a challenge overturns its verdict.
    uint16 public constant CHALLENGE_SLASH_BPS = 5000;
    /// The challenge bond is at least this many times the job fee.
    uint256 public constant CHALLENGE_FEE_MULTIPLE = 2;
    /// Challenge rounds per job (after a Disputed one a new one may open): 3 rounds in all.
    uint8 public constant MAX_CHALLENGES = 2;
    /// Share of the challenger's bond kept when a challenge round finds no quorum.
    uint16 public constant DISPUTE_KEEP_BPS = 2000;

    uint256 public immutable workerBond;
    uint256 public immutable jobReward;
    uint256 public immutable minFee;
    uint64 public immutable commitWindow;
    uint64 public immutable jobTimeout;
    uint64 public immutable unbondDelay;
    uint256 public immutable dailyRewardCap;
    /// May call setControl() once.
    address public immutable deployer;

    enum Status { None, Open, Done, Failed }
    enum ChallengeState { None, Open, Confirmed, Overturned, Disputed }

    struct Worker {
        uint128 bond;
        uint64 unbondAt; // 0 while active
        bool active;
        uint32 agreed;
        uint32 rejected;
        uint64 since;    // when it last became active; only later jobs count
        uint8 recent;    // last STRIKE_WINDOW judged seats, newest in bit 0; 1 = strike
        uint64 quarantinedAt; // 0 = never; see quarantined()
        uint64 lastSeen;  // last register, heartbeat, commit or reveal
        uint64 heldUntil; // bond stays until nothing it sat on can still slash it
    }

    /// One round of 3 seats (round 1 = the job, rounds 2.. = challenges).
    struct Round {
        uint8 commits;
        uint8 reveals;
        uint8 defenders;   // seats taken as a defender
        uint64 start;      // the commit window starts here
        uint64 startBlock; // the lottery uses blockhash(startBlock + 1)
        bytes32 rand;      // the stored lottery; 0 until stored (see _rand)
        uint256 total;     // totalActiveBond when the round opened (the lottery's denominator)
        address[3] seat;
        bytes32[3] commitOf;
        bytes32[3] verdictOf;
        bool[3] revealed;
    }

    struct Job {
        address requester;
        Status status;
        uint8 agreedBy;  // distinct runners that revealed the final verdict
        uint8 chN;       // challenges opened on it (at most MAX_CHALLENGES)
        uint16 bodies;   // bodies when requested
        uint16 drawn;    // of which drawn by lottery (bodies minus seated defenders)
        uint64 settleAt; // quorum reached with seats unrevealed: grace ends here (0 = nothing pending)
        uint64 challengeUntil; // set when the quorum forms (moved after a Disputed challenge)
        bytes32 chain;
        uint256 fee;
        bytes32 result;
        bytes32 seed;
        bytes32 skill;   // NeuroControl.activeSkill() at request time
        string target;
        Round r;
    }

    struct Challenge {
        address challenger;
        ChallengeState state;
        uint64 settleAt;
        uint256 bond;
        bytes32 claim;   // the verdict the challenger says is right
        bytes32 result;
        Round r;
    }

    uint256 public rewardPool;
    uint256 public activeWorkers;
    uint256 public totalActiveBond;
    uint64 public rewardDay;
    uint256 public rewardedToday;
    mapping(address => uint256) public requestCount;
    mapping(address => Worker) public workers;
    mapping(address => uint256) public credit;
    /// Seats a runner committed to and that are not resolved yet (revealed, or missed: penalised by
    /// expire / settle / challengeExpire). withdrawBond needs 0, so a runner that never reveals cannot
    /// take its bond out before its penalty lands, whoever calls expire/settle and whenever (NJ-1).
    mapping(address => uint256) public openSeats;
    Job[] internal jobs;
    /// challenges[id][k]: the k-th challenge (0-based) of job id.
    mapping(uint256 => mapping(uint256 => Challenge)) internal challenges;
    /// Ids of challenged jobs, once per challenge, in order (runners scan it for seats).
    uint256[] public challenged;

    INeuroKnobs public control;
    address[4] public defender;
    uint64 public regrowHour;
    uint256 public regrownThisHour;
    uint256 public totalBurned;
    // Load meter: requests in the latest minute that had any, and the
    // busiest earlier minute still fading (see bodies()).
    uint64 public loadMinute;
    uint64 public loadCount;
    uint64 public peakMinute;
    uint64 public peakCount;

    event Funded(address indexed from, uint256 amount);
    event Registered(address indexed worker, uint256 bond);
    event UnbondRequested(address indexed worker, uint64 at);
    event JobRequested(uint256 indexed id, bytes32 indexed chain, string target, uint256 fee);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event Finalized(uint256 indexed id, bytes32 verdict);
    event JobFailed(uint256 indexed id);
    event Penalized(address indexed worker, uint256 amount);
    event ControlSet(address control);
    event JobSized(uint256 indexed id, bytes32 indexed skill, uint256 bodies, uint256 drawn);
    event FeeSplit(uint256 indexed id, uint256 runners, uint256 burned, uint256 community);
    event Quarantined(address indexed worker);
    event DefenderSeated(address indexed worker, uint256 seat);
    event DefenderVacated(address indexed worker, uint256 seat);
    event Missed(uint256 indexed id, address indexed worker);
    event Settled(uint256 indexed id);
    event Drawn(uint256 indexed id, uint8 round, bytes32 rand);
    /// The lottery block's hash fell out of the 256-block window before anyone used it: the round takes a new block.
    event Redrawn(uint256 indexed id, uint8 round, uint64 startBlock);
    event Challenged(uint256 indexed id, address indexed challenger, uint256 bond);
    event ChallengeClaim(uint256 indexed id, uint8 round, bytes32 claim);
    event ChallengeCommitted(uint256 indexed id, address indexed worker);
    event ChallengeRevealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event ChallengeResolved(uint256 indexed id, ChallengeState state, bytes32 verdict);

    error BadValue();
    error BadJob();
    error NotWorker();
    error Closed();
    error AlreadyIn();
    error NoSeat();
    error TooEarly();
    error BadReveal();
    error Nothing();
    error NotChosen();
    error Paused();
    error NoSkill();
    error NoControl();
    error NotDeployer();
    error UnknownChain();
    error InQuarantine();

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_) {
        if (bond_ == 0 || commitWindow_ == 0 || timeout_ <= commitWindow_ || unbondDelay_ < timeout_) revert BadValue();
        workerBond = bond_;
        jobReward = reward_;
        minFee = minFee_;
        commitWindow = commitWindow_;
        jobTimeout = timeout_;
        unbondDelay = unbondDelay_;
        dailyRewardCap = dailyRewardCap_;
        deployer = msg.sender;
    }

    // ---- shared internals ----

    function _job(uint256 id) internal view returns (Job storage) {
        if (id >= jobs.length) revert BadJob();
        return jobs[id];
    }

    /// The latest challenge of job `id` and its round number (2, 3, ...);
    /// (an empty one, 1) when there is none.
    function _latest(uint256 id) internal view returns (Challenge storage ch, uint8 round) {
        uint8 n = jobs[id].chN;
        return (challenges[id][n == 0 ? 0 : n - 1], n + 1);
    }

    function _paused() internal view returns (bool) {
        return address(control) != address(0) && control.paused();
    }

    /// The lottery of a round: keccak256(seed, blockhash(startBlock + 1), round).
    /// Fixed by a block the caller cannot pick, so failing (a revert) and
    /// trying again in a later block, or calling only when it suits, changes
    /// nothing. 0 = not available: before block startBlock + 2, or (blockhash
    /// 0) more than 256 blocks later, when draw() moves the round to a new
    /// block. A chain whose BLOCKHASH gives 0 inside the window gets a fixed
    /// fallback, keccak256(seed, 1, round): as predictable as the request.
    function _rand(bytes32 seed, Round storage r, uint8 round) internal view returns (bytes32) {
        if (r.rand != 0) return r.rand;
        uint256 n = uint256(r.startBlock) + 1;
        if (block.number <= n) return 0;
        bytes32 h = blockhash(n);
        if (h == 0) {
            if (block.number - n > 256) return 0;
            h = bytes32(uint256(1));
        }
        return keccak256(abi.encode(seed, h, round));
    }

    function _open(Round storage r) internal {
        r.start = uint64(block.timestamp);
        r.startBlock = uint64(block.number);
        r.total = totalActiveBond;
    }

    /// Takes a seat in round `round` for msg.sender.
    function _take(uint256 id, Round storage r, uint8 round, bytes32 commitment) internal {
        Worker storage wk = workers[msg.sender];
        if (!wk.active) revert NotWorker();
        if (_paused()) revert Paused();
        if (block.timestamp >= r.start + commitWindow || r.commits == SEATS) revert NoSeat();
        if (r.rand == 0) {
            bytes32 x = _rand(jobs[id].seed, r, round);
            if (x == 0) revert TooEarly();
            r.rand = x;
            emit Drawn(id, round, x);
        }
        (bool ok, bool asDefender) = _eligible(id, r, msg.sender, round);
        if (!ok) revert NotChosen();
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == msg.sender) revert AlreadyIn();
        r.seat[r.commits] = msg.sender;
        r.commitOf[r.commits] = commitment;
        r.commits += 1;
        if (asDefender) r.defenders += 1;
        openSeats[msg.sender] += 1;
        wk.lastSeen = uint64(block.timestamp);
        // Penalties of this seat come by start + jobTimeout (+ the grace): the bond stays.
        _hold(msg.sender, uint256(r.start) + 2 * uint256(jobTimeout));
    }

    /// Checks msg.sender's commitment; returns how many revealed seats now
    /// hold this verdict (itself included).
    function _reveal(Round storage r, bytes32 verdict, bytes32 salt) internal returns (uint8 same) {
        uint8 s = _seatOf(r, msg.sender);
        if (r.revealed[s]) revert AlreadyIn();
        if (keccak256(abi.encode(verdict, msg.sender, salt)) != r.commitOf[s]) revert BadReveal();
        r.revealed[s] = true;
        r.verdictOf[s] = verdict;
        r.reveals += 1;
        openSeats[msg.sender] -= 1;
        workers[msg.sender].lastSeen = uint64(block.timestamp);
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) same++;
    }

    /// May a round's reveal still come? Open rounds: once seats are full or
    /// the commit window is over, and never after start + jobTimeout (a hard
    /// deadline: expire()/challengeExpire() close the round).
    function _revealOpen(Round storage r) internal view {
        if (block.timestamp >= r.start + jobTimeout) revert Closed();
        if (r.commits < SEATS && block.timestamp < r.start + commitWindow) revert TooEarly();
    }

    /// (eligible, as a defender) for round `round` of job `id`. Rounds 2..
    /// exclude every challenger so far and every seat of the earlier rounds.
    function _eligible(uint256 id, Round storage r, address w, uint8 round) internal view returns (bool, bool) {
        Job storage j = jobs[id];
        Worker storage wk = workers[w];
        uint256 total = r.total;
        if (_rand(j.seed, r, round) == 0 || !wk.active || wk.since >= r.start || total == 0 || quarantined(w)) return (false, false);
        if (round >= 2) {
            for (uint8 i = 0; i < j.r.commits; i++) if (j.r.seat[i] == w) return (false, false);
            for (uint256 c = 0; c + 2 <= round; c++) {
                Challenge storage x = challenges[id][c];
                if (x.challenger == w) return (false, false);
                if (c + 2 < round) for (uint8 i = 0; i < x.r.commits; i++) if (x.r.seat[i] == w) return (false, false);
            }
        }
        // A defender never goes by the lottery, and at most one sits on a
        // round, in every phase, unless no runner but defenders is active.
        if (isDefender(w)) return (r.defenders == 0 || activeWorkers <= _seatedDefenders(), true);
        uint256 stage = ((block.timestamp - r.start) * 3) / commitWindow; // 0, 1, 2 inside the window
        // Last third: every active runner (a real random draw must not leave seats empty).
        if (stage >= 2) return (true, false);
        uint256 base = j.drawn;
        if (stage > 0 && base < SEATS) base = SEATS;
        uint256 k = base << stage;
        uint256 x2 = uint256(keccak256(abi.encode(_rand(j.seed, r, round), w))) % 1e18;
        return (x2 * total < k * uint256(wk.bond) * 1e18, false);
    }

    function _seatOf(Round storage r, address w) internal view returns (uint8) {
        for (uint8 i = 0; i < r.commits; i++) if (r.seat[i] == w) return i;
        revert NoSeat();
    }

    function _challengeWindow() internal view returns (uint256 w) {
        if (address(control) != address(0)) w = control.challengeWindow();
        if (w == 0) w = jobTimeout;
    }

    /// Bonds of round-1 seats stay until a challenge opened by challengeUntil
    /// is over (its reveals end jobTimeout after it opens, its grace and
    /// settle() inside another jobTimeout).
    function _holdRound1(Job storage j) internal {
        uint256 hold = uint256(j.challengeUntil) + 2 * uint256(jobTimeout);
        for (uint8 i = 0; i < j.r.commits; i++) _hold(j.r.seat[i], hold);
    }

    function _hold(address w, uint256 until) internal {
        if (workers[w].heldUntil < until) workers[w].heldUntil = uint64(until);
    }

    function _toCommunity(uint256 amount) internal {
        if (amount == 0) return;
        if (address(control) != address(0)) credit[control.communityFund()] += amount;
        else rewardPool += amount;
    }

    function _settleRound(uint256 id, Round storage r, uint64 at) internal returns (bool) {
        if (at == 0 || block.timestamp < at) return false;
        for (uint8 i = 0; i < r.commits; i++) if (!r.revealed[i]) _miss(id, r.seat[i]);
        return true;
    }

    /// A judged seat: `ok` = its verdict stood. A rejected verdict costs the
    /// penalty and a strike.
    function _judge(address w, bool ok) internal {
        Worker storage wk = workers[w];
        if (ok) {
            wk.agreed += 1;
            _record(w, false);
        } else {
            wk.rejected += 1;
            _penalize(w, PENALTY_BPS, true);
            _record(w, true);
        }
    }

    /// Committed, never revealed: penalty and a strike.
    function _miss(uint256 id, address w) internal {
        openSeats[w] -= 1;
        emit Missed(id, w);
        _penalize(w, PENALTY_BPS, true);
        _record(w, true);
    }

    function _record(address w, bool strike) internal {
        Worker storage wk = workers[w];
        wk.recent = uint8(((uint256(wk.recent) << 1) | (strike ? 1 : 0)) & ((1 << STRIKE_WINDOW) - 1));
        if (strike && strikes(w) >= QUARANTINE_AFTER && !quarantined(w)) _quarantine(w);
    }

    /// Out at once: not active, its bond leaves totalActiveBond and starts
    /// unbonding (withdrawable after unbondDelay, minus penalties).
    function _quarantine(address w) internal {
        Worker storage wk = workers[w];
        wk.recent = 0;
        wk.quarantinedAt = uint64(block.timestamp);
        _deactivate(w);
        emit Quarantined(w);
        for (uint256 i = 0; i < DEFENDERS; i++) {
            if (defender[i] == w) {
                defender[i] = address(0);
                emit DefenderVacated(w, i);
            }
        }
    }

    /// Not active any more, and the unbond timer runs (withdrawBond after
    /// unbondDelay and heldUntil), so the bond never gets stuck.
    function _deactivate(address w) internal {
        Worker storage wk = workers[w];
        if (wk.active) {
            wk.active = false;
            activeWorkers -= 1;
            totalActiveBond -= wk.bond;
        }
        if (wk.unbondAt == 0 && wk.bond > 0) {
            wk.unbondAt = uint64(block.timestamp) + unbondDelay;
            emit UnbondRequested(w, wk.unbondAt);
        }
    }

    /// Takes `bps` of the bond: into the reward pool (`toPool`), or returned
    /// for the caller to hand out (a challenge's slash).
    function _penalize(address w, uint16 bps, bool toPool) internal returns (uint256 cut) {
        Worker storage wk = workers[w];
        cut = (uint256(wk.bond) * bps) / 10_000;
        if (cut == 0) return 0;
        wk.bond -= uint128(cut);
        if (toPool) rewardPool += cut;
        if (wk.active) totalActiveBond -= cut;
        emit Penalized(w, cut);
        // Below the bond: out until topped up (register() again), unbonding meanwhile.
        if (wk.active && wk.bond < workerBond) _deactivate(w);
    }

    /// Strikes within the runner's last STRIKE_WINDOW judged seats.
    function strikes(address w) public view returns (uint256 n) {
        for (uint8 r = workers[w].recent; r != 0; r >>= 1) n += r & 1;
    }

    function quarantined(address w) public view returns (bool) {
        uint64 q = workers[w].quarantinedAt;
        if (q == 0) return false;
        return address(control) == address(0) || q >= control.releasedAt(w);
    }

    /// Seated in a defender seat and still fit for it (incl. a recent heartbeat).
    function isDefender(address w) public view returns (bool) {
        if (w == address(0)) return false;
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return _fit(w);
        return false;
    }

    function _fit(address w) internal view returns (bool) {
        if (address(control) == address(0) || !control.defenderApproved(w) || !workers[w].active || quarantined(w)) return false;
        return block.timestamp < uint256(workers[w].lastSeen) + control.defenderTimeout();
    }

    function _seatedDefenders() internal view returns (uint256 n) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] != address(0) && _fit(defender[i])) n++;
    }

    /// The least bond challenge(id) takes: max(2 x fee, NeuroControl.challengeBond()).
    function challengeBondOf(uint256 id) public view returns (uint256 b) {
        b = _job(id).fee * CHALLENGE_FEE_MULTIPLE;
        if (address(control) != address(0)) {
            uint256 floor_ = control.challengeBond();
            if (floor_ > b) b = floor_;
        }
    }
}

/// @title NeuroJobsChallenges: the challenge rounds of NeuroJobs
/// @notice Runs only through NeuroJobs' delegatecall (on NeuroJobs' storage
///         and balance); NeuroJobs deploys it in its constructor. Called
///         directly it refuses. The rules are documented on NeuroJobs.
contract NeuroJobsChallenges is NeuroJobsBase {
    address private immutable self_;

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_)
        NeuroJobsBase(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_)
    {
        self_ = address(this);
    }

    modifier delegated() {
        if (address(this) == self_) revert NotDeployer();
        _;
    }

    function challenge(uint256 id, bytes32 claim) external payable delegated {
        Job storage j = _job(id);
        if (j.status != Status.Done || block.timestamp >= j.challengeUntil) revert Closed();
        (Challenge storage prev,) = _latest(id);
        if (prev.state != ChallengeState.None && prev.state != ChallengeState.Disputed) revert AlreadyIn();
        if (j.chN >= MAX_CHALLENGES) revert Closed();
        if (_paused()) revert Paused();
        if (claim == bytes32(0) || claim == j.result || msg.value < challengeBondOf(id)) revert BadValue();
        Challenge storage ch = challenges[id][j.chN];
        j.chN += 1;
        ch.challenger = msg.sender;
        ch.state = ChallengeState.Open;
        ch.bond = msg.value;
        ch.claim = claim;
        _open(ch.r);
        // Round-1 bonds stay until this round is over (whatever challengeUntil said).
        uint256 hold = uint256(block.timestamp) + 2 * uint256(jobTimeout);
        for (uint8 i = 0; i < j.r.commits; i++) _hold(j.r.seat[i], hold);
        challenged.push(id);
        emit Challenged(id, msg.sender, msg.value);
        emit ChallengeClaim(id, j.chN + 1, claim);
    }

    function challengeCommit(uint256 id, bytes32 commitment) external delegated {
        _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        if (ch.state != ChallengeState.Open) revert Closed();
        _take(id, ch.r, round, commitment);
        emit ChallengeCommitted(id, msg.sender);
    }

    function challengeReveal(uint256 id, bytes32 verdict, bytes32 salt) external delegated {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        Round storage r = ch.r;
        if (ch.state == ChallengeState.Open) _revealOpen(r);
        else if (ch.settleAt == 0 || block.timestamp >= ch.settleAt) revert Closed();
        uint8 same = _reveal(r, verdict, salt);
        emit ChallengeRevealed(id, msg.sender, verdict);

        if (ch.state != ChallengeState.Open) {
            bool ok = verdict == ch.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { ch.settleAt = 0; emit Settled(id); }
            return;
        }
        if (same >= QUORUM) _resolve(id, j, ch, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) _dispute(id, j, ch, false);
    }

    function challengeExpire(uint256 id) external delegated {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        if (ch.state != ChallengeState.Open) revert Closed();
        if (block.timestamp < ch.r.start + jobTimeout) revert TooEarly();
        _dispute(id, j, ch, true);
    }

    /// The round reached a quorum on `verdict`. Only credits move (no calls out).
    function _resolve(uint256 id, Job storage j, Challenge storage ch, bytes32 verdict) private {
        Round storage r1 = j.r;
        Round storage r2 = ch.r;
        ch.result = verdict;
        bytes32 old = j.result;
        bool overturned = verdict != old;
        ch.state = overturned ? ChallengeState.Overturned : ChallengeState.Confirmed;
        uint256 pot = ch.bond; // shared by the payees below (the challenger's part comes off first)
        if (overturned) {
            j.result = verdict;
            uint256 slashed;
            for (uint8 i = 0; i < r1.commits; i++) {
                if (!r1.revealed[i] || r1.verdictOf[i] != old) continue;
                address w = r1.seat[i];
                workers[w].rejected += 1;
                slashed += _penalize(w, CHALLENGE_SLASH_BPS, false);
                _record(w, true);
            }
            if (verdict == ch.claim) {
                // The challenger was right: bond back plus half of the slash.
                uint256 toChallenger = slashed / 2;
                credit[ch.challenger] += ch.bond + toChallenger;
                pot = slashed - toChallenger;
            } else {
                // Overturned, but not to what the challenger said: its bond is lost too.
                pot += slashed;
            }
        }
        uint8 n1;
        for (uint8 i = 0; i < r1.commits; i++) if (r1.revealed[i] && r1.verdictOf[i] == verdict) n1++;
        uint8 n2;
        for (uint8 i = 0; i < r2.commits; i++) if (r2.revealed[i] && r2.verdictOf[i] == verdict) n2++;
        // Confirmed: half for this round, half for round 1's winners. Overturned:
        // one equal share each for this round's winners and vindicated round-1 seats.
        uint256 s2;
        uint256 s1;
        if (overturned) {
            s1 = s2 = pot / (uint256(n1) + n2);
            j.agreedBy = n1 + n2;
        } else {
            s2 = (pot / 2) / n2;
            s1 = (pot - pot / 2) / n1;
            j.agreedBy += n2;
        }
        uint256 paid;
        for (uint8 i = 0; i < r1.commits; i++) {
            if (r1.revealed[i] && r1.verdictOf[i] == verdict) { credit[r1.seat[i]] += s1; paid += s1; }
        }
        for (uint8 i = 0; i < r2.commits; i++) {
            address w = r2.seat[i];
            if (r2.revealed[i] && r2.verdictOf[i] == verdict) { credit[w] += s2; paid += s2; _judge(w, true); }
            else if (r2.revealed[i]) _judge(w, false);
            else ch.settleAt = uint64(block.timestamp) + commitWindow;
        }
        _toCommunity(pot - paid); // rounding dust
        emit ChallengeResolved(id, ch.state, verdict);
    }

    /// No quorum: DISPUTE_KEEP_BPS of the bond goes to the seats that
    /// revealed (or the community fund), the rest back; the verdict stands,
    /// Disputed, and a new challenge may open (up to MAX_CHALLENGES).
    function _dispute(uint256 id, Job storage j, Challenge storage ch, bool timedOut) private {
        ch.state = ChallengeState.Disputed;
        Round storage r = ch.r;
        uint256 keep = (ch.bond * DISPUTE_KEEP_BPS) / 10_000;
        credit[ch.challenger] += ch.bond - keep;
        uint256 share = r.reveals == 0 ? 0 : keep / r.reveals;
        for (uint8 i = 0; i < r.commits; i++) {
            if (r.revealed[i]) credit[r.seat[i]] += share;
            else if (timedOut) _miss(id, r.seat[i]);
        }
        _toCommunity(keep - share * r.reveals);
        // Another challenge may open for one more challenge window; round-1
        // bonds stay through it. At the cap the window closes now.
        if (j.chN < MAX_CHALLENGES) {
            j.challengeUntil = uint64(block.timestamp + _challengeWindow());
            _holdRound1(j);
        } else if (j.challengeUntil > block.timestamp) {
            j.challengeUntil = uint64(block.timestamp);
        }
        emit ChallengeResolved(id, ChallengeState.Disputed, j.result);
    }
}

/// @title NeuroJobs: the Neuro ZETAPHY job market (testnet, stage 1-2)
/// @notice Someone asks for a contract to be checked and pays a fee in ZETAPHY.
///         Up to three bonded node runners each compute Neuro's verdict on their
///         own machine. The verdict stands once two of them agree, and those two
///         share the fee plus a reward from the pool.
///
///         Commit-reveal stops a runner from copying another's answer: runners
///         first post keccak256(verdict, runner, salt), and reveal only after
///         all seats are taken or the commit window closes, and before the
///         round's hard deadline (start + jobTimeout).
///
///         Payouts are credited, then pulled with withdraw() (no ETH is pushed
///         to arbitrary addresses inside the job logic).
///
///         Seats are not first-come: per job, a lottery weighted by bond
///         decides who may commit (eligible()). Only runners that registered
///         before the job count, and splitting one bond over many addresses
///         does not raise the odds. The denominator (totalActiveBond) is
///         snapshotted when the round opens, so bonds registered or withdrawn
///         later cannot push drawn runners out. Pool rewards are capped at a
///         quarter of the fee per winner and per day, so requesting jobs for
///         oneself does not pay.
///
///         Lottery bound to a block nobody picks: a request records nothing
///         random. For a round opened in block B:
///           rand = keccak256(seed, blockhash(B + 1), round)
///         usable from block B + 2. seed comes from the request (requester,
///         chain, target, time, the requester's own counter). The value is
///         fixed once B + 1 exists, whoever computes it and whenever: a commit
///         that reverts (NotChosen) and is retried every block, or a contract
///         that calls draw() only when it likes the outcome, gets the same
///         rand. eligible() computes it lazily (a view); the first commit or
///         draw(id) stores it. Limits: (a) blockhash only covers 256 blocks;
///         if nobody stored the draw by then, draw() moves the round to the
///         current block (Redrawn) and a new block hash decides; a party
///         that dislikes the draw cannot cause this while any runner is
///         watching, as any draw()/commit stores it. (b) The proposer of
///         block B + 1 can grind that block's contents (and so its hash) and
///         try many candidates: that is the remaining bias, a validator one.
///         (c) A chain whose BLOCKHASH returns 0 inside the window (old
///         zetaphyd) uses keccak256(seed, 1, round): it works, and is as
///         predictable as the request data alone (the unit-test EVM now gives
///         block hashes; zetaphyd v3+ does too).
///
///         Fee: 90% to the runners whose verdict stood, 5% burned (sent to
///         0x…dEaD, locked forever), 5% to the community fund (credited; it
///         withdraws like a runner). Rounding dust goes to the community
///         fund, so fee = runners + burned + community to the wei. A failed
///         or expired job refunds the fee minus FAIL_BURN_BPS (5%), which is
///         burned: whoever makes fake or unanswerable requests pays for them.
///
///         Bodies (runners eligible per job) are elastic:
///           bodies = DEFENDERS + ceil(requests per minute / CAPACITY_PER_BODY)
///         capped by NeuroControl.maxBodies(). Requests per minute is the
///         busiest recent minute, fading linearly to zero over DECAY_MINUTES.
///         Only requests that pass every check count, and with a NeuroControl
///         only chains on its allowlist (chainAllowed) are accepted.
///
///         Immune system: 4 defender seats, filled by regrow() (anyone may
///         call it) from NeuroControl's voted roster, at most
///         maxRegrowPerHour refills per hour. Defenders do not go by the
///         lottery, and at most ONE defender sits on any round, in every
///         phase of the window, unless no active runner is anything but a
///         seated defender (then defenders fill the seats, so jobs never
///         stall). Runners call heartbeat() (a commit or reveal counts too);
///         a defender silent for longer than NeuroControl.defenderTimeout()
///         stops being a defender at once and loses its seat at regrow().
///
///         Strikes: a rejected verdict, and a seat that committed but never
///         revealed, each cost PENALTY_BPS of the bond and a strike.
///         QUARANTINE_AFTER strikes within a runner's last STRIKE_WINDOW
///         judged seats put it in quarantine: not active, out of
///         totalActiveBond, unbonding, defender seat vacated, register()
///         refused until governance releases it (NeuroControl.release).
///         A penalty that leaves the bond below workerBond also deactivates
///         the runner and starts its unbond timer (withdrawBond after
///         unbondDelay and heldUntil; register() again to top up instead).
///
///         Unrevealed seats: once a quorum forms, a seat that has not
///         revealed yet gets a grace of commitWindow seconds to reveal. After
///         the grace anyone may call settle(id): every seat still unrevealed
///         gets the penalty and a strike. A job that times out (expire())
///         does the same at once.
///
///         Bond holds: a seat's bond stays (heldUntil) until start +
///         2 x jobTimeout of every round it sat on, and a round-1 seat's until
///         challengeUntil + 2 x jobTimeout, moved on when a challenge opens or
///         ends Disputed. Every reveal has a hard deadline, so every slash
///         lands before the hold ends. A seat committed and not yet revealed
///         or penalised also holds the bond (openSeats): withdrawBond waits
///         until expire()/settle()/challengeExpire() resolved it, whenever
///         they are called (the runner may call them itself), so the
///         non-reveal penalty cannot be escaped by a quiet keeper (NJ-1).
///
///         Challenges: until challengeUntil (finalize time + challengeWindow,
///         or jobTimeout when 0) anyone may call challenge(id, claim) with a
///         bond of at least max(2 x fee, NeuroControl.challengeBond()) and
///         the verdict it says is right (claim, not the current result). That
///         opens a challenge round: 3 fresh seats by the same lottery (its own
///         start block), never a seat of an earlier round nor any challenger
///         so far; commit-reveal and 2 of 3, hard deadline start + jobTimeout.
///           - Overturned to the claim: each round-1 runner that revealed the
///             overturned verdict loses CHALLENGE_SLASH_BPS (50%) of its bond
///             and gets a strike; the challenger gets its bond back plus half
///             the slash; the other half goes to the round's winners and the
///             round-1 seats that had revealed the new verdict.
///           - Overturned to a verdict that is neither the old one nor the
///             claim: the same slash, but the challenger's whole bond joins
///             the pot (it was wrong too).
///           - Confirmed: the challenger's bond is shared, half by the round's
///             winners, half by round 1's winners.
///           - No quorum (all revealed and none agree, or challengeExpire
///             after jobTimeout): DISPUTE_KEEP_BPS (20%) of the bond goes to
///             the round's seats that revealed (the community fund if none),
///             80% back; the verdict stands, Disputed, and a new challenge may
///             open within a fresh challenge window, up to MAX_CHALLENGES (2)
///             challenges: 3 rounds in all. So a challenge that ends nowhere
///             costs 20% and does not lock out real challengers.
///         Rounding dust always goes to the community fund (to the wei).
///
///         The challenge entry points run in NeuroJobsChallenges (deployed by
///         this constructor) through delegatecall, so NeuroJobs stays under
///         the 24,576-byte code limit; same storage, same address, same ABI.
///
///         NeuroControl's paused() stops new requests, challenges and commits
///         only; reveals, expiry, refunds and withdrawals keep working.
///         Without a NeuroControl nothing is paused, jobs carry skill 0, any
///         chain key is accepted, there are no defenders, bodies are uncapped,
///         challenges need 2 x fee and last jobTimeout, and the community share
///         goes to the reward pool.
contract NeuroJobs is NeuroJobsBase {
    /// The challenge logic (NeuroJobsChallenges), deployed by the constructor.
    address public immutable challengeLogic;

    constructor(uint256 bond_, uint256 reward_, uint256 minFee_, uint64 commitWindow_, uint64 timeout_, uint64 unbondDelay_, uint256 dailyRewardCap_)
        NeuroJobsBase(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_)
    {
        challengeLogic = address(new NeuroJobsChallenges(bond_, reward_, minFee_, commitWindow_, timeout_, unbondDelay_, dailyRewardCap_));
    }

    /// Wires in NeuroControl. Once, by the deployer.
    function setControl(INeuroKnobs control_) external {
        if (msg.sender != deployer) revert NotDeployer();
        if (address(control) != address(0) || address(control_) == address(0)) revert BadValue();
        control = control_;
        emit ControlSet(address(control_));
    }

    // ---- pool and runners ----

    function fund() external payable {
        if (msg.value == 0) revert BadValue();
        rewardPool += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    /// Joins, or comes back (tops up a bond below workerBond, or cancels
    /// unbonding). Only later jobs count it (since = now).
    function register() external payable {
        Worker storage w = workers[msg.sender];
        if (w.active) revert AlreadyIn();
        if (quarantined(msg.sender)) revert InQuarantine();
        uint256 bond = uint256(w.bond) + msg.value;
        if (bond < workerBond) revert BadValue();
        w.bond = uint128(bond);
        w.active = true;
        w.unbondAt = 0;
        w.since = uint64(block.timestamp);
        w.lastSeen = uint64(block.timestamp);
        activeWorkers += 1;
        totalActiveBond += bond;
        emit Registered(msg.sender, bond);
    }

    /// "Still here": keeps a defender seat (see defenderTimeout). Costs only gas.
    function heartbeat() external {
        Worker storage w = workers[msg.sender];
        if (!w.active) revert NotWorker();
        w.lastSeen = uint64(block.timestamp);
    }

    function requestUnbond() external {
        if (!workers[msg.sender].active) revert NotWorker();
        _deactivate(msg.sender);
    }

    /// After unbondDelay, and after heldUntil (see bond holds).
    function withdrawBond() external {
        Worker storage w = workers[msg.sender];
        if (w.active || w.unbondAt == 0 || block.timestamp < w.unbondAt || block.timestamp < w.heldUntil
            || openSeats[msg.sender] != 0) revert TooEarly();
        uint256 amount = w.bond;
        w.bond = 0;
        w.unbondAt = 0;
        credit[msg.sender] += amount;
    }

    function withdraw() external {
        uint256 amount = credit[msg.sender];
        if (amount == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    // ---- jobs ----

    /// @param chain   chain key as bytes32, e.g. "bsc"
    /// @param target  address on that chain, at most MAX_TARGET bytes
    function request(bytes32 chain, string calldata target) external payable returns (uint256 id) {
        return _request(msg.sender, chain, target);
    }

    /// Same as request(), but a refund goes to `refundTo` (StableGateway).
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256 id) {
        if (refundTo == address(0)) revert BadValue();
        return _request(refundTo, chain, target);
    }

    function _request(address requester, bytes32 chain, string calldata target) private returns (uint256 id) {
        if (msg.value < minFee || chain == bytes32(0) || bytes(target).length == 0 || bytes(target).length > MAX_TARGET) revert BadValue();
        bytes32 skill;
        if (address(control) != address(0)) {
            if (control.paused()) revert Paused();
            skill = control.activeSkill();
            if (skill == bytes32(0)) revert NoSkill();
            if (!control.chainAllowed(chain)) revert UnknownChain();
        }
        _countRequest();
        id = jobs.length;
        Job storage j = jobs.push();
        j.requester = requester;
        _open(j.r);
        // Not the job id: jobs slipped in first must not move the seed.
        j.seed = keccak256(abi.encode(requester, chain, target, block.timestamp, requestCount[requester]++));
        j.status = Status.Open;
        j.chain = chain;
        j.target = target;
        j.fee = msg.value;
        j.skill = skill;
        uint256 b = bodies();
        uint256 seated = _seatedDefenders();
        j.bodies = uint16(b);
        j.drawn = uint16(b > seated ? b - seated : 0);
        emit JobRequested(id, chain, target, msg.value);
        emit JobSized(id, skill, b, j.drawn);
    }

    /// Stores the lottery of the round taking seats (round 1 while the job
    /// is open, else the open challenge round). Anyone; once per round; from
    /// block startBlock + 2. If the lottery block fell out of the 256-block
    /// window unused, moves the round to this block instead (Redrawn).
    function draw(uint256 id) external {
        Job storage j = _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        Round storage r;
        if (j.status == Status.Open && j.r.rand == 0) { r = j.r; round = 1; }
        else if (ch.state == ChallengeState.Open && ch.r.rand == 0) r = ch.r;
        else revert Nothing();
        bytes32 x = _rand(j.seed, r, round);
        if (x == 0) {
            if (block.number <= uint256(r.startBlock) + 1) revert TooEarly();
            r.startBlock = uint64(block.number);
            emit Redrawn(id, round, r.startBlock);
            return;
        }
        r.rand = x;
        emit Drawn(id, round, x);
    }

    /// @param commitment keccak256(abi.encode(verdict, msg.sender, salt))
    function commit(uint256 id, bytes32 commitment) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        _take(id, j.r, 1, commitment);
        emit Committed(id, msg.sender);
    }

    /// Also open after a quorum, until settleAt, for a seat that had not
    /// revealed yet: it is judged against the result (no fee share).
    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        Round storage r = j.r;
        if (j.status == Status.Open) _revealOpen(r);
        else if (j.settleAt == 0 || block.timestamp >= j.settleAt) revert Closed();
        uint8 same = _reveal(r, verdict, salt);
        emit Revealed(id, msg.sender, verdict);

        if (j.status != Status.Open) {
            // Late reveal inside the grace after a quorum.
            bool ok = verdict == j.result;
            if (ok) j.agreedBy += 1;
            _judge(msg.sender, ok);
            if (r.reveals == r.commits) { j.settleAt = 0; emit Settled(id); }
            return;
        }

        if (same >= QUORUM) _finalize(id, j, verdict);
        else if (r.reveals == r.commits && (r.commits == SEATS || block.timestamp >= r.start + commitWindow)) {
            // Everyone who committed has revealed and no two agree.
            _fail(id, j, false);
        }
    }

    /// Anyone can close a job that ran out of time without a quorum.
    function expire(uint256 id) external {
        Job storage j = _job(id);
        if (j.status != Status.Open) revert Closed();
        if (block.timestamp < j.r.start + jobTimeout) revert TooEarly();
        _fail(id, j, true);
    }

    /// Anyone, once the reveal grace after a quorum is over (in round 1 or
    /// the latest challenge round): every seat that committed and still has
    /// not revealed gets the penalty and a strike.
    function settle(uint256 id) external {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        bool any;
        if (_settleRound(id, j.r, j.settleAt)) { j.settleAt = 0; any = true; }
        if (_settleRound(id, ch.r, ch.settleAt)) { ch.settleAt = 0; any = true; }
        if (!any) {
            if (j.settleAt != 0 || ch.settleAt != 0) revert TooEarly();
            revert Nothing();
        }
        emit Settled(id);
    }

    // ---- challenge rounds (NeuroJobsChallenges, by delegatecall) ----

    /// Opens a challenge round (see above). The whole msg.value is the bond;
    /// `claim` is the verdict the challenger says is right.
    function challenge(uint256, bytes32) external payable { _delegate(); }
    function challengeCommit(uint256, bytes32) external { _delegate(); }
    /// Like reveal(), for a seat of the open (or just decided) challenge round.
    function challengeReveal(uint256, bytes32, bytes32) external { _delegate(); }
    /// Anyone, jobTimeout after the challenge opened, if the round found no quorum.
    function challengeExpire(uint256) external { _delegate(); }

    function _delegate() private {
        address impl = challengeLogic;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            if iszero(ok) { revert(0, returndatasize()) }
            return(0, returndatasize())
        }
    }

    // ---- views ----

    function jobCount() external view returns (uint256) {
        return jobs.length;
    }

    function challengeCount() external view returns (uint256) {
        return challenged.length;
    }

    function getJob(uint256 id) external view returns (
        address requester, uint64 created, Status status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat
    ) {
        Job storage j = _job(id);
        return (j.requester, j.r.start, j.status, j.chain, j.target, j.fee, j.result, j.r.commits, j.r.reveals, j.r.seat);
    }

    /// May `w` take a round-1 seat on job `id` right now? False until the
    /// lottery block exists (startBlock + 2). A seated defender may if no
    /// defender sits on the job yet (or only defenders are active). Everyone
    /// else goes by a bond-weighted lottery: about `drawn` runners qualify
    /// at first, twice as many (at least 2 x SEATS) after the first third
    /// of the commit window, and every runner in the last third. Only
    /// runners active since before the job, never quarantined ones.
    function eligible(uint256 id, address w) external view returns (bool ok) {
        if (id >= jobs.length) return false;
        (ok,) = _eligible(id, jobs[id].r, w, 1);
    }

    /// Same for the open challenge round: never a seat of an earlier round or a challenger.
    function challengeEligible(uint256 id, address w) external view returns (bool ok) {
        if (id >= jobs.length) return false;
        (Challenge storage ch, uint8 round) = _latest(id);
        if (ch.state != ChallengeState.Open) return false;
        (ok,) = _eligible(id, ch.r, w, round);
    }

    /// The skill a job was requested under, its body counts, when the reveal
    /// grace after a quorum ends (0 = nothing pending), and its round-1
    /// lottery (0 = not available yet; computed even before anyone stores it).
    function jobInfo(uint256 id) external view returns (bytes32 skill, uint256 bodies_, uint256 drawn, uint64 settleAt, bytes32 rand) {
        Job storage j = _job(id);
        return (j.skill, j.bodies, j.drawn, j.settleAt, _rand(j.seed, j.r, 1));
    }

    /// How sure the verdict is: `agreedBy` distinct runners revealed it, the
    /// latest challenge state, until when it can be challenged, and
    /// `settled`: no challenge is possible or running any more.
    function assurance(uint256 id) external view returns (uint8 agreedBy, ChallengeState state, uint64 challengeUntil, bool settled) {
        Job storage j = _job(id);
        (Challenge storage ch,) = _latest(id);
        state = ch.state;
        settled = j.status == Status.Done && state != ChallengeState.Open
            && (state == ChallengeState.Confirmed || state == ChallengeState.Overturned || block.timestamp >= j.challengeUntil);
        return (j.agreedBy, state, j.challengeUntil, settled);
    }

    /// The latest challenge round of job `id` (see challengeRound for which one).
    function challengeInfo(uint256 id) external view returns (
        address challenger, ChallengeState state, uint256 bond, uint64 start, bytes32 rand,
        uint8 commits, uint8 reveals, address[3] memory seat, bytes32 result, uint64 settleAt
    ) {
        _job(id);
        (Challenge storage ch, uint8 round) = _latest(id);
        rand = _rand(jobs[id].seed, ch.r, round);
        challenger = ch.challenger;
        state = ch.state;
        bond = ch.bond;
        start = ch.r.start;
        commits = ch.r.commits;
        reveals = ch.r.reveals;
        seat = ch.r.seat;
        result = ch.result;
        settleAt = ch.settleAt;
    }

    /// How many challenges job `id` has had (the latest is round count + 1)
    /// and what the latest challenger claimed.
    function challengeRound(uint256 id) external view returns (uint8 count, bytes32 claim) {
        _job(id);
        (Challenge storage ch,) = _latest(id);
        return (jobs[id].chN, ch.claim);
    }

    /// Requests per minute right now, times DECAY_MINUTES.
    function load() public view returns (uint256) {
        uint64 m = uint64(block.timestamp / 60);
        uint256 a = _fade(loadCount, loadMinute, m);
        uint256 b = _fade(peakCount, peakMinute, m);
        return a > b ? a : b;
    }

    /// Bodies for a job requested now: DEFENDERS + ceil(requests per minute
    /// / CAPACITY_PER_BODY), at most NeuroControl.maxBodies().
    function bodies() public view returns (uint256 n) {
        uint256 unit = DECAY_MINUTES * CAPACITY_PER_BODY;
        n = DEFENDERS + (load() + unit - 1) / unit;
        uint256 cap = address(control) != address(0) ? control.maxBodies() : type(uint16).max;
        if (n > cap) n = cap;
    }

    function defenders() external view returns (address[4] memory) {
        return defender;
    }

    // ---- immune system ----

    /// Anyone may call it. Vacates defender seats whose runner is no longer
    /// fit, then refills empty seats from NeuroControl's roster, at most
    /// maxRegrowPerHour refills per clock hour.
    function regrow() external returns (uint256 filled) {
        if (address(control) == address(0)) revert NoControl();
        for (uint256 i = 0; i < DEFENDERS; i++) {
            address d = defender[i];
            if (d != address(0) && !_fit(d)) {
                defender[i] = address(0);
                emit DefenderVacated(d, i);
            }
        }
        uint64 hour = uint64(block.timestamp / 1 hours);
        if (regrowHour != hour) { regrowHour = hour; regrownThisHour = 0; }
        uint256 cap = control.maxRegrowPerHour();
        address[] memory r = control.roster();
        uint256 next = 0;
        for (uint256 i = 0; i < DEFENDERS && regrownThisHour < cap; i++) {
            if (defender[i] != address(0)) continue;
            for (; next < r.length; next++) {
                address cand = r[next];
                if (!_seated(cand) && _fit(cand)) {
                    defender[i] = cand;
                    regrownThisHour += 1;
                    filled += 1;
                    emit DefenderSeated(cand, i);
                    next++;
                    break;
                }
            }
            if (next >= r.length && defender[i] == address(0)) break;
        }
    }

    // ---- internals ----

    function _finalize(uint256 id, Job storage j, bytes32 verdict) private {
        Round storage r = j.r;
        j.status = Status.Done;
        j.result = verdict;
        j.challengeUntil = uint64(block.timestamp + _challengeWindow());
        uint8 winners = 0;
        for (uint8 i = 0; i < r.commits; i++) if (r.revealed[i] && r.verdictOf[i] == verdict) winners++;
        j.agreedBy = winners;
        uint256 burnCut = (j.fee * BURN_BPS) / 10_000;
        uint256 fundCut = (j.fee * COMMUNITY_BPS) / 10_000;
        uint256 toRunners = j.fee - burnCut - fundCut;
        uint256 share = toRunners / winners;
        fundCut += toRunners - share * winners; // rounding dust
        // Pool reward per winner: at most jobReward and at most a quarter of
        // the fee, within the daily cap.
        uint256 reward = jobReward < j.fee / 4 ? jobReward : j.fee / 4;
        uint64 today = uint64(block.timestamp / 1 days);
        if (rewardDay != today) { rewardDay = today; rewardedToday = 0; }
        // Every round-1 seat may be slashed by a challenge: its bond stays until then.
        _holdRound1(j);
        for (uint8 i = 0; i < r.commits; i++) {
            address w = r.seat[i];
            if (r.revealed[i] && r.verdictOf[i] == verdict) {
                uint256 pay = share;
                if (reward > 0 && rewardPool >= reward && rewardedToday + reward <= dailyRewardCap) {
                    rewardPool -= reward;
                    rewardedToday += reward;
                    pay += reward;
                }
                credit[w] += pay;
                _judge(w, true);
            } else if (r.revealed[i]) {
                _judge(w, false);
            } else {
                // Not revealed yet: a grace to reveal, then settle() judges it.
                j.settleAt = uint64(block.timestamp) + commitWindow;
            }
        }
        _toCommunity(fundCut);
        totalBurned += burnCut;
        emit FeeSplit(id, share * winners, burnCut, fundCut);
        emit Finalized(id, verdict);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    function _fail(uint256 id, Job storage j, bool timedOut) private {
        j.status = Status.Failed;
        uint256 burnCut = (j.fee * FAIL_BURN_BPS) / 10_000;
        credit[j.requester] += j.fee - burnCut;
        if (timedOut) {
            for (uint8 i = 0; i < j.r.commits; i++) if (!j.r.revealed[i]) _miss(id, j.r.seat[i]);
        }
        totalBurned += burnCut;
        emit FeeSplit(id, 0, burnCut, 0);
        emit JobFailed(id);
        // Last: BURN has no code, so this cannot call back.
        if (burnCut > 0) {
            (bool ok,) = BURN.call{value: burnCut}("");
            require(ok, "burn failed");
        }
    }

    function _seated(address w) private view returns (bool) {
        for (uint256 i = 0; i < DEFENDERS; i++) if (defender[i] == w) return true;
        return false;
    }

    /// N requests counted at minute `from`, seen at minute `m`: N*(DECAY-age), 0 after DECAY_MINUTES.
    function _fade(uint256 n, uint64 from, uint64 m) private pure returns (uint256) {
        uint256 age = m - from;
        return age >= DECAY_MINUTES ? 0 : n * (DECAY_MINUTES - age);
    }

    function _countRequest() private {
        uint64 m = uint64(block.timestamp / 60);
        if (m != loadMinute) {
            // The finished minute becomes the peak if it outweighs the fading one.
            if (_fade(loadCount, loadMinute, m) >= _fade(peakCount, peakMinute, m)) { peakCount = loadCount; peakMinute = loadMinute; }
            loadMinute = m;
            loadCount = 0;
        }
        loadCount += 1;
    }
}

contracts/NeuroOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Neuro cross-chain security oracle (docs/future/crosschain-assist.md, items 18 and 28).
//
//   ZETAPHY                                                       each EVM testnet (Sepolia, Base Sepolia, Arbitrum Sepolia)
//   ThreatRegistry (runner quorum) --read by--> NeuroOracleSender --Hyperlane message--> NeuroOracle (DEXes query it)
//   NeuroJobs (settled verdicts)    --read by--/                     verified by the ISM of OUR validators for origin ZETAPHY
//                                              \--ICS-20 + memo (ibc-hooks)--> a CosmWasm NeuroOracle on osmo-test-5
//
// The sender holds no key and decides nothing: it reads the registry's and NeuroJobs' own state at the
// moment of the call and sends exactly that. Anyone may call push (a runner, a GitHub Actions schedule,
// a user who just saw a flag), paying the Hyperlane fee; a wrong or stale message cannot be sent
// because the contents are not the caller's. The receiver keeps per key the newest state by the
// registry's round (it bumps on every flag and clear), so out-of-order or replayed deliveries cannot
// roll a key back.
//
// Local copies of the Hyperlane v3 interfaces (IMailbox dispatch / quoteDispatch, IMessageRecipient
// handle, ISpecifiesInterchainSecurityModule), as in HyperlaneLockBoxV2.sol; named apart (one unit).

interface INOMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
}

interface INOIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// The parts of ThreatRegistry the sender reads.
interface INOThreats {
    function entries(bytes32 key) external view returns (bool flagged, uint8 reason, uint64 updatedAt, uint32 round, uint8 votes, bool fast, uint8 support, uint64 fastAt);
    function enforcedFrom(bytes32 key) external view returns (uint64);
    function heldFrom(bytes32 key) external view returns (uint64);
    function flaggedCount() external view returns (uint256);
    function flaggedList(uint256 i) external view returns (bytes32);
}

/// The parts of NeuroJobs the sender reads (settled verdicts).
interface INOJobs {
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function jobInfo(uint256 id) external view returns (bytes32 skill, uint256 bodies, uint256 drawn, uint64 settleAt, bytes32 rand);
    function assurance(uint256 id) external view returns (uint8 agreedBy, uint8 state, uint64 challengeUntil, bool settled);
}

/// cosmos/evm's ICS-20 precompile (0x…0802), as zetaphy-hub/chainlib.js encodes it.
interface INOIcs20 {
    struct Height { uint64 revisionNumber; uint64 revisionHeight; }
    function transfer(string calldata sourcePort, string calldata sourceChannel, string calldata denom, uint256 amount, address sender,
        string calldata receiver, Height calldata timeoutHeight, uint64 timeoutTimestamp, string calldata memo) external returns (uint64 nextSequence);
}

/// AuditCertificate's message body (kind 3): see AuditCertificate.certificateBody.
interface INOAudit {
    function certificateBody(uint64 chainId, address target) external view returns (bytes memory);
}

/// One audit certificate as mirrored (AuditCertificate.certificateBody after kind and source chain).
struct NOCert {
    uint64 chainId;
    address target;
    bytes32 codeHash;
    bytes32 reportHash;
    uint8 level;
    uint64 issuedAt;
    uint64 expiresAt;
    bool revoked;
    uint256 requestId;
}

/// One registry key as mirrored: the registry's own numbers at the time of the push.
struct NOItem {
    bytes32 key;
    uint32 round;        // ThreatRegistry Entry.round (bumps on every flag and clear)
    bool flagged;
    uint8 reason;        // ThreatRegistry.Reason
    uint64 enforcedFrom; // ZETAPHY time from which it is enforced (0: not flagged)
    uint64 heldFrom;     // ZETAPHY time from which it holds (0: not flagged)
}

/// One settled NeuroJobs verdict.
struct NOVerdict {
    uint256 jobId;
    bytes32 chain;       // NeuroJobs chain id string (bytes32), e.g. "eth"
    bytes32 target;      // keccak256 of the target string (lowercase as requested)
    bytes32 result;      // the verdict hash runners agreed on
    bytes32 skill;       // the skill the job ran under (model / rules version)
    uint8 agreedBy;
}

/// @title NeuroOracleSender: ZETAPHY side. Reads the registry and NeuroJobs, sends what they say.
contract NeuroOracleSender {
    uint8 public constant KIND_THREATS = 1;
    uint8 public constant KIND_VERDICT = 2;
    uint256 public constant MAX_ITEMS = 32;
    address public constant ICS20 = 0x0000000000000000000000000000000000000802;

    INOThreats public immutable threats;
    INOJobs public immutable jobs;      // zero: verdicts off
    INOMailbox public immutable mailbox;
    address public governance;          // the ZETAPHY timelock

    /// destination domain -> the NeuroOracle there (zero: no route)
    mapping(uint32 => bytes32) public receivers;
    uint32[] public domains;
    /// the round last pushed per destination and key, plus one (0: never)
    mapping(uint32 => mapping(bytes32 => uint32)) public sentRound;
    /// the enforcedFrom last pushed (a fast-lane enforcement keeps the round but moves it)
    mapping(uint32 => mapping(bytes32 => uint64)) public sentEnforcedFrom;

    /// AuditCertificate (docs/future/audit-network.md); zero: certificates off
    INOAudit public audit;

    // IBC (osmo-test-5): a channel and the CosmWasm contract there; empty: off
    string public ibcChannel;
    string public ibcContract;
    uint64 public ibcTimeout = 600;     // seconds

    event Pushed(uint32 indexed domain, bytes32 messageId, uint256 items);
    event VerdictPushed(uint32 indexed domain, uint256 indexed jobId, bytes32 messageId);
    event PushedIbc(string channel, uint64 sequence, uint256 items);
    event CertificatePushed(uint32 indexed domain, uint64 indexed chainId, address indexed target, bytes32 messageId);
    event AuditSet(address audit);
    event ReceiverSet(uint32 indexed domain, bytes32 receiver);
    event IbcRouteSet(string channel, string contractAddr, uint64 timeout);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NoRoute(uint32 domain);
    error TooMany();
    error NothingToSend();
    error NotSettled(uint256 jobId);
    error Fee(uint256 needed);
    error RefundFailed();
    error BadInput();

    constructor(INOThreats threats_, INOJobs jobs_, INOMailbox mailbox_, address governance_) {
        require(address(threats_) != address(0) && address(mailbox_) != address(0) && governance_ != address(0), "zero");
        threats = threats_;
        jobs = jobs_;
        mailbox = mailbox_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "zero");
        governance = g;
        emit GovernanceSet(g);
    }

    /// The NeuroOracle on `domain` (zero removes the route).
    function setReceiver(uint32 domain, bytes32 receiver) external onlyGov {
        if (receivers[domain] == bytes32(0) && receiver != bytes32(0)) domains.push(domain);
        receivers[domain] = receiver;
        emit ReceiverSet(domain, receiver);
    }

    function domainCount() external view returns (uint256) { return domains.length; }

    /// The AuditCertificate whose certificates pushCertificate sends (zero: off).
    function setAudit(INOAudit a) external onlyGov {
        audit = a;
        emit AuditSet(address(a));
    }

    /// An audit certificate (or its revocation), exactly as AuditCertificate states it now, to `domain`.
    function pushCertificate(uint32 domain, uint64 chainId, address target) external payable returns (bytes32 id) {
        bytes32 r = receivers[domain];
        if (r == bytes32(0)) revert NoRoute(domain);
        if (address(audit) == address(0)) revert NothingToSend();
        id = _dispatch(domain, r, audit.certificateBody(chainId, target));
        emit CertificatePushed(domain, chainId, target, id);
    }

    /// The IBC route: our channel to osmo-test-5 and the CosmWasm oracle's address (ibc-hooks calls it).
    function setIbcRoute(string calldata channel, string calldata contractAddr, uint64 timeout) external onlyGov {
        bytes memory c = bytes(channel);
        if (c.length > 0 && (c.length > 20 || !_plain(c) || !_plain(bytes(contractAddr)) || bytes(contractAddr).length > 100 || timeout < 60 || timeout > 1 days)) revert BadInput();
        ibcChannel = channel;
        ibcContract = contractAddr;
        ibcTimeout = timeout;
        emit IbcRouteSet(channel, contractAddr, timeout);
    }

    // ---------------------------------------------------------------- reading

    /// The registry's state of a key, as it would be sent now.
    function itemOf(bytes32 key) public view returns (NOItem memory it) {
        (bool flagged, uint8 reason, , uint32 round, , , , ) = threats.entries(key);
        it.key = key;
        it.round = round;
        it.flagged = flagged;
        it.reason = flagged ? reason : 0;
        if (flagged) {
            it.enforcedFrom = threats.enforcedFrom(key);
            it.heldFrom = threats.heldFrom(key);
        }
    }

    /// Whether `domain` still lacks the current state of each key (never flagged keys: false).
    function pending(uint32 domain, bytes32[] calldata keys) external view returns (bool[] memory out) {
        out = new bool[](keys.length);
        for (uint256 i = 0; i < keys.length; ++i) out[i] = _pending(domain, itemOf(keys[i]));
    }

    function _pending(uint32 domain, NOItem memory it) private view returns (bool) {
        if (it.round == 0) return false;
        uint32 s = sentRound[domain][it.key];
        return s != it.round + 1 || (it.flagged && it.enforcedFrom < sentEnforcedFrom[domain][it.key]);
    }

    /// A page of the registry's flag history (keys may repeat: a key flagged again is listed again),
    /// with each key's current round and state: what the hub's coverage meter compares.
    function snapshot(uint256 start, uint256 n) external view returns (bytes32[] memory keys, uint32[] memory rounds, bool[] memory flagged) {
        uint256 total = threats.flaggedCount();
        uint256 end = start + n > total ? total : start + n;
        uint256 len = end > start ? end - start : 0;
        keys = new bytes32[](len);
        rounds = new uint32[](len);
        flagged = new bool[](len);
        for (uint256 i = 0; i < len; ++i) {
            bytes32 k = threats.flaggedList(start + i);
            (bool f, , , uint32 r, , , , ) = threats.entries(k);
            keys[i] = k;
            rounds[i] = r;
            flagged[i] = f;
        }
    }

    // ---------------------------------------------------------------- Hyperlane

    /// The message body push(domain, keys) would send.
    function threatsBody(bytes32[] calldata keys) public view returns (bytes memory) {
        if (keys.length == 0) revert NothingToSend();
        if (keys.length > MAX_ITEMS) revert TooMany();
        NOItem[] memory items = new NOItem[](keys.length);
        for (uint256 i = 0; i < keys.length; ++i) items[i] = itemOf(keys[i]);
        return abi.encode(KIND_THREATS, block.chainid, items);
    }

    function quote(uint32 domain, bytes32[] calldata keys) external view returns (uint256) {
        bytes32 r = receivers[domain];
        if (r == bytes32(0)) revert NoRoute(domain);
        return mailbox.quoteDispatch(domain, r, threatsBody(keys));
    }

    /// Sends the registry's current state of `keys` (at most MAX_ITEMS) to the NeuroOracle on `domain`.
    /// msg.value pays the Hyperlane fee (quote); anything above it is sent back.
    function push(uint32 domain, bytes32[] calldata keys) external payable returns (bytes32 id) {
        bytes32 r = receivers[domain];
        if (r == bytes32(0)) revert NoRoute(domain);
        bytes memory b = threatsBody(keys);
        ( , , NOItem[] memory items) = abi.decode(b, (uint8, uint256, NOItem[]));
        for (uint256 i = 0; i < items.length; ++i) {
            sentRound[domain][items[i].key] = items[i].round + 1;
            sentEnforcedFrom[domain][items[i].key] = items[i].enforcedFrom;
        }
        id = _dispatch(domain, r, b);
        emit Pushed(domain, id, items.length);
    }

    /// A settled NeuroJobs verdict (no challenge open or possible any more), to `domain`.
    function pushVerdict(uint32 domain, uint256 jobId) external payable returns (bytes32 id) {
        bytes32 r = receivers[domain];
        if (r == bytes32(0)) revert NoRoute(domain);
        bytes memory b = verdictBody(jobId);
        id = _dispatch(domain, r, b);
        emit VerdictPushed(domain, jobId, id);
    }

    function verdictBody(uint256 jobId) public view returns (bytes memory) {
        if (address(jobs) == address(0)) revert NotSettled(jobId);
        (uint8 agreedBy, , , bool settled) = jobs.assurance(jobId);
        if (!settled) revert NotSettled(jobId);
        (, , , bytes32 chain, string memory target, , bytes32 result, , , ) = jobs.getJob(jobId);
        (bytes32 skill, , , , ) = jobs.jobInfo(jobId);
        return abi.encode(KIND_VERDICT, block.chainid, NOVerdict(jobId, chain, keccak256(bytes(target)), result, skill, agreedBy));
    }

    function _dispatch(uint32 domain, bytes32 r, bytes memory b) private returns (bytes32 id) {
        uint256 fee = mailbox.quoteDispatch(domain, r, b);
        if (msg.value < fee) revert Fee(fee);
        id = mailbox.dispatch{value: fee}(domain, r, b);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert RefundFailed();
        }
    }

    // ---------------------------------------------------------------- IBC (osmo-test-5, ibc-hooks)

    /// The ICS-20 memo pushIbc sends: {"wasm":{"contract":C,"msg":{"mirror":{"src_chain":77390,"items":[…]}}}}.
    /// ibc-hooks on Osmosis executes `msg` on C with a sender derived from (channel, this contract's address),
    /// which C checks (zetaphy-network/cosmwasm/neuro-oracle-osmo).
    function ibcMemo(bytes32[] calldata keys) public view returns (string memory) {
        if (keys.length == 0) revert NothingToSend();
        if (keys.length > MAX_ITEMS) revert TooMany();
        bytes memory s = abi.encodePacked('{"wasm":{"contract":"', ibcContract, '","msg":{"mirror":{"src_chain":', _u(block.chainid), ',"items":[');
        for (uint256 i = 0; i < keys.length; ++i) {
            NOItem memory it = itemOf(keys[i]);
            s = abi.encodePacked(s, i == 0 ? "" : ",", '{"key":"', _hex(it.key), '","round":', _u(it.round), ',"flagged":', it.flagged ? "true" : "false",
                ',"reason":', _u(it.reason), ',"enforced_from":', _u(it.enforcedFrom), ',"held_from":', _u(it.heldFrom), "}");
        }
        return string(abi.encodePacked(s, "]}}}}"));
    }

    /// Sends the keys' state over IBC: an ICS-20 transfer of 1 azetaphy (msg.value, at least 1 wei) to the
    /// CosmWasm oracle with the memo above. The relayer carries it; Osmosis' light client of ZETAPHY verifies it.
    function pushIbc(bytes32[] calldata keys) external payable returns (uint64 seq) {
        if (bytes(ibcChannel).length == 0) revert NoRoute(0);
        if (msg.value == 0) revert Fee(1);
        string memory memo = ibcMemo(keys);
        seq = INOIcs20(ICS20).transfer("transfer", ibcChannel, "azetaphy", msg.value, address(this), ibcContract,
            INOIcs20.Height(0, 0), uint64(block.timestamp + ibcTimeout) * 1e9, memo);
        emit PushedIbc(ibcChannel, seq, keys.length);
    }

    // ---------------------------------------------------------------- text helpers

    function _plain(bytes memory b) private pure returns (bool) {
        for (uint256 i = 0; i < b.length; ++i) {
            bytes1 c = b[i];
            if (!((c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-")) return false;
        }
        return true;
    }

    function _u(uint256 v) private pure returns (bytes memory out) {
        if (v == 0) return "0";
        uint256 n;
        for (uint256 x = v; x != 0; x /= 10) ++n;
        out = new bytes(n);
        for (; v != 0; v /= 10) out[--n] = bytes1(uint8(48 + (v % 10)));
    }

    function _hex(bytes32 v) private pure returns (bytes memory out) {
        bytes16 h = "0123456789abcdef";
        out = new bytes(64);
        for (uint256 i = 0; i < 32; ++i) {
            out[2 * i] = h[uint8(v[i]) >> 4];
            out[2 * i + 1] = h[uint8(v[i]) & 0x0f];
        }
    }
}

/// @title NeuroOracle: the mirror on another EVM chain, written only by ZETAPHY's NeuroOracleSender
/// @notice handle() takes a message only from the configured Mailbox, after the ISM this contract names
///         (a multisig ISM of OUR validators for origin ZETAPHY, as HyperlaneLockBoxV2), from origin
///         ZETAPHY and the one NeuroOracleSender. A key keeps the newest state by round; a delivery
///         that is older (or the same) changes nothing. While paused (guardians pause; governance
///         unpauses), handle reverts so messages wait at the Mailbox, and every view answers
///         "not flagged" (a DEX keeps working; `paused()` says the mirror is not current).
///
///         For DEXes: check(token) = the token's address on this chain or its code is flagged
///         (keys as ThreatRegistry.addressKey(block.chainid, token) / codeKey(token.codehash));
///         isFlagged(fp1) for Neuro's fingerprint (computed off-chain). Flags state reproducible
///         facts about code, not intent (docs/LEGAL.md); "enforced" means the registry's enforcement
///         delay passed, which is when ZETAPHY's own bridges and wallet refuse.
contract NeuroOracle {
    struct Mirror {
        uint32 round;
        bool flagged;
        uint8 reason;
        uint64 enforcedFrom;
        uint64 heldFrom;
        uint64 mirroredAt;   // this chain's time of the last update (0: never)
    }

    struct Verdict {
        uint256 jobId;
        bytes32 result;
        bytes32 skill;
        uint8 agreedBy;
        uint64 mirroredAt;
    }

    bytes32 private constant EMPTY_CODEHASH = keccak256("");
    address public immutable mailbox;
    uint32 public immutable zetaphyDomain;
    uint256 public immutable zetaphyChainId;
    bytes32 public immutable remoteSender;   // NeuroOracleSender on ZETAPHY
    INOIsm public interchainSecurityModule;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;

    mapping(bytes32 => Mirror) public mirror;
    mapping(bytes32 => Verdict) public verdicts; // by keccak256(abi.encode(chain, targetHash))
    mapping(bytes32 => NOCert) public certs;     // audit certificates by keccak256(abi.encode(chainId, target))
    bytes32[] public keys;                       // every key ever mirrored, in first-seen order
    uint256 public flaggedNow;                   // keys whose mirrored state is flagged
    uint256 public messages;                     // messages handled
    uint64 public lastUpdate;

    event Mirrored(bytes32 indexed key, uint32 round, bool flagged, uint8 reason, uint64 enforcedFrom);
    event Stale(bytes32 indexed key, uint32 round, uint32 have);
    event VerdictMirrored(uint256 indexed jobId, bytes32 indexed chain, bytes32 indexed target, bytes32 result);
    event CertificateMirrored(uint64 indexed chainId, address indexed target, bytes32 codeHash, uint8 level, bool revoked);
    event Paused(address by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);

    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error BadKind(uint8 kind);
    error IsPaused();
    error NoValue();
    error NotGovernance();
    error NotGuardian();

    constructor(address mailbox_, uint32 zetaphyDomain_, uint256 zetaphyChainId_, bytes32 remoteSender_, INOIsm ism_, address governance_, address guardian_) {
        require(mailbox_ != address(0) && remoteSender_ != bytes32(0) && address(ism_) != address(0) && governance_ != address(0) && zetaphyChainId_ != 0, "zero");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        zetaphyChainId = zetaphyChainId_;
        remoteSender = remoteSender_;
        interchainSecurityModule = ism_;
        governance = governance_;
        if (guardian_ != address(0)) { guardian[guardian_] = true; emit GuardianSet(guardian_, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    // ---------------------------------------------------------------- roles

    function setIsm(INOIsm ism) external onlyGov { require(address(ism) != address(0), "zero"); interchainSecurityModule = ism; emit IsmSet(address(ism)); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    function pause() external { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); paused = true; emit Paused(msg.sender); }
    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    // ---------------------------------------------------------------- Hyperlane

    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (paused) revert IsPaused();
        if (origin != zetaphyDomain) revert WrongOrigin(origin);
        if (sender != remoteSender) revert WrongSender(sender);
        (uint8 kind, uint256 src) = abi.decode(b[:64], (uint8, uint256));
        if (src != zetaphyChainId) revert WrongSource();
        messages += 1;
        lastUpdate = uint64(block.timestamp);
        if (kind == 1) {
            ( , , NOItem[] memory items) = abi.decode(b, (uint8, uint256, NOItem[]));
            for (uint256 i = 0; i < items.length; ++i) _apply(items[i]);
        } else if (kind == 2) {
            ( , , NOVerdict memory v) = abi.decode(b, (uint8, uint256, NOVerdict));
            verdicts[keccak256(abi.encode(v.chain, v.target))] = Verdict(v.jobId, v.result, v.skill, v.agreedBy, uint64(block.timestamp));
            emit VerdictMirrored(v.jobId, v.chain, v.target, v.result);
        } else if (kind == 3) {
            ( , , NOCert memory c) = abi.decode(b, (uint8, uint256, NOCert));
            bytes32 k = keccak256(abi.encode(c.chainId, c.target));
            NOCert storage have = certs[k];
            // newest certificate wins; a revocation of the same one always applies; never un-revoke
            if (c.issuedAt > have.issuedAt || (c.issuedAt == have.issuedAt && c.revoked && !have.revoked)) {
                certs[k] = c;
                emit CertificateMirrored(c.chainId, c.target, c.codeHash, c.level, c.revoked);
            }
        } else revert BadKind(kind);
    }

    function _apply(NOItem memory it) private {
        Mirror storage m = mirror[it.key];
        bool newer = it.round > m.round || (it.round == m.round && m.mirroredAt != 0 && it.flagged && m.flagged
            && (it.enforcedFrom < m.enforcedFrom || it.heldFrom < m.heldFrom));
        if (it.round == 0 || !newer) { emit Stale(it.key, it.round, m.round); return; }
        if (m.mirroredAt == 0) keys.push(it.key);
        if (it.flagged && !m.flagged) flaggedNow += 1;
        else if (!it.flagged && m.flagged) flaggedNow -= 1;
        mirror[it.key] = Mirror(it.round, it.flagged, it.flagged ? it.reason : 0, it.flagged ? it.enforcedFrom : 0, it.flagged ? it.heldFrom : 0, uint64(block.timestamp));
        emit Mirrored(it.key, it.round, it.flagged, it.reason, it.enforcedFrom);
    }

    // ---------------------------------------------------------------- views (the same keys as ThreatRegistry)

    function codeKey(bytes32 codeHash) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.code", codeHash)); }
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.address", chainId, who)); }

    /// (flagged, reason): as soon as the runner quorum flagged it on ZETAPHY (warn).
    function isFlagged(bytes32 key) public view returns (bool, uint8) {
        Mirror storage m = mirror[key];
        if (paused || !m.flagged) return (false, 0);
        return (true, m.reason);
    }

    /// (enforced, reason): once the registry's enforcement time passed (refuse).
    function isEnforced(bytes32 key) public view returns (bool, uint8) {
        Mirror storage m = mirror[key];
        if (paused || !m.flagged || block.timestamp < m.enforcedFrom) return (false, 0);
        return (true, m.reason);
    }

    function isAddressFlagged(uint256 chainId, address who) external view returns (bool, uint8) { return isFlagged(addressKey(chainId, who)); }
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, uint8) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, 0);
        return isFlagged(codeKey(codeHash));
    }

    /// What a DEX asks about a token on this chain: its address (on this chain) or its code is flagged.
    function check(address token) external view returns (bool flagged, bool enforced, uint8 reason) {
        bytes32[2] memory ks = [addressKey(block.chainid, token), token.codehash == bytes32(0) || token.codehash == EMPTY_CODEHASH ? bytes32(0) : codeKey(token.codehash)];
        for (uint256 i = 0; i < 2; ++i) {
            if (ks[i] == bytes32(0)) continue;
            (bool f, uint8 r) = isFlagged(ks[i]);
            if (!f) continue;
            (bool e, ) = isEnforced(ks[i]);
            if (!flagged || (e && !enforced)) { flagged = true; enforced = e; reason = r; }
        }
    }

    /// A settled Neuro verdict for (chain, target): (jobId, result, skill, agreedBy); jobId 0 and result 0: none.
    function verdictOf(bytes32 chain, string calldata target) external view returns (uint256, bytes32, bytes32, uint8) {
        Verdict storage v = verdicts[keccak256(abi.encode(chain, keccak256(bytes(target))))];
        return (v.jobId, v.result, v.skill, v.agreedBy);
    }

    /// A ZETAPHY audit certificate as mirrored: unexpired, not revoked, and for a contract on THIS chain its
    /// EXTCODEHASH is still the certified codeHash (an upgrade or redeploy fails at once). Paused: false.
    function isCertified(uint64 chainId, address target) external view returns (bool) {
        NOCert storage c = certs[keccak256(abi.encode(chainId, target))];
        if (paused || c.issuedAt == 0 || c.revoked || block.timestamp >= c.expiresAt) return false;
        if (chainId == block.chainid && target.codehash != c.codeHash) return false;
        return true;
    }

    function keyCount() external view returns (uint256) { return keys.length; }

    /// The mirrored round of each key (0: never mirrored): the hub's coverage meter compares them with ZETAPHY's.
    function roundsOf(bytes32[] calldata ks) external view returns (uint32[] memory out) {
        out = new uint32[](ks.length);
        for (uint256 i = 0; i < ks.length; ++i) out[i] = mirror[ks[i]].round;
    }
}

contracts/NeuroScore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title NeuroScore: Neuro's learned risk model (gradient-boosted trees), evaluated on-chain
/// @notice The model is zetaphy-neuro/ml/model.json exported to integers by
///         zetaphy-neuro/ml/onchain/export.js (format "NSM1", see ml/onchain/fixed.js):
///         160 trees of depth <= 4 packed in 6 bytes per node, ~18.6 KB, stored as the
///         code of one or more data contracts (read with EXTCODECOPY).
///
///         Score = the calibrated logit times 1e7: p = sigmoid(score / 1e7). Levels
///         (1 low, 2 medium, 3 high) are thresholds on it, set with the model.
///
///         Who does what:
///           - anyone publishes model bytes (publishModel): checked for format, stored,
///             keyed by keccak256(bytes) = the model hash H. Publishing changes nothing.
///           - governance (the ZetaphyTimelock: every change waits its public delay)
///             activates a published model by its hash (activateModel), and appoints
///             feeders. This contract is the model registry: every activation is a
///             numbered version with its hash, model id and level thresholds.
///           - a feeder (a Neuro runner relay governance appointed) posts the feature
///             vector Neuro computed for a token (postFeatures); the contract runs the
///             model on it and stores the score with the vector's hash.
///           - anyone re-runs a stored vector under the current model (rescore) after
///             a model change; until then the old score reads as unknown (scoreOf).
///         What the chain proves: the stored score IS the active model applied to the
///         posted vector. It does not prove the vector is what Neuro would compute
///         for the token: a feeder is trusted for that (the zkML prototype in
///         ml/onchain/zk/ proves the model step off-chain; it has the same gap).
///         A score is a statistical estimate, not a finding about a project.
contract NeuroScore {
    /// The ZetaphyTimelock (or, on a devnet, a multisig): activates models, appoints feeders.
    address public immutable governance;

    /// Most bytes one data contract holds (EIP-170 limit minus the leading STOP byte).
    uint256 public constant CHUNK = 24_575;
    uint256 private constant HEADER = 24;
    uint256 private constant NODE_BYTES = 6;

    struct Model {
        bytes32 hash; // keccak256 of the packed bytes (the model hash H)
        bytes32 modelId; // e.g. "nml-b4c35477f7b1"
        uint16 nFeatures;
        int64 low;
        int64 medium;
        int64 high;
        uint64 activatedAt;
    }

    struct Score {
        int64 score;
        uint32 version;
        uint8 level;
        uint64 time;
        bytes32 featuresHash;
    }

    /// Published models: hash -> the data contracts holding its bytes, in order.
    mapping(bytes32 => address[]) private _chunks;
    mapping(bytes32 => uint256) public publishedSize;
    /// Activated models: version (1, 2, ...) -> model. version 0 = none yet.
    mapping(uint32 => Model) private _models;
    uint32 public version;
    mapping(address => bool) public feeder;
    mapping(address => Score) private _scores;

    event ModelPublished(bytes32 indexed hash, uint256 size, uint256 chunks);
    event ModelActivated(uint32 indexed version, bytes32 indexed hash, bytes32 modelId, int64 low, int64 medium, int64 high);
    event FeederSet(address indexed feeder, bool allowed);
    event Scored(address indexed token, uint32 indexed version, int64 score, uint8 level, bytes32 featuresHash, bytes features);

    error NotGovernance();
    error NotFeeder();
    error ZeroAddress();
    error BadModel(uint256 at);
    error NotPublished();
    error NoModel();
    error BadFeatures();
    error UnknownFeatures();
    error BadLevels();
    error ScoreOutOfRange(int256 score);

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
    }

    // ---- models ----

    /// Stores model bytes (after checking the format) as data contracts. Anyone may
    /// call it; it activates nothing. Returns the model hash.
    function publishModel(bytes calldata data) external returns (bytes32 hash) {
        hash = keccak256(data);
        if (publishedSize[hash] != 0) return hash;
        _validate(data);
        address[] storage list = _chunks[hash];
        for (uint256 o = 0; o < data.length; o += CHUNK) {
            uint256 end = o + CHUNK < data.length ? o + CHUNK : data.length;
            list.push(_store(data[o:end]));
        }
        publishedSize[hash] = data.length;
        emit ModelPublished(hash, data.length, list.length);
    }

    /// Governance only (the timelock): makes a published model the active one.
    /// Levels are fixed calibrated logits (low <= medium <= high).
    function activateModel(bytes32 hash, bytes32 modelId, int64 low, int64 medium, int64 high) external onlyGov {
        if (publishedSize[hash] == 0) revert NotPublished();
        if (low > medium || medium > high) revert BadLevels();
        bytes memory m = _load(hash);
        uint16 nf;
        assembly { nf := and(shr(240, shl(32, mload(add(m, 32)))), 0xffff) }
        uint32 v = version + 1;
        _models[v] = Model(hash, modelId, nf, low, medium, high, uint64(block.timestamp));
        version = v;
        emit ModelActivated(v, hash, modelId, low, medium, high);
    }

    function setFeeder(address who, bool allowed) external onlyGov {
        if (who == address(0)) revert ZeroAddress();
        feeder[who] = allowed;
        emit FeederSet(who, allowed);
    }

    function model(uint32 v) external view returns (Model memory) {
        return _models[v];
    }

    function chunksOf(bytes32 hash) external view returns (address[] memory) {
        return _chunks[hash];
    }

    /// The packed bytes of a published model (for anyone checking them against the hash).
    function modelBytes(bytes32 hash) external view returns (bytes memory) {
        if (publishedSize[hash] == 0) revert NotPublished();
        return _load(hash);
    }

    // ---- scoring ----

    /// Runs the active model on a feature vector (nFeatures x uint32 big-endian, scale 1e7).
    function evaluate(bytes calldata features) public view returns (int256 score, uint8 level) {
        return evaluateAt(version, features);
    }

    /// Runs model `v` (any activated version) on a feature vector.
    function evaluateAt(uint32 v, bytes calldata features) public view returns (int256 score, uint8 level) {
        Model storage md = _models[v];
        if (md.hash == bytes32(0)) revert NoModel();
        if (features.length != uint256(md.nFeatures) * 4) revert BadFeatures();
        score = _eval(_load(md.hash), features);
        level = _level(md, score);
    }

    /// A feeder posts the features Neuro computed for `token`; the score is computed here.
    function postFeatures(address token, bytes calldata features) external returns (int256 score, uint8 level) {
        if (!feeder[msg.sender]) revert NotFeeder();
        return _score(token, features);
    }

    /// Anyone: re-runs the stored feature vector of `token` (its preimage, from the
    /// Scored event) under the active model, e.g. after a model change.
    function rescore(address token, bytes calldata features) external returns (int256 score, uint8 level) {
        if (_scores[token].featuresHash == bytes32(0) || keccak256(features) != _scores[token].featuresHash) revert UnknownFeatures();
        return _score(token, features);
    }

    /// The token's score under the ACTIVE model. known = false when it was never
    /// scored or only under an older model (rescore brings it up to date).
    function scoreOf(address token) external view returns (bool known, int256 score, uint8 level) {
        Score storage s = _scores[token];
        if (s.version == 0 || s.version != version) return (false, 0, 0);
        return (true, s.score, s.level);
    }

    /// The stored record, whatever model it was computed with.
    function scoreRecord(address token) external view returns (Score memory) {
        return _scores[token];
    }

    function _score(address token, bytes calldata features) private returns (int256 score, uint8 level) {
        uint32 v = version;
        (score, level) = evaluateAt(v, features);
        bytes32 fh = keccak256(features);
        int64 stored = _toInt64(score);
        _scores[token] = Score(stored, v, level, uint64(block.timestamp), fh);
        emit Scored(token, v, stored, level, fh, features);
    }

    /// The score as stored (int64). A model whose calibration (a * z / scale + b) leaves the int64
    /// range would otherwise be stored truncated while evaluate() returns the full value: refuse it.
    function _toInt64(int256 x) private pure returns (int64 y) {
        if (x > type(int64).max || x < type(int64).min) revert ScoreOutOfRange(x);
        assembly { y := x } // in range: checked on the line above
    }

    function _level(Model storage md, int256 s) private view returns (uint8) {
        if (s >= md.high) return 3;
        if (s >= md.medium) return 2;
        if (s >= md.low) return 1;
        return 0;
    }

    /// Trees on integer features: a row goes left when x[f] <= threshold; leaves add up
    /// to the margin z; score = trunc(calibA * z / scale) + calibB.
    function _eval(bytes memory m, bytes calldata x) private pure returns (int256 s) {
        assembly {
            let p := add(m, 32)
            let w := mload(p)
            let nt := and(shr(192, w), 0xffff)
            let scale := and(shr(160, w), 0xffffffff)
            let z := signextend(3, and(shr(128, w), 0xffffffff))
            let a := signextend(3, and(shr(96, w), 0xffffffff))
            let b := signextend(3, and(shr(64, w), 0xffffffff))
            let sizes := add(p, 24)
            let node := add(sizes, nt)
            let xo := x.offset
            for { let k := 0 } lt(k, nt) { k := add(k, 1) } {
                let i := node
                for {} 1 {} {
                    let v := mload(i)
                    let f := shr(248, v)
                    if eq(f, 0xff) {
                        z := add(z, signextend(3, and(shr(216, v), 0xffffffff)))
                        break
                    }
                    switch gt(shr(224, calldataload(add(xo, shl(2, f)))), and(shr(216, v), 0xffffffff))
                    case 0 { i := add(i, 6) }
                    default { i := add(node, mul(6, and(shr(208, v), 0xff))) }
                }
                node := add(node, mul(6, byte(0, mload(add(sizes, k)))))
            }
            s := add(sdiv(mul(a, z), scale), b)
        }
    }

    /// Checks the NSM1 layout so evaluation stays inside the bytes and always ends:
    /// every feature index < nFeatures, every right child after its node and inside
    /// its tree, every path ending in a leaf, the sizes adding up to the length.
    function _validate(bytes calldata d) private pure {
        if (d.length < HEADER || bytes4(d[0:4]) != "NSM1") revert BadModel(0);
        uint256 nf = uint16(bytes2(d[4:6]));
        uint256 nt = uint16(bytes2(d[6:8]));
        if (nf == 0 || nt == 0 || uint32(bytes4(d[8:12])) == 0) revert BadModel(4);
        if (int32(uint32(bytes4(d[16:20]))) <= 0) revert BadModel(16);
        if (d.length < HEADER + nt) revert BadModel(24);
        uint256 o = HEADER + nt;
        for (uint256 k = 0; k < nt; k++) {
            uint256 n = uint8(d[HEADER + k]);
            if (n == 0 || d.length < o + n * NODE_BYTES) revert BadModel(HEADER + k);
            for (uint256 i = 0; i < n; i++) {
                uint256 at = o + i * NODE_BYTES;
                uint256 f = uint8(d[at]);
                if (f == 0xff) {
                    if (uint8(d[at + 5]) != 0) revert BadModel(at);
                    continue;
                }
                uint256 r = uint8(d[at + 5]);
                // pre-order: left child = i + 1, right child further on, both inside the tree
                if (f >= nf || i + 1 >= n || r <= i + 1 || r >= n) revert BadModel(at);
            }
            if (uint8(d[o + (n - 1) * NODE_BYTES]) != 0xff) revert BadModel(o);
            o += n * NODE_BYTES;
        }
        if (o != d.length) revert BadModel(o);
    }

    /// Deploys a data contract whose code is 0x00 ++ data (the STOP keeps it from running).
    function _store(bytes calldata data) private returns (address a) {
        bytes memory init = abi.encodePacked(hex"63", uint32(data.length + 1), hex"80600e6000396000f3", hex"00", data);
        assembly { a := create(0, add(init, 32), mload(init)) }
        if (a == address(0)) revert BadModel(0);
    }

    function _load(bytes32 hash) private view returns (bytes memory m) {
        address[] storage list = _chunks[hash];
        uint256 size = publishedSize[hash];
        m = new bytes(size);
        uint256 dst;
        assembly { dst := add(m, 32) }
        for (uint256 i = 0; i < list.length; i++) {
            address a = list[i];
            uint256 len = a.code.length - 1;
            assembly { extcodecopy(a, dst, 1, len) }
            dst += len;
        }
        // bytes past the end stay zero, so a 32-byte read of the last node is safe
    }
}

